(window.__LIB=window.__LIB||{}).tusi={"k":"tusi","chs":[["المقدمة",1],["فصل في غيبة الإمام المهدي (ع)",5],["الأصل الأول: وجوب الإمامة",39],["الأصل الثاني: عصمة الإمام",1],["الأصل الثالث: أن الحق لا يخرج عن الأمة الإسلامية",1],["إبطال مذهب الكيسانية",11],["إبطال مذهب الناووسية",1],["إبطال مذهب الواقفة",1],["الأخبار الواردة في استشهاد الإمام الكاظم (ع)",6],["تصريح الكاظم (ع) بإمامة الرضا (ع)",17],["دلائل إمامة الكاظم (ع) والرد على الواقفة",41],["أسباب ظهور مذهب الواقفة",5],["الأخبار في ذمّ الواقفة",7],["بعض معجزات الإمام الرضا (ع)",9],["اعتراضات المخالفين على ولادة الإمام المهدي (ع)",5],["إبطال الفرق التي قالت بإمامة غير صاحب الزمان (ع)",7],["فلسفة الغيبة وحكمتها",22],["الفرق بين الإمام المستور والإمام المعدوم أو الموجود في السماء",3],["إقامة الحدود في زمن الغيبة",6],["تمييز الحق في زمن غيبة الإمام",6],["كلام السيد المرتضى (ره)",1],["علة غيبة الإمام عن شيعته",19],["كتمان ولادة صاحب الزمان (ع) ليس أمراً غريباً",21],["قصص المعمّرين من العرب والعجم",29],["روايات أهل السنة في أن الأئمة اثنا عشر",12],["روايات الشيعة في أن الأئمة اثنا عشر",16],["أحاديث الأئمة (ع) في غيبة الإمام المهدي (ع)",17],["الروايات المؤكدة لقيام الإمام المهدي (ع)",15],["المهدي من ولد علي وفاطمة (ع)",6],["المهدي من ولد الإمام الحسين (ع)",12],["إبطال الكيسانية وخبر وفاة محمد بن الحنفية",4],["إبطال قول من وقف على الإمام الصادق (ع) وزعم أنه المهدي المنتظر",5],["إمامة الإمام الحسن العسكري (ع)",48],["دلائل ولادة صاحب الزمان (ع)",34],["أخبار من رأى الإمام صاحب الزمان (ع)",19],["معجزات صاحب الزمان (ع) في غيبته",7],["التوقيعات الصادرة عن الإمام المهدي (ع)",31],["أسباب تأخّر ظهور صاحب الأمر (ع)",11],["امتحان الشيعة في زمن الغيبة",13],["أخبار السفراء في زمن الغيبة",3],["السفراء الممدوحون",28],["السفراء الذين ذمّهم الإمام (ع)",7],["السفراء الخاصون للإمام (ع) في الغيبة",41],["مسائل محمد بن عبد الله بن جعفر الحميري",3],["تتمة فضائل الحسين بن روح",17],["أبو الحسن علي بن محمد السمري",8],["مدّعو النيابة الكاذبون الذين ذمّهم الأئمة (ع)",29],["وكلاء السفراء الأربعة",8],["طول عمر الإمام (ع)",16],["وقت ظهور الإمام (ع)",17],["علامات ظهور الإمام المهدي (ع)",60],["بعض صفات صاحب الزمان (ع) وسننه وآدابه",23]],"items":[[1,0,"بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ الحمد لله الذي هدانا لحمده، وجعلنا من أهله، ووفقنا للتمسك بدينه والانقياد لسبيله، ولم يجعلنا من الجاحدين لنعمته، المنكرين لطوله وفضله ومن الذين ﴿إِسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ فَأَنْسَاهُمْ ذِكْرَ اللهِ أُولَئِكَ حِزْبُ الشَّيْطَانِ أَلاَ إِنَّ حِزْبَ الشَّيْطَانِ هُمُ الْخَاسِرُونَ﴾. وصلى الله على سيد أنبيائه وخاتم أصفيائه محمد صلى الله عليه وعلى آله الطيبين، النجوم الزاهرة، والاعلام الظاهرة، الذين نتمسك بولايتهم، ونتعلق بعرى حبلهم، ونرجو الفوز بالتمسك بهم، وسلم تسليما. أما بعد فإني مجيب إلى ما رسمه الشيخ الجليل، أطال الله بقاء‌ه من إملاء كلام في غيبة صاحب الزمان، وسبب غيبته، والعلة التي لاجلها طالت غيبته، وامتداد استتاره، مع شدة الحاجة إليه وانتشار الحيل، ووقوع الهرج والمرج، وكثرة الفساد في الارض، وظهوره في البر والبحر، ولم لم يظهر:وما المانع منه، وما المحوج إليه، والجواب عن كل ما يسأل في ذلك من شبه المخالفين، ومطاعن المعاندين. وأنا مجيب إلى ما سأله، وممتثل ما رسمه، مع ضيق الوقت، وشعث الفكر، وعوائق الزمان. وصوارف الحدثان، وأتكلم بجمل يزول معها الريب وتنحسم به الشبه ولا أطول الكلام فيه(فيمل، فإن كتبي في)الامامة وكتب شيوخنا مبسوطة في هذا المعنى في غاية الاستقصاء، وأتكلم عن(كل)ما يسأل في هذا الباب من الاسئولة المختلفة، وأردف ذلك بطرف من الاخبار الدالة على صحة ما نذكره، ليكون ذلك تأكيدا لما نذكره، وتأنيسا للمتمسكين بالاخبار، والمتعلقين بظواهر الاحوال، فإن كثيرا من الناس يخفى عليهم الكلام اللطيف الذي يتعلق بهذا الباب، وربما لم يتبينه، وأجعل للفريقين طريقا إلى ما نختاره ونلتمسه، ومن الله تعالى أستمد المعونة والتوفيق، فهما المرجوان من جهته، والمطلوبان من قبله، وهو حسبي ونعم الوكيل.","27/1/1/1",""],[1,1,"فصل في الكلام في الغيبة: إعلم أن لنا في الكلام في غيبة صاحب الزمان عليه السلام طريقين.","27/1/2/1",""],[2,1,"أحدهما: أن نقول:إذا ثبت وجوب الامامة في كل حال، وأن الخلق مع كونهم غير معصومين لا يجوز أن يخلو من رئيس في وقت من الاوقات، وأن من شرط الرئيس أن يكون مقطوعا على عصمته، فلا يخلو ذلك الرئيس من أن يكون ظاهرا معلوما، أو غائبا مستورا، فإذا علمنا أن كل من يدعي له الامامة ظاهرا ليس بمقطوع على عصمته، بل ظاهر أفعالهم وأحوالهم ينافي العصمة، علمنا أن من يقطع على عصمته غائب مستور. وإذا علمنا أن كل من يدعي له العصمة قطعا من هو غائب من الكيسانية و الناووسية و الفطحية والواقفة وغيرهم قولهم باطل، علمنا بذلك صحة إمامة ابن الحسن عليه السلام وصحة غيبته وولايته، ولا نحتاج إلى تكلف الكلام في إثبات ولادته، وسبب غيبته، مع ثبوت ما ذكرناه، لأن الحق لا يجوز خروجه عن الأمة.","27/1/2/2",""],[3,1,"والطريق الثاني: أن نقول: الكلام في غيبة ابن الحسن عليه السلام فرع على ثبوت إمامته، والمخالف لنا إما أن يسلم لنا إمامته ويسأل عن سبب غيبته عليه السلام فنتكلف جوابه، أو لا يسلم لنا إمامته فلا معنى لسؤاله عن غيبة من لم يثبت إمامته، ومتى نوزعنا في ثبوت إمامته دللنا عليها بأن نقول:قد ثبت وجوب الامامة مع بقاء التكليف على من ليس بمعصوم في جميع الاحوال والاعصار بالادلة القاهرة، وثبت أيضا أن من شرط الامام أن يكون مقطوعا على عصمته وعلمنا أيضا أن الحق لا يخرج عن الامة. بين قائل يقول: لا إمام، فما ثبت من وجوب الإمامة في كل حال يفسد قوله.","27/1/2/3",""],[4,1,"وقائل يقول بإمامة من ليس بمقطوع على عصمته، فقوله يبطل بما دللنا عليه من وجوب القطع على عصمة الامام عليه السلام. ومن ادعى العصمة لبعض من يذهب إلى إمامته، فالشاهد يشهد بخلاف قوله، لان أفعالهم الظاهرة وأحوالهم تنافي العصمة، فلا وجه لتكلف القول فيما نعلم ضرورة خلافه. ومن ادعيت له العصمة وذهب قوم إلى إمامته كالكيسانية القائلين بإمامة محمد بن الحنفية، والناووسية القائلين بإمامة جعفر بن محمد عليه السلام، وأنه لم يمت والواقفية الذين قالوا:إن موسى بن جعفر عليه السلام لم يمت، فقولهم باطل من وجوه سنذكرها.","27/1/2/4",""],[5,1,"فصار الطريقان محتاجين إلى فساد قول هذه الفرق ليتم ما قصدناه ويفتقران إلى إثبات الاصول(الثلاثة)التي ذكرناها من وجوب الرئاسة، ووجوب القطع على العصمة، وأن الحق لا يخرج عن الامة، ونحن ندل على كل واحد من هذه الاقوال بموجز من القول لان استيفاء ذلك موجود في كتبي في الامامة على وجه لا مزيد عليه. والغرض بهذا الكتاب ما يختص الغيبة دون غيرها والله الموفق لذلك بمنه.","27/1/2/5",""],[1,2,"والذي يدل على وجوب الرئاسة ما ثبت من كونها لطفاًفي الواجبات العقلية فصارت واجبة، كالمعرفة التي لا يعرى مكلف من وجوبها عليه، ألا ترى أن من المعلوم أن من ليس بمعصوم من الخلق متى خلوا من رئيس مهيب يردع المعاند ويؤدب الجاني، ويأخذ على يد المتغلب، ويمنع القوي من الضعيف، وأمنوا ذلك، وقع الفساد، وانتشر الحيل، وكثر الفساد، وقل الصلاح، ومتى كان لهم رئيس هذه صفته كان الامر بالعكس من ذلك، من شمول الصلاح وكثرته، وقلة الفساد ونزارته والعلم بذلك ضروري لا يخفى على العقلاء، فمن دفعه لا يحسن مكالمته، وأجبنا عن كل ما يسأل على ذلك مستوفى في تلخيص الشافي وشرح الجمل لا نطول بذكره ها هنا.","27/1/3/1",""],[2,2,"ووجدت لبعض المتأخرين كلاما اعترض به كلام المرتضى (ره) في الغيبة وظن أنه ظفر بطائل فموه به على من ليس له قريحة ولا بصر بوجوه النظر وأنا أتكلم عليه.","27/1/3/2",""],[3,2,"فقال: الكلام في الغيبة والاعتراض عليها من ثلاثة أوجه. أحدها: أنا نلزم الامامية ثبوت وجه قبح فيها أو في التكليف معها فيلزمهم أن يثبوا أن الغيبة ليس فيها وجه قبح، لان مع ثبوت وجه القبح تقبح الغيبة، وإن ثبت فيها وجه حسن كما نقول في قبح تكليف ما لا يطاق (أن فيه وجه قبح) وإن كان فيه وجه حسن بأن يكون لطفا لغيره.","27/1/3/3",""],[4,2,"والثاني: أن الغيبة تنقض طريق وجوب الامامة في كل زمان، لان كون الناس مع رئيس مهيب متصرف أبعد من القبيح لو اقتضى كونه لطفا واجبا في كل حال، وقبح التكليف مع فقده لانتقض بزمان الغيبة، لانا في زمان الغيبة نكون مع رئيس هذه صفته أبعد من القبيح، وهو دليل وجوب هذه الرئاسة، ولم يجب وجود رئيس هذه صفته في زمان الغيبة ولا قبح التكليف مع فقده، فقد وجد الدليل ولا مدلول وهذا نقض الدليل.","27/1/3/4",""],[5,2,"والثالث: أن يقال: إن الفائدة بالامامة هي كونه مبعدا من القبيح على قولكم، وذلك لا يحصل مع وجوده غائبا فلم ينفصل وجوده من عدمه، وإذا لم يختص وجوده غائبا بوجه الوجوب الذي ذكروه لم يقتض دليلكم وجوب وجوده مع الغيبة، فدليلكم مع أنه منتقض حيث وجد مع انبساط اليد، ولم يجب انبساط اليد مع الغيبة، فهو غير متعلق بوجود إمام غير منبسط اليد ولا هو حاصل في هذه الحال.","27/1/3/5",""],[6,2,"الكلام عليه أن نقول:أما الفصل الأول من قوله: \"إنا نلزم الامامية أن يكون في الغيبة وجه قبح\" وعيد منه محض لا يقترن به حجة، فكان ينبغي أن يتبين وجه القبح الذي أراد إلزامه إياهم لننظر فيه ولم يفعل، فلا يتوجه وعيده. وإن قال ذلك سائلا على وجه: \"ما أنكرتم أن يكون فيها وجه قبح\". فإنا نقول: وجوه القبح معقولة من كون الشيء ظلما وعبثا وكذبا ومفسدة وجهلا وليس شيء من ذلك موجودا ها هنا، فعلمنا بذلك انتفاء وجود القبح. فإن قيل: وجه القبح أنه لم يزح علة المكلف على قولكم، لأن انبساط يده الذي هو لطف في الحقيقة والخوف من تأديبه لم يحصل، فصار ذلك إخلالا بلطف المكلف فقبح لأجله.","27/1/3/6",""],[7,2,"قلنا: (قد)بينا في باب وجوب الامامة بحيث أشرنا إليه أن انبساط يده عليه السلام والخوف من تأديبه إنما فات المكلفين لما يرجع إليهم، لانهم أحوجوه إلى الاستتار بأن أخافوه ولم يمكنوه فأتوا من قبل نفوسهم. وجرى ذلك مجرى أن يقول قائل: \"من لم يحصل له معرفة الله تعالى في تكليفه وجه قبح\"لانه لم يحصل ما هو لطف له من المعرفة، فينبغي أن يقبح تكليفه.","27/1/3/7",""],[8,2,"قلنا: (قد)بينا في باب وجوب الامامة بحيث أشرنا إليه أن انبساط يده عليه السلام والخوف من تأديبه إنما فات المكلفين لما يرجع إليهم، لأنهم أحوجوه إلى الاستتار بأن أخافوه ولم يمكنوه فأتوا من قبل نفوسهم. وجرى ذلك مجرى أن يقول قائل: \"من لم يحصل له معرفة الله تعالى في تكليفه وجه قبح\" لأنه لم يحصل ما هو لطف له من المعرفة، فينبغي أن يقبح تكليفه.","27/1/3/8",""],[9,2,"فما يقولونه ها هنا من أن الكافر أتي من قبل نفسه، لان الله قد نصب له الدلالة على معرفة ومكنه من الوصول إليها، فإذا لم ينظر ولم يعرف أتي في ذلك من قبل نفسه ولم يقبح ذلك تكليفه، فكذلك نقول:إنبساط يد الامام وإن فات المكلف فإنما أتي من قبل نفسه، ولو مكنه لظهر وانبسطت يده فحصل لطفه فلم يقبح تكليفه، لان الحجة عليه لا له. وقد استوفينا نظائر ذلك في الموضع الذي أشرنا إليه، وسنذكر فيما بعد إذا عرض ما يحتاج إلى ذكره.","27/1/3/9",""],[10,2,"وأما الكلام في الفصل الثاني:فهو مبني على المغالطة ولا نقول:إنه لم يفهم ما أورده، لان الرجل كان فوق ذلك لكن أراد التلبيس والتمويه(في قوله): إن دليل وجوب الرئاسة ينتقض بحال الغيبة، لان كون الناس مع رئيس مهيب متصرف أبعد من القبيح لو اقتضى كونه لطفا واجبا على كل حال وقبح التكليف مع فقده لا نتقض بزمان الغيبة(لانا في زمان الغيبة)فلم يقبح التكليف مع فقده، فقد وجد الدليل ولا مدلول وهذا نقض.","27/1/3/10",""],[11,2,"وإنما قلنا: إنه تمويه لانه ظن أنا نقول: إن في حال الغيبة دليل وجوب الامامة قائم ولا إمام فكان نقضا، ولا نقول ذلك، بل دليلنا في حال وجود الامام بعينه هو دليل حال غيبته، في أن في الحالين الامام لطف فلا نقول:إن زمان الغيبة خلا من وجوب رئيس، بل عندنا أن الرئيس حاصل، وإنما ارتفع انبساط يده لما يرجع إلى المكلفين على ما بيناه، لا لان انبساط يده خرج من كونه لطفا بل وجه اللطف به قائم، وإنما لم يحصل لما يرجع إلى غير الله. فجرى مجرى أن يقول قائل:كيف يكون معرفة الله تعالى لطفا مع أن الكافر لا يعرف الله، فلما كان التكليف على الكافر قائما والمعرفة مرتفعة دل على أن المعرفة ليست لطفا على كل حال لانها لو كانت كذلك لكان ذلك نقضا.","27/1/3/11",""],[12,2,"وجوابنا في الامامة كجوابهم في المعرفة من أن الكافر لطفه قائم بالمعرفة وإنما فوت نفسه بالتفريط في النظر المؤدي إليها فلم يقبح تكليفه، فكذلك نقول:الرئاسة لطف للمكلف في حال الغيبة، وما يتعلق بالله من إيجاده حاصل، وإنما ارتفع تصرفه وانبساط يده لامر يرجع إلى المكلفين فاستوى الامران، والكلام في هذه المعنى مستوفى أيضا بحيث ذكرناه.","27/1/3/12",""],[13,2,"وأما الكلام في الفصل الثالث: من قوله:إن الفائدة بالامامة هي كونه مبعدا من القبيح على قولكم، وذلك لم يحصل مع غيبته، فلم ينفصل وجوده من عدمه، فإذا لم يختص وجوده غائبا بوجه الوجوب الذي ذكروه لم يقتض دليلكم وجوب وجوده مع الغيبـة، دليلكم مع أنه منتقض حيث وجد مع انبساط اليد، ولم يجب انبساط اليد مع الغيبة، فهو غير متعلق بوجود إمام غير منبسط اليد ولا هو حاصل في هذه الحال.","27/1/3/13",""],[14,2,"فإنا نقول: إنه لم يفعل في هذا الفصل أكثر من تعقيد القول على طريقة المنطقيين من قلب المقدمات ورد بعضها على بعض، ولا شك أنه قصد بذلك المتويه والمغالطة، وإلا فالامر أوضح من أن يخفى. ومتى قالت الامامية: إن انبساط يد الامام لا يجب في حال الغيبة حتى يقول:دليلكم لا يدل على وجوب إمام غير منبسط اليد، لان هذه حال الغيبة، بل الذي صرحنا به دفعة بعد أخرى أن انبساط يده واجب في الحالين (في) حال ظهوره وحال غيبته، غير أن حال ظهوره مكن منه فانبسطت يده وحال الغيبة لم يمكن فانقبضت يده، لا أن انبساط يده خرج من باب الوجوب. وبينا أن الحجة بذلك قائمة على المكلفين من حيث منعوه ولم يمكنوه فأتوا من قبل نفوسهم، وشبهنا ذلك بالمعرفة دفعة بعد أخرى.","27/1/3/14",""],[15,2,"وأيضا فإنا نعلم أن نصب الرئيس واجب بعد الشرع لما في نصبه من اللطف لتحمله للقيام بما لا يقوم به غيره، ومع هذا فليس التمكين واقعا لأهل الحل والعقد من نصب من يصلح لها خاصة على مذهب أهل العدل الذين كلامنا معهم، ومع هذا لا يقول أحد: إن وجوب نصب الرئيس سقط الآن من حيث لم يقع التمكين منه.","27/1/3/15",""],[16,2,"فجوابنا في غيبة الإمام جوابهم في منع أهل الحل والعقد من اختيار من يصلح للإمامة، ولا فرق بينهما فإنما الخلاف بيننا أنا قلنا:علمنا ذلك عقلا، وقالوا ذلك معلوم شرعا، وذلك فرق من غير موضع الجمع.","27/1/3/16",""],[17,2,"فإن قيل:أهل الحل والعقد إذا لم يمكنوا من اختيار من يصلح للامامة فإن الله يفعل ما يقوم مقام ذلك من الألطاف فلا يجب إسقاط التكليف، وفي الشيوخ من قال إن الامام يجب نصبه في الشرع لمصالح دنياوية، وذلك غير واجب أن يفعل لها اللطف.","27/1/3/17",""],[18,2,"قلنا: أما من قال: نصب الإمام لمصالح دنياوية قوله يفسد:لأنه لو كان كذلك لما وجب إمامته، ولا خلاف بينهم في أنه يجب إقامة الإمام مع الاختيار. على أن ما يقوم به الإمام من الجهاد وتولية الأمراء والقضاة وقسمة الفئ واستيفاء الحدود والقصاصات أمور دينية لا يجوز تركها، ولو كان لمصلحة دنياوية لما وجب ذلك، فقوله ساقط بذلك.","27/1/3/18",""],[19,2,"وأما من قال: يفعل الله ما يقوم مقامه باطل، لأنه لو كان كذلك لما وجب عليه إقامة الإمام مطلقا على كل حال، ولكان يكون ذلك من باب التخيير، كما نقول في فروض الكفايات.وفي علمنا بتعيين ذلك ووجوبه على كل حال دليل على فساد ما قالوه. على أنه يلزم على الوجهين جميعا المعرفة. بأن يقال: الكافر إذا لم يحصل له المعرفة يفعل الله له ما يقوم مقامها، فلا يجب عليه المعرفة على كل حال.","27/1/3/19",""],[20,2,"أو يقال: إن ما يحصل من الانزجار عن فعل الظلم عند المعرفة أمر دنياوي لا يجب لها المعرفة، فيجب من ذلك إسقاط وجوب المعرفة، ومتى قيل:إنه لا بدل للمعرفة، قلنا:وكذلك لا بدل للامام على ما مضى- وذكرناه في تلخيص الشافي-وكذلك إن بينوا أن الانزجار من القبيح عند المعرفة أمر ديني قلنا:مثل ذلك في وجود الإمام سواء.","27/1/3/20",""],[21,2,"فإن قيل:لا يخلو وجود رئيس مطاع منبسط اليد من أن يجب على الله جميع ذلك أو يجب علينا جميعه أو يجب على الله إيجاده وعلينا بسط يده.","27/1/3/21",""],[22,2,"فإن قلتم: يجب جميع ذلك على الله، فإنه ينتقض بحال الغيبة لأنه لم يوجد إمام منبسط اليد، وإن وجب علينا جميعه فذلك تكليف ما لا يطاق، لانا لا نقدر على إيجاده، وإن وجب عليه إيجاده وعلينا بسط يده وتمكينه فما دليلكم عليه، مع أن فيه أنه يجب علينا أن نفعل ما هو لطف للغير، وكيف يجب على زيد بسط يد الإمام لتحصيل لطف عمرو، وهل ذلك إلا نقض الأصول.","27/1/3/22",""],[23,2,"قلنا: الذي نقوله أن وجود الإمام المنبسط اليد إذا ثبت أنه لطف لنا على ما دللنا عليه ولم يكن إيجاده في مقدورنا لم يحسن أن نكلف إيجاده لأنه تكليف ما لا يطاق، وبسط يده وتقوية سلطانه قد يكون في مقدورنا وفي مقدور الله، فإذا لم يفعل الله تعالى علمنا أنه غير واجب عليه وأنه واجب علينا، لانه لابد من أن يكون منبسط اليد ليتم الغرض بالتكليف، وبينا بذلك أن بسط يده لو كان من فعله تعالى لقهر الخلق عليه، والحيلولة بينه وبين أعدائه وتقوية أمره بالملائكة ربما أدى إلى سقوط الغرض بالتكليف، وحصول الالجاء، فإذا يجب علينا بسط يده على كل حال وإذا لم نفعله أتينا من قبل نفوسنا.","27/1/3/23",""],[24,2,"فأما قولهم: في ذلك إيجاب اللطف علينا للغير غير صحيح. لأنا نقول: إن كل من يجب عليه نصرة الإمام وتقوية سلطانه له في ذلك مصلحة تخصه، وإن كانت فيه مصلحة يرجع إلى غيره كما نقوله في أن الأنبياء يجب عليهم تحمل أعباء النبوة والأداء إلى الخلق ما هو مصلحة لهم، لأن لهم في القيام بذلك مصلحة تخصهم وإن كانت فيها مصلحة لغيرهم. ويلزم المخالف في أهل الحل والعقد بأن يقال:كيف يجب عليهم اختيار الإمام لمصلحة ترجع إلى جميع الامة، وهل ذلك إلا إيجاب الفعل عليهم لما يرجع إلى مصلحة غيرهم، فأي شيء أجابوا به فهو جوابنا بعينه سواء.","27/1/3/24",""],[25,2,"فإن قيل: لم زعمتم أنه يجب إيجاده في حال الغيبة وهلا جاز أن يكون معدوما. قلنا:إنما أوجبنا (ذلك) من حيث إن تصرفه الذي هو لطفنا إذا لم يتم إلا بعد وجوده وإيجاده لم يكن في مقدورنا، قلنا عند ذلك:أنه يجب على الله ذلك وإلا أدى إلى أن لا نكون مزاحي العلة بفعل اللطف فنكون أتينا من قبله تعالى لا من قبلنا، وإذا أوجده ولم نمكنه من انبساط يده أتينا من قبل نفوسنا فحسن التكليف وفي الأول لم يحسن.","27/1/3/25",""],[26,2,"فإن قيل: ما الذي تريدون بتمكيننا إياه؟ أتريدون أن نقصده ونشافهه وذلك لا يتم إلا مع وجوده. قيل لكم:لا يصح جميع ذلك إلا مع ظهوره وعلمنا أو علم بعضنا بمكانه. وإن قلتم: نريد بتمكيننا أن نبخع لطاعته والشد على يده، ونكف عن نصرة الظالمين، ونقوم على نصرته متى دعانا إلى إمامته ودلنا عليها بمعجزته. قلنا لكم: فنحن يمكننا ذلك في زمان الغيبة وإن لم يكن الامام موجودا فيه، فكيف قلتم لا يتم ما كلفناه من ذلك إلا مع وجود الإمام. قلنا:الذي نقوله في هذا الباب ما ذكره المرتضى رحمه الله في الذخيرة وذكرناه في تلخيص الشافي أن الذي هو لطفنا من تصرف الإمام وانبساط يده لا يتم إلا بأمور ثلاثة.","27/1/3/26",""],[27,2,"أحدها: يتعلق بالله وهو إيجاده. والثاني: يتعلق به من تحمل أعباء الامامة والقيام بها. والثالث: يتعلق بنا من العزم على نصرته، ومعاضدته، والانقياد له، فوجوب تحمله عليه فرع على وجوده، لأنه لا يجوز أن يتناول التكليف المعدوم، فصار إيجاد الله إياه أصلا لوجوب قيامه، وصار وجوب نصرته علينا فرعا لهذين الأصلين لأنه إنما يجب علينا طاعته إذا وجد، وتحمل أعباء الامامة وقام بها، فحينئذ يجب علينا طاعته، فمع هذا التحقيق كيف يقال:لم لا يكون معدوما.","27/1/3/27",""],[28,2,"فإن قيل: فما الفرق بين أن يكون موجودا مستترا (حتى إذا علم الله منا تمكينه أظهره، وبين أن يكون) معدوما حتى إذا علم منا العزم على تمكينه أوجده. قلنا:لا يحسن من الله تعالى أن يوجب علينا تمكين من ليس بموجود لأنه تكليف ما لا يطاق، فإذا لابد من وجوده.","27/1/3/28",""],[29,2,"فإن قيل: يوجده الله تعالى إذا علم أنا ننطوي على تمكينه بزمان واحد كما أنه يظهره عند مثل ذلك. قلنــا: وجوب تمكينه والانطواء على طاعته لازم في جميع أحوالنا، فيجب أن يكون التمكين من طاعته والمصير إلى أمره ممكنا في جميع الاحوال وإلا لم يحسن التكليف، وإنما كان يتم ذلك لو لم نكن مكلفين في كل حال لوجوب طاعته والانقياد لأمره، بل كان يجب علينا عند ظهوره والأمر عندنا بخلافه.","27/1/3/29",""],[30,2,"ثم يقال لمن خالفنا في ذلك وألزمنا عدمه على استتاره:لم لا يجوز أن يكلف الله تعالى المعرفة ولا ينصب عليها دلالة إذا علم أنا لا ننظر فيها، حتى إذا علم من حالنا أنا نقصد إلى النظر ونعزم على ذلك أوجد الادلة ونصبها، فحينئذ ننظر ونقول ما الفرق بين دلالة منصوبة لا ننظر فيها وبين عدمها حتى إذا عزمنا على النظر فيها أوجدها الله تعالى.","27/1/3/30",""],[31,2,"والمثال الذي ذكره من أنه لو أوجب الله علينا أن نتوضأ من ماء بئر معينة لم يكن لها حبل نستقي به، وقال لنا: إن دنوتم من البئر خلقت لكم حبلا تستقون به(من)الماء، فإنه يكون مزيحا لعلتنا، ومتى لم ندن من البئر كنا قد أتينا من قبل نفوسنا لا من قبله تعالى. وكذلك لو قال السيد لعبده وهو بعيد منه: اشتر لي لحما من السوق، فقال:لا أتمكن من ذلك لأنه ليس معي ثمنه، فقال:إن دنوت أعطيتك ثمنه، فإنه يكون مزيحا لعلته، ومتى لم يدن لأخذ الثمن يكون قد أتي من قبل نفسه لا من قبل سيده.","27/1/3/31",""],[32,2,"وهذه حال ظهور الامام مع تمكيننا فيجب أن يكون عدم تمكيننا هو السبب في أن لم يظهر في هذه الأحوال لا عدمه، إذ كنا لو مكناه عليه السلام لوجد وظهر.","27/1/3/32",""],[33,2,"قلنا: هذا كلام من يظن أنه يجب علينا تمكينه إذا ظهر ولا يجب علينا ذلك في كل حال، ورضينا بالمثال الذي ذكره، لأنه تعالى لو أوجب علينا الاستقاء في الحال لوجب أن يكون الحبل حاصلا في الحال لأن به تزاح العلة، لكن إذا قال:متى دنوتم من البئر خلقت لكم الحبل إنما هو مكلف للدنو لا للاستقاء فيكفي القدرة على الدنو في هذه الحال، لأنه ليس بمكلف للاستقاء منها، فإذا دنا من البئر صار حينئذ مكلفا للاستقاء، فيجب عند ذلك أن يخلق له الحبل، فنظير ذلك أن لا يجب علينا في كل حال طاعة الإمام وتمكينه فلا يجب عند ذلك وجوده، فلما كانت طاعته واجبة في الحال ولم نقف على شرطه ولا وقت منتظر وجب أن يكون موجودا لتزاح العلة في التكليف ويحسن.","27/1/3/33",""],[34,2,"والجواب: عن مثال السيد مع غلامه مثل ذلك لأنه إنما كلفه الدنو منه لا الشراء، فإذا دنا منه وكلفه الشراء وجب عليه إعطاء الثمن. ولهذا قلنا: إن الله تعالى كلف من يأتي إلى يوم القيامة ولا يجب أن يكونوا موجودين مزاحي العلة لأنه لم يكلفهم الآن، فإذا أوجدهم وأزاح علتهم في التكليف بالقدرة والآلة ونصب الادلة حينئذ تناولهم التكليف، فسقط بذلك هذه المغالطة.","27/1/3/34",""],[35,2,"على أن الامام إذا كان مكلفا للقيام بالامر وتحمل أعباء الامامة كيف يجوز أن يكون معدوما وهل يصح تكليف المعدوم عند عاقل، وليس لتكليفه ذلك تعلق بتمكيننا أصلا، بل وجوب التمكين علينا فرع على تحمله على ما مضى القول فيه، وهذا واضح.","27/1/3/35",""],[36,2,"ثم يقال لهم: أليس النبي صلى الله عليه وآله اختفى في الشعب ثلاث سنين لم يصل إليه أحد، واختفى في الغار ثلاثة أيام ولم يجز قياسا على ذلك أن يعدمه الله تعالى تلك المدة مع بقاء التكليف على الخلق الذين بعثه لطفا لهم. ومتى قالوا: إنما اختفى بعدما دعا إلى نفسه وأظهر نبوته فلما أخافوه استتر. قلنا:وكذلك الإمام لم يستتر إلا وقد أظهر آباؤه موضعه وصفته، ودلوا عليه، ثم لما خاف عليه أبوه الحسن بن علي عليهم السلام أخفاه وستره، فالأمران إذا سواء، ثم يقال لهم: خبرونا لو علم الله من حال شخص أن من مصلحته أن يبعث الله إليه نبيا معينا يؤدي إليه مصالحه وعلم أنه لو بعثه لقتله هذا الشخص، ولو منع من قتله قهرا كان فيه مفسدة له أو لغيره، هل يحسن أن يكلف هذا الشخص ولا يبعث إليه ذلك النبي، أو لا يكلف.","27/1/3/36",""],[37,2,"فإن قالوا: لا يكلف. قلنا: وما المانع منه، وله طريق إلى معرفة مصالحه بأن يمكن النبي من الأداء إليه. وإن قلتم: يكلفه ولا يبعث إليه. قلنا: وكيف يجوز أن يكلفه ولم يفعل به ما هو لطف له مقدور.","27/1/3/37",""],[38,2,"فإن قالوا: أتي في ذلك من قبل نفسه. قلنا: هو لم يفعل شيئا وإنما علم أنه لا يمكنه، وبالعلم لا يحسن تكليفه مع ارتفاع اللطف، ولو جاز ذلك لجاز أن يكلف ما لا دليل عليه إذا علم أنه لا ينظر فيه، وذلك باطل، ولابد أن يقال: إنه يبعث إلى ذلك الشخص ويوجب عليه الانقياد له ليكون مزيحا لعلته، فإما أن يمنع منه بما لا ينافي التكليف، أو يجعله بحيث لا يتمكن من قتله، فيكون قد أتي من قبل نفسه في عدم الوصول إليه، وهذه حالنا مع الإمام في حال الغيبة سواء.","27/1/3/38",""],[39,2,"فإن قال: لابد أن يعلمه أن له مصلحة في بعثة هذا الشخص إليه على لسان غيره ليعلم أنه قد أتي من قبل نفسه. قلنا: وكذلك أعلمنا الله على لسان نبيه صلى الله عليه وآله والائمة من آبائه عليهم السلام موضعه، وأوجب علينا طاعته، فإذا لم يظهر لنا علمنا أنا أتينا من قبل نفوسنا فاستوى الأمران.","27/1/3/39",""],[1,3,"وأما الذي يدل على الاصل الثاني وهو أن من شأن الإمام أن يكون مقطوعا على عصمته، فهو أن العلة التي لأجلها احتجنا إلى الإمام ارتفاع العصمة، بدلالة أن الخلق متى كانوا معصومين لم يحتاجوا إلى إمام وإذا خلوا من كونهم معصومين احتاجوا إليه، علمنا عند ذلك أن علة الحاجة هي ارتفاع العصمة، كما نقوله في علة حاجة الفعل إلى فاعل أنها الحدوث، بدلالة أن ما يصح حدوثه يحتاج إلى فاعل في حدوثه، وما لا يصح حدوثه يستغني عن الفاعل، وحكمنا بذلك أن كل محدث يحتاج إلى محدث، فبمثل ذلك يجب الحكم بحاجة كل من ليس بمعصوم إلى إمام وإلا انتقضت العلة، فلو كان الإمام غير معصوم لكانت علة الحاجة فيه قائمة واحتاج إلى إمام آخر، والكلام في إمامه كالكلام فيه، فيؤدي إلى إيجاب أئمة لا نهاية لهم أو الانتهاء إلى معصوم وهو المراد. وهذه الطريقة قد أحكمناها في كتبنا فلا نطول بالاسئلة عليها لأن الغرض بهذا الكتاب غير ذلك، وفي هذا القدر كفاية.","27/1/4/1",""],[1,4,"وأما الاصل الثالث وهو أن الحق لا يخرج عن الامة فهو متفق عليه بيننا وبين خصومنا وإن اختلفنا في علة ذلك. لان عندنا أن الزمان لا يخلو من إمام معصوم لا يجوز عليه الغلط على ما قلناه، فإذا الحق لا يخرج عن الامة لكون المعصوم فيهم. وعند المخالف لقيام أدلة يذكرونها دلت على أن الإجماع حجة، فلا وجه للتشاغل بذلك. فإذا ثبتت هذه الأصول ثبت إمامة صاحب الزمان عليه السلام، لان كل من يقطع على ثبوت العصمة للإمام قطع على أنه الإمام، وليس فيهم من يقطع على عصمة الإمام ويخالف في إمامته إلا قوم دل الدليل على بطلان قولهم كالكيسانية والناووسية والواقفة، فإذا أفسدنا أقوال هؤلاء ثبت إمامته عليه السلام.","27/1/5/1",""],[1,5,"(أقول): وأما الذي يدل على فساد قول الكيسانية القائلين بإمامة محمد بن الحنفية فأشياء.","27/1/6/1",""],[2,5,"منها: أنه لو كان إماما مقطوعا على عصمته لوجب أن يكون منصوصا عليه نصا صريحا لأن العصمة لا تعلم إلا بالنص، وهم لا يدعون نصا صريحا (عليه) وإنما يتعلقون بأمور ضعيفة دخلت عليهم فيها شبهة لا تدل على النص، نحو إعطاء أمير المؤمنين عليه السلام إياه الراية يوم البصرة، وقوله له \"أنت ابني حقا\" مع كون الحسن والحسين عليهما السلام ابنيه وليس في ذلك دلالة على إمامته على وجه، وإنما يدل على فضيلته ومنزلته.","27/1/6/2",""],[3,5,"على أن الشيعة تروي أنه جرى بينه وبين علي بن الحسين عليهما السلام كلام في استحقاق الإمامة فتحاكما إلى الحجر فشهد الحجر لعلي بن الحسين عليهما السلام بالامامة، فكان ذلك معجزا له فسلم له الأمر وقال بإمامته.","27/1/6/3",""],[4,5,"1.والخبر بذلك مشهور عند الإمامية لأنهم رووا أن محمد بن الحنفية نازع علي بن الحسين عليهما السلام في الامامة وادعى أن الأمر أفضي إليه بعد أخيه الحسين عليه السلام، فناظره علي بن الحسين عليه السلام واحتج عليه بآي من القرآن كقوله: ﴿وَأُولُوا الأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ…﴾ وأن هذه الآية جرت في علي بن الحسين عليهما السلام وولده ثم قال له: أحاجك إلى الحجر الأسود، فقال له:كيف تحاجني إلى حجر لا يسمع ولا يجيب؟ فأعلمه أنه يحكم بينهما، فمضيا حتى انتهيا إلى الحجر، فقال علي بن الحسين عليه السلام لمحمد بن الحنفية:تقدم فكلمه. فتقدم إليه ووقف حياله وتكلم ثم أمسك. ثم تقدم علي بن الحسين عليه السلام فوضع يده عليه ثم قال:اللهم إني أسألك باسمك المكتوب في سرادق العظمة،ثم دعا بعد ذلك وقال:لما أنطقت هذا الحجر، ثم قال:أسألك بالذي جعل فيك مواثيق العباد والشهادة لمن وافاك لما أخبرت لمن الامامة والوصية.","27/1/6/4",""],[5,5,"فتزعزع الحجر حتى كاد أن يزول، ثم أنطقه الله تعالى، فقال:يا محمد،سلم الامامة لعلي بن الحسين. فرجع محمد عن منازعته وسلمها إلى علي بن الحسين عليهما السلام. ومنها تواتر الشيعة الامامية بالنص عليه من أبيه وجده وهي موجودة في كتبهم في الاخبار لا نطول بذكرها الكتاب.","27/1/6/5",""],[6,5,"ومنها الأخبار الواردة عن النبي صلى الله عليه وآله من جهة الخاصة والعامة على ما سنذكره فيما بعد بالنص على إمامة الاثني عشر، وكل من قال بإمامتهم قطع على وفاة محمد بن الحنفية وسياقة الامامة إلى صاحب الزمان عليه السلام.","27/1/6/6",""],[7,5,"ومنها انقراض هذه الفرقة فإنه لم يبق في الدنيا في وقتنا ولا قبله بزمان طويل قائل يقول به، ولو كان ذلك حقا لما جاز انقراضه.","27/1/6/7",""],[8,5,"فإن قيل: كيف يعلم انقراضهم وهلا جاز أن يكون في بعض البلاد البعيدة وجزائر البحر وأطراف الأرض أقوام يقولون بهذا القول كما يجوز أن يكون في أطراف الأرض من يقول بمذهب الحسن في أن مرتكب الكبيرة منافق فلا يمكن ادعاء انقراض هذه الفرقة وإنما كان يمكن العلم بذلك لو كان المسلمون فيهم قلة والعلماء محصورين فأما وقد انتشر الإسلام وكثر العلماء فمن أين يعلم ذلك؟ قلنا: هذا يؤدي إلى أن لا يمكن العلم بإجماع الامة على قول ولا مذهب بأن يقال:لعل في أطراف الارض من يخالف ذلك ويلزم أن يجوز أن يكون في أطراف الأرض من يقول:إن البرد لا ينقض الصوم وأنه يجوز للصائم أن يأكل إلى طلوع الشمس، لان الاول كان مذهب أبي طلحة الأنصاري، والثاني مذهب حذيفة والأعمش، وكذلك مسائل كثيرة من الفقه كان الخلف فيها(واقعا)بين الصحابة والتابعين، ثم زال الخلف فيما بعد، واجتمع أهل الأعصار على خلافه، فينبغي أن يشك في ذلك ولا نثق بالإجماع على مسألة سبق الخلاف فيها.","27/1/6/8",""],[9,5,"وهذا طعن من يقول إن الإجماع لا يمكن معرفته ولا التوصل إليه، والكلام في ذلك لا يختص هذه المسألة فلا وجه لايراده هنا. ثم إنا نعلم أن الأنصار طلبت الامرة ودفعهم المهاجرون عنها ثم رجعت الانصار إلى قول المهاجرين على قول المخالف، فلو أن قائلا قال:يجوز عقد الامامة لمن كان من الانصار لان الخلاف سبق فيه، ولعل في أطراف الارض من يقول به، فما كان يكون جوابهم فيه (فأي) شيء قالوه فهو جوابنا بعينه فلا نطول بذكره.","27/1/6/9",""],[10,5,"فإن قيل: إذا كان الإجماع عندكم إنما يكون حجة بكون المعصوم فيه، فمن أين تعلمون دخول قوله في جملة أقوال الأمة؟ (وهلا جاز أن يكون قوله منفردا عنهم فلا تثقون بالإجماع؟). قلنا: المعصوم إذا كان من جملة علماء الامة فلابد (من) أن يكون قوله موجودا في جملة أقوال العلماء، لأنه لا يجوز أن يكون منفردا مظهرا للكفر فإن ذلك لا يجوز عليه، فإذا لابد (من) أن يكون قوله في جملة الأقوال، وإن شككنا في أنه الإمام.","27/1/6/10",""],[11,5,"فإذا اعتبرنا أقوال الامة ووجدنا بعض العلماء يخالف فيه، فإن كنا نعرفه ونعرف مولده ومنشأه لم نعتد بقوله لعلمنا أنه ليس بإمام، وإن شككنا في نسبه لم تكن المسألة إجماعا. فعلى هذا أقوال العلماء من الامة اعتبرناها فلم نجد فيهم قائلا بهذا المذهب الذي هو مذهب الكيسانية أو الواقفة، وإن وجدنا فرضا واحدا أو اثنين فإنا نعلم منشأه ومولده فلا يعتد بقوله واعتبرنا أقوال الباقين الذين نقطع على كون المعصوم فيهم، فسقطت هذه الشبهة على هذا التحرير وبان وهنه.","27/1/6/11",""],[1,6,"فأما القائلون بإمامة جعفر بن محمد عليه السلام من الناووسية وأنه حي لم يمت وأنه المهدي فالكلام عليهم ظاهر، لأنا نعلم موت جعفر بن محمد عليه السلام كما نعلم موت أبيه وجده عليهما السلام، وقتل علي عليه السلام، وموت النبي صلى الله عليه وآله وسلم فلو جاز الخلاف فيه لجاز الخلاف في جميع ذلك، ويؤدي إلى قول الغلاة والمفوضة الذين جحدوا قتل علي والحسين عليهما السلام وذلك سفسطة. وسنشبع الكلام في ذلك عند الكلام على الواقفة (والناووسية) إن شاء الله تعالى.","27/1/7/1",""],[1,7,"وأما الذي يدل على فساد مذهب الواقفة الذين وقفوا في إمامة أبي الحسن موسى عليه السلام وقالوا:إنه المهدي، فقولهم باطل بما ظهر من موته عليه السلام، واشتهر واستفاض، كما اشتهر موت أبيه وجده ومن تقدم من آبائه عليهم السلام. ولو شككنا لم ننفصل من الناووسية والكيسانية والغلاة والمفوضة الذين خالفوا في موت من تقدم من آبائه عليهم السلام. على أن موته اشتهر ما لم يشتهر موت أحد من آبائه عليهم السلام، لأنه أظهر وأحضر والقضاة والشهود. ونودي عليه ببغداد على الجسر وقيل: \"هذا الذي تزعم الرافضة أنه حي لا يموت مات حتف أنفه\" وما جرى هذا المجرى لا يمكن الخلاف فيه.","27/1/8/1",""],[1,8,"فروى يونس بن عبدالرحمن قال: حضر الحسين بن علي الرواسي جنازة أبي إبراهيم عليه السلام. فما وضع على شفير القبر، إذا رسول من سندي بن شاهك قد أتى أبا المض خليفته- وكان مع الجنازة-أن أكشف وجهه للناس قبل أن تدفنه حتى يروه صحيحا لم يحدث به حدث. قال: وكشف عن وجه مولاي حتى رأيته وعرفته، ثم غطي وجهه وأدخل قبره صلى الله عليه.","27/1/9/1",""],[2,8,"وروى محمد بن عيسى بن عبيد العبيدي قال: أخبرتني رحيم أم ولد الحسين بن علي بن يقطين- وكانت امرأة حرة فاضلة قد حجت نيفا وعشرين حجة- عن سعيد مولى أبي الحسن عليه السلام-وكان يخدمه في الحبس ويختلف في حوائجه-أنه حضره حين مات كما يموت الناس من قوة إلى ضعف إلى أن قضى عليه السلام.","27/1/9/2",""],[3,8,"وروى محمد بن خالد البرقي، عن محمد بن عباد المهلبي قال:لما حبس هارون الرشيد أبا إبراهيم موسى عليه السلام وأظهر الدلائل والمعجزات وهو في الحبس تحير الرشيد، فدعا يحيى بن خالد البرمكي فقال له:يا أبا علي أما ترى ما نحن فيه من هذه العجائب، ألا تدبر في أمر هذا الرجل تدبيرا يريحنا من غمه؟ فقال له يحيى بن خالد البرمكي:الذي أراه لك يا أمير المؤمنين أن تمنن عليه وتصل رحمه، فقد- والله- أفسد علينا قلوب شيعتنا. وكان يحيى يتولاه، وهارون لا يعلم ذلك. فقال هارون: انطلق إليه وأطلق عنه الحديد، وأبلغه عني السلام، وقل له: يقول لك ابن عمك: إنه قد سبق مني فيك يمين أني لا أخليك حتى تقر لي بالاساء‌ة، وتسألني العفو عما سلف منك، وليس عليك في إقرارك عار، ولا في مسألتك إياي منقصة. وهذا يحيى بن خالد (هو) ثقتي ووزيري، وصاحب أمري، فسله بقدر ما أخرج من يميني وانصرف راشد.","27/1/9/3",""],[4,8,"قال محمد بن عباد: فأخبرني موسى بن يحيى بن خالد: أن أبا إبراهيم عليه السلام قال ليحيى: يا أبا علي أنا ميت، وإنما بقي من أجلي أسبوع، أكتم موتي وائتني يوم الجمعة عند الزوال، وصل علي أنت وأوليائي فرادى، وانظر إذا سار هذا الطاغية إلى الرقة، وعاد إلى العراق لا يراك ولا تراه لنفسك، فإني رأيت في نجمك ونجم ولدك ونجمه أنه يأتي عليكم فاحذروه. ثم قال: يا أبا علي أبلغه عني:يقول لك موسى بن جعفر: رسولي يأتيك يوم الجمعة فيخبرك بما ترى، و ستعلم غدا إذا جاثيتك بين يدي الله من الظالم والمعتدي على صاحبه، والسلام. فخرج يحيى من عنده، واحمرت عيناه من البكاء حتى دخل على هارون فأخبره بقصته وما رد عليه، فقال (له) هارون: إن لم يدع النبوة بعد أيام فما أحسن حالنا. فلما كان يوم الجمعة توفي أبو إبراهيم عليه السلام، وقد خرج هارون إلى المدائن قبل ذلك، فأخرج إلى الناس حتى نظروا إليه، ثم دفن عليه السلام ورجع الناس، فافترقوا فرقتين: فرقة تقول: مات، وفرقة تقول: لم يمت.","27/1/9/4",""],[5,8,"وأخبرنا أحمد بن عبدون سماعا وقراء‌ة عليه قال: أخبرنا أبو الفرج علي بن الحسين الأصبهاني، قال: حدثني أحمد بن عبيدالله بن عمار قال: حدثنا علي بن محمد النوفلي، عن أبيه قال الأصبهاني: وحدثني أحمد بن محمد بن سعيد قال: حدثني يحيى بن الحسن العلوي، وحدثني غيرهما ببعض قصـته، وجمعت ذلك بعضه إلى بعض، قـالوا: كان السبب في أخـذ موسى بن جعفر عليهما السلام أن الرشيد جعل ابنه في حجر جعفر بن محمد بن الاشعث، فحسده يحيى بن خالد البرمكي وقال: إن أفضت الخلافة إليه زالت دولتي ودولة ولدي. فاحتال على جعفر بن محمد-وكان يقول بالامامة-حتى داخله وأنس إليه. وكان يكثر غشيانه في منزله، فيقف على أمره، فيرفعه إلى الرشيد ويزيد عليه بما يقدح في قلبه. ثم قال يوما لبعض ثقاته:تعرفون لي رجلا من آل أبي طالب ليس بواسع الحال يعرفني ما أحتاج (إليه)؟ فدل على علي بن إسماعيل بن جعفر بن محمد، فحمل إليه (يحيى بن خالد مالا). وكان موسى عليه السلام يأنس إليه ويصله، وربما أفضى إليه بأسراره كلها. فكتب ليشخص به، فأحسن موسى عليه السلام بذلك فدعاه فقال: إلى أين يا بن أخي؟ قال: إلى بغداد. قال: ما تصنع؟ قال: علي دين أنا مملق. قال: فانا أقضي دينك وأفعل بك واصنع. فلم يلتفت إلى ذلك. فقال له: أنظر يا بن أخي، لا تؤتم أولادي. وأمر له بثلثمائة دينار وأربعة آلاف درهم. فلما قام من بين يديه، قال أبوالحسن موسى عليه السلام لمن حضره:والله ليسعين في دمي، ويؤتمن أولادي. فقالوا له: جعلنـا الله فداك، فأنت تعلم هـذا من حـاله وتعطيه وتصله؟!فقـال لهم:نعم، حدثني أبي، عن آبائه، عن رسول الله صلى الله عليه وآله وسلم:\"إن الرحم إذا قطعت فوصلت قطعها الله.\" فخرج علي بن إسماعيل حتى أتى إلى يحيى بن خالد فتعرف منه خبر موسى بن جعفر عليه السلام ورفعه إلى الرشيد، وزاد عليه وقال له:إن الاموال تحمل إليه من المشرق والمغرب، وإن له بيوت أموال، وإنه اشترى ضيعة بثلاثين ألف دينار فسماها \"اليسيرة\" وقال (له) صاحبها وقد أحضر المال. لا آخذ هذا النقد، ولا آخذ إلا نقد كذ. فأمر بذلك المال فرد وأعطاه ثلاثين ألف دينار من النقد الذي سأل بعينه، فرفع ذلك كله إلى الرشيد، فأمر له بمائتي ألف درهم يسبب له على بعض النواحي فاختار كور المشرق، ومضت رسله لتقبض المال، ودخل هو في بعض الأيام إلى الخلاء فزحر زحرة خرجت منها حشوته (كله) فسقط، وجهدوا في ردها فلم يقدروا، فوقع لما به وجاء‌ه المال وهو ينزع فقال: ما أصنع به وأنا في الموت. وحج الرشيد في تلك السنة فبدأ بقبر النبي صلى الله عليه وآله فقال: يا رسول الله إني أعتذر إليك من شيء أريد أن أفعله، أريد أن أحبس موسى بن جعفر فإنه يريد التشتيت بأمّتك وسفك دمائها. ثم أمر به فأخذ من المسجد فادخل إليه فقيده، وأخرج من داره بغلان عليهما قبتان مغطاتان هو عليه السلام في إحداهما، ووجه مع كل واحدة منهما خيلا فأخذ بواحدة على طريق البصــرة، والأخرى على طريق الكوفة، ليعمي على الناس أمره، وكان في التي مضت إلى البصرة.وأمر الرسول أن يسلمه إلى عيسى بن جعفر بن المنصور، وكان على البصرة حينئذ فمضى به، فحبسه عنده سنة. ثم كتب إلى الرشيد أن خذه مني وسلمه إلى من شئت وإلا خليت سبيله، فقد اجتهدت بأن أجد عليه حجة، فما أقدر على ذلك حتى أني لاتسمع عليه إذا دعا لعله يدعو علي أو عليك، فما أسمعه يدعو إلا لنفسه يسأل الرحمة والمغفرة. فوجه من تسلمه منه، وحبسه عند الفضل بن الربيع ببغداد فبقي عنده مدة طويلة وأراد الرشيد على شيء من أمره فأبى. فكتب بتسليمه إلى الفضل بن يحيى فتسلمه منه وأراد ذلك منه فلم يفعل. وبلغه أنه عنده في رفاهية وهو حينئذ بالرقة. فأنفذ مسرور الخادم إلى بغداد على البريد، وأمره أن يدخل من فوره إلى موسى بن جعفر عليه السلام فيعرف خبره، فإن كان الامر على ما بلغه أوصل كتابا منه إلى العباس بن محمد وأمره بامتثاله، وأوصل كتابا منه آخر إلى السندي بن شاهك يأمره بطاعة العباس. فقدم مسرور فنزل دار الفضل بن يحيى لا يدري أحد ما يريد، ثم دخل على موسى بن جعفر عليه السلام فوجده على ما بلغ الرشيد، فمضى من فوره إلى العباس بن محمد والسندي، فأوصل الكتابين إليهما. فلم يلبث الناس أن خرج الرسول يركض إلى الفضل بن يحيى، فركب معه وخرج مشدوهاً دهشاً، حتى دخل (على) العباس، فدعا بسياط وعقابين. فوجه ذلك إلى السندي، وأمر بالفضل فجرد ثم ضربه مائة سوط، وخرج متغير اللون خلاف ما دخل، فاذهبت نخوته، فجعل يسلم على الناس يمينا وشمالا. وكتب مسرور بالخبر إلى الرشيد، فأمر بتسليم موسى عليه السلام إلى السندي بن شاهك وجلس مجلسا حافلا، وقال: أيها الناس إن الفضل بن يحيى قد عصاني وخالف طاعتي ورأيت أن ألعنه فالعنوه. فلعنه الناس من كل ناحية حتى ارتج البيت والدار بلعنه. وبلغ يحيى بن خالد فركب إلى الرشيد، ودخل من غير الباب الذي يدخل الناس منه حتى جاء‌ه من خلفه وهو لا يشعر، ثم قال له: التفت إلي يا أمير المؤمنين. فأصغى إليه فزعا فقال له: إن الفضل حدث، وأنا أكفيك ما تريد. فانطلق وجهه وسر، وأقبل على الناس فقال: إن الفضل كان عصاني في شيء فلعنته، وقد تاب وأناب إلى طاعتي فتولوه. فقالوا له:نحن أولياء من واليت وأعداء من عاديت وقد توليناه. ثم خرج يحيى بن خالد بنفسه على البريد حتى أتى بغداد، فماج الناس وأرجفوا بكل شيء. فأظهر أنه ورد لتعديل السواد والنظر في أمر العمال، وتشاغل ببعض ذلك ودعا السندي فأمره فيه بأمره، فامتثله. وسأل موسى عليه السلام السندي عند وفاته أن يحضره مولى له ينزل عند دار العباس بن محمد في أصحاب القصب ليغسله، ففعل ذلك. قال: سألته أن يأذن لي أن أكفنه فأبى وقال: إنا أهل بيت مهور نسائنا وحج صرورتنا وأكفان موتانا من طهرة أموالنا، وعندي كفني. فلما مات أدخل عليه الفقهاء ووجوه أهل بغداد وفيهم: الهيثم بن عدي وغيره، فنظروا إليه لا أثر به، وشهدوا على ذلك، وأخرج فوضع على الجسر ببغداد ونودي: هذا موسى بن جعفر قد مات فانظروا إليه. فجعل الناس يتفرسون في وجهه وهو ميت. قال: وحدثني رجل من بعض الطالبيين أنه نودي عليه: هذا موسى بن جعفر الذي تزعم الرافضة أنه لا يموت فانظروا إليه. فنظروا إليه. قالوا: وحمل فدفن في مقابر قريش، فوقع قبره إلى جانب رجل من النوفليين يقال له عيسى بن عبد الله.","27/1/9/5",""],[6,8,"وروى محمد بن يعقوب عن علي بن إبراهيم، عن محمد بن عيسى بن عبيد، عن الحسن بن محمد بن بشار قال حدثني شيخ من أهل قطيعة الربيع من العامة ممن كان يقبل قوله، قال:جمعنا السندي بن شاهك ثمانين رجلا من الوجوه المنسوبين إلى الخير فأدخلنا على موسى بن جعفر عليه السلام، وقال لنا السندي:يا هؤلاء انظروا إلى هذا الرجل هل حدث به حدث؟ فإن أمير المؤمنين لم يرد به سوء، وإنما ننتظر به أن يقدم ليناظره وهو صحيح موسع عليه في جميع أموره فسلوه وليس لنا هم إلا النظر إلى الرجل في فضله وسمته. فقال موسى بن جعفر عليه السلام:أما ما ذكره من التوسعة وما أشبهها فهو على ما ذكر، غير أني أخبركم أيها النفر إني قد سقيت السم في سبع تمرات وأنا غدا أخضر وبعد غد أموت. فنظرت إلى السندي بن شاهك يضطرب ويرتعد مثل السعفة. فموته عليه السلام أشهر من أن يحتاج إلى ذكر الرواية به، لأن المخالف في ذلك يدفع الضرورات، والشك في ذلك يؤدي إلى الشك في موت كل واحد من آبائه وغيرهم فلا يوثق بموت أحد. على أن المشهور عنه عليه السلام أنه وصى إلى ابنه علي بن موسى عليه السلام وأسند إليه أمره بعد موته، والأخبار بذلك أكثر من أن تحصى، نذكر منها طرفا ولو كان حيا باقيا لما احتاج إليه.","27/1/9/6",""],[1,9,"فمن ذلك ما رواه محمد بن يعقوب الكليني، عن محمد بن الحسن، عن سهل بن زياد، عن محمد بن علي وعبيد الله بن المرزبان، عن ابن سنان قال:دخلت على أبي الحسن موسى عليه السلام-من قبل أن يقدم العراق بسنة-وعلي إبنه جالس بين يديه، فنظر إلي وقال: يا محمد (أما إنه) سيكون في هذه السنة حركة فلا تجزع لذلك. قال: قلت: وما يكون جعلني الله فداك فقد أقلقتني؟ قال: أصير إلى هذه الطاغية أما إنه لا يبدأني منه سوء ومن الذي يكون بعده. قال: قلت: وما يكون جعلني الله فداك؟ قال: يضل الله الظالمين ويفعل الله ما يشاء. قال قلت: وما ذلك جعلني الله فداك؟ قال: من ظلم ابني هذا حقه وجحده إمامته من بعدي كان كمن ظلم علي بن أبي طالب عليه السلام إمامته و جحده حقه بعد رسول الله صلى الله عليه وآله وسلم. قال:قلت:والله لئن مد الله لي في العمر لاسلمن له حقه ولا قرن بإمامته. قال: صدقت يا محمد يمد الله في عمرك وتسلم له حقه عليه السلام وتقر له بإمامته وإمامة من يكون بعده. قال: قلت: ومن ذاك؟ قال: ابنه محمد. قال: قلت: له الرضا والتسليم.","27/1/10/1",""],[2,9,"عنه، عن أحمد بن مهران، عن محمد بن علي، عن محمد بن سنان وإسماعيل بن عباد القصري جميعا، عن داود الرقي قال:قلت لابي إبراهيم عليه السلام:جعلت فداك إني قد كبر سني فخذ بيدي(وانقذني)من النار،(من صاحبنا بعدك)؟ فأشار إلى إبنه أبي الحسن عليه السلام فقال:هذا صاحبكم من بعدي.","27/1/10/2",""],[3,9,"عنه، عن الحسين بن محمد، عن معلى بن محمد، عن أحمد بن محمد بن عبدالله، عن الحسن، عن ابن أبي عمير، عن محمد بن إسحاق بن عمار قال:قلت لابي الحسن الاول عليه السلام:ألا تدلني على من آخذ منه ديني؟ فقال:هذا ابني علي. إن أبي أخذ بيدي فأدخلني إلى قبر رسول الله صلى الله عليه وآله وسلم وقال:يا بني إن الله قال:﴿إِنِّي جَاعِلٌ فِي الأَرْضِ خَلِيفَةً﴾. وإن الله عز وجل إذا قال قولا وفى به.","27/1/10/3",""],[4,9,"عنه، عن محمد بن يحيى، عن أحمد بن محمد بن عيسى، عن الحسن بن محبوب، عن الحسين بن نعيم الصحاف قال: كنت أنا وهشام بن الحكم وعلي بن يقطين ببغداد، فقال علي بن يقطين:كنت عند العبد الصالح عليه السلام (جالسا فدخل عليه إبنه علي) فقال لي: يا علي بن يقطين هذا علي سيد ولدي، أما إني (قد) نحلته كنيتي. فضرب هشام براحته جبهته، ثم قال:ويحك كيف قلت؟ فقال علي بن يقطين:سمعته والله منه كما قلت.فقال هشام: إن الأمر (والله) فيه من بعده.","27/1/10/4",""],[5,9,"عنه، عن عدة من أصحابنا، عن أحمد بن محمد بن عيسى، عن معاوية بن حكيم، عن نعيم القابوسي، عن أبي الحسن موسى عليه السلام (أنه) قال:ابني علي أكبر ولدي وآثرهم عندي وأحبهم إلي وهو ينظر معي في الجفر ولم ينظر فيه إلا نبي أو وصي نبي.","27/1/10/5",""],[6,9,"عنه، عن أحمد بن مهران، عن محمد بن علي، عن محمد بن سنان وعلي بن الحكم جميعا، عن الحسين بن المختار قال: خرجت إلينا ألواح من أبي الحسن عليه السلام- وهو في الحبس-:عهدي إلى أكبر ولدي أن يفعل كذا وأن يفعل كذا، وفلان لا تنله شيئا حتى ألقاك أو يقضي الله علي الموت.","27/1/10/6",""],[7,9,"عنه، عن أحمد بن مهران، عن محمد بن علي، عن زياد بن مروان القندي- (وكان من الواقفة) قال: دخلت على أبي إبراهيم عليه السلام وعنده أبو الحسن إبنه فقال لي:يا زياد هذا إبنى علي، أن كتابه كتابي، وكلامه كلامي، ورسوله رسولي، وما قال فالقول قوله.","27/1/10/7",""],[8,9,"عنه، عن أحمد بن مهران، عن محمد بن علي، عن محمد بن الفضل، عن المخزومي- وكانت أمه من ولد جعفر بن أبي طالب- قال بعث إلينا أبوالحسن موسى عليه السلام فجمعنا ثم قال(لنا):أتدرون لم جمعتكم؟ فقلنا: لا. قال: اشهدوا أن ابني هذا وصيي والقيم بأمري وخليفتي من بعدي. من كان له عندي دين فليأخذه من ابني هذا، ومن كانت له عندي عدة فليتنجزه منه،ومن لم يكن له بد من لقائي فلا يلقني إلا بكتابه.","27/1/10/8",""],[9,9,"عنه، عن أحمد بن مهران، عن محمد بن علي، عن أبي علي الخزاز، عن داود بن سليمان قال:قلت لابي إبراهيم عليه السلام: إني أخاف أن يحدث حدث ولا ألقاك فأخبرني عن الامام بعدك؟ فقال:ابني فلان -يعني أبا الحسن عليه السلام.","27/1/10/9",""],[10,9,"وبهذا الاسناد، عن ابن مهران، عن محمد بن علي، عن سعيد بن أبي الجهم عن نصر بن قابوس قال:قلت لابي إبراهيم عليه السلام:إني سألت أباك عليه السلام من الذي يكون بعدك؟ فأخبرني أنك أنت هو، فلما توفي أبو عبدالله عليه السلام ذهب الناس يمينا وشمالا وقلت بك أنا وأصحابي. فأخبرني من الذي يكون من بعدك من ولدك؟ قال: إبني فلان.","27/1/10/10",""],[11,9,"عنه، عن أحمد، عن محمد بن علي، عن الضحاك بن الاشعث، عن داود بن زربي قال:جئت إلى أبي إبراهيم عليه السلام بمال (قال): فأخذ بعضه وترك بعضه، فقلت:أصلحك الله لأي شيء تركته عندي؟ فقال: إن صاحب هذا الأمر يطلبه منك. فلما جاء نعيه بعث إليّأبو الحسن الرضا عليه السلام، فسألني ذلك المال، فدفعته إليه.","27/1/10/11",""],[12,9,"عنه، عن أحمد بن مهران، عن محمد بن علي، عن علي بن الحكم، عن عبد الله بن إبراهيم بن علي بن عبد الله بن جعفر بن أبي طالب، عن يزيد بن سليط في حديث طويل عن أبي إبراهيم عليه السلام أنه قال في السنة التي قبض عليه السلام فيها: إني أؤخذ في هذه السنة، والأمر (هو) إلى إبني علي سمي علي. فأما علي الاول فعلي بن أبي طالب وأما (علي) الآخر فعلي بن الحسين عليهما السلام، أعطي فهم الاول وحلمه ونصره ووده وذمته (ومحنته) ومحنة الآخر، وصبره على ما يكره…تمام الخبر.","27/1/10/12",""],[13,9,"وروى، أبو الحسين محمد بن جعفر الاسدي، عن سعد بن عبد الله، عن جماعة من أصحابنا منهم محمد بن الحسين بن أبي الخطاب والحسن بن موسى الخشاب ومحمد بن عيسى بن عبيد، عن محمد بن سنان عن الحسن بن الحسن-في حديث له- قال: قلت لأبي الحسن موسى عليه السلام: أسألك؟ فقال: سل إمامك. فقلت:من تعني؟ فإني لا أعرف إماما غيرك. قال: هو علي إبني قد نحلته كنيتي. قلت: سيدي أنقذني من النار، فإن أبا عبد الله عليه السلام قال:إنك أنت القائم بهذا الأمر! قال: أو لم أكن قائما؟ ثم قال: يا حسن، ما من إمام يكون قائما في أمة إلا وهو قائمهم، فإذا مضى عنهم فالذي يليه هو القائم. الحجة حتى يغيب عنهم، فكلنا قائم. فاصرف جميع ما كنت تعاملني به إلى إبني علي. (والله) والله ما أنا فعلت ذاك به، بل الله فعل به ذاك.","27/1/10/13",""],[14,9,"وروى أحمد بن إدريس، عن علي بن محمد بن قتيبة، عن الفضل بن شاذان النيشابوري، عن محمد بن سنان وصفوان بن يحيى وعثمان بن عيسى، عن موسى بن بكر قال:كنت عند أبي إبراهيم عليه السلام فقال لي:إن جعفرا عليه السلام كان يقول: سعد امرؤ لم يمت حتى يرى خلفه من نفسه، ثم أومأ بيده إلى إبنه علي فقال:هذا وقد أراني الله خلفي من نفسي.","27/1/10/14",""],[15,9,"عنه، عن سعد بن عبد الله، عن محمد بن عيسى بن عبيد، عن علي بن الحكم وعلي بن الحسن بن نافع، عن هارون بن خارجة قال: قال لي هارون بن سعد العجلي: قد مات إسماعيل الذي كنتم تمدون إليه أعناقكم، وجعفر شيخ كبير يموت غدا أو بعد غد فتبقون بلا إمام. فلم أدر ما أقول، فأخبرت أبا عبد الله عليه السلام بمقالته فقال: هيهات هيهات! أبى الله، والله،أن ينقطع هذا الأمر حتى ينقطع الليل والنهار. فإذا رأيته فقل له: هذا موسى بن جعفر يكبر ونزوجه، ويولد له فيكون خلفا إن شاء الله تعالى.","27/1/10/15",""],[16,9,"وفي خبر آخر قال أبو عبد الله عليه السلام في حديث طويل: يظهر صاحبنا وهو من صلب هذا، وأومأ بيده إلى موسى بن جعفر عليه السلام، فيملأها عدلا كما ملئت جورا وظلما وتصفو له الدنيا.","27/1/10/16",""],[17,9,"وروى أيوب بن نوح عن الحسن بن علي بن فضال قال سمعت علي بن جعفر يقول: كنت عند أخي موسى بن جعفر عليه السلام، كان والله حجة الله في الأرض بعد أبي صلى الله عليه وآله وسلم، إذ طلع ابنه علي فقال لي: يا علي، هذا صاحبك، وهو مني بمنزلتي من أبي. فثبتك الله على دينه. فبكيت وقلت في نفسي: نعى والله إلى نفسه. فقـال: يا علي، لا بد من أن تمضي مقادير الله في، ولي برسول الله صلى الله عليه وآله وسلم أسوة وبأمير المؤمنين وفاطمة والحسن والحسين عليه السلام. وكان هذا قبل أن يحمله هارون الرشيد في المرة الثانية بثلاثة أيام تمام الخبر. والأخبار في هذا المعنى أكثر من أن تحصى وهي موجودة في كتب الإمامية معروفة ومشهورة من أرادها وقف عليها من هناك وفي هذا القدر هاهنا كفاية إن شاء الله تعالى.","27/1/10/17",""],[1,10,"فإن قيل كيف تعولون على هذه الأخبار وتدعون العلم بموته والواقفة تروي أخبارا كثيرة تتضمن أنه لم يمت وأنه القائم المشار إليه موجودة في كتبهم وكتب أصحابكم فكيف تجمعون بينها وكيف تدعون العلم بموته مع ذلك. قلنا: لم نذكر هذه الأخبار إلا على جهة الاستظهار والتبرع لا لأنا احتجنا إليها في العلم بموته لأن العلم بموته حاصل لا يشك فيه كالعلم بموت آبائه عليه السلام والمشكك في موته كالمشكك في موتهم وموت كل من علمنا بموته. وإنما استظهرنا بإيراد هذه الأخبار تأكيدا لهذا العلم كما نروي أخبارا كثيرة فيما نعلم بالعقل والشرع وظاهر القرآن والإجماع وغير ذلك فنذكر في ذلك أخبارا على وجه التأكيد. فأما ما ترويه الواقفة فكلها أخبار آحاد لا يعضدها حجة ولا يمكن ادعاء العلم بصحتها ومع هذا فالرواة لها مطعون عليهم لا يوثق بقولهم ورواياتهم وبعد هذا كله فهي متأولة. ونحن نذكر جملا مما رووه ونبين القول فيها فمن ذلك أخبار ذكرها أبو محمد علي بن أحمد العلوي الموسوي في كتابه في نصرة الواقفة.","27/1/11/1",""],[2,10,"قال حدثني محمد بن بشر قال حدثني الحسن بن سماعة عن أبان بن عثمان عن الفضيل بن يسار قال سمعت أبا عبد الله عليه السلام يقول: لا ينسجني والقائم أب.","27/1/11/2",""],[3,10,"قال الموسوي وأخبرني علي بن خلف الأنماطي قال حدثنا عبد الله بن وضاح عن يزيد الصائغ قال لما ولد لأبي عبد الله عليه السلام أبو الحسن عليه السلام عملت له أوضاحا وأهديتها إليه،فلما أتيت أبا عبد الله عليه السلام بها قال لي: يا يزيد أهديتها والله لقائم آل محمد صلى الله عليه وآله وسلم.","27/1/11/3",""],[4,10,"قال الموسوي وحدثني أحمد بن الحسن الميثمي عن أبيه عن أبي سعيد المدائني قال سمعت أبا جعفر عليه السلام يقول: إن الله استنقذ بني إسرائيل من فرعونها بموسى بن عمران وإن الله مستنقذ هذه الأمة من فرعونها بسميه.","27/1/11/4",""],[5,10,"قال وحدثني حنان بن سدير قال كان أبي جالسا وعنده عبد الله بن سليمان الصيرفي وأبو المراهف وسالم الأشل فقال عبد الله بن سليمان لأبي يا أبا الفضل: أعلمت أنه ولد لأبي عبد الله عليه السلام غلام فسماه فلانا،يسميه باسمه.فقال سالم: إن هذا لحق. فقال عبد الله: نعم. فقال سالم: والله لأن يكون حقا أحب إلي من أن انقلب إلى أهلي بخمسمائة دينار وإني محتاج إلى خمسة دراهم أعود بها على نفسي وعيالي.فقال له عبد الله بن سليمان: ولم ذاك؟قال: بلغني في الحديث أن الله عرض سيرة قائم آل محمد على موسى بن عمران فقال: اللهم اجعله من بني إسرائيل. فقال له: ليس إلى ذلك سبيل. فقال: اللهم اجعلني من أنصاره. فقيل له: ليس إلى ذلك سبيل. فقال: اللهم اجعله سميي. فقيل له: أعطيت ذلك.","27/1/11/5",""],[6,10,"قال: وروى زيد الشحام وغيره قال: سمعت سالما يقول: سمعت أبا جعفر عليه السلام يقول: إن الله تعالى عرض سيرة قائم آل محمد على موسى بن عمران… وذكر الحديث،","27/1/11/6",""],[7,10,"قال: وحدثني بحر بن زياد الطحان عن محمد بن مروان عن أبي جعفر عليه السلام قال: قال رجل: جعلت فداك، إنهم يروون أن أمير المؤمنين عليه السلام قال بالكوفة على المنبر: لو لم يبق من الدنيـا إلا يوم لطوّل الله ذلك اليوم حتى يبعث الله رجلاً مني يملأها قسطاً وعدلاً كما ملئت ظلما وجورا. فقال أبو جعفر عليه السلام: نعم. قال: فأنت هو؟ فقال: لا،ذاك سمي فالق البحر.","27/1/11/7",""],[8,10,"قال وحدثني أبو محمد الصيرفي عن الحسين بن سليمان عن ضريس الكناسي عن أبي خالد الكابلي قال سمعت علي بن الحسين عليه السلام وهو يقول: إن قارون كان يلبس الثياب الحمر وإن فرعون كان يلبس السود ويرخي الشعور فبعث الله عليهم موسى عليه السلام وإن بني فلان لبسوا السواد وأرخوا الشعور وإن الله تعالى مهلكهم بسميه.","27/1/11/8",""],[9,10,"قال: وبهذا الإسناد،قال: تذاكرنا عنده القائم فقال: اسمه اسم لحديدة الحلاق.","27/1/11/9",""],[10,10,"قال: وروى جعفر بن سماعة عن محمد بن الحسن عن أبيه الحسن بن هارون قال: قال أبو عبد الله عليه السلام: ابني ه��ا، يعني أبا الحسن عليه السلام، هو القائم وهو من المحتوم وهو الذي يملأها قسطاً وعدلاًكما ملئت ظلما وجورا.","27/1/11/10",""],[11,10,"قال وحدثني عبد الله بن سلام عن عبد الله بن سنان قال سمعت أبا عبد الله عليه السلام يقول: من المحتوم أن ابني هذا قائم هذه الأمة وصاحب السيف،وأشار بيده إلى أبي الحسن عليه السلام.","27/1/11/11",""],[12,10,"قال وأخبرني علي بن رزق الله عن أبي الوليد الطرائفي قال كنت ليلة عند أبي عبد الله عليه السلام إذ نادى غلامه فقال: انطلق فادع لي سيد ولدي. فقال له الغلام: من هو؟فقال: فلان. يعني أبا الحسن عليه السلام. قال فلم ألبث حتى جاء بقميص بغير رداء…إلى أن قال: ثم ضرب بيده على عضدي وقال: يا أبا الوليد كأني بالراية السوداء صاحبه الرقعة الخضراء تخفق فوق رأس هذا الجالس ومعه أصحابه يهدون جبال الحديد هدا لا يأتون على شيء إلا هدوه. قلت: جعلت فداك، هذا؟قال: نعم هذا، يا أبا الوليد، يملأها قسطاً وعدلاًكما ملئت ظلما وعدوانا. يسير في أهل القبلة بسيرة علي بن أبي طالب عليه السلام. يقتل أعداء الله حتى يرضي الله. قلت: جعلت فداك، هذا؟قال: هذا. ثم قال: فاتبعه وأطعه وصدقه وأعطه الرضا من نفسك فإنك ستدركه إن شاء الله.","27/1/11/12",""],[13,10,"قال وحدثني عبد الله بن جميل عن صالح بن أبي سعيد القماط قال حدثني عبد الله بن غالب قال أنشدت أبا عبد الله عليه السلام هذه القصيدة: فإن تك أنت المرتجى للذي نرى فتلك التي من ذي العلى فيك نطلب. فقال: ليس أنا صاحب هذه الصفة ولكن هذا صاحبها،وأشار بيده إلى أبي الحسن عليه السلام.","27/1/11/13",""],[14,10,"قال وحدثني أبو عبد الله لذاذ عن صارم بن علوان الجوخي قال دخلت أنا والمفضل ويونس بن ظبيان والفيض بن المختار والقاسم شريك المفضل على أبي عبد الله عليه السلام وعنده إسماعيل ابنه،فقال الفيض: جعلت فداك،نتقبل من هؤلاء الضياع فنقبلها بأكثر مما نتقبلها. فقال: لا بأس به. فقال له إسماعيل ابنه: لم تفهم يا أبة!! فقال أبو عبد الله عليه السلام: أنا لم أفهم! أقول لك الزمني فلا تفعل. فقام إسماعيل مغضبا،فقال الفيض: إنا نرى أنه صاحب هذا الأمر من بعدك. فقال أبو عبد الله عليه السلام: لا والله ما هو كذلك. ثم قال: هذا ألزم لي من ذلك، وأشار إلى أبي الحسن عليه السلام وهو نائم،فضمه إليه فنام على صدره. فلما انتبه أخذ أبو عبد الله عليه السلام بساعده ثم قال: هذا والله ابني حقا هو والله يملأها قسطاً وعدلاًكما ملئت ظلما وجورا. فقال له قاسم الثانية: هذا جعلت فداك؟قال: إي والله ابني هذا لا يخرج من الدنيا حتى يملأ الله الأرض به قسطاً وعدلاً كما ملئت ظلما وجورا،ثلاث أيمان يحلف بها.","27/1/11/14",""],[15,10,"قال وحدثني حنان بن سدير عن إسماعيل البزاز قال قال أبو عبد الله عليه السلام: إن صاحب هذا الأمر يلي الوصية وهو ابن عشرين سنة. فقال إسماعيل: فو الله ما وليها أحد قط كان أحدث منه وإنه لفي السن الذي قال أبو عبد الله عليه السلام.","27/1/11/15",""],[16,10,"قال وحدثني إبراهيم بن محمد بن حمران عن يحيى بن القاسم الحذاء وغيره عن جميل بن صالح عن داود بن زربي قال بعث إلي العبد الصالح عليه السلام وهو في الحبس فقال: ائت هذا الرجل، يعني يحيى بن خالد، فقل له: يقول لك أبو فلان: ما حملك على ما صنعت؟! أخرجتني من بلادي وفرقت بيني وبين عيالي. فأتيته وأخبرته فقال: زبيدة طالق وعليه أغلظ الأيمان لوددت أنه غرم الساعة ألفي ألف وأنت خرجت، فرجعت إليه فأبلغته، فقال: ارجع إليه فقل له: يقول لك: والله لتخرجني أو لأخرجن.","27/1/11/16",""],[17,10,"قال وحدثني إبراهيم بن محمد بن حمران عن إسماعيل بن منصور الزبالي قال سمعت شيخا بأذرعات قد أتت عليه عشرون ومائة سنة قال سمعت عليا عليه السلام يقول على منبر الكوفة: كأني بابن حميدة قد ملأها عدلا وقسطا كما ملئت ظلما وجورا. فقام إليه رجل فقال: أهو منك أو من غيرك؟فقال: لا،بل هو رجل مني.","27/1/11/17",""],[18,10,"قال وحدثني أحمد بن الحسن قال حدثني يحيى بن إسحاق العلوي عن أبيه قال دخلت على أبي عبد الله عليه السلام فسألته عن صاحب هذا الأمر من بعده، قال: صاحب البهمة. وأبو الحسن في ناحيـة الدار ومعه عناق مكية ويقول لهـا: اسجدي لله الذي خلقك. ثم قال: أما إنه الذي يملأها قسطاً وعدلاً كما ملئت ظلما وجورا.","27/1/11/18",""],[19,10,"قال وحدثني الحسين بن علي بن معمر عن أبيه عن عبد الله بن سنان قال سمعت أبا عبد الله عليه السلام، وذكر البداء لله، فقال: فما أخرج الله إلى الملائكة وأخرجه الملائكة إلى الرسل فأخرجه الرسل إلى الآدميين فليس فيه بداء وإن من المحتوم أن ابني هذا هو القائم.","27/1/11/19",""],[20,10,"قال وروى بقباقة أخو بنين الصيرفي قال حدثني الإصطخري أنه سمع أبا عبد الله عليه السلام يقول: كأني بابن حميدة على أعوادها قد دانت له شرق الأرض وغربها.","27/1/11/20",""],[21,10,"قال وحدثني محمد بن عطاء ضرغامة عن خلاد اللؤلؤي قال حدثني سعيد المكي عن أبي عبد الله عليه السلام، وكانت له منزلة منه،قال: قال أبو عبد الله عليه السلام: يا سعيد،الأئمة اثنا عشر إذا مضى ستة فتح الله على السابع ويملك منا أهل البيت خمسة وتطلع الشمس من مغربها على يد السادس.","27/1/11/21",""],[22,10,"قال وحدثني حنان بن سدير عن أبي إسماعيل الأبرص عن أبي بصير قال قال أبو عبد الله عليه السلام: على رأس السابع منا الفرج.","27/1/11/22",""],[23,10,"قال وحدثني عبد الله بن جبلة عن سلمة بن جناح عن حازم بن حبيب قال قلت لأبي عبد الله عليه السلام: إن أبوي هلكا وقد أنعم الله علي ورزق. أفأتصدق عنهما وأحج؟فقال: نعم. ثم قال بيمينه: يا أبا حازم من جاءك يخبرك عن صاحب هذا الأمر أنه غسله وكفنه ونفض التراب من قبره فلا تصدقه.","27/1/11/23",""],[24,10,"قال وحدثني أبو محمد الصيرفي عن عبد الكريم بن عمرو عن أبي بصير عن أبي عبد الله عليه السلام قال سمعته يقول: كأني بابني هذا، يعني أبا الحسن عليه السلام، قد أخذه بنو فلان فمكث في أيديهم حينا ودهرا،ثم خرج من أيديهم فيأخذ بيد رجل من ولده حتى ينتهي به إلى جبل رضوى.","27/1/11/24",""],[25,10,"قال وحدثني جعفر بن سليمان عن داود الصرمي عن علي بن أبي حمزة قال قال لي أبو عبد الله عليه السلام: من جاءك فقال لك إنه مرض ابني هذا وأغمضه وغسله ووضعه في لحده ونفض يده من تراب قبره فلا تصدقه.","27/1/11/25",""],[26,10,"قال: وروي عن سليمان بن داود عن علي بن أبي حمزة عن أبي الحسن عليه السلام قال،قال لي: يا علي من أخبرك أنه مرضني وغمضني وغسلني ووضعني في لحدي ونفض يده من تراب قبري فلا تصدقه.","27/1/11/26",""],[27,10,"قال: وأخبرني أعين بن عبد الرحمن بن أعين قال: بعثني عبد الله بن بكير إلى عبد الله الكاهلي سنة أخذ العبد الصالح عليه السلام زمن المهدي،فقال: أقرئه السلام وسله أتاه خبر…إلى أن قال: أقرئه السلام وقل له: حدثني أبو العيزار في مسجدكم منذ ثلاثين سنة وهو يقول: قال أبو عبد الله عليه السلام: يقدم لصاحب هذا الأمر العراق مرتين؛ فأما الأولى فيعجل سراحه ويحسن جائزته،وأما الثانية فيحبس فيطول حبسه ثم يخرج من أيديهم عنوة.","27/1/11/27",""],[28,10,"قال: وأخبرني إبراهيم بن محمد بن حمران وحمران والهيثم بن واقد الجزري عن عبد الله الأرجاني قال: كنت عند أبي عبد الله عليه السلام إذ دخل عليه العبد الصالح عليه السلام فقال: يا أحمد افعل كذا. فقلت: جعلت فداك،اسمه فلان. فقال: بل اسمه أحمد ومحمد. ثم قال لي: يا عبد الله إن صاحب هذا الأمر يؤخذ فيحبس فيطول حبسه فإذا هموا به دعا باسم الله الأعظم فأفلته من أيديهم.","27/1/11/28",""],[29,10,"قال: وروى بعض أصحابنا عن أبي محمد البزاز قال: حدثنا عمرو بن منهال القماط عن حديد الساباطي عن أبي عبد الله عليه السلام قال: إن لأبي الحسن عليه السلام غيبتين؛ إحداهما تقل والأخرى تطول،حتى يجيئكم من يزعم أنه مات وصلى عليه ودفنه ونفض تراب القبر من يده. فهو في ذلك كاذب؛ ليس يموت وصي حتى يقيم وصيا، ولا يلي الوصي إلا الوصي،فإن وليه غير وصي عمي.","27/1/11/29",""],[30,10,"قال: وحدثنا عبد الله بن سلام أبو هريرة عن زرعة عن مفضل قال: كنت جالسا عند أبي عبد الله عليه السلام إذ جاءه أبو الحسن ومحمد ومعهما عناق يتجاذبانها، فغلبه محمد عليها، فاستحيا أبو الحسن فجاء فجلس إلى جانبي، فضممته إليّ وقبلته،فقال أبو عبد الله عليه السلام: أما إنه صاحبكم، مع أن بني العباس يأخذونه فيلقى منهم عنتا، ثم يفلته الله من أيديهم بضرب من الضروب، ثم يعمى على الناس أمره حتى تفيض عليه العيون وتضطرب فيه القلوب كما تضطرب السفينة في لجة البحر وعواصف الريح،ثم يأتي الله على يديه بفرج لهذه الأمة للدين والدنيا.","27/1/11/30",""],[31,10,"قال وحدثني حنان عن أبي عبد الرحمن المسعودي قال حدثنا المنهال بن عمرو عن أبي عبد الله النعمان عن أبي جعفر عليه السلام قال: صاحب الأمر يسجن حينا ويموت حينا ويهرب حينا.","27/1/11/31",""],[32,10,"قال: وروى بحر بن زياد عن عبد الله الكاهلي أنه سمع أبا عبد الله عليه السلام يقول: إن جاءكم من يخبركم بأنه مرض ابني هذا وهو شهده وهو أغمضه وغسله وأدرجه في أكفانه وصلى عليه ووضعه في قبره وهو حثا عليه التراب فلا تصدقوه. ولا بد من أن يكون ذا. فقال له محمد بن زياد التميمي وكان حاضر الكلام بمكة: يا أبا يحيى،هذه والله فتنة عظيمة. فقال له الكاهلي: فسهم الله فيه أعظم،يغيب عنهم شيخ ويأتيهم شاب فيه سنة من يونس.","27/1/11/32",""],[33,10,"قال: وروى أحمد بن الحارث رفعه إلى أبي عبد الله عليه السلام أنه قال: لو قد يقوم القائم لقال الناس: أنى يكون هذا وبليت عظامه؟","27/1/11/33",""],[34,10,"قال: وروى سليمان بن داود عن علي بن أبي حمزة عن أبي بصير قال: سمعت أبا جعفر عليـه السـلام يقـول:في صـاحب هذا الأمر أربع سنن من أربعة أنبياء؛ سنة من موسى وسنة من عيسى وسنة من يوسف وسنة من محمد صلى الله عليه وآله وسلم. أما من موسى فخائف يترقب، وأما من يوسف فالسجن،وأما من عيسى فيقال: مات، ولم يمت،وأما من محمد صلى الله عليه وآله وسلم فالسيف.","27/1/11/34",""],[35,10,"قال: وروى علي بن عبد الله عن زرعة بن محمد عن مفضل قال: سمعت أبا عبد الله عليه السلام يقول: إن بني العباس سيعبثون بابني هذا ولن يصلوا إليه. ثم قال: وما صائحة تصيح وما ساقة تسق وما ميراث يقسم وما أمة تباع.","27/1/11/35",""],[36,10,"قال: وروى أحمد بن علي عن محمد بن الحسين بن إسماعيل عن عبد الرحمن بن الحجاج قال: سمعت أبا إبراهيم عليه السلام يقول: إن بني فلان يأخذونني ويحبسونني. وقال: وذاك وإن طال فإلى سلامة.","27/1/11/36",""],[37,10,"قال: وروى إبراهيم بن المستنير عن المفضل قال: سمعت أبا عبد الله عليه السلام يقول: إن لصاحب هذا الأمر غيبتين؛ إحداهما أطول من الأخرى،حتى يقال: مات! وبعض يقول: قتل. فلا يبقى على أمره إلا نفر يسير من أصحابه،ولا يطلع أحد على موضعه وأمره ولا غيره إلا المولى الذي يلي أمره.","27/1/11/37",""],[38,10,"قال: وروى علي بن معاذ قال: قلت لصفوان بن يحيى: بأي شي‏ء قطعت على علي؟قال: صليت ودعوت الله واستخرت عليه وقطعت عليه.","27/1/11/38",""],[39,10,"ثم قال: وقال علي بقباقة: سألت صفوان بن يحيى وابن جندب وجماعة من مشيختهم،وكان الذي بينه وبينهم عظيم: بأي شي‏ء قطعتم على هذا الرجل؟ألشي‏ء بان لكم فأقبل قولكم؟قالوا كلهم: لا والله،إلا أنه قال فصدقناه. وأحالوا جميعا على البزنطي فقلت: سوءة لكم وأنتم مشيخة الشيعة! أترسلونني إلى ذلك الصبي الكذاب فأقبل منه وأدعكم أنتم؟","27/1/11/39",""],[40,10,"قال: وسئل بعض أصحابنا عن علي بن رباط: هل سمع أحدا روى عن أبي الحسن عليه السلام أنه قال: علي ابني وصيي، أو إمام بعدي، أو بمنزلتي من أبي، أو خليفتي،أو معنى هذا. قال: لا.","27/1/11/40",""],[41,10,"قال: وسأل أبو بكر الأرمني عبد الله بن المغيرة: بأي شي‏ء قطعت على علي؟قال: أخبرتني سلمى أنه لم يكن عند أبيه أحد بمنزلته.","27/1/11/41",""],[1,11,"فروى الثقات أن أول من أظهر هذا الاعتقاد علي بن أبي حمزة البطائني وزياد بن مروان القندي وعثمان بن عيسى الرواسي طمعوا في الدنيا ومالوا إلى حطامها واستمالوا قوما فبذلوا لهم شيئا مما اختانوه من الأموال نحو حمزة بن بزيع وابن المكاري وكرام الخثعمي وأمثالهم.","27/1/12/1",""],[2,11,"فروى محمد بن يعقوب عن محمد بن يحيى العطار عن محمد بن أحمد عن محمد بن جمهور عن أحمد بن الفضل عن يونس بن عبد الرحمن قال: مات أبو إبراهيم عليه السلام وليس من قوامه أحد إلا وعنده المال الكثير،وكان ذلك سبب وقفهم وجحدهم موته طمعا في الأموال. كان عند زياد بن مروان القندي سبعون ألف دينار وعند علي بن أبي حمزة ثلاثون ألف دينار.فلما رأيت ذلك وتبينت الحق وعرفت من أمر أبي الحسن الرضا عليه السلام ما علمت، تكلمت ودعوت الناس إليه،فبعثا إلي وقالا: ما يدعوك إلى هذا؟إن كنت تريد المال فنحن نغنيك! وضمنا لي عشرة آلاف دينار وقالا لي: كف. فأبيت وقلت لهما: إنا روينا عن الصادقين عليه السلام أنهم قالوا: إذا ظهرت البدع فعلى العالم أن يظهر علمه فإن لم يفعل سلب نور الإيمان، وما كنت لأدع الجهاد وأمر الله على كل حال،فناصباني وأضمرا لي العداوة.","27/1/12/2",""],[3,11,"وروى محمد بن الحسن بن الوليد عن الصفار وسعد بن عبد الله الأشعري جميعا عن يعقوب بن يزيد الأنباري عن بعض أصحابه قال: مضى أبو إبراهيم عليه السلام وعند زياد القندي سبعون ألف دينار وعند عثمان بن عيسى الرواسي ثلاثون ألف دينار وخمس جوار ومسكنه بمصر، فبعث إليهم أبو الحسن الرضا عليه السلام أن احملوا ما قبلكم من المال وما كان اجتمع لأبي عندكم من أثاث وجوار فإني وارثه وقائم مقامه وقد اقتسمنا ميراثه ولا عذر لكم في حبس ما قد اجتمع لي ولوارثه قبلكم،وكلام يشبه هذا. فأما ابن أبي حمزة فإنه أنكره ولم يعترف بما عنده،وكذلك زياد القندي. وأما عثمان بن عيسى فإنه كتب إليه أن أباك عليه السلام لم يمت، وهو حي قائم، ومن ذكر أنه مات فهو مبطل،وأعمل على أنه قد مضى كما تقول فلم يأمرني بدفع شي‏ء إليك، وأما الجواري فقد أعتقهن وتزوجت بهن.","27/1/12/3",""],[4,11,"وروى أحمد بن محمد بن سعيد بن عقدة عن محمد بن أحمد بن نصر التيمي قال: سمعت حرب بن الحسن الطحان يحدث يحيى بن الحسن العلوي أن يحيى بن المساور قال: حضرت جماعة من الشيعة وكان فيهم علي بن أبي حمزة فسمعته يقول: دخل علي بن يقطين على أبي الحسن موسى عليه السلام فسأله عن أشياء فأجابه، ثم قال أبو الحسن عليه السلام: يا علي،صاحبك يقتلني. فبكى علي بن يقطين وقال: يا سيدي وأنا معه؟قال: لا يا علي. لا تكون معه ولا تشهد قتلي. قال علي: فمن لنا بعدك يا سيدي؟فقال: علي ابني هذا؛هو خير من أخلف بعدي. هو مني بمنزلة أبي هو لشيعتي، عنده علم ما محتاجون إليه، سيد في الدنيا وسيد في الآخرة وإنه لمن المقربين. فقال يحيى بن الحسن لحرب: فما حمل علي بن أبي حمزة على أن برئ منه وحسده؟ قال: سألت يحيى بن المساور عن ذلك، فقال: حمله ما كان عنده من ماله الذي اقتطعه ليشقيه الله في الدنيا والآخرة...","27/1/12/4",""],[5,11,"وروى علي بن حبشي بن قوني عن الحسين بن أحمد بن الحسن بن علي بن فضال قال: كنت أرى عند عمي علي بن الحسن بن فضال شيخا من أهل بغداد وكان يهازل عمي. فقال له يوما: ليس في الدنيا شر منكم يا معشر الشيعة- أو قال الرافضة - .فقال له عمي: ولم؟ لعنك الله.قال: أنا زوج بنت أحمد بن أبي بشر السراج،قال لي لما حضرته الوفاة: إنه كان عندي عشرة آلاف دينار وديعة لموسى بن جعفر عليه السلام فدفعت ابنه عنها بعد موته وشهدت أنه لم يمت! فالله الله،خلصوني من النار وسلموها إلى الرضا.فو الله ما أخرجنا حبه ولقد تركناه يصلى بها في نار جهنم.","27/1/12/5",""],[1,12,"وأما ما روي من الطعن على رواة الواقفة فأكثر من أن يحصى، وهو موجود في كتب أصحابنا نحن نذكر طرفا منه:","27/1/13/1",""],[2,12,"روى محمد بن أحمد بن يحيى الأشعري عن عبد الله بن محمد عن الخشاب عن أبي داود قال: كنت أنا وعيينة بياع القصب عند علي بن أبي حمزة البطائني، وكان رئيس الواقفة،فسمعته يقول: قال لي أبو إبراهيم عليه السلام: إنما أنت وأصحابك، يا علي، أشباه الحمير. فقال لي عيينة: أسمعت؟ قلت: إي والله لقد سمعت.فقال: لا والله،لا أنقل إليه قدمي ما حييت.","27/1/13/2",""],[3,12,"وروى ابن عقدة عن علي بن الحسن بن فضال عن محمد بن عمر بن يزيد وعلي بن أسباط جميعا قالا: قال لنا عثمان بن عيسى الرواسي: حدثني زياد القندي وابن مسكان قالا: كنـا عنـد أبي إبـراهيم عليـه السلام إذ قال: يدخل عليكم الساعة خير أهل الأرض. فدخل أبو الحسن الرضا عليه السلام وهو صبي. فقلنا: خير أهل الأرض. ثم دنا فضمه إليه فقبله وقال: يا بني، تدري ما قال ذان؟ قال: نعم، يا سيدي، هذان يشكان فيّ. قال علي بن أسباط: فحدثت بهذا الحديث الحسن بن محبوب فقال: بتر الحديث… لا،ولكن حدثني علي بن رئاب أن أبا إبراهيم عليه السلام قال لهما: إن جحدتماه حقه أو خنتماه فعليكما لعنة الله والملائكة والناس أجمعين. يا زياد، لا تنجب أنت وأصحابك أبدا. قال علي بن رئاب: فلقيت زياد القندي فقلت له: بلغني أن أبا إبراهيم عليه السلام قال لك كذا وكذا. فقال: أحسبك قد خولطت! فمر وتركني فلم أكلمه ولا مررت به. قال الحسن بن محبوب: فلم نزل نتوقع لزياد دعوة أبي إبراهيم عليه السلام حتى ظهر منه أيام الرضا عليه السلام ما ظهر،ومات زنديقا.","27/1/13/3",""],[4,12,"وروى أحمد بن محمد بن يحيى عن أبيه عن محمد بن الحسين بن أبي الخطاب عن صفوان بن يحيى عن إبراهيم بن يحيى بن أبي البلاد قال: قال الرضا عليه السلام: ما فعل الشقي حمزة بن بزيع؟ قلت: هو ذا قد قدم. فقال: يزعم أن أبي حي! هم اليوم شكاك، ولا يموتون غدا إلا على الزندقة. قال صفوان: فقلت فيما بيني وبين نفسي: شكاك قد عرفتهم! فكيف يموتون على الزندقة؟ فما لبثنا إلا قليلا حتى بلغنا عن رجل منهم أنه قال عند موتهك هو كافر برب أماته! قال صفوان: فقلت: هذا تصديق الحديث.","27/1/13/4",""],[5,12,"وروى أبو علي محمد بن همام عن علي بن رباح قال: قلت للقاسم بن إسماعيل القرشي، وكان ممطورا: أي شي‏ء سمعت من محمد بن أبي حمزة؟ قال: ما سمعت منه إلا حديثا واحدا. قال ابن رباح: ثم أخرج بعد ذلك حديثا كثيرا فرواه عن محمد بن أبي حمزة. قال ابن رباح: وسألت القاسم هذا: كم سمعت من حنان؟ فقال: أربعة أحاديث أو خمسة. قال: ثم أخرج بعد ذلك حديثا كثيرا فرواه عنه.","27/1/13/5",""],[6,12,"وروى أحمد بن محمد بن عيسى عن سعد بن سعد عن أحمد بن عمر قال: سمعت الرضا عليه السلام يقول في ابن أبي حـمزة: أليـس هو الذي يروي أن رأس المهدي يهدى إلى عيسى بن موسى وهو صاحب السفياني؟ وقال إن أبا إبراهيم عليه السلام يعود إلى ثمانية أشهر. فما استبان لهم كذبه.","27/1/13/6",""],[7,12,"وروى محمد بن أحمد بن يحيى عن بعض أصحابنا عن محمد بن عيسى بن عبيد عن محمد بن سنان قال: ذكر علي بن أبي حمزة عند الرضا عليه السلام فلعنه،ثم قال: إن علي بن أبي حمزة أراد أن لا يعبد الله في سمائه وأرضه،فأبى الله إلا أن يتم نوره ولو كره المشركون. ولو كره اللعين المشرك. قلت: المشرك؟قال: نعم والله،وإن رغم أنفه. كذلك وهو في كتاب الله ﴿يُرِيدُونَ أَنْ يُطْفِؤُا نُورَ اللَّهِ بِأَفْواهِهِمْ﴾وقد جرت فيه وفي أمثاله إنه أراد أن يطفئ نور الله.","27/1/13/7",""],[1,13,"ويبطل ذلك أيضا ما ظهر من المعجزات على يد الرضا عليه السلام الدالة على صحة إمامته وهي مذكورة في الكتب. ولأجلها رجع جماعة من القول بالوقف مثل عبد الرحمن بن الحجاج ورفاعة بن موسى ويونس بن يعقوب وجميل بن دراج وحماد بن عيسى وغيرهم وهؤلاء من أصحاب أبيه الذين شكوا فيه ثم رجعوا. وكذلك من كان في عصره مثل أحمد بن محمد بن أبي نصر والحسن بن علي الوشاء وغيرهم ممن كان قال بالوقف فالتزموا الحجة وقالوا بإمامته وإمامة من بعده من ولده.","27/1/14/1",""],[2,13,"فروى جـعفر بن محمـد بن مـالك عن محمـد بن الحسـين بن أبي الخطـاب عن محمد بن أبي عمير عن أحمد بن محمد بن أبي نصر وهو من آل مهران وكانوا يقولون بالوقف وكان على رأيهـم فكاتب أبـا الحسن الرضا عليـه السلام وتعنت في المسائل فقال: كتبت إليه كتابا وأضمرت في نفسي أني متى دخلت عليه أسأله عن ثلاث مسائل من القرآن وهي قوله تعالى: ﴿أَفَأَنْتَ تُسْمِعُ الصُّمَّ أَوْ تَهْدِي الْعُمْيَ﴾ وقوله: ﴿فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلامِ﴾ وقوله: ﴿إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ ولكِنَّ اللَّهَ يَهْدِي مَنْ يَشاءُ﴾. قال أحمد: فأجابني عن كتابي وكتب في آخره الآيات التي أضمرتها في نفسي أن أسأله عنها ولم أذكرها في كتابي إليه. فلما وصل الجواب أنسيت ما كنت أضمرته،فقلت: أي شي‏ء هذا من جوابي؟ثم ذكرت أنه ما أضمرته.","27/1/14/2",""],[3,13,"وكذلك الحسن بن علي الوشاء وكان يقول بالوقف فرجع،وكان سببه أنه قال: خرجت إلى خراسان في تجارة لي، فلما وردته بعث إلي أبو الحسن الرضا عليه السلام يطلب مني حبرة،وكانت بين ثيابي قد خفي علي أمرها. فقلت: ما معي منها شي‏ء. فرد الرسول وذكر علامتها وأنها في سفط كذا. فطلبتها فكان كما قال،فبعثت بها إليه. ثم كتبت مسائل أسأله عنها،فلما وردت بابه خرج إلي جواب تلك المسائل التي أردت أن أسأله عنها من غير أن أظهرتها. فرجع عن القول بالوقف إلى القطع على إمامته.","27/1/14/3",""],[4,13,"وقال أحمد بن محمد بن أبي نصر: قال ابن النجاشي: من الإمام بعد صاحبكم؟ فدخلت على أبي الحسن الرضا عليه السلام فأخبرته،فقال: الإمام بعدي ابني؟ ثم قال: هل يجرؤ أحد أن يقول ابني وليس له ولد؟!","27/1/14/4",""],[5,13,"وروى عبد الله بن جعفر الحميري عن محمد بن عيسى اليقطيني قال: لما اختلف الناس في أمر أبي الحسن الرضا عليه السلام جمعت من مسائله مما سئل عنه وأجاب عنه خمس عشرة ألف مسألة.","27/1/14/5",""],[6,13,"وروى محمد بن عبد الله بن الأفطس قال: دخلت على المأمون فقربني وحياني،ثم قال: رحم الله الرضا عليه السلام ما كان أعلمه. لقد أخبرني بعجب. سألته ليلة وقد بايع له الناس فقلت: جعلت فداك،أرى لك أن تمضي إلى العراق وأكون خليفتك بخراسان. فتبسم ثم قال: لا،لعمري ولكن من دون خراسان بدرجات. إن لنا هنا مكثا ولست ببارح حتى يأتيني الموت ومنها المحشر لا محالة. فقلت له: جعلت فداك، وما علمك بذلك؟فقال: علمي بمكاني كعلمي بمكانك. قلت: وأين مكاني، أصلحك الله؟فقال: لقد بعدت الشقة بيني وبينك. أموت بالمشرق وتموت بالمغرب. فقلت: صدقت. والله ورسوله أعلم وآل محمد. فجهدت الجهد كله وأطمعته في الخلافة وما سواها فما أطمعني في نفسه.","27/1/14/6",""],[7,13,"وروى محمد بن عبد الله بن الحسن الأفطس قال: كنت عند المأمون يوما ونحن على شراب حتى إذا أخذ منه الشراب مأخذه صرف ندماءه واحتبسني، ثم أخرج جواريه وضربن وتغنين. فقال لبعضهن: بالله لما رثيت من بطوس قطنا. فأنشأت تقول: سقيا لطوس ومن أضحى بها قطنا من عترة المصطفى أبقى لنا حزنا أعني أبا حسن المأمون إن له حقا على كل من أضحى بها شجنا قال محمد بن عبد الله: فجعل يبكي حتى أبكاني. ثم قال لي: ويلك يا محمد! أيلزمني أهل بيتي وأهل بيتك أن أنصب أبا الحسن علما؟ والله أن لو أخرجت من هذا الأمر لأجلسته مجلسي،غير أنه عوجل فلعن الله عبد الله وحمزة ابني الحسن فإنهما قتلاه. ثم قال لي: يا محمد بن عبد الله والله لأحدثنك بحديث عجيب فاكتمه. قلت: ما ذاك يا أمير المؤمنين؟ قال: لما حملت زاهرية ببدر أتيته فقلت له: جعلت فداك، بلغني أن أبا الحسن موسى بن جعفر وجعفر بن محمد ومحمد بن علي وعلي بن الحسين والحسين بن علي عليهم السلام كانوا يزجرون الطير ولا يخطئون. وأنت وصي القوم وعندك علم ما كان عندهم، وزاهرية حظيتي ومن لا أقدم عليها أحدا من جواري، وقد حملت غير مرة،كل ذلك يسقط. فهل عندك في ذلك شي‏ء ننتفع به؟فقال: لا تخش من سقطها، فستسلم وتلد غلاما صحيحا مسلما، أشبه الناس بأمه، قد زاده الله في خلقه مرتبتين،في يده اليمنى خنصر وفي رجله اليمنى خنصر. فقلت في نفسي: هذه والله فرصة! إن لم يكن الأمر على ما ذكر خلعته. فلم أزل أتوقع أمرها حتى أدركها المخاض،فقلت للقيمة: إذا وضعت فجيئيني بولدها ذكرا كان أو أنثى. فما شعرت إلا بالقيمة وقد أتتني بالغلام كما وصفه؛ زائد اليد والرجل،كأنه كوكب دري. فأردت أن أخرج من الأمر يومئذ وأسلم ما في يدي إليه، فلم تطاوعني نفسي،لكني دفعت إليه الخاتم فقلت: دبر الأمر، فليس عليك مني خلاف،وأنت المقدم. وبالله أن لو فعل لفعلت.","27/1/14/7",""],[8,13,"وقصته مع حبابة الوالبية صاحبة الحصاة التي طبع فيها أمير المؤمنين عليه السلام وقال لها: من طبع فيها فهو إمام. وبقيت إلى أيام الرضا عليه السلام فطبع فيها، وقد شهدت من تقدم من آبائه عليهم السلام وطبعوا فيه،وهو عليه السلام آخر من لقيتهم وماتت بعد لقائها إياه وكفنها في قميصه.","27/1/14/8",""],[9,13,"وكذلك قصته مع أم غانم الأعرابية صاحبة الحصاة أيضا التي طبع فيها أمير المؤمنين عليه السلام وطبع بعده سائر الأئمة إلى زمان أبي محمد العسكري عليه السلام معروفة مشهورة.","27/1/14/9",""],[1,14,"فإن قيل: قد مضى في كلامكم أنا نعلم موت موسى بن جعفر عليهما السلام كما نعلم موت أبيه وجده عليهما السلام فعليكم لقائل أن يقول: إنا نعلم أنه لم يكن للحسن بن علي ابن كما نعلم أنه لم يكن له عشرة بنين وكما نعلم أنه لم يكن للنبي صلى الله عليه وآله وسلم ابن لصلبه عاش بعد موته. فإن قلتم لو علمنا أحدهما كما نعلم الآخر لما جاز أن يقع فيه خلاف كما لا يجوز أن يقع الخلاف في الآخر. قيل لمخالفكم أن يقول ولو علمنا موت محمد بن الحنفية وجعفر بن محمد وموسى بن جعفر عليهم السلام كما نعلم موت محمد بن علي بن الحسين عليهما السلام لما وقع الخلاف في أحدهما كما لم يجز أن يقع في الآخر.","27/1/15/1",""],[2,14,"قلنا نفي ولادة الأولاد من الباب الذي لا يصح أن يعلم صدوره في موضع من المواضع ولا يمكن أحدا أن يدعي فيمن لم يظهر له ولد أن يعلم أنه لا ولد له وإنما يرجع في ذلك إلى غالب الظن والأمارة بأنه لو كان له ولد لظهر وعرف خبره لأن العقلاء قد تدعوهم الدواعي إلى كتمان أولادهم لأغراض مختلفة. فمن الملوك من يخفيه خوفا عليه وإشفاقا وقد وجد من ذلك كثير في عادة الأكاسرة والملوك الأول وأخبارهم معروفة. وفي الناس من يولد له ولد من بعض سراياه أو ممن تزوج بها سرا فيرمى به ويجحده خوفا من وقوع الخصومة مع زوجته وأولاده الباقين وذلك أيضا يوجد كثيرا في العادة. وفي الناس من يتزوج بامرأة دنية في المنزلة والشرف وهو من ذوي الأقدار والمنازل فيولد له فيأنف من إلحاقه به فيجحده أصلا.وفيهم من يتحرج فيعطيه شيئا من ماله. وفي الناس من يكون من أدونهم نسبا فيتزوج بامرأة ذات شرف ومنزلة لهوى منها فيه بغير علم من أهلها أما بأن يزوجه نفسها بغير ولي على مذهب كثير من الفقهاء أو تولى أمرها الحاكم فيزوجها على ظاهر الحال، فيولد له فيكون الولد صحيحا وتنتفي منه أنفه وخوفا من أوليائها وأهلها،وغير ذلك من الأسباب التي لا نطول بذكرها الكتاب. فلا يمكن ادعاء نفي الولادة جملة وإنما نعلم ما نعلمه إذا كانت الأحوال سليمة ونعلم أنه لا مانع من ذلك فحينئذ نعلم انتفاءه. فأما علمنا بأنه لم يكن للنبي صلى الله عليه وآله وسلم ابن عاش بعده فإنما علمناه لما علمنا عصمته ونبوته ولو كان له ولد لأظهره لأنه لا مخافة عليه في إظهاره،وعلمنا أيضا بإجماع الأمة على أنه لم يكن له ابن عاش بعده. ومثل ذلك لا يمكن أن يدعى العلم به في ابن الحسن عليه السلام لأن الحسن عليه السلام كان كالمحجور عليه وفي حكم المحبوس وكان الولد يخاف عليه لما علم وانتشر من مذهبهم أن الثاني عشر هو القائم بالأمر المؤمل لإزالة الدول،فهو مطلوب لا محالة وخاف أيضا من أهله كجعفر أخيه الذي طمع في الميراث والأموال فلذلك أخفاه ووقعت الشبهة في ولادته. ومثل ذلك لا يمكن ادعاء العلم به في موت من علم موته لأن الميت مشاهد معلوم يعرف بشاهد الحال موته وبالأمارات الدالة عليه يضطر من رآه إلى ذلك فإذا أخبر من لم يشاهده علمه واضطر إليه وجرى الفرق بين الموضعين.مثل ما يقول الفقهاء في الأحكام الشرعية من أن البينة إنما يمكن أن تقوم على إثبات الحقوق لا على نفيها لأن النفي لا يقوم عليه بينة إلا إذا كان تحته إثبات فبان الفرق بين الموضعين لذلك.","27/1/15/2",""],[3,14,"فإن قيل العادة تسوي بين الموضعين لأن الموت قد يشاهد الرجل يحتضر كما تشاهد القوابل الولادة وليس كل أحد يشاهد احتضار غيره كما أنه ليس كل أحد يشاهد ولادة غيره ولكن أظهر ما يمكن في علم الإنسان بموت غيره إذا لم يكن يشاهده أن يكون جاره ويعلم بمرضه ويتردد في عيادته ثم يعلم بشدة مرضه ويشتد الخوف من موته ثم يسمع الواعية من داره ولا يكون في الدار مريض غيره ويجلس أهله للعزاء وآثار الحزن والجزع عليهم ظاهرة ثم يقسم ميراثه ثم يتمادى الزمان ولا يشاهد ولا يعلم لأهله غرض في إظهار موته وهو حي. فهذه سبيل الولادة لأن النساء يشاهدن الحمل ويتحدثن بذلك سيما إذا كانت حرمة رجل نبيه يتحدث الناس بأحوال مثله وإذا استسر بجـارية في بعض المواضـع لم يخف تردده إليهـا ثم إذا ولد المولود ظهر البشر والسرور في أهل الدار وهنأهم الناس إذا كان المهنأ جليل القدر وانتشر ذلك وتحدث على حسب جلالة قدره ويعلم الناس أنه قد ولد مولود سيما إذا علم أنه لا غرض في أن يظهر أنه ولد له ولد ولم يولد له. فمتى اعتبرنا العادة وجدناها في الموضعين على سواء وإن نقض الله العادة فإنه يمكن في أحدهما مثل ما يمكن في الآخر فإنه قد يجوز أن يمنع الله ببعض الشواغل عن مشاهدة الحامل وعن أن يحضر ولادتها إلا عدد يؤمن مثلهم على كتمان أمره ثم ينقله الله من مكان الولادة إلى قلة جبل أو برية لا أحد فيها ولا يطلع على ذلك الأمر إلا من لا يظهره إلا على المأمون مثله. وكما يجوز ذلك فإنه يجوز أن يمرض الإنسان ويتردد إليه عواده فإذا اشتد حاله وتوقع موته وكان يؤيس من حياته نقله الله إلى قلة جبل وصير مكانه شخصا ميتا يشبهه كثيرا من الشبه ثم يمنع بالشواغل وغيرها من مشاهدته إلا لمن يوثق به ثم يدفن الشخص ويحضر جنازته من كان يتوقع موته ولا يرجو حياته فيتوهم أن المدفون هو ذاك العليل. وقد يسكن نبض الإنسان وتنفسه وينقض الله العادة ويغيبه عنهم وهو حي لأن الحي منا إنما يحتاج إليهما لإخراج البخارات المحترقة مما حول القلب بإدخال هواء بارد صاف ليروح عن القلب وقد يمكن أن يفعل الله من البرودة في الهواء المحدق بالقلب ما يجري مجرى هواء بارد يدخلها بالتنفس فيكون الهواء المحدق بالقلب أبدا باردا ولا يحترق منه شي‏ء لأن الحرارة التي تحصل فيه تقوم بالبرودة.","27/1/15/3",""],[4,14,"والجواب أنا نقول أولا أنه لا يلتجئ من يتكلم في الغيبة إلى مثل هذه الخرافات إلا من كان مفلسا من الحجة عاجزا عن إيراد شبهة قوية غير متمكن من الكلام عليها بما يرتضي مثله فعند ذلك يلتجئ إلى مثل هذه التمويهات والتذليقات. ونحن نتكلم على ذلك على ما به فنقول إن ما ذكر من الطريق الذي به يعلم موت الإنسان ليس بصحيح على كل وجه لأنه قد يتفق جميع ذلك وينكشف عن باطل بأن يكون لمن أظهر ذلك غرض حكمي فيظهر التمارض ويتقدم إلى أهله بإظهار جميع ذلك ليختبر به أحوال غيره ممن له عليه طاعة أو إمرة وقد سبق الملوك كثيرا والحكماء إلى مثل ذلك وقد يدخل عليهم أيضا شبهة بأن يلحقه علة سكتة فيظهرون جميع ذلك ثم ينكشف عن باطل وذلك أيضا معلوم بالعادات وإنما يعلم الموت بالمشاهدة وارتفاع الحس وجمود النبض ويستمر ذلك أوقاتا كثيرة ربما انضاف إلى ذلك أمارات معلومة بالعادة من جرب المرضى ومارسهم يعلم ذلك.","27/1/15/4",""],[5,14,"وهذه حالة موسى بن جعفر عليهماالسلام فإنه أظهر للخلق الكثير الذين لا يخفى على مثلهم الحال ولا يجوز عليهم دخول الشبهة في مثله. وقوله بأنه يجوز أن يغيب الله الشخص ويحضر شخصا على شبهه على أصله لا يصح لأن هذا يسد باب الأدلة ويؤدي إلى الشك في المشاهدات وأن جميع ما نراه ليس هو الذي رأيناه بالأمس ويلزم الشك في موت جميع الأموات ويجي‏ء منه مذهب الغلاة والمفوضة الذين نفوا القتل عن أمير المؤمنين عليه السلام وعن الحسين عليه السلام وما أدى إلى ذلك يجب أن يكون باطلا. وما قاله أن الله يفعل داخل الجوف حول القلب من البرودة ما ينوب مناب الهواء ضرب من هوس الطب ومع ذلك يؤدي إلى الشك في موت جميع الأموات على ما قلناه على أن على قانون الطب حركات النبض والشريانات من القلب وإنما يبطل ببطلان الحرارة الغريزية فإذا فقد حركات النبض علم بطلان الحرارة وعلم عند ذلك موته وليس ذلك بموقوف على التنفس ولهذا يلتجئون إلى النبض عند انقطاع النفس أو ضعفه فيبطل ما قالوه. وحمله الولادة على ذلك وما ادعاه من ظهور الأمر فيه صحيح متى فرضنا الأمر على ما قاله من أنه يكون الحمل لرجل نبيه وقد علم إظهاره ولا مانع من ستره وكتمانه ومتى فرضنا كتمانه وستره لبعض الأغراض التي قدمنا بعضها لا يجب العلم به ولا اشتهاره. على أن الولادة في الشرع قد استقر أن يثبت بقول القابلة ويحكم بقولها في كونه حيا أو ميتا فإذا جاز ذلك كيف لا يقبل قول جماعة نقلوا ولادة صاحب الأمر عليه السلام وشاهدوه وشاهدوا من شاهده من الثقات. ونحن نورد الأخبار في ذلك عمن رآه وحكى له.وقد أجاز صاحب السؤال أن يعرض في ذلك عارض يقتضي المصلحة أنه إذا ولد أن ينقله الله إلى قلة جبل أو موضع يخفى فيه أمره ولا يطلع عليه أحد وإنما ألزم على ذلك عارضا في الموت وقد بينا الفصل بين الموضعين.","27/1/15/5",""],[1,15,"وأما من خالف من الفرق الباقية الذين قالوا بإمامة غيره كالمحمدية الذين قالوا بإمامة محمد بـن عـلي بـن محمـد بن عـلي الرضـا عليه السلام والفطحية القائلة بإمامة عبد الله بن جعفر بن محمد الصادق عليه السلام وفي هذا الوقت بإمامة جعفر بن علي. وكالفرقة القائلة أن صاحب الزمان حمل لم يولد بعد. وكالذين قالوا أنه مات ثم يعيش. وكالذين قالوا بإمامة الحسن عليه السلام وقالوا هو اليقين ولم يصح لنا ولادة ولده فنحن في فترة. فقولهم ظاهر البطلان من وجوه: أحدها انقراضهم فإنه لم يبق قائل يقول بشي‏ء من هذه المقالات ولو كان حقا لما انقرض. ومنها أن محمد بن علي العسكري مات في حياة أبيه موتا ظاهرا.والأخبار في ذلك ظاهرة معروفة من دفعه كمن دفع موت من تقدم من آبائه عليهم السلام.","27/1/16/1",""],[2,15,"فروى سعد بن عبد الله الأشعري قال: حدثني أبو هاشم داود بن القاسم الجعفري قال: كنت عند أبي الحسن العسكري عليه السلام وقت وفاة ابنه أبي جعفر، وقد كان أشار إليه ودل عليه، وإني لأفكر في نفسي وأقول: هذه قصة أبي إبراهيم عليه السلام وقصة إسماعيل. فأقبل علي أبو الحسن عليه السلام وقال: نعم،يا أبا هاشم. بدا لله في أبي جعفر وصير مكانه أبا محمد،كما بدا له في إسماعيل بعد ما دل عليه أبو عبد الله عليه السلام ونصبه. وهو كما حدثتك نفسك وإن كره المبطلون. أبو محمد ابني الخلف من بعدي؛ عنده ما تحتاجونه إليه ومعه آلة الإمامة، والحمد لله.","27/1/16/2",""],[3,15,"وأما من قال إنه لا ولد لأبي محمد عليه السلام ولكن هاهنا حمل مشهور سيولد، فقوله باطل لأن هذا يؤدي إلى خلو الزمان من إمام يرجع إليه، وقد بينا فساد ذلك. على أنا سندل على أنه قد ولد له ولد معروف ونذكر الروايات في ذلك فيبطل قول هؤلاء أيضا.","27/1/16/3",""],[4,15,"وأما من قال إن الأمر مشتبه فلا يدرى هل للحسن عليه السلام ولد أم لا، وهو مستمسك بالأول حتى يتحقق ولادة ابنه، فقوله أيضا يبطل بما قلناه من أن الزمان لا يخلو من إمام، لأن موت الحسن عليه السلام قد علمناه كما علمنا موت غيره. وسنبين ولادة ولده فيبطل قولهم أيضا.","27/1/16/4",""],[5,15,"وأما من قال إنه لا إمام بعد الحسن عليه السلام، فقوله باطل بما دللنا عليه من أن الزمان لا يخلو من حجة لله عقلا وشرعا. وأما من قال إن أبا محمد عليه السلام مات ويحيا بعد موته، فقوله باطل بمثل ما قلناه،لأنه يؤدي إلى خلو الخلق من إمام من وقت وفاته عليه السلام إلى حين يحييه الله تعالى.","27/1/16/5",""],[6,15,"واحتجاجهم بما روي من أن صاحب هذا الأمر يحيا بعد ما يموت وأنه سمي قائما لأنه يقوم بعد ما يموت، باطل لأن ذلك يحتمل لو صح الخبر أن يكون أراد بعد أن مات ذكره حتى لا يذكره إلا من يعتقد إمامته فيظهره الله لجميع الخلق،على أنا قد بينا أن كل إمام يقوم بعد الإمام الأول يسمى قائما.","27/1/16/6",""],[7,15,"وأما القائلون بإمامة عبد الله بن جعفر من الفطحية وجعفر بن علي، فقولهم باطل بما دللنا عليه من وجوب عصمة الإمام وهما لم يكونا معصومين، وأفعالهما الظاهر التي تنافي العصمة معروفة، نقلها العلماء،وهي موجودة في الكتب فلا نطول بذكرها الكتاب. على أن المشهور الذي لا مرية فيه ��ين الطائفة أن الإمامة لا تكون في أخوين بعد الحسن والحسين عليهما السلام. فالقول بإمامة جعفر بعد أخيه الحسن يبطل بذلك.","27/1/16/7",""],[1,16,"فإذا ثبت بطلان هذه الأقاويل كلها لم يبق إلا القول بإمامة ابن الحسن عليه السلام، وإلا لأدى إلى خروج الحق عن الأمة وذلك باطل. وإذا ثبتت إمامته بهذه السياقة ثم وجدناه غائبا عن الأبصار علمنا أنه لم يغب مع عصمته وتعين فرض الإمامة فيه وعليه إلا لسبب سوغه ذلك وضرورة ألجأته إليه وإن لم يعلم على وجه التفصيل.","27/1/17/1",""],[2,16,"وجرى ذلك مجرى الكلام في إيلام الأطفال والبهائم وخلق المؤذيات والصور المشينات ومتشابه القرآن إذا سألنا عن وجهها بأن نقول: إذا علمنا أن الله تعالى حكيم لا يجوز أن يفعل ما ليس بحكمه ولا صواب علمنا أن هذه الأشياء لها وجه حكمة وإن لم نعلمه معينا. وكذلك نقول في صاحب الزمان عليه السلام، فإنا نعلم أنه لم يستتر إلا لأمر حكمي يسوغه ذلك وإن لم نعلمه مفصلا.","27/1/17/2",""],[3,16,"فإن قيل: نحن نعترض قولكم في إمامته بغيبته بأن نقول إذا لم يمكنكم بيان وجه حسنها دل ذلك على بطلان القول بإمامته، لأنه لو صح لأمكنكم بيان وجه الحسن فيه.","27/1/17/3",""],[4,16,"قلنا: إن لزمنا ذلك لزم جميع أهل العدل قول الملحدة إذا قالوا إنا نتوصل بهذه الأفعال التي ليست بظاهرة الحكمة إلى أن فاعلها ليس بحكيم،لأنه لو كان حكيما لأمكنكم بيان وجه الحكمة فيها وإلا فما الفصل.","27/1/17/4",""],[5,16,"فإذا قلتم: نتكلم أولا في إثبات حكمته فإذا ثبت بدليل منفصل ثم وجدنا هذه الأفعال المشتبهة الظاهر حملناها على ما يطابق ذلك فلا يؤدي إلى نقض ما علمنا ومتى لم يسلموا لنا حكمته انتقلت المسألة إلى الكلام في حكمته.","27/1/17/5",""],[6,16,"قلنا: مثل ذلك هاهنا من أن الكلام في غيبته فرع على إمامته، فإذا علمنا إمامته بدليل وعلمنا عصمته بدليل آخر وعلمناه غاب،حملنا غيبته على وجه يطابق عصمته فلا فرق بين الموضعين.","27/1/17/6",""],[7,16,"ثم يقال للمخالف في الغيبة: أتجوز أن يكون للغيبة سبب صحيح اقتضاها ووجه من الحكمة أوجبها أم لا تجوز ذلك؟فإن قال: يجوز ذلك.قيل له: فإذا كان ذلك جائزا فكيف جعلت وجود الغيبة دليلا على فقد الإمام في الزمان مع تجويزك لها سببا لا ينافي وجود الإمام؟ وهل يجري ذلك إلا مجرى من توصل بإيلام الأطفال إلى نفي حكمة الصانع تعالى وهو معترف بأنه يجوز أن يكون في إيلامهم وجه صحيح لا ينافي الحكمة؟ أو من توصل بظاهر الآيات المتشابهات إلى أنه تعالى مشبه للأجسام وخالق لأفعال العباد مع تجويزه أن يكون لها وجوه صحيحة توافق الحكمة والعدل والتوحيد ونفي التشبيه؟","27/1/17/7",""],[8,16,"وإن قال: لا أجوز ذلك، قيل: هذا تحجر شديد فيما لا يحاط بعلمه ولا يقطع على مثله، فمن أين قلت إن ذلك لا يجوز وانفصل ممن قال لا يجوز أن يكون للآيات المتشابهات وجوه صحيحة تطابق أدلة العقل ولا بد أن تكون على ظواهرها؟","27/1/17/8",""],[9,16,"ومتى قيل: نحن متمكنون من ذكر وجوه الآيات المتشابهات وأنتم لا تتمكنون من ذكر سبب صحيح للغيبة، قلنا: كلامنا على من يقول لا أحتاج إلى العلم بوجوه الآيات المتشابهات مفصلا بل يكفيني علم الجملة، ومتى تعاطيت ذلك كان تبرعا، وإن اقتنعتم لنفسكم بذلك فنحن أيضا نتمكن من ذكر وجه صحة الغيبة وغرض حكمي لا ينافي عصمته. وسنذكر ذلك فيما بعد، وقد تكلمنا عليه مستوفى في كتاب الإمامة.","27/1/17/9",""],[10,16,"ثم يقال: كيف يجوز أن يجتمع صحة إمامة ابن الحسن عليه السلام بما بيناه من سياقة الأصول العقلية مع القول بأن الغيبة لا يجوز أن يكون لها سبب صحيح؟ وهل هذا إلا تناقض ويجري مجرى القول بصحة التوحيد والعدل مع القطع على أنه لا يجوز أن يكون للآيات المتشابهات وجه يطابق هذه الأصول؟","27/1/17/10",""],[11,16,"ومتى قالوا: نحن لا نسلم إمامة ابن الحسن عليه السلام،كان الكلام معهم في ثبوت الإمامة دون الكلام في سبب الغيبة. وقد تقدمت الدلالة على إمامته عليه السلام بما لا يحتاج إلى إعادته. وإنما قلنا ذلك لأن الكلام في سبب غيبة الإمام عليه السلام فرع على ثبوت إمـامته، فأمـا قبل ثبوتها فلا وجه للكلام في سبب غيبته كما لا وجه للكلام في وجوه الآيات المتشابهات وإيلام الأطفال وحسن التعبد بالشرائع قبل ثبوت التوحيد والعدل.","27/1/17/11",""],[12,16,"فإن قيل: إلا كان السائل بالخيار بين الكلام في إمامة ابن الحسن عليه السلام ليعرف صحتها من فسادها وبين أن يتكلم في سبب الغيبة؟","27/1/17/12",""],[13,16,"قلنا: لا خيار في ذلك، لأن من شك في إمامة ابن الحسن عليه السلام يجب أن يكون الكلام معه في نص إمامته والتشاغل بالدلالة عليها، ولا يجوز مع الشك فيها أن نتكلم في سبب الغيبة لأن الكلام في الفروع لا يسوغ إلا بعد إحكام الأصول لها كما لا يجوز أن يتكلم في سبب إيلام الأطفال قبل ثبوت حكمة القديم تعالى وأنه لا يفعل القبيح، وإنما رجحنا الكلام في إمامته عليه السلام على الكلام في غيبته وسببها لأن الكلام في إمامته مبني على أمور عقلية لا يدخلها الاحتمال.","27/1/17/13",""],[14,16,"وسبب الغيبة ربما غمض واشتبه فصار الكلام في الواضح الجلي أولى من الكلام في المشتبه الغامض كما فعلناه مع المخالفين للملة فرجحنا الكلام في نبوة نبينا صلى الله عليه وآله وسلم على الكلام على ادعائهم تأبيد شرعهم لظهور ذلك وغموض هذا وهذا بعينه موجود هاهنا ومتى عادوا إلى أن يقولوا الغيبة فيها وجه من وجوه القبح فقد مضى الكلام عليه على أن وجوه القبح معقولة وهي كونه ظلما أو كذبا أو عبثا أو جهلا أو استفسادا وكل ذلك ليس بحاصل هاهنا فيجب أن لا يدعى فيه وجه القبح.","27/1/17/14",""],[15,16,"فإن قيل: إلا منع الله الخلق من الوصول إليه وحال بينهم وبينه ليقوم بالأمر ويحصل ما هو لطف لنا كما نقول في النبي صلى الله عليه وآله وسلم إذ بعثه الله تعالى فإن الله تعالى يمنع منه ما لم يؤد فكان يجب أن يكون حكم الإمام مثله.","27/1/17/15",""],[16,16,"قلنا: المنع على ضربين: أحدهما لا ينافي التكليف بأن لا يلجأ إلى ترك القبيح، والآخر يؤدي إلى ذلك.فالأول قد فعله الله تعالى من حيث منع من ظلمه بالنهي عنه والحث على وجوب طاعته والانقياد لأمره ونهيه وأن لا يعصى في شي‏ء من أوامره وأن يساعد على جميع ما يقوي أمـره ويشيد سلطانه فإن جميـع ذلك لا ينافي التكليـف فـإذا عصى من عصى في ذلك ولـم يفعل ما يتم معه الغرض المطلوب يكون قد أتى من قبل نفسه لا من قبل خالقه.والضرب الآخر أن يحول بينهم وبينه بالقهر والعجز عن ظلمه وعصيانه فذلك لا يصح اجتماعه مع التكليف فيجب أن يكون ساقطا.","27/1/17/16",""],[17,16,"فأما النبي صلى الله عليه وآله وسلم فإنما نقول: يجب أن يمنع الله منه حتى يؤدي الشرع لأنه لا يمكن أن يعلم ذلك إلا من جهته فلذلك وجب المنع منه. وليس كذلك الإمام، لأن علة المكلفين مزاحة فيما يتعلق بالشرع والأدلة منصوبة على ما يحتاجون إليه ولهم طريق إلى معرفتها من دون قوله، ولو فرضنا أنه ينتهي الحال إلى حد لا يعرف الحق من الشرعيات إلا بقوله لوجب أن يمنع الله تعالى منه ويظهره بحيث لا يوصل إليه مثل النبي صلى الله عليه وآله. ونظير مسألة الإمام أن النبي صلى الله عليه وآله وسلم إذا أدى ثم عرض فيما بعد ما يوجب خوفه لا يحب على الله تعالى المنع منه لأن علة المكلفين قد انزاحت بما أداه إليهم فلهم طريق إلى معرفة لطفهم.اللهم إلا أن يتعلق به أداء آخر في المستقبل فإنه يجب المنع منه كما يجب في الابتداء فقد سوينا بين النبي والإمام.","27/1/17/17",""],[18,16,"فإن قيل: بينوا، على كل حال، وإن لم يجب عليكم،وجه علة الاستتار وما يمكن أن يكون علة على وجه ليكون أظهر في الحجة وأبلغ في باب البرهان.","27/1/17/18",""],[19,16,"قلنا: مما يقطع على أنه سبب لغيبة الإمام هو خوفه على نفسه بالقتل بإخافة الظالمين إياه ومنعهم إياه من التصرف فيما جعل إليه التدبير والتصرف فيه. فإذا حيل بينه وبين مراده سقط فرض القيام بالإمامة. وإذا خاف على نفسه وجبت غيبته ولزم استتاره كما استتر النبي صلى الله عليه وآله وسلم تارة في الشعب وأخرى في الغار،ولا وجه لذلك إلا الخوف من المضار الواصلة إليه. وليس لأحد أن يقول إن النبي صلى الله عليه وآله وسلم ما استتر عن قومه إلا بعد أدائه إليهم ما وجب عليه أداؤه ولم يتعلق بهم إليه حاجة وقولكم في الإمام بخلاف ذلك، وأيضا فإن استتار النبي صلى الله عليه وآله وسلم ما طال ولا تمادى،واستتار الإمام قد مضت عليه الدهور وانقرضت عليه العصور.","27/1/17/19",""],[20,16,"وذلك أنه ليس الأمر على ما قالوه، لأن النبي صلى الله عليه وآله وسلم إنما استتر في الشعب والغار بمكة قبل الهجرة وما كان أدى جميع الشريعة، فإن أكثر الأحكام ومعظم القرآن نزل بالمدينة فكيف أوجبتم أنه كان بعد الأداء؟ ولو كان الأمر على ما قالوه من تكامل الأداء قبل الاستتار لما كان ذلك رافعا للحاجة إلى تدبيره وسياسته وأمره ونهيه،فإن أحدا لا يقول إن النبي صلى الله عليه وآله وسلم بعد أداء الشرع غير محتاج إليه ولا مفتقر إلى تدبيره ولا يقول ذلك معاند. وهو الجواب عن قول من قال إن النبي صلى الله عليه وآله وسلم ما يتعلق من مصلحتنا قد أداه وما يؤدي في المستقبل لم يكن في الحال مصلحة للخلق فجاز لذلك الاستتار وليس كذلك الإمام عندكم، لأن تصرفه في كل حال لطف للخلق فلا يجوز له الاستتار على وجه ووجب تقويته والمنع منه ليظهر ويزاح علة المكلف، لأنا قد بينا أن النبي صلى الله عليه وآله وسلم مع أنه أدى المصلحة التي تعلقت بتلك الحال فلم يستغن عن أمره ونهيه وتدبيره بلا خلاف بين المحصلين، ومع هذا جاز له الاستتار فكذلك الإمام. على أن أمر الله تعالى له بالاستتار بالشعب تارة وفي الغار أخرى ضرب من المنع منه لأنه ليس كل المنع أن يحول بينهم وبينه بالعجز أو بتقويته بالملائكة، لأنه لا يمتنع أن يفرض في تقويته بذلك مفسدة في الدين، فلا يحسن من الله تعالى فعله، ولو كان خاليا من وجوه الفساد،وعلم الله تعالى أنه تقتضيه المصلحة لقواه بالملائكة وحال بينهم وبينه فلما لم يفعل ذلك مع ثبوت حكمته ووجوب إزاحة علة المكلفين علمنا أنه لم يتعلق به مصلحة بل مفسدة. وكذلك نقول في الإمام عليه السلام إن الله تعالى منع من قتله بأمره بالاستتار والغيبة، ولو علم أن المصلحة تتعلق بتقويته بالملائكة لفعل،فلما لم يفعل مع ثبوت حكمته ووجوه إزاحة علة المكلفين في التكليف علمنا أنه لم يتعلق به مصلحة بل ربما كان فيه مفسدة. بل الذي نقول إن في الجملة يجب على الله تعالى تقوية يد الإمام بما يتمكن معه من القيام ويبسط يده ويمكن ذلك بالملائكة وبالبشر، فإذا لم يفعله بالملائكة علمنا أنه لأجل أنه تعلق به مفسدة فوجب أن يكون متعلقا بالبشر،فإذا لم يفعلوه أتوا من قبل نفوسهم لا من قبله تعالى. فيبطل بهذا التحرير جميع ما يورد من هذا الجنس. وإذا جاز في النبي صلى الله عليه وآله وسلم أن يستتر مع الحاجة إليه لخوف الضرر وكانت التبعة في ذلك لازمة لمخيفية ومحوجية إلى الغيبة فكذلك غيبة الإمام عليه السلام سواء. فأما التفرقة بطول الغيبة وقصرها فغير صحيحة لأنه لا فرق في ذلك بين القصير المنقطع والطويل الممتد لأنه إذا لم يكن في الاستتار لائمة على المستتر إذا أحوج إليه بل اللائمة على من أحوجه إليها جاز أن يتطاول سبب الاستتار كما جاز أن يقصر زمانه.","27/1/17/20",""],[21,16,"فإن قيل: إذا كان الخوف أحوجه إلى الاستتار فقد كان آباؤه عليه السلام عندكم على تقية وخوف من أعدائهم فكيف لم يستتروا؟","27/1/17/21",""],[22,16,"قلنا: ما كان على آبائه عليهم السلام خوف من أعدائهم مع لزوم التقية والعدول عن التظاهر بالإمامة ونفيها عن نفوسهم، وإمام الزمان عليه السلام كل الخوف عليه لأنه يظهر بالسيف ويدعو إلى نفسه ويجاهد من خالفه عليه فأي نسبة بين خوفه من الأعداء وخوف آبائه عليهم السلام لو لا قلة التأمل. على أن آباءه عليهم السلام متى قتلوا أو ماتوا كان هناك من يقوم مقامهم ويسد مسدهم يصلح للإمامة من أولاده وصاحب الأمر عليه السلام بالعكس من ذلك،لأن من المعلوم أنه لا يقوم أحد مقامه ولا يسد مسده فبان الفرق بين الأمرين.","27/1/17/22",""],[1,17,"وقد بينا فيما تقدم الفرق بين وجوده غائبا لا يصل إليه أحد أو أكثرهم وبين عدمه حتى إذا كان المعلوم التمكن بالأمر يوجده.","27/1/18/1",""],[2,17,"وكذلك قولهم: ما الفرق بين وجوده بحيث لا يصل إليه أحد وبين وجوده في السماء؟ بأن قلنا إذا كان موجودا في السماء بحيث لا يخفى عليه أخبار أهل الأرض فالسماء كالأرض وإن كان يخفى عليه أمرهم فذلك يجري مجرى عدمه ثم نقلب عليهم في النبي صلى الله عليه وآله وسلم بأن يقال أي فرق بين وجوده مستترا وبين عدمه وكونه في السماء،فأي شي‏ء قالوه قلنا مثله على ما مضى القول فيه. وليس لهم أن يفرقوا بين الأمرين بأن النبي صلى الله عليه وآله وسلم ما استتر من كل أحد وإنما استتر من أعدائه وإمام الزمان مستتر عن الجميع.","27/1/18/2",""],[3,17,"لأنا أولاً لا نقطع على أنه مستتر عن جميع أوليائه،والتجويز في هذا الباب كاف. على أن النبي صلى الله عليه وآله وسلم لما استتر في الغار كان مستترا من أوليائه وأعدائه ولم يكن معه إلا أبو بكر وحده،وقد كان يجوز أن يستتر بحيث لا يكون معه أحد من ولي ولا عدو إذا اقتضت المصلحة ذلك.","27/1/18/3",""],[1,18,"فإن قيل: فالحدود في حال الغيبة ما حكمها؟ فإن سقطت عن الجاني على ما يوجبها الشرع فهذا نسخ الشريعة وإن كانت باقية فمن يقيمها؟","27/1/19/1",""],[2,18,"قلنا: الحدود المستحقة باقية في جنوب مستحقيها، فإن ظهر الإمام ومستحقوها باقون أقامها عليهم بالبينة أو الإقرار،وإن كان فات ذلك بموته كان الإثم في تفويتها على من أخاف الإمام وألجأه إلى الغيبة. وليس هذا نسخا لإقامة الحدود لأن الحد إنما يجب إقامته مع التمكن وزوال المنع ويسقط مع الحيلولة، وإنما يكون ذلك نسخا لو سقط إقامتها مع الإمكان وزوال الموانع.","27/1/19/2",""],[3,18,"ويقال لهم: ما يقولون في الحال التي لا يتمكن أهل الحل والعقد من اختيار الإمام، ما حكم الحدود؟ فإن قلتم: سقطت، فهذا نسخ على ما ألزمتمونا.وإن قلتم: هي باقية في جنوب مستحقيها، فهو جوابنا بعينه.","27/1/19/3",""],[4,18,"فإن قيل: قد قال أبو علي إن في الحال التي لا يتمكن أهل الحل والعقد من نصب الإمام يفعل الله ما يقوم مقام إقامة الحدود ويزاح علة المكلف. وقال أبو هاشم: إن إقامة الحدود دنياوية لا تعلق لها بالدين.","27/1/19/4",""],[5,18,"قلنـا: أمـا مـا قـاله أبو علي فلو قلنـا مثله ما ضرنا لأن إقامة الحدود ليس هو الذي لأجله أوجبنا الإمام حتى إذا فات إقامته انتقض دلالة الإمامة،بل ذلك تابع للشرع. وقد قلنا إنه لا يمتنع أن يسقط فرض إقامتها في حال انقباض يد الإمام أو تكون باقية في جنوب أصحابها،وكما جاز ذلك جاز أيضا أن يكون هناك ما يقوم مقامها فإذا صرنا إلى ما قاله لم ينتقض علينا أصل.","27/1/19/5",""],[6,18,"وأما ما قاله أبو هاشم من أن ذلك لمصالح الدنيا، فبعيد لأن ذلك عبادة واجبة ولو كان لمصلحة دنياوية لما وجبت. على أن إقامة الحدود عنده على وجه الجزاء، والنكال جزء من العقاب، وإنما قدم في دار الدنيا بعضه لما فيه من المصلحة، فكيف يقول مع ذلك أنه لمصالح دنياوية؟ فبطل ما قالوه.","27/1/19/6",""],[1,19,"فإن قيل: كيف الطريق إلى إصابة الحق مع غيبة الإمام؟فإن قلتم: لا سبيل إليها،جعلتم الخلق في حيرة وضلالة وشك في جميع أمورهم.وإن قلتم: يصاب الحق بأدلته،قيل لكم هذا تصريح بالاستغناء عن الإمام بهذه الأدلة.","27/1/20/1",""],[2,19,"قلنا: الحق على ضربين؛ عقلي وسمعي. فالعقلي يصاب بأدلته والسمعي عليه أدلة منصوبة من أقوال النبي صلى الله عليه وآله وسلم ونصوصه وأقوال الأئمة عليهم السلام من ولده، وقد بينوا ذلك وأوضحوه ولم يتركوا منه شيئا لا دليل عليه.","27/1/20/2",""],[3,19,"غير أن هذا وإن كان على ما قلناه فالحاجة إلى الإمام قد بينا ثبوتها لأن جهة الحاجة إليه المستمرة في كل حال وزمان كونه لطفا لنا على ما تقدم القول فيه ولا يقوم غيره مقامه فالحاجة المتعلقة بالسمع أيضا ظاهرة لأن النقل وإن كان واردا عن الرسول صلى الله عليه وآله وسلم وعن آباء الإمام عليهم السلام بجميع ما يحتاج إليه في الشريعة فجائز على الناقلين العدول عنه إما تعمدا وإما لشبهة فينقطع النقل أو يبقى فيمن لا حجة في نقله. وقد استوفينا هذه الطريقة في تلخيص الشافي فلا نطول بذكرها الكتاب.","27/1/20/3",""],[4,19,"فإن قيل: لو فرضنا أن الناقلين كتم بعض منهم بعض الشريعة واحتيج إلى بيان الإمام ولم يعلم الحق إلا من جهته وكان خوف القتل من أعدائه مستمرا كيف يكون الحال؟","27/1/20/4",""],[5,19,"فإن قلتم: يظهر وإن خاف القتل، فيجب أن يكون خوف القتل غير مبيح له الاستتار ويلزم ظهوره. وإن قلتم: لا يظهر وسقط التكليف في ذلك الشي‏ء المكتوم عن الأمة،خرجتم من الإجماع لأنه منعقد على أن كل شي‏ء شرعه النبي صلى الله عليه وآله وسلم وأوضحه فهو لازم للأمة إلى أن تقوم الساعة. وإن قلتم: إن التكليف لا يسقط،صرحتم بتكليف ما لا يطاق وإيجاب العمل بما لا طريق إليه.","27/1/20/5",""],[6,19,"قلنا: قد أجبنا عن هذا السؤال في التلخيص مستوفى،وجملته إن الله تعالى لو علم أن النقل ببعض الشرع المفروض ينقطع في حال يكون تقية الإمام فيها مستمرة وخوفه من الأعداء باقيا لأسقط ذلك عمن لا طريق له إليه. فإذا علمنا بالإجماع أن تكليف الشرع مستمر ثابت على جميع الأمة إلى قيام الساعة علمنا عند ذلك أنه لو اتفق انقطاع النقل بشي‏ء من الشرع لما كان ذلك إلا في حال يتمكن فيها الإمام عليه السلام من الظهور والبروز والإعلام والإنذار.","27/1/20/6",""],[1,20,"وكان المرتضى رحمه الله يقول أخيرا لا يمتنع أن يكون هاهنا أمور كثيرة غير واصلة إلينا هي مودعة عند الإمام عليه السلام وإن كان قد كتمها الناقلون ولم ينقلوها ولم يلزم مع ذلك سقوط التكليف عن الخلق لأنه إذا كان سبب الغيبة خوفه على نفسه من الذين أخافوه فمن أحوجه إلى الاستتار أتى من قبل نفسه في فوت ما يفوته من الشرع، كما أنه أتى من قبل نفسه فيما يفوته من تأديب الإمام وتصرفه من حيث أحوجه إلى الاستتار ولو زال خوفه لظهر فيحصل له اللطف بتصرفه وتبين له ما عنده مما انكتم عنه فإذا لم يفعل وبقي مستترا أتى من قبل نفسه في الأمرين،وهذا قوي تقتضيه الأصول.","27/1/21/1",""],[1,21,"وفي أصحابنا من قال إن علة الاستتار عن أوليائه خوفه من أن يشيعوا خبره ويتحدثوا باجتماعهم معه سرورا به،فيؤدي ذلك إلى الخوف من الأعداء وإن كان غير مقصود. وهذا الجواب يضعف، لأن عقلاء شيعته لا يجوز أن يخفى عليهم ما في إظهار اجتماعهم معه من الضرر عليه وعليهم،فكيف يخبرون بذلك العامة مع علمهم بما عليه وعليهم فيه من المضرة العامة وإن جاز هذا على الواحد والاثنين لا يجوز على جماعة شيعته الذين لا يظهر لهم. على أن هذا يلزم عليه أن يكون شيعته قد عدموا الانتفاع به على وجه لا يتمكنون من تلافيه وإزالته لأنه إذا علق الاستتار بما يعلم من حالهم أنهم يفعلونه فليس في مقدورهم الآن ما يقتضي من ظهور الإمام عليه السلام وهذا يقتضي سقوط التكليف الذي الإمام لطف فيه عنهم وفي أصحابنا من قال علة استتاره عن الأولياء ما يرجع إلى الأعداء لأن انتفاع جميع الرعية من ولي وعدو بالإمام إنما يكون بأن ينفذ أمره ببسط يده فيكون ظاهرا متصرفا بلا دافع ولا منازع. وهذا مما المعلوم أن الأعداء قد حالوا دونه ومنعوا منه.","27/1/22/1",""],[2,21,"قالوا: ولا فائدة في ظهوره سرا لبعض أوليائه لأن النفع المبتغى من تدبير الأمة لا يتم إلا بظهوره للكل ونفوذ الأمر، فقد صارت العلة في استتار الإمام على الوجه الذي هو لطف ومصلحة للجميع واحدة.","27/1/22/2",""],[3,21,"ويمكن أن يعترض هذا الجواب بأن يقال: إن الأعداء وإن حالوا بينه وبين الظهور على وجه التصرف والتدبير فلم يحولوا بينه وبين لقاء من شاء من أوليائه على سبيل الاختصاص وهو يعتقد طاعته ويوجب اتباع أوامره، فإن كان لا نفع في هذا اللقاء لأجل الاختصاص لأنه غير نافذ الأمر للكل فهذا تصريح بأنه لا انتفاع للشيعة الإمامية بلقاء أئمتها من لدن وفاة أمير المؤمنين إلى أيام الحسن بن علي أبي القائم عليه السلام لهذه العلة. ويوجب أيضا أن يكون أولياء أمير المؤمنين عليه السلام وشيعته لم يكن لهم بلقائه انتفاع قبل انتقال الأمر إلى تدبيره وحصوله في يده وهذا بلوغ من قائله إلى حد لا يبلغه متأمل. على أنه لو سلم أن الانتفاع بالإمام لا يكون إلا مع الظهور لجميع الرعية ونفوذ أمره فيهم لبطل قولهم من وجه آخر، وهو أنه يؤدي إلى سقوط التكليف الذي الإمام لطف فيه عن شيعته لأنه إذا لم يظهر لهم لعلة لا يرجع إليهم ولا كان في قدرتهم وإمكانهم إزالته فلا بد من سقوط التكليف عنهم، لأنه لو جـاز أن يمنع قوم من المكلفين غيـرهم لطفهم ويكـون التكليف الذي ذلك اللطف لطف فيه مستمرا عليهم لجاز أن يمنع بعض المكلفين غيره بقيد وما أشبهه من المشي على وجه لا يمكن من إزالته ويكون تكليف المشي مع ذلك مستمرا على الحقيقة.","27/1/22/3",""],[4,21,"وليس لهم أن يفرقوا بين القيد وبين اللطف من حيث كان القيد يتعذر معه الفعل ولا يتوهم وقوعه وليس كذلك فقد اللطف لأن أكثر أهل العدل على أن فقد اللطف كفقد القدرة والآلة وأن التكليف مع فقد اللطف فيمن له لطف معلوم كالتكليف مع فقد القدرة والآلة ووجود الموانع وأن من لم يفعل له اللطف ممن له لطف معلوم غير مزاح العلة في التكليف كما أن الممنوع غير مزاح العلة.","27/1/22/4",""],[5,21,"والذي ينبغي أن يجاب عن السؤال الذي ذكرناه عن المخالف أن نقول إنا أولا لا نقطع على استتاره عن جميع أوليائه بل يجوز أن يظهر لأكثرهم ولا يعلم كل إنسان إلا حال نفسه فإن كان ظاهرا له فعلته مزاحة،وإن لم يكن ظاهرا له علم أنه إنما لم يظهر له لأمر يرجع إليه وإن لم يعلمه مفصلا لتقصير من جهته وإلا لم يحسن تكليفه.","27/1/22/5",""],[6,21,"فإذا علم بقاء تكليفه عليه واستتار الإمام عنه علم أنه لأمر يرجع إليه كما تقوله جماعتنا فيمن لم ينظر في طريق معرفة الله تعالى فلم يحصل له العلم وجب أن يقطع على أنه إنما لم يحصل لتقصير يرجع إليه وإلا وجب إسقاط تكليفه وإن لم يعلم ما الذي وقع تقصيره فيه.","27/1/22/6",""],[7,21,"فعلى هذا التقرير أقوى ما يعلل به ذلك إن الإمام إذا ظهر ولا يعلم شخصه وعينه من حيث المشاهدة فلا بد من أن يظهر عليه علم معجز يدل على صدقه والعلم بكون الشي‏ء معجزا يحتاج إلى نظر يجوز أن يعترض فيه شبهه فلا يمتنع أن يكون المعلوم من حال من لم يظهر له أنه متى ظهر وأظهر المعجز لم ينعم النظر فيدخل عليه فيه شبهة فيعتقد أنه كذاب ويشيع خبره فيؤدي إلى ما تقدم القول فيه.","27/1/22/7",""],[8,21,"فإن قيل: أي تقصير وقع من الولي الذي لم يظهر له الإمام لأجل هذا المعلوم من حاله وأي قدرة له على النظر فيما يظهر له الإمام معه وإلى أي شي‏ء يرجع في تلافي ما يوجب غيبته؟","27/1/22/8",""],[9,21,"قلنا: ما أحلنا في سبب الغيبة عن الأولياء إلا على معلوم يظهر موضع التقصير فيه وإمكان تلافيه لأنه غير ممتنع أن يكون من المعلوم من حاله أنه متى ظهر له الإمام قصر في النظر في معجزة فإنما أتى في ذلك لتقصيره الحاصل في العلم بالفرق بين المعجز والممكن والدليل من ذلك والشبهة ولو كان من ذلك على قاعدة صحيحة لم يجز أن يشتبه عليه معجز الإمام عند ظهوره له فيجب عليه تلافي هذا التقصير واستدراكه.","27/1/22/9",""],[10,21,"وليس لأحد أن يقول هذا تكليف لما لا يطاق وحوالة على غيب لأن هذا الولي ليس يعرف ما قصر فيه بعينه من النظر والاستدلال فيستدركه حتى يتمهد في نفسه ويتقرر ونراكم تلزمونه ما لا يلزمه وذلك أن ما يلزم في التكليف قد يتميز تارة ويشتبه أخرى بغيره وإن كان التمكن من الأمرين ثابتا حاصلا. فالولي على هذا إذا حاسب نفسه ورأى أن الإمام لا يظهر له وأفسد أن يكون السبب في الغيبة ما ذكرناه من الوجوه الباطلة وأجناسها علم أنه لا بد من سبب يرجع إليه،وإذا علم أن أقوى العلل ما ذكرناه علم أن التقصير واقع من جهته في صفات المعجز وشروطه فعليه معاودة النظر في ذلك عند ذلك وتخليصه من الشوائب وما يوجب الالتباس فإنه من اجتهد في ذلك حق الاجتهاد ووفى النظر شروطه فإنه لا بد من وقوع العلم بالفرق بين الحق والباطل وهذه المواضع الإنسان فيها على نفسه بصيرة وليس يمكن أن يؤمر فيها بأكثر من التناهي في الاجتهاد والبحث والفحص والاستسلام للحق. وقد بينا أن هذا نظير ما نقول لمخالفينا إذا نظروا في أدلتنا ولم يحصل لهم العلم سواء.","27/1/22/10",""],[11,21,"فإن قيل: لو كان الأمر على ما قلتم لوجب أن لا يعلم شيئا من المعجزات في الحال وهذا يؤدي إلى أن لا يعلم النبوة وصدق الرسول وذلك يخرجه عن الإسلام فضلا عن الإيمان.","27/1/22/11",""],[12,21,"قلنا: لا يلزم ذلك لأنه لا يمتنع أن تدخل الشبهة في نوع من المعجزات دون نوع وليس إذا دخلت الشبهة في بعضها دخل في سائرها فلا يمتنع أن يكون المعجز الدال على النبوة لم تدخل عليه فيه شبهة فحصل له العلم بكونه معجزا وعلم عند ذلك نبوة النبي صلى الله عليه وآله وسلم والمعجز الذي يظهر على يد الإمام إذا ظهر يكون أمرا آخرا يجوز أن يدخل عليه الشبهة في كونه معجزا فيشك حينئذ في إمامته وإن كان عالما بالنبوة.","27/1/22/12",""],[13,21,"وهذا كما نقول إن من علم نبوة موسى عليه السلام بالمعجزات الدالة على نبوته إذا لم ينعم النظر في المعجزات الظاهرة على عيسى ونبينا محمد صلى الله عليه وآله وسلم لا يجب أن يقطع على أنه ما عرف تلك المعجزات لأنه لا يمتنع أن يكون عارفا بها وبوجه دلالتها وإن لم يعلم هذه المعجزات واشتبه عليه وجه دلالتها.","27/1/22/13",""],[14,21,"فإن قيل: فيجب على هذا أن يكون كل من لم يظهر له الإمام يقطع على أنه على كبيرة يلحق بالكفر لأنه مقصر على ما فرضتموه فيما يوجب غيبة الإمام عنه ويقتضي فوت مصلحته فقد لحق الولي على هذا بالعدو.","27/1/22/14",""],[15,21,"قلنا: ليس يجب في التقصير الذي أشرنا إليه أن يكون كفرا ولا ذنبا عظيما لأنه في هذه الحال ما اعتقد في الإمام أنه ليس بإمام ولا أخافه على نفسه وإنما قصر في بعض العلوم تقصيرا كان كالسبب في أن علم من حاله أن ذلك الشك في الإمامة يقع منه مستقبلا والآن فليس بواقع فغير لازم أن يكون كافرا غير أنه وإن لم يلزم أن يكون كفرا ولا جاريا مجرى تكذيب الإمام والشك في صدقه فهو ذنب وخطأ لا ينافيان الإيمان واستحقاق الثواب ولو لم يلحق الولي بالعدو على هذا التقدير لأن العدو في الحال معتقد في الإمام ما هو كفر وكبيرة والولي بخلاف ذلك.","27/1/22/15",""],[16,21,"وإنما قلنا إن ما هو كالسبب في الكفر لا يجب أن يكون كفرا في الحال أن أحدا لو اعتقد في القادر منا بقدرة أنه يصح أن يفعل في غيره من الأجسام مبتدئا كان ذلك خطأ وجهلا ليس بكفر ولا يمتنع أن يكون المعلوم من حال هذا المعتقد أنه لو ظهر نبي يدعو إلى نبوته وجعل معجزة أن يفعل الله تعالى على يده فعلا بحيث لا يصل إليه أسباب البشر أنه لا يقبله وهذا لا محالة لو علم أنه معجز كان يقبله وما سبق من اعتقاده في مقدور القدر كان كالسبب في هذا ولم يلزم أن يجري مجراه في الكفر.","27/1/22/16",""],[17,21,"فإن قيل: إن هذا الجواب أيضا لا يستمر على أصلكم لأن الصحيح من مذهبكم أن من عرف الله تعالى بصفاته وعرف النبوة والإمامة وحصل مؤمنا لا يجوز أن يقع منه كفر أصلا فإذا ثبت هذا فكيف يمكنكم أن تجعلوا علة الاستتار عن الولي أن المعلوم من حاله أنه إذا ظهر الإمام فظهر على يده علم معجز شك فيه ولا يعرفه إماما وإن الشك في ذلك كفر وذلك ينقض أصلكم الذي صححتموه.","27/1/22/17",""],[18,21,"قيل: هذا الذي ذكرتموه ليس بصحيح لأن الشك مع المعجز الذي يظهر على يد الإمام ليس بقادح في معرفته لغير الإمام على طريق الجملة وإنما يقدح في أن ما علم على طريق الجملة وصحت معرفته هل هو هذا الشخص أم لا والشك في هذا ليس بكفر لأنه لو كان كفرا لوجب أن يكون كفرا وإن لم يظهر المعجز فإنه لا محالة قبل ظهور هذا المعجز في يده شاك فيه ويجوز كونه إماما وكون غيره كذلك وإنما يقدح في العلم الحاصل له على طريق الجملة أن لو شك في المستقبل في إمامته على طريق الجملة وذلك مما يمنع من وقوعه منه مستقبلا.","27/1/22/18",""],[19,21,"وكان المرتضى رضي الله عنه يقول: سؤال المخالف لنا لم لا يظهر الإمام للأولياء غير لازم لأنه إن كان غرضه أن لطف الولي غير حاصل فلا يحصل تكليفه فإنه لا يتوجه فإن لطف الولي حاصل لأنه إذا علم الولي أن له إماما غائبا يتوقع ظهوره عليه السلام ساعة ساعة ويجوز انبساط يده في كل حال فإن خوفه من تأديبه حاصل وينزجر لمكانه عن المقبحات ويفعل كثيرا من الواجبات فيكون حال غيبته كحال كونه في بلد آخر بل ربما كان في حال الاستتار أبلغ لأنه مع غيبته يجوز أن يكون معه في بلده وفي جواره ويشاهده من حيث لا يعرفه ولا يقف على أخباره وإذا كان في بلد آخر ربما خفي عليه خبره فصار حال الغيبة والانزجار حاصلا عن القبيح على ما قلناه.","27/1/22/19",""],[1,22,"وإذا لم يكن قد فاتهم اللطف جاز استتاره عنهم وإن سلم أنه يحصل ما هو لطف لهم ومع ذلك يقال لم لا يظهر لهم قلنا ذلك غير واجب على كل حال فسقط السؤال من أصله. على أن لطفهم بمكانه حاصل من وجه آخر وهو أن لمكانه يثقون بوصول جميع الشرع إليهم ولولاه لما وثقوا بذلك وجوزوا أن يخفى عليهم كثير من الشرع وينقطع دونهم وإذا علموا وجوده في الجملة أمنوا جميع ذلك فكان اللطف بمكانه حاصلا من هذا الوجه أيضا. وقد ذكرنا فيما تقدم أن ستر ولادة صاحب الزمان عليه السلام ليس بخارق للعادات إذ جرى أمثال ذلك فيما تقدم من أخبار الملوك،وقد ذكره العلماء من الفرس ومن روى أخبار الدولتين. من ذلك ما هو مشهور كقصة كيخسرو وما كان من ستر أمه حملها وإخفاء ولادتها وأمه بنت ولد أفراسياب ملك الترك وكان جده كيقاوس أراد قتل ولده فسترته أمه إلى أن ولدته وكان من قصته ما هو مشهور في كتب التواريخ ذكره الطبري.","27/1/23/1",""],[2,22,"وقد نطق القرآن بقصة إبراهيم عليه السلام وأن أمه ولدته خفيا وغيبته في المغارة حتى بلغ وكان من أمره ما كان. وما كان من قصة موسى عليه السلام فإن أمه ألقته في البحر خوفا عليه وإشفاقا من فرعون عليه وذلك مشهور نطق به القرآن. ومثل ذلك قصة صاحب الزمان عليه السلام سواء، فكيف يقال إن هذا خارج عن العادات؟ ومن الناس من يكون له ولد من جارية يستتر بها من زوجته برهة من الزمان حتى إذا حضرته الوفاة أقر به.","27/1/23/2",""],[3,22,"وفي الناس من يستر أمر ولده خوفا من أهله أن يقتلوه طمعا في ميراثه.قد جرت العادات بذلك فلا ينبغي أن يتعجب من مثله في صاحب الزمان عليه السلام. وقد شاهدنا من هذا الجنس كثيرا وسمعنا منه غير قليل فلا نطول بذكره لأنه معلوم بالعادات. وكم وجدنا من ثبت نسبه بعد موت أبيه بدهر طويل ولم يكن أحد يعرفه إذا شهد بنسبة رجلان مسلمان ويكون الأب أشهدهما على نفسه سترا عن أهله وخوفا من زوجته وأهله فوصى به فشهدا بعد موته أو شهدا بعقده على امرأة عقدا صحيحا فجاءت بولد يمكن أن يكون منه فوجب بحكم الشرع إلحاقه به. والخبر بولادة ابن الحسن عليه السلام وارد من جهات أكثر مما يثبت به الأنساب في الشرع. ونحن نذكر طرفا من ذلك فيما بعد إن شاء الله تعالى.[b]","27/1/23/3",""],[4,22,"وأما إنكار جعفر بن علي عم صاحب الزمان عليه السلام شهادة الإمامية بولد لأخيه الحسن بن علي ولد في حياته ودفعه بذلك وجوده بعده وأخذه تركته وحوزه ميراثه وما كان منه في حمل سلطان الوقت على حبس جواري الحسن عليه السلام واستبدالهن بالاستبراء لهن من الحمل ليتأكد نفيه لولد أخيه وإباحته دماء شيعتهم بدعواهم خلفا له بعده كان أحق بمقامه فليس بشبهة يعتمد على مثلها أحد من المحصلين لاتفاق الكل على أن جعفرا لم يكن له عصمة كعصمة الأنبياء فيمتنع عليه لذلك إنكار حق ودعوى باطل؛ بل الخطأ جائز عليه والغلط غير ممتنع منه.","27/1/23/4",""],[5,22,"وقد نطق القرآن بما كان من ولد يعقوب عليه السلام مع أخيهم يوسف عليه السلام وطرحهم إياه في الجب وبيعهم إياه بالثمن البخس وهم أولاد الأنبياء وفي الناس من يقول كانوا أنبياء. فإذا جاز منهم مثل ذلك مع عظم الخطإ فيه فلم لا يجوز مثله من جعفر بن علي مع ابن أخيه وأن يفعل معه من الجحد طمعا في الدنيا ونيلها وهل يمنع من ذلك أحد إلا مكابر معاند.","27/1/23/5",""],[6,22,"فإن قيل: كيف يجوز أن يكون للحسن بن علي عليه السلام ولد مع إسناده وصيته في مرضه الذي توفي فيه إلى والدته المسماة بحديث المكناة بأم الحسن بوقوفه وصدقاته وأسند النظر إليها في ذلك ولو كان له ولد لذكره في الوصية؟","27/1/23/6",""],[7,22,"قيل: إنما فعل ذلك قصدا إلى تمام ما كان غرضه في إخفاء ولادته وستر حاله عن سلطان الوقت ولو ذكر ولده أو أسند وصيته إليه لناقض غرضه خاصة وهو احتاج إلى الإشهاد عليها وجوه الدولة وأسباب السلطان وشهود القضاة ليتحرس بذلك وقوفه ويتحفظ صدقاته ويتم به السترعلى ولده بإهمال ذكره وحراسة مهجته بترك التنبيه على وجوده. ومن ظن أن ذلك دليل على بطلان دعوى الإمامية في وجود ولد للحسن عليه السلام كان بعيدا من معرفة العادات. وقد فعل نظير ذلك الصـادق جعفـر بن محمد عليه السلام حين أسند وصيته إلى خمسة نفر أولهم المنصور إذ كان سلطان الوقت ولم يفرد ابنه موسى عليه السلام بها إبقاء عليه وأشهد معه الربيع وقاضي الوقت وجاريته أم ولده حميدة البربرية وختمهم بذكر ابنه موسى بن جعفر عليه السلام لستر أمره وحراسة نفسه ولم يذكر مع ولده موسى أحدا من أولاده الباقين لعلمه كان فيهم من يدعي مقامه من بعده ويتعلق بإدخاله في وصيته،ولو لم يكن موسى عليه السلام ظاهرا مشهورا في أولاده معروف المكان منه وصحة نسبه واشتهار فضله وعلمه وكان مستورا لما ذكره في وصيته ولاقتصر على ذكر غيره كما فعل الحسن بن علي والد صاحب الزمان عليه السلام.","27/1/23/7",""],[8,22,"فإن قيل: قولكم أنه منذ ولد صاحب الزمان عليه السلام إلى وقتنا هذا مع طول المدة لا يعرف أحد مكانه ولا يعلم مستقره ولا يأتي بخبره من يوثق بقوله خارج عن العادة،لأن كل من اتفق له الاستتار عن ظالم لخوف منه على نفسه أو لغير ذلك من الأغراض يكون مدة استتاره قريبة ولا يبلغ عشرين سنة ولا يخفى أيضا على الكل في مدة استتارة مكانه ولا بد من أن يعرف فيه بعض أوليائه وأهل مكانه أو يخبر بلقائه وقولكم بخلاف ذلك.","27/1/23/8",""],[9,22,"قلنا: ليس الأمر على ما قلتم، لأن الإمامية تقول إن جماعة من أصحاب أبي محمد الحسن بن علي عليه السلام قد شاهدوا وجوده في حياته وكانوا أصحابه وخاصته بعد وفاته والوسائط بينه وبين شيعته معروفون، ربما ذكرناهم فيما بعد، ينقلون إلى شيعته معالم الدين ويخرجون إليهم أجوبته في مسائلهم فيه ويقبضون منهم حقوقه وهم جماعة كان الحسن بن علي عليهما السلام عد لهم في حياته واختصهم أمناء له في وقته وجعل إليهم النظر في أملاكه والقيام بأموره بأسمائهم وأنسابهم وأعيانهم،كأبي عمرو عثمان بن سعيد السمان وابنه أبي جعفر محمد بن عثمان بن سعيد وغيرهم ممن سنذكر أخبارهم فيما بعد إن شاء الله تعالى. وكانوا أهل عقل وأمانة وثقة ظاهرة ودراية وفهم وتحصيل ونباهة،وكانوا معظمين عند سلطان الوقت لعظم أقدارهم وجلالة محلهم مكرمين لظاهر أمانتهم واشتهار عدالتهم حتى أنه كان يدفع عنهم ما يضيفه إليهم خصومهم. وهذا يسقط قولهم أن صاحبكم لم يره أحد ودعواهم خلافه.","27/1/23/9",""],[10,22,"فأما بعد انقراض أصحاب أبيه فقد كان مدة من الزمان أخباره واصلة من جهة السفراء الذين بينه وبين شيعته ويوثق بقولهم ويرجع إليهم لدينهم وأمانتهم وما اختصوا به من الدين والنزاهة وربما ذكرنا طرفا من أخبارهم فيما بعد.","27/1/23/10",""],[11,22,"وقد سبق الخبر عن آبائه عليه السلام بأن القائم عليه السلام له غيبتان؛أخراهما أطول من الأولى. فالأولى يعرف فيها خبره،والأخرى لا يعرف فيها خبره. فجاء ذلك موافقا لهذه الأخبار فكان ذلك دليلا ينضاف إلى ما ذكرناه وسنوضح عن هذه الطريقة فيما بعد إن شاء الله تعالى. فأما خروج ذلك عن العادات، فليس الأمر على ما قالوه،ولو صح لجاز أن ينقض الله تعالى العادة في ستر شخص ويخفى أمره لضرب من المصلحة وحسن التدبير لما يعرض من المانع من ظهوره.","27/1/23/11",""],[12,22,"وهذا الخضرعليه السلام موجود قبل زماننا من عهد موسى عليه السلام عند أكثر الأمة وإلى وقتنا هذا باتفاق أهل السير؛ لا يعرف مستقره ولا يعرف أحد له أصحابا إلا ما جاء به القرآن من قصته مع موسى عليه السلام. وما يذكره بعض الناس أنه يظهر أحيانا ولا يعرف ويظن من يراه أنه بعض الزهاد فإذا فارق مكانه توهمه المسمى بالخضر ولم يكن عرفه بعينه في الحال ولا ظنه فيها بل اعتقد أنه بعض أهل الزمان.","27/1/23/12",""],[13,22,"وقد كان من غيبة موسى بن عمران عليه السلام من وطنه وهربه من فرعون ورهطه ما نطق به القرآن ولم يظفر به أحد مدة من الزمان ولا عرفه بعينه حتى بعثه الله نبيا ودعا إليه فعرفه الولي والعدو.","27/1/23/13",""],[14,22,"وقد كان من قصة يوسف بن يعقوب عليه السلام ما جاء به سورة في القرآن وتضمنت استتار خبره عن أبيه وهو نبي الله يأتيه الوحي صباحا ومساء وما يخفى عليه خبر ولده وعن ولده أيضا حتى أنهم كانوا يدخلون عليه ويعاملونه ولا يعرفونه وحتى مضت على ذلك السنون والأزمان ثم كشف الله أمره وظهر خبره وجمع بينه وبين أبيه وإخوته،وإن لم يكن ذلك في عادتنا اليوم ولا سمعنا بمثله.","27/1/23/14",""],[15,22,"وكان من قصة يونس بن متى نبي الله عليه السلام مع قومه وفراره منهم حين تطاول خلافهم له واستخفـافهم بحقوقه وغيبته عنهم وعن كل أحد حتى لم يعلم أحد من الخلق مستقره وستره الله تعالى في جوف السمكة وأمسك عليه رمقه بضرب من المصلحة إلى أن انقضت تلك المدة ورده الله تعالى إلى قومه وجمع بينهم وبينه. وهذا أيضا خارج عن عادتنا وبعيد من تعارفنا،قد نطق به القرآن وأجمع عليه أهل الإسلام.","27/1/23/15",""],[16,22,"ومثل ما حكيناه أيضا قصة أصحاب الكهف وقد نطق بها القرآن وتضمن شرح حالهم واستتارهم عن قومهم فرارا بدينهم. ولو لا ما نطق القرآن به لكان مخالفونا يجحدونه دفعا لغيبة صاحب الزمان عليه السلام وإلحاقهم به،لكن أخبر الله تعالى أنهم بقوا ثلاثمائة سنة مثل ذلك مستترين خائفين ثم أحياهم الله تعالى فعادوا إلى قومهم وقصتهم مشهورة في ذلك.","27/1/23/16",""],[17,22,"وإذا كان ما ذكرناه معروفا كائنا كيف يمكن مع ذلك إنكار غيبة صاحب الزمان عليه السلام اللهم إلا أن يكون المخالف دهريا معطلا ينكر جميع ذلك ويحيله فلا نتكلم معه في الغيبة بل ننتقل معه إلى الكلام في أصل التوحيد وإن ذلك مقدور، وإنما نكلم في ذلك من أقر بالإسلام وجوز كون ذلك مقدورا لله تعالى فبين لهم نظائره في العادات.","27/1/23/17",""],[18,22,"وقد كان من أمر صاحب الحمار الذي نزل بقصته القرآن وأهل الكتاب يزعمون أنه كان نبيا فأماته الله تعالى مائة عام ثم بعثه وبقي طعامه وشرابه لم يتغير.وكان ذلك خارقا للعادة. وأمثال ما قلناه كثيرة مما رواه أصحاب السير والتواريخ من ملوك الفرس وغيبتهم عن أصحابهم مدة لا يعرفون خبرهم ثم عودهم وظهورهم لضرب من التدبير،وإن لم ينطق به القرآن فهو مذكور في التواريخ. وكذلك جماعة من حكماء الروم والهند قد كانت لهم غيبات وأحوال خارجة عن العادات لا نذكرها لأن المخالف ربما جحدها على عادتهم جحد الأخبار وهو مذكور في التواريخ.","27/1/23/18",""],[19,22,"فإن قيل: ادعاؤكم طول عمر صاحبكم أمر خارق للعادات مع بقائه على قولكم كامل العقل تام القوة والشباب لأنه على قولكم له في هذا الوقت الذي هو سنة سبع وأربعين وأربعمائة مائة وإحدى وتسعون سنة،لأن مولده على قولكم سنة ست وخمسين ومائتين.","27/1/23/19",""],[20,22,"ولم تجر العادة بأن يبقى أحد من البشر هذه المدة، فكيف انتقضت العادة فيه ولا يجوز انتقاضها إلا على يد الأنبياء؟","27/1/23/20",""],[21,22,"قلنا: الجواب عن ذلك من وجهين؛ أحدهما، أنا لا نسلم أن ذلك خارق لجميع العادات، بل العادات فيما تقدم قد جرت بمثلها وأكثر من ذلك،وقد ذكرنا بعضها كقصة الخضر عليه السلام وقصة أصحاب الكهف وغير ذلك. وقد أخبر الله تعالى عن نوح عليه السلام أنه لبث في قومه ألف سنة إلا خمسين عاما. وأصحاب السير يقولون إنه عاش أكثر من ذلك وإنما دعا قومه إلى الله تعالى هذه المدة المذكورة بعد أن مضت عليه ستون من عمره.","27/1/23/21",""],[1,23,"وروى أصحاب الأخبار أن سلمان الفارسي رضي الله عنه لقي عيسى بن مريم عليه السلام وبقي إلى زمان نبينا صلى الله عليه وآله وسلم، وخبره مشهور.","27/1/24/1",""],[2,23,"وروى أصحاب الحديث أن الدجال موجود وأنه كان في عصر النبي صلى الله عليه وآله وسلم وأنه باق إلى الوقت الذي يخرج فيه، وهو عدو الله.","27/1/24/2",""],[3,23,"وروى من ذكر أخبار العرب أن لقمان بن عاد كان أطول الناس عمرا وأنه عاش ثلاثة آلاف سنة وخمسمائة سنة، ويقال إنه عاش عمر سبعة أنسر وكان يأخذ فرخ النسر الذكر فيجعله في الجبل فيعيش النسر ما عاش، فإذا مات أخذ آخر فرباه حتى كان آخرها لبد، وكان أطولها عمرا،","27/1/24/3",""],[4,23,"ومنهم ربيع بن ضبع بن وهب بن بغيض بن مالك بن سعد بن عيس بن فزارة، عاش ثلاثمائة سنة وأربعين سنة،فأدرك النبي صلى الله عليه وآله وسلم ولم يسلم.","27/1/24/4",""],[5,23,"وروي أنه عاش إلى أيام عبد الملك بن مروان،وخبره معروف فإنه قال له: فصل لي عمرك. قال: عشت مائتي سنة في فترة عيسى، وعشرين ومائة سنة في الجاهلية، وستين في الإسلام. فقال له: لقد طلبك جد غير عاثر. وأخباره معروفة، وهو الذي يقول وقد طعن في ثلاثمائة سنة: أصبح مني الشباب قد حسرا إن يناعني فقد ثوى عصرا والأبيات معروفة. وهو الذي يقول: إذا كان الشتاء فأدفئوني فإن الشيخ يهدمه الشتاء فأما حين يذهب كل قر فسربال خفيف أو رداء إذا عاش الفتى مائتين عاما فقد أودى المسرة والفتاء","27/1/24/5",""],[6,23,"ومنهم المستوغر بن ربيعة بن كعب بن زيد بن مناة، عاش ثلاثمائة وثلاثين سنة حتى قال: ولقد سئمت من الحياة وطولها وعمرت من بعد السنين سنينا مائة أتت من بعدها مائتان لي وعمرت من عدد الشهور سنينا هل ما بقي إلا كما قد فاتنا يوم يكر وليلة تحدونا","27/1/24/6",""],[7,23,"ومنهم أكثم بن صيفي الأسدي، عاش ثلاثمائة سنة وثلاثين سنة، وكان ممن أدرك النبي صلى الله عليه وآله وسلم وآمن به ومات قبل أن يلقاه، وله أخبار كثيرة وحكم وأمثال. وهو القائل: وإن امرأ قد عاش تسعين حجة إلى مائة لم يسأم العيش جاهل خلت مائتان غير ست وأربع وذلك من عد الليالي قلائل وكان والده صيفي بن رياح بن أكثم أيضا من المعمرين،عاش مائتين وسبعين سنة لا ينكر من عقله شي‏ء، وهو المعروف بذي الحلم الذي قال فيه المتلمس اليشكري: لذي الحلم قبل اليوم ما تقرع العصا وما علم الإنسان إلا ليعلما","27/1/24/7",""],[8,23,"ومنهم ضبيرة بن سعيد بن سعد بن سهم بن عمرو، عاش مائتي سنة وعشرين سنة ولم يشب قط، وأدرك الإسلام ولم يسلم. وروى أبو حاتم والرياشي عن العتبي عن أبيه قال: مات ضبيرة السهمي وله مائتا سنة وعشرون سنة، وكان أسود الشعر صحيح الأسنان، ورثاه ابن عمه قيس بن عدي فقال: من يأمن الحدثان بعـ ـد ضبيرة السهمي ماتا سبقت منيته المشيـ ـب وكان ميتته افتلاتا فتزودوا لا تهلكوا من دون أهلكم خفاتا","27/1/24/8",""],[9,23,"ومنهم دريد بن الصمة الجشمي، عاش مائتي سنة وأدرك الإسلام فلم يسلم،وكان أحد قواد المشركين يوم حنين ومقدمتهم. حضر حرب النبي صلى الله عليه وآله وسلم فقتل يومئذ.","27/1/24/9",""],[10,23,"ومنهم محصن بن غسان بن ظالم الزبيدي،عاش مائتي سنة وستا وخمسين سنة.","27/1/24/10",""],[11,23,"ومنهم عمرو بن حممة الدوسي، عاش أربعمائة سنة،وهو الذي يقول: كبرت وطال العمر حتى كأنني سليم أفاع ليلة غير مودع ‏فما الموت أفناني ولكن تتابعت علي سنون من مصيف ومربع ‏ثلاث مئات قد مررن كواملا وها أنا هذا أرتجي منه أربع","27/1/24/11",""],[12,23,"ومنهم الحارث بن مضاض الجرهمي، عاش أربعمائة سنة،وهو القائل: كان لم يكن بين الحجون إلى الصفا أنيس ولم يسمر بمكة سامر ‏ بلى نحن كنا أهلها فأبادنا صروف الليالي والجدود العواثر","27/1/24/12",""],[13,23,"ومنهم عبد المسيح بن بقيلة الغساني، ذكر الكلبي وأبو عبيدة وغيرهما أنه عاش ثلاثمائة سنة وخمسين سنة، وأدرك الإسلام فلم يسـلم، وكان نصرانيا. وخبره مع خالد بن الوليد لما نزل على الحيرة معروف،حتى قال له: كم أتى لك؟قال: خمسون وثلاثمائة سنة. قال: فما أدركت؟قال: أدركت سفن البحر ترفأ إلينا في هذا الجرف،ورأيت المرأة من أهل الحيرة تضع مكتلها على رأسها لا تزود إلا رغيفا واحدا حتى تأتي الشام وقد أصبحت خرابا.وذلك دأب الله في العباد والبلاد. وهو القائل: والناس أبناء علات فمن علموا أن قد أقل فمجفو ومحقور وهم بنون لأم إن رأوا نشبا فذاك بالغيب محفوظ ومحصور","27/1/24/13",""],[14,23,"ومنهم النابغة الجعدي من بني عامر بن صعصعة،يكنى أبا ليلى.قال أبو حاتم السجستاني: كان النابغة الجعدي أسن من النابغة الذبياني.","27/1/24/14",""],[15,23,"وروي أنه كان يفتخر ويقول: أتيت النبي صلى الله عليه وآله وسلم فأنشدته: بلغنا السماء مجدنا وجدودنا وإنا لنرجو فوق ذلك مظهرا فقال النبي صلى الله عليه وآله وسلم: أين المظهر يا أبا ليلى؟ فقلت: الجنة يا رسول الله. فقال: أجل إن شاء الله تعالى. ثم أنشدته: ولا خير في حلم إذا لم يكن له بوادر تحمي صفوه أن يكدرا ولا خير في جهل إذا لم يكن له حليم إذا ما أورد الأمر أصدرا فقال له النبي صلى الله عليه وآله وسلم: لا يفضض الله فاك.","27/1/24/15",""],[16,23,"وقيل أنه عاش مائة وعشرين سنة ولم يسقط من فيه سن ولا ضرس. وقال بعضهم: رأيته وقد بلغ الثمانين تزف غروبه. وكان كلما سقطت له ثنية تنبت له أخرى مكانها. وهو من أحسن الناس ثغرا.","27/1/24/16",""],[17,23,"ومنهم أبو الطمحان القيني من بني كنانة بن القين.قال أبو حاتم: عاش أبو الطمحان القيني من بني كنانة مائتي سنة، وقال في ذلك: حنتني حانيات الدهر حتى كأني خاتل أدنو لصيد قصير الخطو يحسب من رآني ولست مقيدا أني بقيد وأخباره وأشعاره معروفة.","27/1/24/17",""],[18,23,"ومنهم ذو الإصبع العدواني. قال أبو حاتم: عاش ثلاثمائة سنة، وهو أحد حكام العرب في الجاهلية، وأخباره وأشعاره وحكمه معروفة.","27/1/24/18",""],[19,23,"ومنهم زهير بن جناب الحميري،لم نذكر نسبه لطوله.قال أبو حاتم: عاش زهير بن جناب مائتي سنة وعشرين سنة، وواقع مائتي وقعة، وكان سيدا مطاعا، عاش شريفا في قومه.ويقال: كانت فيه عشر خصال لم يجتمعن في غيره من أهل زمانه: كان سيد قومه، وشريفهم، وخطيبهم، وشاعرهم، ووافدهم إلى الملوك، وطبيبهم، والطب في ذلك الزمان شرف، وحازى قومه، وهو الكاهن، وكان فارس قومه وله البيت فيهم والعدد منهم،وأوصى إلى بنيه فقال: يا بني إني كبرت سني وبلغت حرسا من دهري أي دهرا فأحكمتني التجارب والأمور تجربة واختبار فاحفظوا عني ما أقول وعوا، وإياكم والخور عند المصائب والتواكل عند النوائب،فإن ذلك داعية الغم وشماتة العدو وسوء الظن بالرب. وإياكم أن تكونوا بالأحداث مغترين ولها آمنين ومنها ساخرين، فإنه ما سخر قوم قط إلا ابتلوا، ولكن توقعوها فإنما الإنسان في الدنيا غرض تعاوره الزمان فمقصر دونه ومجاوز موضعه وواقع عن يمينه وشماله،ثم لا بد أن يصيبه. وأقواله معروفة وكذلك أشعاره.","27/1/24/19",""],[20,23,"ومنهم دويد بن نهد بن زيد بن أسود بن أسلم بن ألحاف بن قضاعة.قال أبو حاتم: عاش دويد بن زيد أربعمائة وستا وخمسين سنة، ووصيته معروفة وأخباره مشهورة. ومن قوله: ألقى علي الدهر رجلا ويدا والدهر ما أصلح يوما أفسدا يفسد ما أصلحه اليوم غـــدا","27/1/24/20",""],[21,23,"ومنهم الحارث بن كعب بن عمرو بن وعلة المذحجي، ومذحج هي أم مالك بن أدد،وسميت مذحجا لأنها ولدت على أكمة تسمى مذحجا. قال أبو حاتم: جمع الحارث بن كعب بنيه لما حضرته الوفاة فقال: يا بني قد أتت علي ستون ومائة سنة ما صافحت يميني يمين غادر ولا قنعت نفسي بحلة فاجر ولا صبوت بابنة عم ولا كنة ولا طرحت عندي مومسة قناعها ولا بحت لصديق بسر. وإني لعلى دين شعيب النبي عليه السلام وما عليه أحد من العرب غيري وغير أسد بن خزيمة وتميم بن مر،فاحفظوا وصيتي وموتوا على شريعتي. إلهكم فاتقوه يكفكم المهم من أموركم ويصلح لكم أعمالكم وإياكم ومعصيته لا يحل بكم الدمار ويوحش منكم الديار.يا بني كونوا جميعا ولا تتفرقوا فتكونوا شيعا، فإن موتا في عز خير من حياة في ذل وعجز. وكل ما هو كائن كائن، وكل جمع إلى تباين. الدهر ضربان؛ فضرب رجاء وضرب بلاء. واليوم يومان؛فيوم حبرة ويوم عبرة. والناس رجلان؛ فرجل لك ورجل عليك. تزوجوا الأكفاء وليستعملن في طيبهن الماء،وتجنبوا الحمقاء فإن ولدها إلى أفن ما يكون إلا أنه لا راحة لقاطع القرابة.وإذا اختلف القوم أمكنوا عدوهم، وآفة العدد اختلاف الكلمة، والتفضل بالحسنة يقي السيئة، والمكافأة بالسيئة الدخول فيها، والعمل بالسوء يزيل النعماء، وقطيعة الرحم تورث الهم، وانتهاك الحرمة يزيل النعمة، وعقوق الوالدين يورث النكد ويمحق العدد ويخرب البلد، والنصيحة تجر الفضيحة، والحقد يمنع الرفد، ولزوم الخطيئة يعقب البلية، وسوء الرعة يقطع أسباب المنفعة. الضغائن تدعو إلى التباين. ثم أنشأ يقول: أكلت شبابي فأفنيته وأفنيت بعد دهور دهورا ثلاثة أهلين صاحبتهم فبادوا فأصبحت شيخا كبيرا قليل الطعام عسير القيام قد ترك الدهر خطوي قصيرا أبيت أراعي نجوم السماء أقلب أمري بطونا ظهورا فهذا طرف من أخبار المعمرين من العرب، واستيفاؤه في الكتب المصنفة في هذا المعنى موجود.","27/1/24/21",""],[22,23,"وأما الفرس فإنها تزعم أن فيما تقدم من ملوكها جماعة طالت أعمارهم، فيروون أن الضحاك صاحب الحيتين عاش ألف سنة ومائتي سنة وأفريدون العادل عاش فوق ألف سنة،ويقولون إن الملك الذي أحدث المهرجان عاش ألفي سنة وخمسمائة سنة استتر منها عن قومه ستمائة سنة.وغير ذلك مما هو موجود في تواريخهم وكتبهم لا نطول بذكرها. فكيف يقال إن ما ذكرناه في صاحب الزمان خارج عن العادات؟","27/1/24/22",""],[23,23,"ومن المعمرين من العرب يعرب بن قحطان، واسمه ربيعة، أول من تكلم بالعربية، ملك مائتي سنة على ما ذكره أبو الحسن النسابة الأصفهاني في كتاب الفرع والشجر، وهو أبو اليمن كلها وهو منها كعدنان إلا شاذا نادرا.","27/1/24/23",""],[24,23,"ومنهم عمرو بن عامر مزيقيا. روى الأصفهاني عن عبد المجيد بن أبي عيس الأنصاري والشرقي بن قطامي أنه عاش ثمانمائة سنة أربعمائة سنة سوقة في حياة أبيه وأربعمائة سنة ملكا، وكان في سني ملكه يلبس في كل يوم حلتين،فإذا كان بالعشي مزقت الحلتان عنه لئلا يلبسهما غيره فسمي مزيقيا.وقيل إنما سمي بذلك لأن على عهده تمزقت الأزد فصاروا إلى أقطار الأرض،وكان ملك أرض سبإ فحدثته الكهان بأن الله يهلكها بالسيل العرم فاحتال حتى باع ضياعه وخرج فيمن أطاعه من أولاده وأهله قبل السيل العرم ومنه انتشرت الأزد كلها والأنصار من ولده.","27/1/24/24",""],[25,23,"ومنهم جلهمة بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن يعرب، ويقال لجلهمة طيئ وإليه تنسب طيئ كلها وله خبر يطول شرحه، وكان له ابن أخ يقال له يحابر بن مالك بن أدد، وكان قد أتى على كل واحد منهما خمسمائة سنة وقع بينهما ملاحاة بسبب المرعى فخاف جلهمة هلاك عشيرته فرحل عنه وطوى المنازل فسمي طيئا،وهو صاحب أجأ وسلمى جبلين بطيئ ولذلك خبر يطول معروف.","27/1/24/25",""],[26,23,"ومنهم عمرو بن لحي وهو ربيعة بن حارثة بن عمرو مزيقيا في قول علماء خزاعة كان رئيس خزاعة في حرب خزاعة وجرهم، وهو الذي سن السائبة والوصيلة والحام ونقل صنمين-وهما هبل ومناة- من الشام إلى مكة فوضعهما للعبادة فسلم هبل إلى خزيمة بن مدركة، فقيل هبل خزيمة، وصعد على أبي قبيس ووضع مناة بالمسلل وقدم بالنرد،وهو أول من أدخلها مكة فكانوا يلعبون بها في الكعبة غدوة وعشية.","27/1/24/26",""],[27,23,"فروي عن النبي صلى الله عليه وآله وسلم أنه قال: رفعت إلى النار فرأيت عمرو بن لحي رجلا قصيرا أحمر أزرق يجر قصبة في النار. فقلت: من هذا؟قيل: عمرو بن لحي.","27/1/24/27",""],[28,23,"فإن كان المخالف لنا في ذلك من يحيل ذلك من المنجمين وأصحاب الطبائع فالكلام معهم في أصل هذه المسألة وأن العالم مصنوع وله صانع أجرى العادة بقصر الأعمار وطولها وأنه قادر على إطالتها وعلى إفنائها فإذا بين ذلك سهل الكلام. وإن كان المخالف في ذلك من يسلم ذلك غير أنه يقول هذا خارج عن العادات فقد بينا أنه ليس بخارج عن جميع العادات. ومتى قالوا خارج عن عادتنا،قلنا وما المانع منه.فإن قيل ذلك لا يجوز إلا في زمن الأنبياء، قلنا نحن ننازع في ذلك وعندنا يجوز خرق العادات على يد الأنبياء والأئمة والصالحين،وأكثر أصحاب الحديث يجوزون ذلك وكثير من المعتزلة والحشوية وإن سموا ذلك كرامات كان ذلك خلافا في عبارة وقد دللنا على جواز ذلك في كتبنا وبينا أن المعجز إنما يدل على صدق من يظهر على يده ثم نعلمه نبيا أو إماما أو صالحا لقوله وكلما يذكرونه من شبههم قد بينا الوجه في كتبنا لا نطول بذكره هاهنا.","27/1/24/28",""],[29,23,"ووجدت بخط الشريف الأجل الرضي أبي الحسن محمد بن الحسين الموسوي رضي الله عنه تعليقا في تقاويم جمعها مؤرخا بيوم الأحد الخامس عشر من المحرم سنة إحدى وثمانين وثلاثمائة أنه ذكر له حال شيخ في باب الشام قد جاوز المائة وأربعين سنة، فركبت إليه حتى تأملته وحملته إلى القرب من داري بالكرخ وكان أعجوبة شاهد الحسن بن علي بن محمد بن علي الرضا عليهم السلام أبا القائم عليه السلام ووصف صفته… إلى غير ذلك من العجائب التي شاهدها،هذه حكاية خطه بعينها.","27/1/24/29",""],[1,24,"ومما يدل على إمامة صاحب الزمان ابن الحسن بن علي بن محمد بن الرضا عليهم السلام وصحة غيبته ما رواه الطائفتان المختلفتان والفرقتان المتباينتان العامة والإمامية وأن الأئمة عليهم السلام بعد النبي صلى الله عليه وآله وسلم اثنا عشر لا يزيدون ولا ينقصون،وإذا ثبت ذلك فكل من قال بذلك قطع على الأئمة الاثني عشر الذين نذهب إلى إمامتهم وعلى وجود ابن الحسن عليه السلام وصحة غيبته لأن من خالفهم في شي‏ء من ذلك لا يقصر الإمامة على هذا العدد بل يجوز الزيادة عليها وإذا ثبت بالأخبار التي نذكرها هذا العدد المخصوص ثبت ما أردناه. فنحن نذكر جملا من ذلك ونحيل الباقي على الكتب المصنفة في هذا المعنى لئلا يطول به الكتاب إن شاء الله تعالى.","27/1/25/1",""],[2,24,"ما أخبرني به أبو عبد الله أحمد بن عبدون المعروف بابن الحاشر قال: حدثني أبو الحسين محمد بن علي الشجاعي الكاتب قال: أخبرنا أبو عبد الله محمد بن إبراهيم المعروف بابن أبي زينب النعماني الكاتب قال: أخبرنا محمد بن عثمان بن علان الذهبي البغدادي بدمشق قال: حدثنا أبو بكر بن أبي خيثمة قال: حدثني علي بن الجعد قال: حدثني زهير بن معاوية عن زياد بن خيثمة عن الأسود بن سعيد الهمداني قال: سمعت جابر بن سمرة يقول: سمعت رسول الله صلى الله عليه وآله وسلم يقول: يكون بعدي اثنا عشر خليفة كلهم من قريش. قال: فلما رجع إلى منزله أتته قريش فقالوا: ثم يكون ماذا؟ فقال: ثم يكون الهرج.","27/1/25/2",""],[3,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا ابن أبي خيثمة قال: حدثني زهير بن معاوية عن زياد بن علاقة وسماك بن حرب وحصين بن عبد الرحمن كلهم عن جابر بن سمرة أن رسول الله صلى الله عليه وآله وسلم قال: يكون بعدي اثنا عشر خليفة… ثم تكلم بكلام لم أفهمه، فقال بعضهم: سألت القوم فقالوا: قال: كلهم من قريش.","27/1/25/3",""],[4,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا ابن عود عن الشعبي عن جابر بن سمرة قال: ذكر أن النبي صلى الله عليه وآله وسلم قال: لا يزال أهل هذا الدين ينصرون على من ناواهم إلى اثني عشر خليفة. فجعل الناس يقومون ويقعدون، وتكلم بكلمة لم أفهمها، فقلت لأبي- أو لأخي -: أي شي‏ء قال؟ فقال: قال: كلهم من قريش.","27/1/25/4",""],[5,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا أحمد قال: حدثنا عبيد الله بن عمر قال: حدثنا سليمان بن أحمر قال: حدثنا ابن عون، عن الشعبي،عن جابر بن سمرة قال: ذكر أن النبي صلى الله عليه وآله وسلم قال: لا يزال أهل هذا الدين ينصرون على من ناواهم إلى اثني عشر خليفة. فجعل الناس يقومون ويقعدون، وتكلم بكلمة لم أفهمها،فقلت لأبي-أو لأخي- :أي شي‏ء قال؟فقال: كلهم من قريش.","27/1/25/5",""],[6,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا أحمد بن أبي خيثمة قال: حدثنا يحيى بن معين قال: حدثنا عبد الله بن صالح قال: حدثنا الليث بن سعد عن خالد بن يزيد عن سعيد بن أبي هلال عن ربيعة بن سيف قال: كنا عند شفي الأصبحي فقال: سمعت عبد الله بن عمر يقول: سمعت رسول الله صلى الله عليه وآله وسلم يقول: يكون خلفي اثنا عشر خليفة.","27/1/25/6",""],[7,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا أحمد قال: حدثنا عفان ويحيى بن إسحاق السيلحيني قال: حدثنا حماد بن سلمة قال: حدثنا عبد الله بن عثمان عن أبي الطفيل قال: قال لي عبد الله بن عمر: يا أبا الطفيل، عد اثني عشر من بني كعب بن لؤي. ثم يكون النقف والنقاف.","27/1/25/7",""],[8,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا أحمد قال: حدثنا المقدمي عن عاصم بن عمر بن علي بن مقدام أبو يونس قال: حدثني أبي عن فطر بن خليفة عن أبي خالد الوالبي قال: حدثنا جابر بن سمرة قال: سمعت رسول الله صلى الله عليه وآله وسلم يقول: لا يزال هذا الدين ظاهرا لا يضره من ناواه حتى يقوم اثنا عشر خليفة كلهم من قريش.","27/1/25/8",""],[9,24,"وبهذا الإسناد عن محمد بن عثمان قال: حدثنا عبد الله بن جعفر الرقي قال:حدثنا عيسى بن يونس عن مجالد بن سعيد عن الشعبي عن مسروق قال: كنا عند ابن مسعود فقال له رجل: حدثكم نبيكم كم يكون بعده من الخلفاء؟ فقال: نعم. وما سألني عنها أحد قبلك وإنك لأحدث القوم سنا. سمعته يقول: يكون بعدي عدة نقباء موسى عليه السلام. قال الله عز وجل ﴿وبَعَثْنا مِنْهُمُ اثْنَيْ عَشَرَ نَقِيباً﴾.","27/1/25/9",""],[10,24,"وأخبرني جماعة عن أبي محمد هارون بن موسى التلعكبري قال:أخبرني أبو علي أحمد بن علي المعروف بابن الخضيب الرازي قال:حدثني بعض أصحابنا عن حنظلة بن زكريا التميمي، عن أحمد بن يحيى الطوسي، عن أبي بكر عبد الله بن أبي شيبة، عن محمد بن فضيل، عن الأعمش، عن أبي صالح، عن ابن عباس قال: نزل جبرئيل عليه السلام بصحيفة من عند الله على رسول الله صلى الله عليه وآله وسلم فيها اثنا عشر خاتما من ذهب، فقال له: إن الله تعالى يقرأ عليك السلام ويأمرك أن تدفع هذه الصحيفة إلى النجيب من أهلك بعدك يفك منها أول خاتم ويعمل بما فيها، فإذا مضى دفعها إلى وصيه بعده، وكذلك الأول يدفعها إلى الآخر واحدا بعد واحد. ففعل النبي صلى الله عليه وآله وسلم ما أمر به. ففك علي بن أبي طالب عليه السلام أولها وعمل بما فيها، ثم دفعها إلى الحسن عليه السلام ففك خاتمه وعمل بما فيها، ودفعها بعده إلى الحسين عليه السلام، ثم دفعها الحسين إلى علي بن الحسين عليه السلام، ثم واحدا بعد واحد حتى ينتهي إلى آخرهم عليهم السلام.","27/1/25/10",""],[11,24,"وبهذا الإسناد عن التلعكبري، عن أبي علي محمد بن همام، عن الحسن بن علي القوهستاني، عن زيد بن إسحاق،عن أبيه قال:سألت أبي عيسى بن موسى فقلت له: من أدركت من التابعين؟فقال: ما أدري ما تقول؟ولكني كنت بالكوفة فسمعت شيخا في جامعها يحدث عن عبد خير قال: قال أمير المؤمنين عليه السلام: قال لي رسول الله صلى الله عليه وآله وسلم: يا علي، الأئمة الراشدون المهديون المغصوبون حقوقهم من ولدك أحد عشر إماما وأنت… والحديث مختصر.","27/1/25/11",""],[12,24,"وأخبرني جماعة عن أبي محمد هارون بن موسى التلعكبري،عن محمد بن أحمد بن عبد الله الهاشمي قال:حدثني أبو موسى عيسى بن أحمد بن عيسى بن المنصور قال:حدثني أبو الحسن علي بن محمد العسكري عن أبيه محمد بن علي عن أبيه علي بن موسى عن أبيه موسى بن جعفر عن أبيه جعفر بن محمد عن أبيه محمد بن علي عن أبيه علي بن الحسين عن أبيه الحسين بن علي صلى الله عليه وآله وسلم قال: قال لي علي عليه السلام: قال رسول الله صلى الله عليه وآله وسلم: مَن سره أن يلقى الله عز وجل آمنا مطهرا لا يحزنه الفزع الأكبر فليتولك وليتول بنيك الحسن والحسين وعلي بن الحسين ومحمد بن علي وجعفر بن محمد وموسى بن جعفر وعلي بن موسى ومحمدا وعليا والحسن ثم المهدي،وهو خاتمهم. وليكونن في آخر الزمان قوم يتولونك يا علي،يشنأهم الناس. ولو أحبوهم كان خيرا لهم لو كانوا يعلمون. يؤثرونك وولدك على الآباء والأمهات والإخوة والأخوات وعلى عشائرهم والقرابات. صلوات الله عليهم أفضل الصلوات. أولئك يحشرون تحت لواء الحمد،يتجاوز عن سيئاتهم ويرفع درجاتهم جزاء بما كانوا يعملون.","27/1/25/12",""],[1,25,"فأما ما روي من جهة الخاصة فأكثر من أن يحصى، غير أنا نذكر طرفا منها:","27/1/26/1",""],[2,25,"روى محمد بن عبد الله بن جعفر الحميري فيما أخبرنا به جماعة عن أبي المفضل الشيباني عنه عن أبيه عن محمد بن الحسين عن محمد بن أبي عمير، وأخبرنا أيضا جماعة عن عدة من أصحابنا عن محمد بن يعقوب عن محمد بن يحيى عن أحمد بن محمد عن ابن أبي عمير عن عمر بن أذينة عن أبان بن أبي عياش عن سليم بن قيس قال: سمعت عبد الله بن جعفر الطيار يقول: كنا عند معاوية أنا والحسن والحسين عليهم السلام وعبد الله بن عباس وعمـر بن أم سـلمة وأسـامة بن زيـد، فجـرى بيني وبين معـاوية كلام فقلت لمعاوية: سمعت رسول الله صلى الله عليه وآله وسلم يقول: أنا أولى بالمؤمنين من أنفسهم، ثم أخي علي بن أبي طالب أولى بالمؤمنين من أنفسهم، فإذا استشهد علي فالحسن أولى بالمؤمنين من أنفسهم، فإذا مضى الحسن فالحسين أولى بالمؤمنين من أنفسهم، فإذا استشهد فابنه علي بن الحسين أولى بالمؤمنين من أنفسهم، وستدركه يا علي، ثم ابنه محمد بن علي أولى بالمؤمنين من أنفسهم يا علي ثم يكمله اثنا عشر إماما تسعة من ولد الحسين. قال عبد الله بن جعفر: استشهدت الحسن والحسين وعبد الله بن عباس وعمر بن أم سلمة وأسامة بن زيد فشهدوا لي عند معاوية. قال سليم بن قيس: وقد سمعت ذلك من سلمان وأبي ذر والمقداد. وذكروا أنهم سمعوا ذلك من رسول الله صلى الله عليه وآله وسلم.","27/1/26/2",""],[3,25,"وبهذا الإسناد عن محمد بن عبد الله بن جعفر عن أبيه عن محمد بن أحمد بن يحيى عن محمد بن الحسين عن أبي سعيد العصفري عن عمرو بن ثابت عن أبي الجارود عن أبي جعفر عليه السلام قال: قال رسول الله صلى الله عليه وآله وسلم: إني وأحد عشر من ولدي وأنت يا علي زر الأرض؛ أعني أوتادها وجبالها. بنا أوتد الله الأرض أن تسيخ بأهلها. فإذا ذهب الاثنا عشر من ولدي ساخت الأرض بأهلها ولم ينظروا.","27/1/26/3",""],[4,25,"عنه عن أبيه عن جعفر بن محمد بن مالك عن محمد بن نعمة السلولي عن وهيب بن حفص عن عبد الله بن القاسم عن عبد الله بن خالد عن أبي السفاتج عن جابر بن يزيد عن أبي جعفر عليه السلام عن جابر بن عبد الله الأنصاري قال: دخلت على فاطمة عليها السلام وبين يديها لوح فيه أسماء الأوصياء من ولدها. فعددت اثني عشر اسما آخرهم القائم؛ ثلاثة منهم محمد وثلاثة منهم علي.","27/1/26/4",""],[5,25,"وأخبرني جماعة عن عدة من أصحابنا عن محمد بن يعقوب عن علي بن إبراهيم بن هاشم عن أبيه عن ابن عمير عن سعيد بن غزوان عن أبي بصير عن أبي جعفر عليه السلام قال: يكون تسعة أئمة بعد الحسين؛ تاسعهم قائمهم.","27/1/26/5",""],[6,25,"محمد بن عبد الله بن جعفر عن أبيه عن محمد بن عيسى عن محمد بن الفضل عن أبي حمــزة عـن أبـي جـعفر عليـه السـلام قـال: إن الله تعالى أرسل محمدا صلى الله عليه وآله وسلم إلى الجن والإنس عامة. وكان من بعده اثنا عشر وصيا، منهم من سبقنا ومنهم من بقي، وكل وصي جرت به السنة والأوصياء الذين من بعد محمد صلى الله عليه وآله وسلم على سنة أوصياء عيسى إلى محمد صلى الله عليه وآله وسلم، وكانوا اثني عشر، وكان أمير المؤمنين عليه السلام على سنة المسيح.","27/1/26/6",""],[7,25,"عنه عن أبي الحسين،وأخبرني جماعة عن أبي محمد التلعكبري عن أبي الحسين محمد بن جعفر الأسدي عن سهل بن زياد الآدمي عن الحسن بن العباس بن الحريش الرازي عن أبي جعفر الثاني عليه السلام أن أمير المؤمنين عليه السلام قال لابن عباس: إن ليلة القدر في كل سنة، وإنه ينزل في تلك الليلة أمر السنة،ولذلك الأمر ولاة بعد رسول الله صلى الله عليه وآله وسلم. فقال ابن عباس: من هم؟ فقال: إنا وأحد عشر من صلبي؛ أئمة محدثون.","27/1/26/7",""],[8,25,"محمد بن عبد الله بن جعفر الحميري عن أبيه عن أحمد بن هلال العبرتائي عن ابن أبي عمير عن سعيد بن غزوان عن أبي بصير عن أبي عبد الله عليه السلام قال: قال رسول الله صلى الله عليه وآله وسلم في حديث له: إن الله اختار من الناس الأنبياء، واختار من الأنبياء الرسل، واختارني من الرسل، واختار مني عليا، واختار من علي الحسن والحسين، واختار من الحسين الأوصياء، تاسعهم قائمهم،وهو ظاهرهم وباطنهم.","27/1/26/8",""],[9,25,"وأخبرني جماعة عن أبي جعفر محمد بن سفيان البزوفري عن أبي علي أحمد بن إدريس وعبد الله بن جعفر الحميري عن أبي الخير صالح بن أبي حماد الرازي والحسن بن ظريف جميعا عن بكر بن صالح عن عبد الرحمن بن سالم عن أبي بصير عن أبي عبد الله عليه السلام قال: قال أبي محمد بن علي عليه السلام لجابر بن عبد الله الأنصاري: إن لي إليك حاجة. فمتى يخف عليك أن أخلو بك فأسألك عنها؟ قال له جابر: في أي الأوقات أحببت.فخلا به أبي في بعض الأوقات فقال له: يا جابر، أخبرني عن اللوح الذي رأيته في يد أمي فاطمة عليها السلام وما أخبرتك به أمي أنه في ذلك اللوح مكتوب. فقال جابر: أشهد بالله أني دخلت على أمك فاطمة عليها السلام في حياة رسول الله صلى الله عليه وآله وسلم فهنأتها بولادة الحسين عليه السلام، ورأيت في يدها لوحا أخضر، فظننت أنه زمرد،ورأيت فيه كتابا أبيض شبه نور الشمس. فقلت لها: بأبي وأمي يا ابنة رسول الله، ما هذا اللوح؟فقالت: هذا اللوح أهداه الله عز وجل إلى رسول الله صلى الله عليه وآله وسلم؛ فيه اسم أبي واسم بعلي واسم ابنيَّ وأسماء الأوصياء من ولدي،فأعطانيه أبي ليسرني بذلك. قال جابر: فأعطتنيه أمك فاطمة عليها السلام فقرأته فاستنسخته. قال له أبي: فهل لك يا جابر أن تعرضه علي؟ قال: نعم.فمشى معه أبي حتى انتهى إلى منزل جابر،فأخرج أبي صحيفة من رق وقال: يا جابر انظر في كتابك لأقرأ أنا عليك. فنظر جابر في نسخته وقرأه أبي، فما خالف حرف حرفا. قال جابر: فأشهد بالله أني هكذا رأيت في اللوح مكتوبا: بسم الله الرحمن الرحيم. هذا كتاب من الله العزيز الحكيم لمحمد نبيه ونوره وسفيره وحجابه ودليله،نزل به الروح الأمين من عند رب العالمين. عظِّم يا محمد أسمائي، واشكر نعمائي،ولا تجحد آلائي. إني أنا الله لا إله إلا أنا، قاصم الجبارين، ومديل المظلومين، وديان الدين. إني أنا الله لا إله إلا أنا؛من رجا غير فضلي أو خاف غير عدلي عذبته عذابا لا أعذبه أحدا من العالمين. فإياي فاعبد وعليّ فتوكل. إني لم أبعث نبيا فكملت أيامه وانقضت مدته إلا جعلت له وصيا، وإني فضلتك على الأنبياء وفضلت وصيك عليا على الأوصياء، وأكرمتك بشبليك بعده وسبطيك الحسن والحسين، فجعلت حسنا معدن علمي بعد انقضاء مدة أبيه، وجعلت حسينا خازن علمي وأكرمته بالشهادة وختمت له بالسعادة،وهو أفضل من استشهد وأرفع الشهداء درجة. جعلت كلمتي التامة معه وحجتي البالغة عنده،بعترته أثيب وأعاقب: أولهم علي سيد العابدين وزين أولياء الماضين. وابنه شبيه جده المحمود محمد الباقر باقر علمي والمعدن لحكمتي. سيهلك المرتابون في جعفر؛ الراد عليه كالراد عليّ. حق القول مني لأكرمن مثوى جعفـر ولأسرّنّـه في أشياعه وأنصاره وأوليائه. انتج بعده فتنة عمياء حندس لأن خيط فرضي لا ينقطع وحجتي لا تخفى،وإن أوليائي لا يشقون. إلا ومن جحد واحدا منهم فقد جحد نعمتي، ومن غير آية من كتابي فقد افترى علي، وويل للمفترين الجاحدين عند انقضاء مدة عبدي موسى وحبيبي وخيرتي. إن المكذب بالثامن مكذب بكل أوليائي، وعلي وليي وناصري ومن أضع عليه أعباء النبوة وأمتعه بالاضطلاع بها. يقتله عفريت مستكبر يدفن في المدينة التي بناها العبد الصالح إلى جنب شر خلقي. حق القول مني لأقرن عينيه بمحمد ابنه وخليفته ووارث علمه، فهو معدن علمي وموضع سري وحجتي على خلقي، جعلت الجنة مثواه وشفعته في سبعين ألف من أهل بيته،كلهم قد استوجبوا النار. وأختم بالسعادة لابنه علي وليي وناصري والشاهد في خلقي وأميني على وحيي. أخرج منه الداعي إلى سبيلي والخازن لعلمي الحسن. ثم أكمل ذلك بابنه رحمة للعالمين؛ عليه كمال موسى وبهاء عيسى وصبر أيوب، سيذل أوليائي في زمانه ويتهادى رءوسهم كما يتهادى رءوس الترك والديلم، فيقتلون ويحرقون ويكونون خائفين مرعوبين وجلين، تصبغ الأرض بدمائهم ويفشو الويل والرنة في نسائهم. أولئك أوليائي حقا بهم أدفع كل فتنة عمياء حندس،وبهم أكشف الزلازل وأرفع الإصار والأغلال: ﴿أُولئِكَ عَلَيْهِمْ صَلَواتٌ مِنْ رَبِّهِمْ ورَحْمَةٌ وأُولئِكَ هُمُ الْمُهْتَدُونَ﴾. قال عبد الرحمن بن سالم: قال لي أبو بصير: لو لم تسمع في دهرك إلا هذا الحديث لكفاك. فصنه إلا عن أهله","27/1/26/9",""],[10,25,"s","27/1/26/10",""],[11,25,"أخبرنا جماعة عن أبي عبد الله الحسين بن علي بن سفيان البزوفري عن علي بن سنان الموصلي العدل عن علي بن الحسين عن أحمد بن محمد بن الخليل عن جعفر بن أحمد المصري عن عمه الحسن بن علي عن أبيه عن أبي عبد الله جعفر بن محمد عن أبيه الباقر عن أبيه ذي الثفنات سيد العابدين عن أبيه الحسين الزكي الشهيد عن أبيه أمير المؤمنين عليه السلام قال: قال رسول الله صلى الله عليه وآله وسلم في الليلة التي كانت فيها وفاته لعلي عليه السلام: يا أبا الحسن،أحضر صحيفة ودواة. فأملأ رسول الله صلى الله عليه وآله وسلم وصيته حتى انتهى إلى هذا الموضع فقال: يا علي، إنه سيكون بعدي اثنا عشر إماما،ومن بعدهم اثنا عشر مهديا. فأنت يا علي أول الاثني عشر إماما،سماك الله تعالى في سمائه عليا المرتضى وأمير المؤمنين والصديق الأكبر والفاروق الأعظم والمأمون والمهدي. فلا تصح هذه الأسماء لأحد غيرك. يا علي، أنت وصيي على أهل بيتي حيهم وميتهم وعلى نسائي، فمن ثبّتّها لقيتني غدا، ومن طلقتَها فأنا بريء منها لم ترني ولم أرها في عرصة القيامة. وأنت خليفتي على أمتي من بعدي، فإذا حضرتك الوفاة فسلمها إلى ابني الحسن البر الوصول. فإذا حضرته الوفاة فليسلمها إلى ابني الحسين الشهيد الزكي المقتول. فإذا حضرته الوفاة فليسلمها إلى ابنه سيد العابدين ذي الثفنات علي. فإذا حضرته الوفاة فليسلمها إلى ابنه محمد الباقر. فإذا حضرته الوفاة فليسلمها إلى ابنه جعفر الصادق. فإذا حضرته الوفاة فليسلمها إلى ابنه موسى الكاظم. فإذا حضرته الوفاة فليسلمها إلى ابنه علي الرضا. فإذا حضرته الوفاة فليسلمها إلى ابنه محمد الثقة التقي. فإذا حضرته الوفاة فليسلمها إلى ابنه علي الناصح. فإذا حضرته الوفاة فليسلمها إلى ابنه الحسن الفاضل. فإذا حضرته الوفاة فليسلمها إلى ابنه محمد المستحفظ من آل محمد. فذلك اثنا عشر إماما. ثم يكون من بعده اثنا عشر مهديا. فإذا حضرته الوفاة فليسلمها إلى ابنه أول المقربين، له ثلاثة أسام؛ اسم كاسمي واسم أبي وهو عبدالله، وأحمد،والاسم الثالث المهدي. هو أول المؤمنين.","27/1/26/11",""],[12,25,"وأخبرني جماعة عن عدة من أصحابنا عن محمد بن يعقوب عن أبي علي الأشعري عن الحسين بن عبد الله عن الحسن بن موسى الخشاب عن الحسن بن سماعة عن علي بن الحسن بن رباط عن ابن أذينة عن زرارة قال:سمعت أبا جعفر عليه السلام يقول: الاثنا عشر الإمام من آل محمد كلهم محدث من ولد رسول الله صلى الله عليه وآله وسلم وولد علي بن أبي طالب عليه السلام،فرسول الله وعلي هما الوالدان.","27/1/26/12",""],[13,25,"وبهذا الإسناد عن محمد بن يحيى عن محمد الحسين عن مسعدة بن زياد عن أبي عبد الله عليه السلام؛ ومحمد بن الحسين عن إبراهيم بن أبي يحيى المدني عن أبي هارون العبدي عن أبي سعيد الخدري قال: كنت حاضرا لما هلك أبو بكر واستخلف عمر،أقبل يهودي من عظماء يثرب يزعم يهود المدينة أنه أعلم أهل زمانه حتى رفع إلى عمر فقال له: يا عمر، إني جئتك أريد الإسلام؛ فإن خبرتني عما أسألك عنه فأنت أعلم أصحاب هذا الكتاب والسنة وجميع ما أريد أن أسأل عنه. قال: فقال له عمر: إني لست هناك، لكني أرشدك إلى من هو أعلم أمتنا بالكتاب والسنة وجميع ما قد تسأل عنه، وهو ذاك. وأومأ إلى علي عليه السلام. فقال له اليهودي: يا عمر، إن كان هذا كما تقول فما لك وبيعة الناس؟ وإنما ذاك أعلمكم. فزبره عمر. ثم إن اليهودي قام إلى علي عليه السلام فقال: أنت كما ذكر عمر؟ فقال: وما قال عمر؟ فأخبره، قال: فإن كنت كما قال عمر سألتك عن أشياء أريد أن أعلم هل يعلمها أحد منكم فاعلم أنكم في دعواكم خير الأمم وأعلمها صادقون، ومع ذلك أدخل في دينكم الإسلام. فقال أمير المؤمنين علي عليه السلام: نعم،أنا كما ذكر لك عمر. سل عما بدا لك أخبرك عنه إن شاء الله تعالى. قال: أخبرني عن ثلاثة وثلاثة وواحدة. قال له علي عليه السلام: يا يهودي، لم لم تقل أخبرني عن سبع؟ فقال اليهودي: إنك إن أخبرتني بالثلاث سألتك عن الثلاث، وإلا كففت! وإن أجبتني في هذه السبع فأنت أعلم أهل الأرض وأفضلهم وأولى الناس بالناس. فقال: سل عما بدا لك يا يهودي. قال: أخبرني عن أول حجر وضع على وجه الأرض، وأول شجرة غرست على وجه الأرض، وأول عين نبعت على وجه الأرض. فأخبره أمير المؤمنين عليه السلام. ثم قال له اليهودي: فأخبرني عن هذه الأمة؛ كم لها من إمام هدى، وأخبرني عن نبيكم محمد؛ أين منزله في الجنة،وأخبرني من معه في الجنة. فقال له أمير المؤمنين عليه السلام: إن لهذه الأمة اثني عشر إمام هدى من ذرية نبيها، وهم مني. وأما منزل نبينا صلى الله عليه وآله وسلم في الجنة فهو أفضلها وأشرفها؛ جنة عدن. وأما من معه في منزله منها فهؤلاء الاثنا عشر من ذريته وأمهم وجدتهم أم أمهم وذراريهم،لا يشركهم فيها أحد.","27/1/26/13",""],[14,25,"وبهذا الإسناد عن محمد بن يعقوب عن عدة من أصحابنا عن أحمد بن محمد البرقي عن أبي هاشم داود بن القاسم الجعفري عن أبي جعفر الثاني عليه السلام قال: أقبل أمير المؤمنين عليه السلام ومعه الحسن بن علي عليه السلام وهو متكئ على يد سلمان فدخل المسجد الحرام إذ أقبل رجل حسن الهيئة واللباس،فسلم علي أمير المؤمنين عليه السلام فرد عليه السلام فجلس. ثم قال: يا أمير المؤمنين، أسألك عن ثلاث مسائل؛ إن أخبرتني بهن علمت أن القوم قد ركبوا من أمرك ما قضى عليهم وإن ليسوا بمأمونين في دنياهم وآخرتهم،وإن تكن الأخرى علمت أنك وهم شرع سواء.فقال له أمير المؤمنين عليه السلام: سلني عما بدا لك.قال:أخبرني عن الرجل إذا نام أين تذهب روحه، وعن الرجل كيف يذكر وينسى،وعن الرجل يشبه ولده الأعمام والإخوان.فالتفت أمير المؤمنين عليه السلام إلى الحسن عليه السلام فقال: يا أبا محمد،أجبه.فأجابه الحسن عليه السلام. فقال الرجل: أشهد أن لا إله إلا الله، ولم أزل أشهد بها، وأشهد أن محمدا رسول الله ولم أزل أشهد بذلك، وأشهد أنك وصي رسول الله والقائم بحجته- وأشار إلى أمير المؤمنين عليه السلام-ولم أزل أشهد بها، وأشهد أنك وصيه والقائم بحجته- وأشار إلى الحسن- وأشهد أن الحسين بن علي وصي أبيه والقائم بحجته بعدك، وأشهد على علي بن الحسين أنه القائم بأمر الحسين بعده، وأشهد على محمد بن علي أنه القائم بأمر علي بن الحسين، وأشهد على جعفر بن محمد أنه القائم بأمر محمد بن علي، وأشهد على موسى أنه القائم بأمر جعفر بن محمد، وأشهد على علي بن موسى أنه القائم بأمر موسى بن جعفر، وأشهد على محمد بن علي أنه القائم بأمرعلي بن موسى، وأشهد على علي بن محمد بأنه القائم بأمر محمد بن علي، وأشهد على الحسن بن علي بأنه القائم بأمر علي بن محمد، وأشهد على رجل من ولد الحسن لا يكنى ولا يسمى حتى يظهر أمره فيملأها عدلاً كما ملئت ظلماً وجوراً. والسلام عليك يا أمير المؤمنين ورحمة الله وبركاته. ثم قام فمضى، فقال أمير المؤمنين عليه السلام: يا أبا محمد، اتبعه انظر أين يقصد. فخرج الحسن عليه السلام،فقال له: ما كان إلا أن وضع رجله خارجا من المسجد فما دريت أين أخذ من أرض الله. فرجعت إلى أمير المؤمنين فأعلمته، فقال: يا أبا محمد، أتعرفه؟ فقلت: الله ورسوله وأمير المؤمنين أعلم. فقال عليه السلام: هو الخضر عليه السلام. فهذا طرف من الأخبار قد أوردناها، ولو شرعنا في إيراد ما من جهة الخاصة في هذا المعنى لطال به الكتاب، وإنما أوردنا ما أوردنا منها ليصح ما قلناه من نقل الطائفتين المختلفتين. ومن أراد الوقوف على ذلك فعليه بالكتب المصنفة في ذلك فإنه يجد من ذلك شيئا كثيرا حسب ما قلناه.","27/1/26/14",""],[15,25,"فإن قيل: دلوا أولا على صحة هذه الأخبار فإنها أخبار آحاد لا يعول عليها فيما طريقه العلم وهذه مسألة علمية ثم دلوا على أن المعني بها من تذهبون إلى إمامته فإن الأخبار التي رويتموهـا عن مخالفيكم وأكثر ما رويتموهـا من جهة الخاصة إذا سلمت فليس فيها صحة ما تذهبون إليه لأنها تتضمن العدد فحسب ولا تتضمن غير ذلك فمن أين لكم إن أئمتكم هم المرادون بها دون غيرهم.","27/1/26/15",""],[16,25,"قلنا: أما الذي يدل على صحتها فإن الشيعة الإمامية يروونها على وجه التواتر خلفا عن سلف وطريقة تصحيح ذلك موجودة في كتب الإمامية النصوص على أمير المؤمنين عليه السلام والطريقة واحدة. وأيضا فإن نقل الطائفتين المختلفتين المتباينتين في الاعتقاد يدل على صحة ما قد اتفقوا على نقله لأن العادة جارية أن كل من اعتقد مذهبا وكان الطريق إلى صحة ذلك النقل فإن دواعيه تتوفر إلى نقله وتتوفر دواعي من خالفه إلى إبطال ما نقله أو الطعن عليه والإنكار لراويته بذلك جرت العادات في مدائح الرجال وذمهم وتعظيمهم والنقص منهم. ومتى رأينا الفرقة المخالفة لهذه الفرقة قد نقلت مثل نقلها ولم تتعرض للطعن على نقله ولم تنكر متضمن الخبر دل ذلك على أن الله تعالى قد تولى نقله وسخرهم لروايته وذلك دليل على صحة ما تضمنه الخبر. وأما الدليل على أن المراد بالأخبار والمعني بها أئمتنا عليه السلام فهو أنه إذا ثبت بهذه الأخبار أن الإمامة محصورة في الاثني عشر إماما وأنهم لا يزيدون ولا ينقصون ثبت ما ذهبنا إليه لأن الأمة بين قائلين قائل يعتبر العدد الذي ذكرناه فهو يقول إن المراد بها من يذهب إلى إمامته ومن خالف في إمامتهم لا يعتبر هذا العدد فالقول مع اعتبار العدد أن المراد غيرهم خروج عن الإجماع وما أدى إلى ذلك وجب القول بفساده.","27/1/26/16",""],[1,26,"ويدل أيضا على إمامة ابن الحسن عليه السلام وصحة غيبته ما ظهر وانتشر من الأخبار الشائعة الذائعة عن آبائه عليه السلام قبل هذه الأوقات بزمان طويل من أن لصاحب هذا الأمر غيبة وصفة غيبته وما يجري فيه من الاختلاف ويحدث فيها من الحوادث وأنه يكون له غيبتان إحداهما أطول من الأخرى وأن الأولى يعرف فيها خبره والثانية لا يعرف فيها أخباره فوافق ذلك على ما تضمنته الأخبار. ولو لا صحتها وصحة إمامته لما وافق ذلك لأن ذلك لا يكون إلا بإعلام الله تعالى على لسان نبيه صلى الله عليه وآله وسلم وهذه أيضا طريقة معتمدة اعتمدها الشيوخ قديما.","27/1/27/1",""],[2,26,"ونحن نذكر من الأخبار التي تضمن ذلك طرفا ليعلم صحة ما قلناه لأن استيفاء جميع ما روي في هذا المعنى يطول وهو موجود في كتب الأخبار من اراده وقف عليه من هناك.","27/1/27/2",""],[3,26,"فمن ذلك ما أخبرنا به جماعة عن أبي محمد التلعكبري عن أحمد بن علي الرازي عن محمد بن جعفر الأسدي عن سعد بن عبد الله عن موسى بن عمر بن يزيد عن علي بن أسباط عن علي بن أبي حمزة عن أبي بصير عن أبي جعفر محمد بن علي عليه السلام في قول الله تعالى: ﴿قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ ماؤُكُمْ غَوْراً فَمَنْ يَأْتِيكُمْ بِماءٍ مَعِينٍ﴾ قال: نزلت في الإمام. فقال إن أصبح إمامكم غائبا عنكم فمن يأتيكم بإمام ظاهر يأتيكم بأخبار السماء والأرض وبحلال الله تعالى وحرامه؟ ثم قال: أما والله ما جاء تأويل هذه الآية ولا بد أن يجي‏ء تأويلها.","27/1/27/3",""],[4,26,"سعد بن عبد الله عن الحسين بن عمرو بن يزيد عن أبي الحسن بن أبي الربيع المدائني عن محمد بن إسحاق عن أسيد بن ثعلبة عن أم هانئ قالت لقيت أبا جعفر عليه السلام فسألته عن قول الله تعالى: ﴿فَلاَأُقْسِمُ بِالْخُنَّسِ. الْجَوارِ الْكُنَّسِ.﴾ فقال: إمام يخنس في زمانه عند انقطاع من علمه عند الناس، سنة ستين ومائتين، ثم يبدو كالشهاب الوقاد. فإن أدركت ذلك قرت عينك.","27/1/27/4",""],[5,26,"سعد بن عبد الله عن أحمد بن محمد بن عيسى عن موسى بن قاسم البجلي وأبي قتادة علي بن محمد بن حفص عن علي بن جعفر عن أخيه موسى بن جعفر عليه السلام قال: قلت له: ما تأويل قول الله تعالى: ﴿قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ ماؤُكُمْ غَوْراً فَمَنْ يَأْتِيكُمْ بِماءٍ مَعِينٍ﴾؟ فقال: إذا فقدتم إمامكم فلم تروه فماذا تصنعون؟","27/1/27/5",""],[6,26,"وأخبرني جماعة عن أبي جعفر محمد بن سفيان البزوفري عن أحمد بن إدريس عن علي بن محمد بن قتيبة عن الفضل بن الشاذان عن عبد الرحمن بن أبي نجران عن صفوان بن يحيى عن أبي أيوب عن أبي بصير قال: قال أبو عبد الله عليه السلام: إن بلغكم عن صاحبكم غيبة فلا تنكروها.","27/1/27/6",""],[7,26,"محمد بن جعفر الأسدي عن سعد بن عبد الله عن جعفر بن محمد بن مالك عن إسحاق بن محمد الصيرفي عن يحيى بن المثنى العطار عن عبد الله بن بكير عن عبيد بن زرارة قال:سمعت أبا عبد الله عليه السلام يقول: يفقد الناس إمامهم فيشهد الموسم فيراهم ولا يرونه.","27/1/27/7",""],[8,26,"أحمد بن إدريس عن علي بن محمد عن الفضل بن شاذان عن عبد الله بن جبلة عن عبد الله بن المستنير عن المفضل بن عمر قال:سمعت أبا عبد الله عليه السلام يقول: إن لصاحب هذا الأمر غيبتين؛ إحداهما تطول حتى يقول بعضهم: مات! ويقول بعضهم: قتل! ويقول بعضهم: ذهب! حتى لا يبقى على أمره من أصحابه إلا نفر يسير. لا يطلع على موضعه أحد من ولده ولا غيره إلا المولى الذي يلي أمره.","27/1/27/8",""],[9,26,"وبهذا الإسناد عن الفضل بن شاذان النيشابوري عن عبد الرحمن بن أبي نجران عن علي بن أبي حمزة عن أبي بصير عن أبي جعفر عليه السلام قال: لا بد لصاحب هذا الأمر من عزلة، ولا بد في عزلته من قوة، وما بثلاثين من وحشة، ونعم المنزل طيبة.","27/1/27/9",""],[10,26,"سعد بن عبد الله عن الحسن بن علي الزيتوني عن الزهري الكوفي عن بنان بن حمدويه قال: ذكر عند أبي الحسن العسكري عليه السلام مضي أبي جعفر عليه السلام فقال: ذاك إليّ ما دمت حياً باقياً. ولكن كيف بهم إذا فقدوا من بعدي؟","27/1/27/10",""],[11,26,"وأخبرنا ابن أبي جيد القمي عن محمد بن الحسن بن الوليد عن محمد بن الحسن الصفار عن العباس بن معروف عن عبد الله بن حمدويه بن البراء عن ثابت عن إسماعيل عن عبد الأعلى مولى آل سام قال: خرجت مع أبي عبد الله عليه السلام، فلما نزلنا الروحاء نظر إلى جبلها مطللا عليها فقال لي: ترى هذا الجبل؟ هذا جبل يدعى رضوى من جبال فارس، أحبنا فنقله الله إلينا. أما إن فيه كل شجرة مطعم ونعم أمان للخائف مرتين. أما إن لصاحب هذا الأمر فيه غيبتين؛ واحدة قصيرة والأخرى طويلة.","27/1/27/11",""],[12,26,"أحمد بن إدريس عن علي بن محمد عن الفضل بن شاذان عن محمد بن أبي عمير عن الحسين بن أبي العلاء عن أبي بصير عن أبي عبد الله عليه السلام قال: لما دخل سلمان رضي الله عنه الكوفة ونظـر إليهـا ذكـر مـا يكون من بلائها حتى ذكر ملك بني أمية والذين من بعدهم. ثم قال: فإذا كان ذلك فالزموا أحلاس بيوتكم حتى يظهر الطاهر ابن الطاهر المطهر ذو الغيبة الشريد الطريد.","27/1/27/12",""],[13,26,"وروى أبو بصير عن أبي جعفر عليه السلام قال: في القائم شبه من يوسف. قلت: وما هو؟قال: الحيرة والغيبة.","27/1/27/13",""],[14,26,"وأخبرني جماعة عن أبي المفضل عن محمد بن عبد الله بن جعفر الحميري عن أبيه عن محمد بن الحسين بن أبي الخطاب عن موسى بن سعدان عن عبد الله بن القاسم عن المفضل بن عمر قال: سألت أبا عبد الله عليه السلام عن تفسير جابر،فقال: لا تحدث به السفل فيذيعونه. أما تقرأ كتاب الله تعالى: ﴿فَإِذا نُقِرَ فِي النَّاقُورِ﴾؟ إن منا إماما مستترا،فإذا أراد الله إظهار أمره نكت في قلبه نكتة فظهر فقام بأمر الله تعالى.","27/1/27/14",""],[15,26,"وروى عبد الله بن محمد بن خالد الكوفي عن منذر بن محمد بن قابوس عن نصر بن السندي عن أبي داود سليمان بن سفيان المسترق عن ثعلبة بن ميمون عن مالك الجهني عن الحارث بن المغيرة عن الأصبغ بن نباتة؛ورواه سعد بن عبد الله عن محمد بن الحسين بن أبي الخطاب عن الحسن بن علي بن فضال عن ثعلبة بن ميمون عن مالك الجهني عن الأصبغ بن نباتة قال: أتيت أمير المؤمنين عليه السلام فوجدته ينكت في الأرض، فقلت له: يا أمير المؤمنين، ما لي أراك مفكرا تنكت في الأرض؟ أرغبة منك فيها؟ قال: لا والله، ما رغبت فيها ولا في الدنيا قط. ولكني تفكرت في مولود يكون من ظهر الحادي عشر من ولدي، هو المهدي الذي يملأها عدلاً وقسطاً كما ملئت ظلماً وجوراً، يكون له حيرة وغيبة تضل فيها أقوام ويهتدي فيها آخرون. قلت: يا مولاي، فكم تكون الحيرة والغيبة؟ قال: ستة أيام أو ستة أشهر أو ست سنين. فقلت: وإن هذا الأمر لكائن؟ فقال: نعم،كما أنه مخلوق. وأنى لك بهذا الأمر يا أصبغ؟ أولئك خيار هذه الأمة مع أبرار هذه العترة. قال: قلت: ثم ما يكون بعد ذلك؟ قال: ثم يفعل الله ما يشاء، فإن له بداءات وإرادات وغايات ونهايات.","27/1/27/15",""],[16,26,"وروى سعد بن عبد الله عن أبي محمد الحسن بن عيسى العلوي قال: حدثني أبي عيسى بن محمد عن أبيه محمد بن علي بن جعفر عن أبيه علي بن جعفر عن أخيه موسى بن جعفر عليه السلام قال: قال لي: يا بني، إذا فقد الخامس من ولد السابع من الأئمة فالله الله في أديانكم،فإنه لا بد لصاحب هذا الأمر من غيبة يغيبها حتى يرجع عن هذا الأمر من كان يقول به. يا بني،إنما هي محنة من الله امتحن بها خلقه لو علم آباؤكم وأجدادكم دينا أصح من هذا الدين لاتبعوه. قال أبو الحسن: فقلت له: يا سيدي، من الخامس من ولد السابع؟ قال: يا بني، عقولكم تصغر عن هذا وأحلامكم تضيق عن حمله، ولكن إن تعيشوا تدركوه.","27/1/27/16",""],[17,26,"أخبرني جماعة عن أبي المفضل محمد بن عبد الله بن محمد بن عبيد الله بن المطلب رحمه الله قال: حدثنا أبو الحسين محمد بن بحر بن سهل الشيباني الرهني قال: أخبرنا علي بن الحارث عن سعد بن المنصور الجواشني قال: أخبرنا أحمد بن علي البديلي قال: أخبرني أبي عن سدير الصيرفي قال: دخلت أنا والمفضل بن عمر وداود بن كثير الرقي وأبو بصير وأبان بن تغلب على مولانا الصادق عليه السلام، فرأيناه جالسا على التراب وعليه مسح خيبري مطرف بلا جيب مقصر الكمين، وهو يبكي بكاء الوالهة الثكلى ذات الكبد الحري، قد نال الحزن من وجنتيه وشاع التغير في عارضيه وأبلى الدمع محجريه، وهو يقول: سيدي، غيبتك نفت رقادي، وضيقت على مهادي، وابتزت مني راحة فؤادي. سيدي، غيبتك أوصلت مصائبي بفجائع الأبد، وفقد الواحد بعد الواحد بفناء الجمع والعدد، فما أحس بدمعة ترقأ من عيني وأنين يفشا من صدري. قال سدير: فاستطارت عقولنا ولهاً وتصدعت قلوبنا جزعاًمن ذلك الخطب الهائل والحادث الغائل. فظننا أنه سمت لمكروهة قارعة أو حلت به من الدهر بائقة. فقلنا: لا أبكى الله عينيك يا ابن خير الورى! من أية حادثة تستذرف دمعتك وتستمطر عبرتك؟ وأية حالة حتمت عليك هذا المأتم؟ قـال: فزفر الصـادق عليـه السـلام زفـرة انتفـخ منها جـوفه واشتد منها خوفه، فقال: ويكم، إني نظرت صبيحة هذا اليوم في كتاب الجفر المشتمل على علم البلايا والمنايا وعلم ما كان وما يكون إلى يوم القيامة، الذي خص الله تقدس اسمه به محمدا والأئمة من بعده، وتأملت فيه مولد قائمنا عليه السلام وغيبته وإبطاءه وطول عمره وبلوى المؤمنين من بعده في ذلك الزمان، وتولد الشكوك في قلوب الشيعة من طول غيبته، وارتداد أكثرهم عن دينه وخلعهم ربقة الإسلام من أعناقهم التي قال الله عز وجل ﴿وكُلَّ إِنسانٍ أَلْزَمْناهُ طائِرَهُ فِي عُنُقِهِ﴾، يعني الولاية، فأخذتني الرقة واستولت علي الأحزان. فقلنا: يا ابن رسول الله، كرمنا وفضلنا بإشراكك إيانا في بعض ما أنت تعلمه من علم ذلك. قال: إن الله تعالى ذكره أدار في القائم منا ثلاثة أدارها لثلاثة من الرسل؛ قدر مولده تقدير مولد موسى عليه السلام، وقدر غيبته تقدير غيبة عيسى عليه السلام، وقدر إبطاءه تقدير إبطاء نوح عليه السلام. وجعل له من بعد ذلك عمر العبد الصالح- أعني الخضر عليه السلام- دليلا على عمره. فقلنا: اكشف لنا يا ابن رسول الله عن وجوه هذه المعاني. قال: أما مولد موسى عليه السلام، فإن فرعون لما وقف على أن زوال ملكه على يده أمر بإحضار الكهنة فدلوا على نسبه وأنه يكون من بني إسرائيل، فلم يزل يأمر أصحابه بشق بطون الحوامل من نساء بني إسرائيل حتى قتل في طلبه نيفا وعشرين ألف مولود، وتعذر عليه الوصول إلى قتل موسى عليه السلام بحفظ الله تعالى إياه. كذلك بنو أمية وبنو العباس لما أن وقفوا على أن به زوال مملكة الأمراء والجبابرة منهم على يدي القائم منا ناصبونا العداوة ووضعوا سيوفهم في قتل أهل بيت رسول الله صلى الله عليه وآله وسلم وإبادة نسله، طمعا منهم في الوصول إلى قتل القائم عليه السلام. فأبى الله أن يكشف أمره لواحد من الظلمة إلا أن يتم نوره ولو كره المشركون. وأما غيبة عيسى عليه السلام، فإن اليهود والنصارى اتفقت على أنه قُتل، فكذبهم الله عز وجل بقوله ﴿وما قَتَلُوهُ وما صَلَبُوهُ ولكِنْ شُبِّهَ لَهُمْ﴾. كذلك غيبة القائم، فإن الأمة ستنكرهـا لطولهـا؛ فمن قائل يقول: إنه لم يولد! وقـائل يفتري بقوله: إنه ولد ومات! وقائل يكفر بقوله إن حادي عشرنا كان عقيما! وقائل يمرق بقوله إنه يتعدى إلى ثالث عشر فصاعدا! وقائل يعصي الله بدعواه أن روح القائم عليه السلام ينطق في هيكل غيره! وأما إبطاء نوح عليه السلام، فإنه لما استنزل العقوبة من السماء بعث الله إليه جبرئيل عليه السلام معه سبع نويات،فقال: يا نبي الله، إن الله جل اسمه يقول لك إن هؤلاء خلائقي وعبادي، لست أبيدهم بصاعقة من صواعقي إلا بعد تأكيد الدعوة وإلزام الحجة. فعاود اجتهادك في الدعوة لقومك فإني مثيبك عليه واغرس هذا النوى فإن لك في نباتها وبلوغها وإدراكها إذا أثمرت الفرج والخلاص، وبشر بذلك من تبعك من المؤمنين. فلما نبتت الأشجار وتأزرت وتسوقت وأغصنت وزها الثمر عليها بعد زمان طويل استنجز من الله العدة فأمره الله تعالى أن يغرس من نوى تلك الأشجار ويعاود الصبر والاجتهاد ويؤكد الحجة على قومه، فأخبر بذلك الطوائف التي آمنت به فارتد منهم ثلاثمائة رجل وقالوا: لو كان ما يدعيه نوح حقا لما وقع في عدته خلف! ثم إن الله تعالى لم يزل يأمره عند إدراكها كل مرة أن يغرس تارة بعد أخرى إلى أن غرسها سبع مرات،وما زالت تلك الطوائف من المؤمنين ترتد منهم طائفة بعد طائفة إلى أن عادوا إلى نيف وسبعين رجلا. فأوحى الله عز وجل عند ذلك إليه وقال: الآن أسفر الصبح عن الليل لعينك حين صرح الحق عن محضه وصفا الأمر للايمان من الكدر بارتداد كل من كانت طينته خبيثة،فلو أني أهلكت الكفار وأبقيت من ارتد من الطوائف التي كانت آمنت بك لما كنت صدقت وعدي السابق للمؤمنين الذين أخلصوا لي التوحيد من قومك واعتصموا بحبل نبوتك بأن أستخلفهم في الأرض وأمكن لهم دينهم وأبدل خوفهم بالأمن لكي تخلص العبادة لي بذهاب الشك من قلوبهم. وكيف يكون الاستخلاف والتمكين وبدل الخوف بالأمن مني لهم مع ما كنت أعلم من ضعف يقين الذين ارتدوا وخبث طينتهم وسوء سرائرهم التي كانت نتائج النفـاق وسـنوخ الضـلالة؟ فلـو أنهـم تنسموا من الملك الذي أوتي المؤمنون وقت الاستخلاف إذا هلكت أعداؤهم لنشقوا روائح صفاته ولاستحكم سرائر نفاقهم وتأبد خبال ضلالة قلوبهم ولكاشفوا إخوانهم بالعداوة وحاربوهم على طلب الرئاسة والتفرد بالأمر والنهي عليهم! وكيف يكون التمكين في الدين وانتشار الأمر في المؤمنين مع إثارة الفتن وإيقاع الحروب كلا ﴿واصْنَعِ الْفُلْكَ بِأَعْيُنِنا ووَحْيِنا﴾. قال الصادق عليه السلام: وكذلك القائم عليه السلام، فإنه تمتد غيبته ليصرح الحق عن محضه ويصفو الإيمان من الكدر بارتداد كل من كانت طينته خبيثة من الشيعة الذين يخشى عليهم النفاق إذا أحسوا بالاستخلاف والتمكين والأمن المنتشر في عهد القائم عليه السلام. قال المفضل: فقلت: يا ابن رسول الله، فإن النواصب تزعم أن هذه الآية أنزلت في أبي بكر وعمر وعثمان وعلي. فقال: لا هدى الله قلوب الناصبة! متى كان الدين الذي ارتضاه الله ورسوله متمكنا بانتشار الأمن في الأمة وذهاب الخوف من قلوبها وارتفاع الشك من صدورها في عهد واحد من هؤلاء أو في عهد علي عليه السلام مع ارتداد المسلمين والفتن التي كانت تثور في أيامهم والحروب والفتن التي كانت تشب بين الكفار وبينهم؟ ثم تلا الصادق عليه السلام هذه الآية مثلا لإبطاء القائم عليه السلام: ﴿حَتَّى إِذَا اسْتَيْأَسَ الرُّسُلُ وظَنُّوا أَنَّهُمْ قَدْ كُذِبُوا جاءَهُمْ نَصْرُنا…﴾ الآية. وأما العبد الصالح- أعني الخضرعليه السلام- فإن الله تعالى ما طول عمره لنبوة قررها له ولا لكتاب نزل عليه ولا لشريعة ينسخ بها شريعة من كان قبله من الأنبياء عليهم السلام ولا لإمامة يلزم عباده الاقتداء بها ولا لطاعة يفرضها. بلى،إن الله تعالى لما كان في سابق علمه أن يقدر من عمر القائم عليه السلام في أيام غيبته ما يقدره وعلم ما يكون من إنكار عباده بمقدار ذلك العمر في الطول طول عمر العبد الصالح من غير سبب أوجب ذلك إلا لعلة الاستدلال به على عمر القائم عليه السلام ليقطع بذلك حجة المعاندين لئلا يكون للناس على الله حجة. و الأخبار في هذا المعنى أكثر من أن تحصى ذكرنا طرفا منها لئلا يطول به الكتاب. فإن قيل: هذه كلها أخبار آحاد لا يعول على مثلها في هذه المسألة لأنها مسألة علمية. قلنا: موضع الاستدلال من هذه الأخبار ما تضمن الخبر بالشي‏ء قبل كونه فكان كما تضمنه فكان ذلك دلالة على صحة ما ذهبنا إليه من إمامة ابن الحسن لأن العلم بما يكون لا يحصل إلا من جهة علام الغيوب. فلو لم يرو إلا خبر واحد ووافق مخبره ما تضمنه الخبر لكان ذلك كافيا ولذلك كان ما تضمنه القرآن من الخبر بالشي‏ء قبل كونه دليلا على صدق النبي صلى الله عليه وآله وسلم وأن القرآن من قبل الله تعالى وإن كانت المواضع التي تضمنت ذلك محصورة ومع ذلك مسموعة من مخبر واحد لكن دل على صدقه من الجهة التي قلناها. على أن هذه الأخبار متواتر بها لفظا ومعنى.فأما اللفظ فإن الشيعة تواترت بكل خبر منه،وأما المعنى فإن كثرة الأخبار واختلاف جهاتها وتباين طرقها وتباعد رواتها يدل على صحتها لأنه لا يجوز أن يكون كلها باطلة. ولذلك يستدل في مواضع كثيرة على معجزات النبي صلى الله عليه وآله وسلم التي هي سوى القرآن وأمور كثيرة في الشرع تتواتر معنى وإن كان كل لفظ منها منقولا من جهة الآحاد وذلك معتمد عند من خالفنا في هذه المسألة فلا ينبغي أن يتركوه وينسوه إذا جئنا إلى الكلام في الإمامة والعصبية لا ينبغي أن تنتهي بالإنسان إلى حد يجحد الأمور المعلومة. وهذا الذي ذكرناه معتبر في مدائح الرجال وفضائلهم ولذلك استدل على سخاء حاتم وشجاعة عمرو وغير ذلك بمثل ذلك وإن كان كل واحد مما يروى من عطاء حاتم ووقوف عمرو في موقف من المواقف من جهة الآحاد وهذا واضح.","27/1/27/17",""],[1,27,"ومما يدل أيضا على إمامة ابن الحسن عليه السلام زائدا على ما مضى أنه لا خلاف بين الأمة أنه سيخرج في هذه الأمة مهدي يملأ الأرض قسطاً وعدلاً كما ملئت ظلماً وجوراً ،وإذا بينا أن ذلك المهدي من ولد الحسين عليه السلام وأفسدنا قول كل من يدعي ذلك من ولد الحسين سوى ابن الحسن عليه السلام ثبت أن المراد به هو عليه السلام.","27/1/28/1",""],[2,27,"روى إبراهيـم بن سلمة عن أحمـد بن مالك الفزاري عن حيـدر بن محمد الفزاري عن عباد بن يعقوب عن نصر بن مزاحم عن محمد بن مروان عن الكلبي عن أبي صالح عن ابن عباس في قوله تعالى: ﴿وفِي السَّماءِ رِزْقُكُمْ وما تُوعَدُونَ﴾، قال: هو خروج المهدي عليه السلام.","27/1/28/2",""],[3,27,"s131- وبهذا الإسناد عن ابن عباس في قوله: ﴿اعْلَمُوا أَنَّ اللَّهَ يُحْيِ الْأَرْضَ بَعْدَ مَوْتِها﴾: يعني يصلح الأرض بقائم آل محمد من بعد موتها. يعني من بعد جور أهل مملكتها ﴿قَدْ بَيَّنَّا لَكُمُ الْآياتِ﴾ بقائم آل محمد ﴿لَعَلَّكُمْ تَعْقِلُونَ﴾.","27/1/28/3",""],[4,27,"محمد بن إسحاق المقري عن علي بن العباس المقانعي عن بكار بن أحمد عن الحسن بن الحسين عن سفيان الجريري عن عمرو بن هاشم الطائي عن إسحاق بن عبد الله بن علي بن الحسين في هذه الآية: ﴿فَوَ رَبِّ السَّماءِ والْأَرْضِ إِنَّهُ لَحَقٌّ مِثْلَ ما أَنَّكُمْ تَنْطِقُونَ﴾. قال: قيام القائم من آل محمد. قال: وفيه نزلت ﴿وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وعَمِلُوا الصَّالِحاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ ولَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضى لَهُمْ ولَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْناً يَعْبُدُونَنِي لا يُشْرِكُونَ بِي شَيْئاً﴾. قال: نزلت في المهدي عليه السلام.","27/1/28/4",""],[5,27,"وأخبرنا الحسين بن عبيد الله عن أبي جعفر محمد بن سفيان البزوفري عن أحمد بن إدريس عن علي بن محمد بن قتيبة النيشابوري عن الفضل بن شاذان النيشابوري عن الحسن بن علي بن فضال عن المثنى الحناط عن الحسن بن زياد الصيقل قال: سمعت أبا عبد الله جعفر بن محمد عليهما السلام يقول: إن القائم لا يقوم حتى ينادي مناد من السماء تسمع الفتاة في خدرها ويسمع أهل المشرق والمغرب. وفيه نزلت هذه الآية: ﴿إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّماءِ آيَةً فَظَلَّتْ أَعْناقُهُمْ لَها خاضِعِينَ﴾.","27/1/28/5",""],[6,27,"وأخبرني جماعة عن أبي محمد هارون بن موسى التلعكبري عن أبي علي الرازي عن ابن أبي دارم عن علي بن العباس السندي المقانعي عن محمد بن هاشم القيسي عن سهل بن تمام البصري عن عمران القطان عن قتادة عن أبي نضرة عن جابر بن عبد الله الأنصاري قال: قال رسول الله صلى الله عليه وآله وسلم: المهدي يخرج في آخر الزمان.","27/1/28/6",""],[7,27,"محمد بن إسحاق المقري عن المقانعي عن بكار بن أحمد عن الحسن بن الحسين عن المعلى بن زياد عن العلاء بن بشير المرادي عن أبي الصديق الناجي عن أبي سعيد الخدري قال: قال رسول الله صلى الله عليه وآله وسلم: أبشركم بالمهدي؛يبعث في أمتي على اختلاف من الناس وزلزال. يملأ الأرض عدلاً وقسطاً كما ملئت جوراً وظلماً. يرضى عنه ساكن السماء وساكن الأرض.","27/1/28/7",""],[8,27,"عنه عن المقانعي عن بكار بن أحمد عن الحسن بن الحسين عن تليد عن أبي الجحاف عن خالد بن عبد الملك عن مطر الوراق عن الناجي، يعني أبا الصديق،عن أبي سعيد قال: قال رسول الله صلى الله عليه وآله وسلم: أبشروا بالمهدي -قال ثلاثا- يخرج على حين اختلاف من الناس وزلزال شديد. يملأ الأرض قسطاً وعدلاً كما ملئت ظلماً وجوراً.يملأ قلوب عباده عبادة ويسعهم عدله.","27/1/28/8",""],[9,27,"محمد بن إسحاق المقري عن علي بن العباس المقانعي عن بكار بن أحمد عن الحسن بن الحسين عن سفيان الجريري عن عبد المؤمن عن الحارث بن حصيرة عن عمارة بن جوين العبدي عن أبي سعيد الخدري قال:سمعت رسول الله صلى الله عليه وآله وسلم يقول على المنبر: إن المهدي من عترتي من أهل بيتي. يخرج في آخر الزمان. ينزل له من السماء قطرها وتخرج له الأرض بذرها، فيملأ الأرض عدلاً وقسطاً كما ملأها القوم ظلماً وجوراً.","27/1/28/9",""],[10,27,"عنه عن علي بن العباس المقانعي عن بكار بن أحمد عن مصبح عن قيس عن أبي حصين عن أبي صالح عن أبي هريرة قال: قال رسول الله صلى الله عليه وآله وسلم: لو لم يبق من الدنيا إلا يوم واحد لطول الله ذلك اليوم حتى يخرج رجلاً من أهل بيتي يملأ الأرض عدلاًكما ملئت ظلماً وجوراً.","27/1/28/10",""],[11,27,"عنه عن علي عن بكار عن علي بن قادم عن فطر عن عاصم عن زر بن حبيش عن عبدالله بن مسعود قـال: قال رسول الله صلى الله عليه وآله وسلم: لو لم يبق من الدنيا إلا يوم لطول الله تعالى ذلك اليوم حتى يبعث رجلاً مني يواطئ اسمه اسمي واسم أبيه اسم أبي يملأ الأرض عدلاً كما ملئت ظلماً.","27/1/28/11",""],[12,27,"وعنه عن المقانعي عن جعفر بن محمد الزهري عن إسحاق بن منصور عن قيس بن الربيع وغيره عن عاصم عن زر عن عبد الله بن مسعود قال: قال رسول الله صلى الله عليه وآله وسلم: لا تذهب الدنيا حتى يلي أمتي رجل من أهل بيتي يقال له المهدي.","27/1/28/12",""],[13,27,"محمد بن علي عن عثمان بن أحمد السماك عن إبراهيم بن عبد الله الهاشمي عن الحسن بن الفضل البوصرائي عن سعد بن عبد الحميد الأنصاري عن عبد الله بن زياد اليمامي عن عكرمة بن عمار عن إسحاق بن عبد الله بن أبي طلحة عن أنس بن مالك قال: قال رسول الله صلى الله عليه وآله وسلم: نحن بنو عبد المطلب سادة أهل الجنة: أنا وعلي وحمزة وجعفر والحسن والحسين والمهدي.","27/1/28/13",""],[14,27,"عنه عن الحسين بن محمد القطعي عن علي بن حاتم عن محمد بن مروان عن عبيد بن يحيى الثوري عن محمد بن الحسين عن أبيه عن جده عن علي عليه السلام في قوله تعالى: ﴿ونُرِيدُ أَنْ نَمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الْأَرْضِ ونَجْعَلَهُمْ أَئِمَّةً ونَجْعَلَهُمُ الْوارِثِينَ﴾ قال: هم آل محمد، يبعث الله مهديهم بعد جهدهم فيعزهم ويذل عدوهم.","27/1/28/14",""],[15,27,". والأخبار في هذا المعنى أكثر من أن تحصى لا نطول بذكرها الكتاب.","27/1/28/15",""],[1,28,"ما أخبرني جماعة عن أبي جعفر محمد بن سفيان البزوفري عن أحمد بن إدريس عن علي بن محمد بن قتيبة النيشابوري عن الفضل بن شاذان عن نصر بن مزاحم عن ابن لهيعة عن أبي قبيل عن عبد الله بن عمرو بن العاص قال:قال رسول الله صلى الله عليه وآله وسلم في حديث طويل: … فعند ذلك خروج المهدي،وهو رجل من ولد هذا-وأشار بيده إلى علي بن أبي طالب عليه السلام- . به يمحق الله الكذب ويذهب الزمان الكلب،وبه يخرج ذل الرق من أعناقكم. ثم قال: أنا أول هذه الأمة، والمهدي أوسطها،وعيسى آخرها. وبين ذلك شيخ أعوج.","27/1/29/1",""],[2,28,"محمد بن علي عن عثمان بن أحمد السماك عن إبراهيم بن عبد الله الهاشمي عن إبراهيم بن هانئ عن نعيم بن حماد المروزي عن بقية بن الوليد عن أبي بكر بن أبي مريم عن الفضل بن يعقوب الرخامي عن عبد الله بن جعفر عن أبي المليح عن زياد بن بيان عن علي بن نفيل عن سعيد بن المسيب عن أم سلمة قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: المهدي من عترتي من ولد فاطمة.","27/1/29/2",""],[3,28,"أحمد بن إدريس عن علي بن محمد بن قتيبة عن الفضل بن شاذان عن مصبح عن أبي عبد الرحمن عمن سمع وهب بن منبه يقول عن ابن عباس في حديث طويل أنه قال: … يا وهب،ثم يخرج المهدي. قلت: من ولدك؟قال: لا والله، ما هو من ولدي،ولكن من ولد علي. وطوبى لمن أدرك زمانه. وبه يفرج الله عن الأمة حتى يملأها قسطاً وعدلاً… إلى آخر الخبر.","27/1/29/3",""],[4,28,"أحمد بن إدريس عن علي بن محمد بن قتيبة عن الفضل بن شاذان عن محمد بن سنان عن عمار بن مروان عن المنخل بن جميل عن جابر الجعفي عن أبي جعفر عليه السلام قال: المهدي رجل من ولد فاطمة، وهو رجل ادم.","27/1/29/4",""],[5,28,"أخبرنا جماعة عن التلعكبري عن أحمد بن علي الرازي عن محمد بن علي عن عثمان بن أحمد السماك عن إبراهيم بن العلاء الهاشمي عن أبي المليح عن زياد بن بيان عن علي بن نفيل عن سعيد بن المسيب عن أم سلمة قالت: سمعت رسول الله صلى الله عليه وآله وسلم يقول: المهدي من عترتي من ولد فاطمة.","27/1/29/5",""],[6,28,"أحمد بن إدريس عن علي بن الفضل عن أحمد بن عثمان عن أحمد بن رزق عن يحيى بن العلاء الرازي قال: سمعت أبا عبد الله عليه السلام يقول: ينتج الله تعالى في هذه الأمة رجلاًمني وأنا منه. يسوق الله تعالى به بركات السماوات والأرض فينزل السماء قطرها ويخرج الأرض بذرها وتأمن وحوشها وسباعها، ويملأ الأرض قسطاً وعدلاً كما ملئت ظلماً وجوراً. ويقتل حتى يقول الجاهل: لو كان هذا من ذرية محمد لرحم!","27/1/29/6",""],[1,29,"وأما الذي يدل على أنه يكون من ولد الحسين عليه السلام فالأخبار التي أوردناها في أن الأئمة اثنا عشر وذكر تفاصيلهم هي متضمنة لذلك، ولأن كل من اعتبر العدد الذي ذكرناه قال: المهدي من ولد الحسين عليه السلام. وهو من أشرنا إليه. ويزيد ذلك وضوحا:","27/1/30/1",""],[2,29,"ما أخبرني به جماعة عن التلعكبري عن أحمد بن علي الرازي عن محمد بن إسحاق المقرئ عن علي بن العباس المقانعي عن بكار بن أحمد عن الحسن بن الحسين عن سفيان الجريري عن الفضيل بن الزبير قال: سمعت زيد بن علي عليه السلام يقول: هذا المنتظر من ولد الحسين بن علي في ذرية الحسين وفي عقب الحسين عليه السلام. وهو المظلوم الذي قال الله تعالى ﴿ومَنْ قُتِلَ مَظْلُوماً فَقَدْ جَعَلْنا لِوَلِيِّهِ - قال: وليه رجل من ذريته من عقبه، ثم قرأ ﴿وجَعَلَها كَلِمَةً باقِيَةً فِي عَقِبِهِ﴾ - سُلْطاناً فَلا يُسْرِفْ فِي الْقَتْلِ﴾. قال: سلطانه حجته على جميع من خلق الله تعالى حتى يكون له الحجة على الناس ولا يكون لأحد عليه حجة.","27/1/30/2",""],[3,29,"وبهذا الإسناد عن سفيان الجريري قال:سمعت محمد بن عبد الرحمن بن أبي ليلى يقول: والله لا يكون المهدي أبدا إلا من ولد الحسين عليه السلام.","27/1/30/3",""],[4,29,"وبهذا الإسناد عن أحمد بن علي الرازي عن أحمد بن إدريس عن علي بن محمد بن قتيبة عن الفضل بن شاذان عن إبراهيم بن الحكم بن ظهير عن إسماعيل بن عياش عن الأعمش عن أبي وائل قال: نظر أمير المؤمنين عليه السلام إلى ابنه الحسين عليه السلام فقال: إن ابني هذا سيد كما سماه رسول الله سيداً. وسيخرج الله تعالى من صلبه رجلاً باسم نبيكم فيشبهه في الخلق والخلق، يخرج على حين غفلة من الناس وإماتة من الحق وإظهار من الجور. والله لو لم يخرج لضربت عنقه،يفرح لخروجه أهل السماء وسكانها. يملأ الأرض عدلاً كما ملئت جوراً وظلماً. تمام الخبر.","27/1/30/4",""],[5,29,"وبهذا الإسناد عن أحمد بن إدريس عن علي بن محمد بن قتيبة عن الفضل بن شاذان عن عمرو بن عثمان عن محمد بن عذافر عن عقبة بن يونس عن عبد الله بن شريك في حديث له-اختصرناه– قال: مر الحسين عليه السلام على حلقة من بني أمية وهم جلوس في مسجد الرسول صلى الله عليه وآله وسلم فقال: أما والله، لا تذهب الدنيا حتى يبعث الله مني رجلاً يقتل منكم ألفاً ومع الألف ألفاً ومع الألف ألفاً. فقلت: جعلت فداك، إن هؤلاء أولاد كذا وكذا. لا يبلغون هذا. فقال: ويحك،إن في ذلك الزمان يكون للرجل من صلبه كذا وكذا رجلا وإن مولى القوم من أنفسهم.","27/1/30/5",""],[6,29,"وبهذا الإسناد عن أحمد بن إدريس عن أحمد بن محمد بن عيسى عن الحسين بن سعيد الأهوازي عن الحسين بن علوان عن أبي هارون العبدي عن أبي سعيد الخدري في حديث له طويل- اختصرناه- قال: قال رسول الله صلى الله عليه وآله وسلم لفاطمة عليها السلام: يا بنية، إنا أهل البيت أعطينا سبعاًلم يعطها أحد قبلنا: نبينا خير الأنبياء وهو أبوك، ووصينا خير الأوصياء وهو بعلك، وشهيدنا خير الشهداء وهو عم أبيك حمزةُ، ومنا من له جناحان خضيبان يطير بهما في الجنة وهو ابن عمك جعفر، ومنا سبطا هذه الأمة وهما ابناك الحسن والحسين، ومنا والله الذي لا إله إلا هو مهدي هذه الأمة الذي يصلي خلفه عيسى بن مريم. ثم ضرب بيده على منكب الحسين عليه السلام فقال: من هذا ثلاثاً.","27/1/30/6",""],[7,29,"فإن قيل: أليس قد خالف جماعة فيهم من قال المهدي من ولد علي عليه السلام، فقال هو محمد بن الحنفية؟ وفيهم من قال من السبائية هو علي عليه السلام لم يمت. وفيهم من قال جعفر بن محمد لم يمت. وفيهم من قال موسى بن جعفر لم يمت. وفيهم من قال المهدي هو أخوه محمد بن علي وهو حي باق لم يمت. ما الذي يفسد قول هؤلاء؟ قلت: هذه الأقوال كلها أفسدناها بما دللنا عليه من موت من ذهبوا إلى حياته، وبما بينا أن الأئمة اثنا عشر. وبما دللنا على صحة إمامة ابن الحسن عليه السلام من الاعتبار وبما سنذكره من صحة ولادته وثبوت معجزاته الدالة على إمامته، غير أنا نشير إلى إبطال هذه الأقوال بجمل من الأخبار ولا نطول بذكرها لئلا يطول به الكتاب ويمله القارئ.","27/1/30/7",""],[8,29,"فأما من خالف في موت أمير المؤمنين وذكر أنه حي باق فهو مكابر لأن العلم بموته وقتله أظهر وأشهر من قتل كل أحد وموت كل إنسان والشك في ذلك يؤدي إلى الشك في موت النبي صلى الله عليه وآله وسلم وجميع أصحابه. ثم ما ظهر من وصيته وإخبار النبي صلى الله عليه وآله وسلم إياه: أنك تقتل وتخضب لحيتك من رأسك يفسد ذلك أيضا،وذلك أشهر من أن يحتاج إلى أن يروى فيه الأخبار.","27/1/30/8",""],[9,29,"أخبرنا ابن أبي جيد عن محمد بن الحسن بن الوليد عن محمد بن أبي القاسم البرقي عن محمد بن علي أبي سمينة الكوفي عن حماد بن عيسى عن إبراهيم بن عمر عن أبان بن أبي عياش عن سليم بن قيس الهلالي عن جابر بن عبد الله الأنصاري عن عبد الله بن عباس قال: قال رسول الله صلى الله عليه وآله وسلم في وصيته لأمير المؤمنين عليه السلام: يا علي، إن قريشا ستظاهر عليك وتجتمع كلمتهم على ظلمك وقهرك. فإن وجدت أعوانا فجاهدهم، وإن لم تجد أعوانا فكف يدك واحقن دمك،فإن الشهادة من ورائك. لعن الله قاتلك.","27/1/30/9",""],[10,29,"أحمد بن إدريس عن محمد بن عبد الجبار عن صفوان بن يحيى قال.بعث إلي أبو الحسن موسى بن جعفر عليه السلام بهذه الوصية مع الأخرى.","27/1/30/10",""],[11,29,"وأخبرنا أحمد بن عبدون عن ابن أبي الزبير القرشي عن علي بن الحسن بن فضال عن محمد بن عبد الله بن زرارة عمن رواه عن عمرو بن شمر عن جابر عن أبي جعفر عليه السلام قال: هذه وصية أمير المؤمنين عليه السلام إلى الحسن عليه السلام،وهي نسخة كتاب سليم بن قيس الهلالي رفعها إلى أبان وقرأها عليه. قال أبان: وقرأتها على علي بن الحسين عليهما السلام فقال: صدق سليم. رحمه الله. قال سليم: فشهدت وصية أمير المؤمنين عليه السلام حين أوصى إلى ابنه الحسن عليه السلام وأشهد على وصيته الحسين عليه السلام ومحمدا وجميع ولده ورؤساء شيعته وأهل بيته.وقال: يا بني،أمرني رسول الله صلى الله عليه وآله وسلم أن أوصي إليك وأن أدفع إليك كتبي وسلاحي.ثم أقبل عليه فقال: يا بني، أنت ولي الأمر وولي الدم، فإن عفوت فلك، وإن قتلت فضربة مكان ضربة ولا تأثم… ثم ذكر الوصية إلى آخرها. فلما فرغ من وصيته قال: حفظكم الله وحفظ فيكم نبيكم. أستودعكم الله وأقرأ عليكم السلام ورحمة الله. ثم لم يزل يقول: لا إله إلا الله حتى قبض ليلة ثلاث وعشرين من شهر رمضان ليلة الجمعة سنة أربعين من الهجرة،وكان ضرب ليلة إحدى وعشرين من شهر رمضان.","27/1/30/11",""],[12,29,"وفي رواية أخرى أنه قبض ليلة إحدى وعشرين وضرب ليلة تسع عشرة. وهي الأظهر.","27/1/30/12",""],[1,30,"وأما وفاة محمد بن علي بن الحنفية وبطلان قول من ذهب إلى إمامته فقد بيناه فيما مضى من الكتاب، وعلى هذه الطريقة إذا بينا أن المهدي من ولد الحسين عليه السلام بطل قول المخالف في إمامته عليه السلام. ويزيده بيانا:","27/1/31/1",""],[2,30,"ما رواه الحسين بن سعيد عن حماد بن عيسى عن ربعي بن عبد الله عن الفضيل بن يسار قال: قال لي أبو جعفر عليه السلام: لما توجه الحسين عليه السلام إلى العراق دفع إلى أم سلمة زوج النبي صلى الله عليه وآله وسلم الوصية والكتب وغير ذلك، وقال لها: إذا أتاك أكبر ولدي فادفعي إليه ما قد دفعت إليك. فلما قتل الحسين عليه السلام أتى علي بن الحسين عليه السلام أم سلمة فدفعت إليه كل شي‏ء أعطها الحسين عليه السلام.","27/1/31/2",""],[3,30,"وروى سعد بن عبد الله عن محمد بن عيسى بن عبيد عن يونس بن عبد الرحمن عن الحسين بن ثوير بن أبي فاختة عن أبي عبد الله عليه السلام قال: لا تعود الإمامة في أخوين بعد الحسن والحسين عليهما السلام،ولا يكون بعد علي بن الحسين عليه السلام إلا في الأعقاب وأعقاب الأعقاب.","27/1/31/3",""],[4,30,"وما جرى بين محمد بن الحنفية وعلي بن الحسين عليه السلام ومحاكمتهما إلى الحجر معروف لا نطول بذكره هاهنا.","27/1/31/4",""],[1,31,"وأما الناووسية الذين وقفوا على أبي عبد الله جعفر بن محمد عليه السلام وقالوا هو المهدي قد بينا أيضا فساد قولهم بما علمناه من موته واشتهار الأمر فيه ولصحة إمامة ابنه موسى بن جعفر عليه السلام وبما ثبت من إمامة الاثني عشر عليه السلام ويؤكد ذلك ما ثبت من صحة وصيته إلى من أوصى إليه وظهور الحال في ذلك.","27/1/32/1",""],[2,31,"أخبرنا جماعة عن أبي جعفر محمد بن سفيان البزوفري عن أحمد بن إدريس عن أحمد بن محمد بن عيسى عن الحسن بن محبوب عن جميل بن صالح عن هشام بن أحمر عن سالمة مولاة أبي عبد الله عليه السلام قالت: كنت عند أبي عبد الله جعفر بن محمد عليه السلام حين حضرته الوفاة وأغمي عليه،فلما أفاق قال: أعطوا الحسن بن علي بن علي بن الحسين -وهو الأفطس- سبعين دينارا وأعطوا فلانا كذا وفلانا كذا. فقلت: أتعطي رجلا حمل عليك بالشفرة يريد أن يقتلك؟ قال: تريدينيأن لا أكون من الذين قال الله عز وجل: ﴿والَّذِينَ يَصِلُونَ ما أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ ويَخْشَوْنَ رَبَّهُمْ ويَخافُونَ سُوءَ الْحِسابِ﴾؟ نعم يا سالمة،إن الله تعالى خلق الجنة فطيبها وطيب ريحها. وإن ريحها ليوجد من مسيرة ألفي عام. ولا يجد ريحها عاق ولا قاطع رحم.","27/1/32/2",""],[3,31,"وروى أبو أيوب الخوزي قال: بعث إلي أبو جعفر المنصور في جوف الليلن فدخلت عليه وهو جالس على كرسي وبين يديه شمعة وفي يده كتاب،فلما سلمت عليه رمى الكتاب إلي وهو يبكي وقال: هذا كتاب محمد بن سليمان يخبرنا أن جعفر بن محمد قد مات. فإنا لله وإنا إليه راجعون- ثلاثا- وأين مثل جعفر؟! ثم قال لي: اكتب…فكتبت صدر الكتاب. ثم قال: اكتب: إن كان قد أوصى إلى رجل بعينه فقدمه واضرب عنقه. قال: فرجع الجواب إليه أنه قد أوصى إلى خمسة أحدهم أبو جعفر المنصور ومحمد بن سليمان وعبد الله وموسى ابني جعفر وحميدة.فقال المنصور: ليس إلى قتل هؤلاء سبيل.","27/1/32/3",""],[4,31,"وأما الواقفة الذين وقفوا على موسى بن جعفر عليهماالسلام وقالوا هو فقد أفسدنا أقوالهم بما دللنا عليه من موته واشتهار الأمر فيه وثبوت إمامة ابنه الرضا عليه السلام وفي ذلك كفاية لمن أنصف.","27/1/32/4",""],[5,31,"وأما المحمدية الذين قالوا بإمامة محمد بن علي العسكري وأنه حي لم يمت،فقولهم باطل لما دللنا به على إمامة أخيه الحسن بن علي أبي القائم عليه السلام. وأيضا فقد مات محمد في حياة أبيه عليه السلام موتا ظاهرا كما مات أبوه وجده،فالمخالف في ذلك مخالف في الضرورات. ويزيد ذلك بيانا:","27/1/32/5",""],[1,32,"ما رواه سعد بن عبد الله عن جعفر بن محمد بن مالك عن سيار بن محمد البصري عن علي بن عمر النوفلي قال: كنت مع أبي الحسن العسكري عليه السلام في داره فمر عليه أبو جعفر، فقلت له: هذا صاحبنا؟ فقال: لا. صاحبكم الحسن.","27/1/33/1",""],[2,32,"وعنه عن هارون بن مسلم بن سعدان عن أحمد بن محمد بن رجا صاحب الترك قال:قال أبو الحسن عليه السلام: الحسن ابني القائم من بعدي.","27/1/33/2",""],[3,32,"عنه عن أحمد بن عيسى العلوي من ولد علي بن جعفر قال: دخلت على أبي الحسن عليه السلام بصريا فسلمنا عليه، فإذا نحن بأبي جعفر وأبي محمد قد دخلا،فقمنا إلى أبي جعفر لنسلم عليه فقال أبو الحسن عليه السلام: ليس هذا صاحبكم. عليكم بصاحبكم. وأشار إلى أبي محمد عليه السلام.","27/1/33/3",""],[4,32,"وروى يحيى بن بشار القنبري قال: أوصى أبو الحسن عليه السلام إلى ابنه الحسن عليه السلام قبل مضيه بأربعة أشهر،وأشهدني على ذلك وجماعة من الموالي.","27/1/33/4",""],[5,32,"فقد رواه سعد بن عبد الله الأشعري قال:حدثني أبو هاشم داود بن القاسم الجعفري قال: كنت عند أبي الحسن عليه السلام وقت وفاة ابنه أبي جعفر، وقد كان أشار إليه ودل عليه، فإني لأفكر في نفسي وأقول هذه قضية أبي إبراهيم وقضية إسماعيل، فأقبل علي أبو الحسن عليه السلام فقال: نعم يا أبا هاشم. بدا لله تعالى في أبي جعفر وصير مكانه أبا محمد،كما بدا لله في إسماعيل بعد ما دل عليه أبو عبد الله عليه السلام ونصبه. وهو كما حدثت به نفسك وإن كره المبطلون. أبو محمد ابني الخلف من بعدي؛ عنده ما تحتاجون إليه ومعه آلة الإمامة، والحمد لله.","27/1/33/5",""],[6,32,"سعد عن علي بن محمد الكليني عن إسحاق بن محمد النخعي عن شاهويه بن عبد الله الجلاب قال: كنت رويت عن أبي الحسن العسكري عليه السلام في أبي جعفر ابنه روايات تدل عليه، فلما مضى أبو جعفر قلقت لذلك وبقيت متحيرا لا أتقدم ولا أتأخر، وخفت أن أكتب إليه في ذلك فلا أدري ما يكون. فكتبت إليه أسأله الدعاء وأن يفرج الله تعالى عنا في أسباب من قبل السلطان كنا نغتم بها في غلماننا. فرجع الجواب بالدعـاء ورد الغلمان علينـا،وكتب في آخر الكتاب: أردتَ أن تسـأل عن الخلف بعد مضي أبي جعفر، وقلقت لذلك، فلا تغتم، فإن الله لا يضل قوماًبعد إذ هداهم حتى يبين لهم ما يتقون. صاحبكم بعدي أبو محمد ابني، وعنده ما تحتاجون إليه. يقدم الله ما يشاء ويؤخر ما يشاء: ﴿ما نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِها نَأْتِ بِخَيْرٍ مِنْها أَوْ مِثْلِها﴾. قد كتبت بما فيه بيان وقناع لذي عقل يقظان.","27/1/33/6",""],[7,32,"قال محمد بن الحسن ما تضمن الخبر المتقدم من قوله بدا لله في محمد كما بدا له في إسماعيل معناه ظهر من الله وأمره في أخيه الحسن ما زال الريب والشك في إمامته، فإن جماعة من الشيعة كانوا يظنون أن الأمر في محمد من حيث كان الأكبر، كما كان يظن جماعة أن الأمر في إسماعيل بن جعفر دون موسى عليه السلام. فلما مات محمد ظهر من أمر الله فيه وأنه لم ينصبه إماما كما ظهر في إسماعيل مثل ذلك، لا أنه كان نص عليه ثم بدا له في النص على غيره فإن ذلك لا يجوز على الله تعالى العالم بالعواقب.","27/1/33/7",""],[8,32,"وروى سعد بن عبد الله عن محمد بن أحمد العلوي عن أبي هاشم داود بن القاسم الجعفري قال: سمعت أبا الحسن العسكري عليه السلام يقول: الخلف من بعدي الحسن. فكيف لكم بالخلف من بعد الخلف؟ فقلت: ولم جعلني الله فداك؟ فقال: لأنكم لا ترون شخصه ولا يحل لكم ذكره باسمه. فقلت: فكيف نذكره؟فقال: قولوا الحجة من آل محمد صلى الله عليه وآله وسلم.","27/1/33/8",""],[9,32,"وروى محمد بن الحسين بن أبي الخطاب عن ابن أبي الصهبان قال: لما مات أبو جعفر محمد بن علي بن محمد بن علي بن موسى عليهم السلام وضع لأبي الحسن علي بن محمد عليه السلام كرسي فجلس عليه، وكان أبو محمد الحسن بن علي عليهما السلام قائما في ناحية،فلما فرغ من غسل أبي جعفر التفت أبو الحسن إلى أبي محمد عليه السلام فقال: يا بني، أحدث لله شكرا فقد أحدث فيك أمرا.","27/1/33/9",""],[10,32,"وأما معجزاته الدالة على إمامته فأكثر من أن تحصى. منها:","27/1/33/10",""],[11,32,"ما رواه سعد بن عبد الله الأشعري عن أبي هاشم داود بن القاسم الجعفري قال: كنت عند أبي محمد عليه السلام فاستؤذن لرجل من أهل اليمن فدخل رجل طويل جسيم، فسلم عليه بالولاية، فقلت في نفسي ليت شعري من هذا؟ فقال أبو محمد عليه السلام: هذا من ولد الأعرابية صاحبة الحصاة التي طبع فيها آبائي بخواتيم فانطبعت. ثم قال: هاتها. فأخرج حصاة وفي جانب منها موضع أملس، فطبع فيها فانطبع. وكأني أقرأ نقش خاتمه الساعة: الحسن بن علي. ثم نهض الرجل وهو يقول: ﴿رَحْمَةُ اللهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ.﴾ ﴿ذُرِّيَّةٌ بَعْضُهَا مِنْ بَعْضٍ.﴾أشهد أن حقك الحق الواجب كوجوب حق أمير المؤمنين والأئمة عليهم السلام، وإليك انتهت الحكمة والولاية،وأنك ولي الله الذي لا عذر لأحد في الجهل بك. فسألته عن اسمه،فقال: اسمي مهجع بن الصلت بن عقبة بن سمعان بن غانم ابن أم غانم، وهي الأعرابية اليمانية صاحبة الحصاة التي ختم فيها أمير المؤمنين عليه السلام…تمام الحديث.","27/1/33/11",""],[12,32,"وروى علي بن محمد بن زياد الصيمري قال: دخلت على أبي أحمد عبيد الله بن عبد الله بن طاهر وبين يديه رقعة أبي محمد عليه السلام فيها: إني نازلت الله في هذا الطاغي - يعني المستعين- وهو آخذه بعد ثلاث. فلما كان اليوم الثالث خلع وكان من أمره ما كان إلى أن قتل.","27/1/33/12",""],[13,32,"وروى سعد بن عبد الله عن أبي هاشم الجعفري قال: كنت محبوسا مع أبي محمد عليه السلام في حبس المهتدي بن الواثق، فقال لي: يا با هاشم، إن هذا الطاغي أراد أن يعبث بالله في هذه الليلة، وقد بتر الله عمره وجعله للقائم من بعده. ولم يكن لي ولد وسأرزق ولدا. قال أبو هاشم: فلما أصبحنا شغب الأتراك على المهتدي فقتلوه، وولي المعتمد مكانه وسلمنا الله تعالى.","27/1/33/13",""],[14,32,"وأخبرني جمـاعة عن التلعكبري عن أحـمد بن علي الرازي عن الحسـين بن علي عن محمد بن الحسن بن رزين قال: حدثني أبو الحسن الموسوي الخيبري قال: حدثني أبي أنه كان يغشى أبا محمد عليه السلام بسر من رأى كثيرا، وأنه أتاه يوما فوجده وقد قدمت إليه دابته ليركب إلى دار السلطان، وهو متغير اللون من الغضب، وكان يجيئه رجل من العامة فإذا ركب دعا له وجاء بأشياء يشيع بها عليه،فكان عليه السلام يكره ذلك. فلما كان ذلك اليوم زاد الرجل في الكلام وألح، فسار حتى انتهى إلى مفرق الطريقين وضاق على الرجل أحدهما من الدواب فعدل إلى طريق يخرج منه ويلقاه فيه، فدعا عليه السلام ببعض خدمه وقال له: امض فكفن هذا. فتبعه الخادم. فلما انتهى عليه السلام إلى السوق ونحن معه خرج الرجل من الدرب ليعارضه، وكان في الموضع بغل واقف، فضربه البغل فقتله، ووقف الغلام فكفنه كما أمره،وسار عليه السلام وسرنا معه.","27/1/33/14",""],[15,32,"وروى سعد بن عبد الله عن داود بن قاسم الجعفري قال: كنت عند أبي محمد عليه السلام فقال: إذا قام القائم يهدم المنار والمقاصير التي في المساجد. فقلت في نفسي: لأي معنى هذا؟فأقبل علي فقال: معنى هذا أنها محدثة مبتدعة لم يبنها نبي ولا حجة.","27/1/33/15",""],[16,32,"وبهذا الإسناد عن أبي هاشم الجعفري قال:سمعت أبا محمد عليه السلام يقول: من الذنوب التي لا تغفر قول الرجل: ليتني لا أؤاخذ إلا بهذا. فقلت في نفسي: إن هذا لهو الدقيق؛ينبغي للرجل أن يتفقد من أمره ومن نفسه كل شي‏ء. فأقبل علي أبو محمد عليه السلام فقال: يا أبا هاشم،صدقت. فالزم ما حدثت به نفسك،فإن الإشراك في الناس أخفى من دبيب الذر على الصفا في الليلة الظلماء ومن دبيب الذر على المسح الأسود.","27/1/33/16",""],[17,32,"سعد بن عبد الله عن أحمد بن الحسين بن عمر بن يزيد قال:أخبرني أبو الهيثم بن سيابة أنه كتب إليه لما أمر المعتز بدفعه إلى سعيد الحاجب عند مضيه إلى الكوفة وأن يحدث فيه ما يحدث به الناس بقصر ابن هبيرة: جعلني الله فداك، بلغنا خبر قد أقلقنا وأبلغ منا؟ فكتب عليه السلام إليه: بعد ثالث يأتيكم الفرج. فخلع المعتز اليوم الثالث.","27/1/33/17",""],[18,32,"أخبرني جماعة عن أبي المفضل الشيباني عن أبي الحسين محمد بن بحر بن سهل الشيباني الرهني قال:قال بشر بن سليمان النخاس، وهو من ولد أبي أيوب الأنصاري أحد موالي أبي الحسن وأبي محمد عليهما السلام وجارهما بسر من رأى: أتاني كافور الخادم فقال: مولانا أبو الحسن علي بن محمد العسكري عليهما السلام يدعوك إليه. فأتيته،فلما جلست بين يديه قال لي: يا بشر، إنك من ولد الأنصار، وهذه الموالاة لم تزل فيكم يرثها خلف عن سلف، وأنتم ثقاتنا أهل البيت،وإني مزكيك ومشرفك بفضيلة تسبق بها الشيعة في الموالاة بها بسر أطلعك عليه وأنفذك في ابتياع أمة. فكتب كتابا لطيفا بخط رومي ولغة رومية وطبع عليه خاتمه وأخرج شقيقة صفراء فيها مائتان وعشرون دينارا فقال: خذها،وتوجه بها إلى بغداد وأحضر معبر الفرات ضحوة يوم كذا. فإذا وصلت إلى جانبك زواريق السبايا وترى الجواري فيها ستجد طوائف المبتاعين من وكلاء قواد بني العباس وشرذمة من فتيان العرب، فإذا رأيت ذلك فأشرف من البعد على المسمى عمر بن يزيد النخاس عامة نهارك إلى أن تبرز للمبتاعين جارية صفتها كذا وكذا، لابسة حريرين صفيقين، تمتنع من العرض ولمس المعترض والانقياد لمن يحاول لمسها. وتسمع صرخة رومية من وراء ستر رقيق فاعلم أنها تقول: وا هتك ستراه! فيقول بعض المبتاعين: على ثلاثمائة دينار، فقد زادني العفاف فيها رغبة. فتقول له بالعربية: لو برزت في زي سليمان بن داود وعلى شبه ملكه ما بدت لي فيك رغبة، فاشفق على مالك. فيقول النخاس: فما الحيلة ولا بد من بيعك؟فتقول الجارية: وما العجلة؟ ولا بد من اختيار مبتاع يسكن قلبي إليه وإلى وفائه وأمانته. فعند ذلك قم إلى عمر بن يزيد النخاس وقل له إن معك كتابا ملصقا لبعض الأشراف كتبه بلغة رومية وخط رومي، ووصف فيه كرمه ووفاءه ونبله وسخاءه. فناولها لتتأمل منه أخلاق صاحبه، فإن مالت إليه ورضيته فأنا وكيله في ابتياعها منك. قال بشر بن سليمان: فامتثلت جميع ما حده لي مولاي أبو الحسن عليه السلام في أمر الجارية، فلما نظرت في الكتاب بكت بكاء شديدا وقالت لعمر بن يزيد: بعني! من صاحب هذا الكتاب؟وحلفت بالمحرجة والمغلظة أنه متى امتنع من بيعها منه قتلت نفسها. فما زلت أشاحه في ثمنها حتى استقر الأمر فيه على مقدار ما كان أصحبنيه مولاي عليه السلام من الدنانير، فاستوفاه مني وتسلمت الجارية ضاحكة مستبشرة،وانصرفت بها إلى الحجيرة التي كنت آوي إليها ببغداد. فما أخذها القرار حتى أخرجت كتاب مولانا عليه السلام من جيبها وهي تلثمه وتطبقه على جفنها وتضعه على خدها وتمسحه على بدنها.فقلت تعجبا منها: تلثمين كتابا لا تعرفين صاحبه؟ فقالت: أيها العاجز الضعيف المعرفة بمحل أولاد الأنبياء! أعرني سمعك وفرغ لي قلبك. أنا ملكية بنت يشوعا بن قيصر ملك الروم،وأمي من ولد الحواريين تنسب إلى وصي المسيح شمعون. أنبئك بالعجب: إن جدي قيصر أراد أن يزوجني من ابن أخيه وأنا من بنات ثلاث عشرة سنة، فجمع في قصره من نسل الحواريين من القسيسين والرهبان ثلاثمائة رجل ومن ذوي الأخطار منهم سبعمائة رجل، وجمع من أمراء الأجناد وقواد العسكر ونقباء الجيوش وملوك العشائر أربعة آلاف،وأبرز من بهي ملكه عرشا مصنوعا من أصناف الجوهر إلى صحن القصر ورفعه فوق أربعين مرقاة. فلما صعد ابن أخيه وأحدقت الصلب وقامت الأساقفة عكفا ونشرت أسفار الإنجيل تسافلت الصلب من الأعلى فلصقت بالأرض وتقوضت أعمدة العرش فانهارت إلى القرار وخر الصاعد من العرش مغشيا عليه، فتغيرت ألوان الأساقفة وارتعدت فرائصهم، فقال كبيرهم لجدي: أيها الملك، أعفنا من ملاقاة هذه النحوس الدالة على زوال دولة هذا الدين المسيحي والمذهب الملكاني. فتطير جدي من ذلك تطيرا شديدا وقال للأساقفة: أقيموا هذه الأعمدة وارفعوا الصلبان وأحضروا أخا هذا المدبر العاثر المنكوس جده لأزوجه هذه الصبية فيدفع نحوسه عنكم بسعوده. فلما فعلوا ذلك حدث على الثاني مثل ما حدث على الأول وتفرق الناس. وقـام جـدي قيـصر مغتمـا فدخـل منـزل النسـاء وأرخيـت الستـور. وأريـت في تلك الليلة كأن المسيح وشمعون وعدة من الحواريين قد اجتمعوا في قصر جدي ونصبوا فيه منبرا من نور يباري السماء علوا وارتفاعا في الموضع الذي كان نصب جدي فيه عرشه، ودخل عليهم محمد صلى الله عليه وآله وسلم وختنه ووصيه وعدة من أبنائه عليهم السلام.فتقدم المسيح إليه فاعتنقه،فيقول له محمد صلى الله عليه وآله وسلم: يا روح الله، إني جئتك خاطبا من وصيك شمعون فتاته مليكة لابني هذا. وأومأ بيده إلى أبي محمد عليه السلام ابن صاحب هذا الكتاب. فنظر المسيح إلى شمعون وقال له: قد أتاك الشرف! فصل رحمك رحم آل محمد عليهم السلام. قال: قد فعلت.فصعد ذلك المنبر فخطب محمد صلى الله عليه وآله وسلم وزوجني من ابنه، وشهد المسيح عليه السلام وشهد أبناء محمد عليهم السلام والحواريون. فلما استيقظت أشفقت أن أقص هذه الرؤيا على أبي وجدي مخافة القتل، فكنت أسرها ولا أبديها لهم. وضرب صدري بمحبة أبي محمد عليه السلام حتى امتنعت من الطعام والشراب، فضعفت نفسي ودق شخصي ومرضت مرضا شديدا،فما بقي في مدائن الروم طبيب إلا أحضره جدي وسأله عن دوائي. فلما برح به اليأس قال: يا قرة عيني، وهل يخطر ببالك شهوة فأزودكها في هذه الدنيا؟ فقلت: يا جدي،أرى أبواب الفرج علي مغلقة. فلو كشفت العذاب عمن في سجنك من أسارى المسلمين وفككت عنهم الأغلال وتصدقت عليهم ومنيتهم الخلاص رجوت أن يهب لي المسيح وأمه عافية. فلما فعل ذلك تجلدت في إظهار الصحة من بدني قليلا وتناولت يسيرا من الطعام،فسر بذلك وأقبل على إكرام الأسارى وإعزازهم. فأريت أيضا بعد أربع عشرة ليلة كأن سيدة نساء العالمين فاطمة عليها السلام قد زارتني ومعها مريم ابنة عمران وألف من وصائف الجنان، فتقول لي مريم: هذه سيدة نساء العالمين أم زوجك أبي محمد. فأتعلق بها وأبكي وأشكو إليها امتناع أبي محمد عليه السلام من زيارتي. فقالت سيدة النساء عليها السلام: إن ابني أبا محمد لا يزورك وأنت مشركة بالله على مذهب النصارى. وهذه أختي مريم بنت عمران تبرأ إلى الله تعالى من دينك. فإن ملت إلى رضى الله ورضى المسيح ومريم عليهما السلام وزيارة أبي محمد إياك فقولي: أشهد أن لا إله إلا الله وأن أبي محمدا رسول الله. فلما تكلمت بهذه الكلمة ضمتني إلى صدرها سيدة نساء العالمين عليها السلام وطيبت نفسي وقالت: الآن توقعي زيارة أبي محمد، فإني منفذته إليك. فانتبهت وأنا أنول وأتوقع لقاء أبي محمد عليه السلام. فلما كان في الليلة القابلة رأيت أبا محمد عليه السلام وكأني أقول له: جفوتني يا حبيبي بعد أن أتلفت نفسي معالجة حبك. فقال: ما كان تأخري عنك إلا لشركك، فقد أسلمت وأنا زائرك في كل ليلة إلى أن يجمع الله تعالى شملنا في العيان. فما قطع عني زيارته بعد ذلك إلى هذه الغاية. قال بشر: فقلت لها: وكيف وقعت في الأسارى؟ فقالت: أخبرني أبو محمد عليه السلام ليلة من الليالي أن جدك سيسير جيشا إلى قتال المسلمين يوم كذا وكذا ثم يتبعهم، فعليك باللحاق بهم متنكرة في زي الخدم مع عدة من الوصائف من طريق كذا. ففعلت ذلك فوقعت علينا طلائع المسلمين حتى كان من أمري ما رأيت وشاهدت، وما شعر بأني ابنة ملك الروم إلى هذه الغاية أحد سواك، وذلك باطلاعي إياك عليه. ولقد سألني الشيخ الذي وقعت إليه في سهم الغنيمة عن اسمي فأنكرته وقلت: نرجس. فقال: اسم الجواري. قلت: العجب إنك رومية ولسانك عربي؟!قالت: نعم، من ولوع جدي وحمله إياي على تعلم الآداب أن أوعز إلى امرأة ترجمانة لي في الاختلاف إلي. وكانت تقصدني صباحا ومساء وتفيدني العربية حتى استمر لساني عليها واستقام. قال بشر: فلما انكفأت بها إلى سر من رأى دخلت على مولاي أبي الحسن عليه السلام،فقال: كيف أراك الله عز الإسلام وذل النصرانية وشرف محمد وأهل بيته عليهم السلام؟ قالت: كيف أصف لك يا ابن رسول الله ما أنت أعلم به مني؟ قال: فإني أحببت أن أكرمك. فما أحب إليك؛ عشرة آلاف دينار أم بشرى لك بشرف الأبد؟ قالت: بشرى بولد لي.قال لها: أبشري بولد يملك الدنيا شرقا وغربا ويملأ الأرض قسطاً وعدلاً كما ملئت ظلماً وجوراً. قالت: ممن؟ قال: ممن خطبك رسول الله صلى الله عليه وآله وسلم له ليلة كذا في شهر كذا من سنة كذا بالرومية. قالت: من المسيح ووصيه؟ قال لها: ممن زوجك المسيح عليه السلام ووصيه. قالت: من ابنك أبي محمد عليه السلام؟ فقال: هل تعرفينه؟ قالت: وهل خلت ليلة لم يرني فيها منذ الليلة التي أسلمت على يد سيدة النساء عليها السلام؟ قال: فقال مولانا: يا كافور، ادع أختي حكيمة. فلما دخلت قال لها: ها هيه. فاعتنقتها طويلا وسرت بها كثيرا. فقال لها أبو الحسن عليه السلام: يا بنت رسول الله، خذيها إلى منزلك وعلميها الفرائض والسنن، فإنها زوجة أبي محمد وأم القائم عليه السلام.","27/1/33/18",""],[19,32,"وأخبرنا جماعة عن أبي محمد هارون بن موسى التلعكبري رحمه الله قال: كنت في دهليز أبي علي محمد بن همام رحمه الله على دكة إذ مر بنا شيخ كبير عليه دراعة، فسلم على أبي علي بن همام فرد عليه السلام ومضى.فقال لي: أتدري من هو هذا؟ فقلت لا. فقال: هذا شاكري لسيدنا أبي محمد عليه السلام. أفتشتهي أن تسمع من أحاديثه عنه شيئا؟قلت: نعم. فقال لي: معك شي‏ء تعطيه؟فقلت له: معي درهمان صحيحان. فقال: هما يكفيانه. فمضيت خلفه فلحقته فقلت له: أبو علي يقول لك تنشط للمصير إلينا. فقال: نعم. فجئنا إلى أبي علي بن همام فجلس إليه، فغمز بي أبو علي أن أسلم إليه الدرهمين، فسلمتها إليه. فقال لي: ما يحتاج إلى هذا؟ ثم أخذهما. فقال له أبو علي بن همام: يا با عبد الله محمد! حدثنا عن أبي محمد عليه السلام ما رأيت. فقال: كان أستاذي صالحا من بين العلويين لم أر قط مثله، وكان يركب بسرج صفته بزيون مسكي وأزرق. (قال) وكان يركب إلى دار الخلافة بسر من رأى في كل إثنين وخميس. (قال) وكان يوم النوبة يحضر من الناس شي‏ء عظيم ويغص الشارع بالدواب والبغال والحمير والضجة فلا يكون لأحد موضع يمشي ولا يدخل بينهم.(قال) فإذا جاء أستاذي سكنت الضجة وهدأ صهيل الخيل ونهاق الحمير. (قال) وتفرقت البهائم حتى يصير الطريق واسعا لا يحتاج أن يتوقى من الدواب تحفه ليزحمها. ثم يدخل فيجلس في مرتبته التي جعلت له. فإذا أراد الخروج وصاح البوابون: هاتوا دابة أبي محمد، سكن صياح الناس وصهيل الخيل،فتفرقت الدواب حتى يركب ويمضي. وقال الشاكري: واستدعاه يوما الخليفة وشق ذلك عليه وخاف أن يكون قد سعى به إليه بعض من يحسده على مرتبته من العلويين والهاشميين، فركب ومضى إليه. فلما حصل في الدار قيل له: إن الخليفة قد قام. ولكن اجلس في مرتبتك أو انصرف. (قـال) فانصـرف وجـاء إلى سوق الدواب وفيها من الضجة والمصادمة واختلاف الناس شي‏ء كثير. فلما دخل إليها سكن الناس وهدأت الدواب. (قال) وجلس إلى نخاس كان يشتري له الدواب. (قال) فجي‏ء له بفرس كبوس لا يقدر أحد أن يدنو منه. (قال) فباعوه إياه بوكس، فقال لي: يا محمد،قم فاطرح السرج عليه. (قال) فقلت: إنه لا يقول لي ما يؤذيني. فحللت الحزام وطرحت السرج عليه،فهدأ ولم يتحرك. وجئت به لأمضي به، فجاء النخاس فقال لي: ليس يباع. فقال لي: سلمه إليهم. قال: فجاء النخاس ليأخذه، فالتفت إليه التفاتة ذهب منه منهزما. (قال) وركب ومضينا، فلحقنا النخاس فقال: صاحبه يقول أشفقت أن يرد،فإن كان قد علم ما فيه من الكبس فليشتره. فقال لي أستاذي: قد علمت. فقال: قد بعتك. فقال لي: خذه. فأخذته. (قال) فجئت به إلى الإصطبل،فما تحرك ولا آذاني ببركة أستاذي.فلما نزل جاء إليه وأخذ أذنه اليمنى فرقاه ثم أخذ أذنه اليسرى فرقاه. فوالله لقد كنت أطرح الشعير له فأفرقه بين يديه فلا يتحرك. هذا ببركة أستاذي. قال أبو محمد: قال أبو علي بن همام: هذا الفرس يقال له الصئول. (قال) يرجم بصاحبه حتى يرجم به الحيطان ويقوم على رجليه ويلطم صاحبه. قال محمد الشاكري: كان أستاذي أصلح من رأيت من العلويين والهاشميين. ما كان يشرب هذا النبيذ. كان يجلس في المحراب ويسجد فأنام وانتبه وأنام وهو ساجد، وكان قليل الأكل. كان يحضره التين والعنب والخوخ وما شاكله فيأكل منه الواحدة والثنتين ويقول: شل هذا يا محمد إلى صبيانك. فأقول: هذا كله؟ فيقول: خذه. ما رأيت قط أسدى منه. فهذه بعض دلائله، ولو استوفيناها لطال به الكتاب. وكان مع إمامته من أكرم الناس وأجودهم.","27/1/33/19",""],[20,32,"أخبرني جماعة عن التلعكبري عن أحمد بن علي الرازي عن الحسين بن علي عن أبي الحسن الأيادي قال:حدثني أبو جعفر العمري رضي الله عنه أن أبا طاهر بن بلبل حج فنظر إلى علي بن جعفر الهماني وهو ينفق النفقات العظيمة، فلما انصرف كتب بذلك إلى أبي محمد عليه السلام،فوقع في رقعته: قد كنا أمرنا له بمائة ألف دينار،ثم أمرنا له بمثلها فأبى قبولها إبقاء علينا. ما للناس والدخول في أمرنا فيما لم ندخلهم فيه؟","27/1/33/20",""],[21,32,"فأما القائلون بأن الحسن بن علي لم يمت وهو حي باق وهو المهدي فقولهم باطل بما علمنا موته كما علمنا موت من تقدم من آبائه. والطريقة واحدة والكلام عليهم واحد. هذا مع انقراض القائلين به واندراسهم،ولو كانوا محقين لما انقرضوا. ويدل أيضا على صحة وفاته:","27/1/33/21",""],[22,32,"ما رواه سعد بن عبد الله الأشعري قال:سمعت أحمد بن عبيد الله بن خاقان وهو عامل السلطان بقم-في حديث طويل اختصرناه– قال: لما اعتل أبو محمد الحسن بن علي عليه السلام بعث إلى أبي أن ابن الرضا قد اعتل،فركب مبادرا إلى دار الخلافة. ثم رجع مستعجلا ومعه خمسة من خدم أمير المؤمنين من ثقاته وخاصته،منهم نحرير. فأمرهم بلزوم دار أبي محمد وتعرف خبره وحاله. وبعث إلى نفر من المتطببين فأمرهم بالاختلاف إليه وتعهده صباحا ومساء. فلما كان بعد يومين أخبر أنه قد ضعف،فركب حتى نظر إليه ثم أمر المتطببين بلزومه وبعث إلى قاضي القضاة فأحضره مجلسه وأمره أن يختار من أصحابه عشرة فبعث بهم إلى دار أبي محمد وأمرهم بلزومه ليلا ونهارا.فلم يزالوا هناك حتى توفي عليه السلام لأيام مضت من شهر ربيع الأول سنة ستين ومائتين. فصارت سر من رأى ضجة واحدة: مات ابن الرضا.ثم أخذوا في تهيئته وعطلت الأسواق وركب أبي وبنو هاشم وسائر الناس إلى جنازته وأمر السلطان أبا عيسى بن المتوكل بالصلاة عليه، فلما وضعت الجنازة دنا أبو عيسى فكشف عن وجهه وعرضه على بني هاشم من العلوية والعباسية والقواد والكتاب والقضاة والفقهاء المعدلين وقال: هذا الحسن بن علي بن محمد بن الرضا، مات حتف أنفه على فراشه، حضره من خدم أمير المؤمنين من ثقاته فلان وفلان وفلان. ثم غطى وجهه وصلى عليه وكبرعليه خمسا وأمر بحمله فحمل من وسط داره ودفن في البيت الذي دفن فيه أبوه.","27/1/33/22",""],[23,32,"وأما من قال إن الحسن بن علي عليهما السلام يعيش بعد موته وإنه القائم بالأمر وتعلقهم بما روي عن أبي عبد الله عليه السلام أنه قال: إنما سمي القائم قائما لأنه يقوم بعد ما يموت، فقوله باطل بما دللنا عليه من موته. وادعاؤهم أنه يعيش يحتاج إلى دليل، ولو جاز لهم ذلك لجاز أن تقول الواقفة إن موسى بن جعفر عليهماالسلام يعيش بعد موته. على أن هذا يؤدي إلى خلو الزمان من إمام بعد موت الحسن عليه السلام إلى حين يحيى. وقد دللنا بأدلة عقلية على فساد ذلك.ويدل على فساد ذلك أيضا:","27/1/33/23",""],[24,32,"ما رواه سعد بن عبد الله الأشعري عن محمد بن عيسى بن عبيد ومحمد بن الحسين بن أبي الخطاب عن محمد بن الفضل عن أبي حمزة الثمالي قال: قلت لأبي عبد الله عليه السلام: أتبقى الأرض بغير إمام؟ فقال: لو بقيت الأرض بغير إمام ساعة لساخت.","27/1/33/24",""],[25,32,"وقول أمير المؤمنين عليه السلام: اللهم إنك لا تخلي الأرض من حجة إما ظاهرا مشهورا أو خائفا مغمورا يدل على ذلك.","27/1/33/25",""],[26,32,"على أن قوله يقوم بعد ما يموت لو صح الخبر احتمل أن يكون أراد يقوم بعد ما يموت ذكره ويخمل ولا يعرف،وهذا جائز في اللغة. وما دللنا به على أن الأئمة اثنا عشر يبطل هذا المقال لأن الحسن بن علي عليه السلام هو الحادي عشر فيبطل قولهم على أن القائلين بذلك قد انقرضوا ولله الحمد ولو كان حقا لما انقرض القائلون به.","27/1/33/26",""],[27,32,"وأما من ذهب إلى الفترة بعد الحسن بن علي عليهما السلام وخلو الزمان من إمام، فقولهم باطـل بمـا دللنـا عليـه مـن أن الزمـان لا يخلـو عن إمـام في حـال من الأحـوال بأدلـة عقليـة وشرعية وتعلقهم بالفترات بين الرسل باطل لأن الفترة عبارة عن خلو الزمان من نبي ونحن لا نوجب النبوة في كل حال وليس في ذلك دلالة على خلو الزمان من إمام على أن القائلين بذلك قد انقرضوا ولله الحمد فسقط هذا القول أيضا.","27/1/33/27",""],[28,32,"وأما القائلون بإمامة جعفر بن علي بعد أخيه عليه السلام، فقولهم باطل بما دللنا عليه من أنه يجب أن يكون الإمام معصوما لا يجوز عليه الخطأ، وأنه يجب أن يكون أعلم الأمة بالأحكام. وجعفر لم يكن معصوما بلا خلاف، وما ظهر من أفعاله التي تنافي العصمة أكثر من أن يحصى، لا نطول بذكرها الكتاب، وإن عرض فيما بعد ما يقتضي ذكر بعضها ذكرناه. وأما كونه عالما فإنه كان خاليا منه، فكيف تثبت إمامته على أن القائلين بهذه المقالة قد انقرضوا أيضا ولله الحمد والمنة.","27/1/33/28",""],[29,32,"وأما من قال لا ولد لأبي محمد عليه السلام فقوله يبطل بما دللنا عليه من إمامة الاثني عشر وسياقة الأمر فيهم. ويزيده بيانا:","27/1/33/29",""],[30,32,"ما رواه محمد بن عبد الله بن جعفر الحميري عن أبيه عن أحمد بن محمد بن عيسى الأشعري عن أحمد بن محمد بن أبي نصر عن عقبة بن جعفر قال: قلت لأبي الحسن عليه السلام: قد بلغت ما بلغت وليس لك ولد. فقال: يا عقبة بن جعفر،إن صاحب هذا الأمر لا يموت حتى يرى ولده من بعده.","27/1/33/30",""],[31,32,"عنه عن أبيه عن محمد بن عيسى عن الحسن بن علي الخزاز عن عمر بن أبان عن الحسن بن أبي حمزة عن أبيه عن أبي جعفر عليه السلام قال: يا با حمزة،إن الأرض لن تخلو إلا وفيها عالم منا. فإن زاد الناس قال قد زادوا،وإن نقصوا قال قد نقصوا. ولن يخرج الله ذلك العالم حتى يرى في ولده من يعلم مثل علمه أو ما شاء الله.","27/1/33/31",""],[32,32,"وروى محمد بن يعقوب الكليني رفعه قال:قال أبو محمد عليه السلام حين ولد الحجة عليه السلام: زعم الظلمة أنهم يقتلونني ليقطعوا هذا النسل. فكيف رأوا قدرة الله. وسماه المؤمل.","27/1/33/32",""],[33,32,"وروى سعد بن عبد الله عن أبي هاشم داود بن القاسم الجعفري قال: كنت محبوسا مع أبي محمد عليه السلام في حبس المهتدي بن الواثق،فقال لي: يا أبا هاشم،إن هذا الطاغي أراد أن يعبث بالله في هذه الليلة. وقد بتر الله تعالى عمره، وقد جعله الله للقائم من بعده. ولم يكن لي ولد وسأرزق ولدا. قال أبو هاشم: فلما أصبحنا وطلعت الشمس شغب الأتراك المهتدي فقتلوه، وولي المعتمد مكانه وسلمنا الله.","27/1/33/33",""],[34,32,"فأما من زعم أن الأمر قد اشتبه عليه فلا يدري هل لأبي محمد عليه السلام ولد أم لا، إلا أنهم متمسكون بالأول حتى يصح لهم الآخر،فقوله باطل بما دللنا عليه من صحة إمامة ابن الحسن وبما بينا من أن الأئمة اثنا عشر. ومع ذلك لا ينبغي التوقف بل يجب القطع على إمامة ولده،وبما قدمناه أيضا من أنه لا يمضي إمام حتى يولد له ويرى عقبه. ويؤكد ذلك ما رواه:","27/1/33/34",""],[35,32,"محمد بن عبد الله بن جعفر الحميري عن أبيه عن علي بن سليمان بن رشيد عن الحسن بن علي الخزاز قال: دخل علي بن أبي حمزة على أبي الحسن الرضا عليه السلام فقال له: أنت إمام؟قال: نعم. فقال له: إني سمعت جدك جعفر بن محمد عليه السلام يقول: لا يكون الإمام إلا وله عقب. فقال: أنسيت يا شيخ أو تناسيت؟ ليس هكذا قال جعفر عليه السلام. إنما قال جعفر عليه السلام: لا يكون الإمام إلا وله عقب، إلا الإمام الذي يخرج عليه الحسين بن علي عليه السلام فإنه لا عقب له. فقال له: صدقت،جعلت فداك. هكذا سمعت جدك يقول.","27/1/33/35",""],[36,32,"وما دللنا عليه من أن الزمان لا يخلو من إمام عقلا وشرعا يفسد هذا القول أيضا.","27/1/33/36",""],[37,32,"فأما تمسكهم بما روي تمسكوا بالأول حتى يصح لكم الآخر، فهو خبر واحد. ومع هذا فقد تأوله سعد بن عبد الله بتأويل قريب.","27/1/33/37",""],[38,32,"قال: قوله تمسكوا بالأول حتى يظهر لكم الآخر هو دليل على إيجاب الخلف، لأنه يقتضي وجوب التمسك بالأول ولا يبحث عن أحوال الآخر إذا كان مستورا غائبا في تقية حتى يأذن الله في ظهوره ويكون الذي يظهر أمره ويشهر نفسه على أن القائلين بذلك قد انقرضوا، والحمد لله.","27/1/33/38",""],[39,32,"وأما من قال بإمامة الحسن عليه السلام وقالوا: انقطعت الإمامة كما انقطعت النبوة، فقولهم باطل بما دللنا عليه من أن الزمان لا يخلو عن إمام عقلا وشرعا، وبما بيناه من أن الأئمة اثنا عشر. وسنبين صحة ولادة القائم عليه السلام بعده، فسقط قولهم من كل وجه، على أن هؤلاء قد انقرضوا بحمد الله.","27/1/33/39",""],[40,32,"وقد بينا فساد قول الذاهبين إلى إمامة جعفر بن علي من الفطحية الذين قالوا بإمامة عبد الله بن جعفر لما مات الصادق عليه السلام، فلما مات عبد الله ولم يخلف ولدا رجعوا إلى القول بإمامة موسى بن جعفر ومن بعده إلى الحسن بن علي عليه السلام، فلما مات الحسن عليه السلام قالوا بإمامة جعفر. وقول هؤلاء يبطل من وجوه أفسدناها، ولأنه لا خلاف بين الإمامية أن الإمامة لا تجتمع في أخوين بعد الحسن والحسين وقد رووا في ذلك أخبارا كثيرة.","27/1/33/40",""],[41,32,"منها ما رواه سعد بن عبد الله عن محمد بن الوليد الخزاز عن يونس بن يعقوب قال:سمعت أبا عبد الله عليه السلام يقول: أبى الله أن يجعل الإمامة لأخوين بعد الحسن والحسين عليهما السلام.","27/1/33/41",""],[42,32,"عنه عن محمد بن الحسين بن أبي الخطاب عن سليمان بن جعفر عن حماد بن عيسى الجهني قال: قال أبوعبدالله عليه السلام: لا تجتمع الإمامة في أخوين بعد الحسن والحسين عليهما السلام. إنما هي في الأعقاب وأعقاب الأعقاب.","27/1/33/42",""],[43,32,"وروى محمد بن عبد الله بن جعفر الحميري عن أبيه عن محمد بن عيسى بن عبيد عن يونس بن عبد الرحمن عن الحسين بن ثوير بن أبي فاختة عن أبي عبد الله عليه السلام قال: لا تعود الإمامة في أخوين بعد الحسن والحسين عليهماالسلام أبدا. إنها جرت من علي بن الحسين عليه السلام كما قال عز وجل: ﴿وَأُولُوا الْأَرْحامِ بَعْضُهُمْ أَوْلى بِبَعْضٍ فِي كِتابِ اللَّهِ مِنَ الْمُؤْمِنِينَ والْمُهاجِرِينَ.﴾","27/1/33/43",""],[44,32,"فلا تكون بعد علي بن الحسين عليه السلام إلا في الأعقاب وأعقاب الأعقاب.","27/1/33/44",""],[45,32,"ومنها أنه لا خلاف أنه لم يكن معصوما، وقد بينا أن من شرط الإمام أن يكون معصوما، وما ظهر من أفعاله ينافي العصمة.","27/1/33/45",""],[46,32,"وقد روي أنه لما ولد لأبي الحسن عليه السلام جعفر هنئوه به فلم يروا به سرورا، فقيل له في ذلك فقال: هون عليك أمره سيضل خلقا كثيرا.","27/1/33/46",""],[47,32,"وروى سعد بن عبد الله قال: حدثني جماعة منهم أبو هاشم داود بن القاسم الجعفري والقاسم بن محمد العباسي ومحمد بن عبيد الله ومحمد بن إبراهيم العمري وغيرهم ممن كان حبس بسبب قتل عبد الله بن محمد العباسي أن أبا محمد عليه السلام وأخاه جعفرا دخلا عليهم ليلا، قالوا: كنا ليلة من الليالي جلوسا نتحدث إذ سمعنا حركة باب السجن فراعنا ذلك، وكان أبو هاشم عليلا، فقال لبعضنا: اطلع وانظر ما ترى. فاطلع إلى موضع الباب فإذا الباب فتح وإذا هو برجلين قد أدخلا إلى السجن ورد الباب وأقفل. فدنا منهما فقال: من أنتما؟ فقال أحدهما: نحن قوم من الطالبية، حبسنا. فقال: من أنتما؟ فقال: أنا الحسن بن علي وهذا جعفر بن علي. فقال لهما: جعلني الله فداكما، إن رأيتما أن تدخلا البيت. وبادر إلينا وإلى أبي هاشم فأعلمنا ودخلا. فلما نظر إليهما أبو هاشم قام عن مضربة كانت تحته، فقبل وجه أبي محمد عليه السلام وأجلسه عليها، وجلس جعفر قريبا منه،فقال جعفر: واشطناه! بأعلى صوته،يعني جارية له. فزجره أبو محمد عليه السلام وقال له: اسكت. وأنهم رأوا فيه آثار السكر وأن النوم غلبه وهو جالس معهم فنام على تلك الحال. وما روي فيه وله من الأفعال والأقوال الشنيعة أكثر من أن تحصى، ننزه كتابنا عن ذلك.","27/1/33/47",""],[48,32,"فأما من قال إن للخلف ولدا وإن الأئمة ثلاثة عشر، فقولهم يفسد بما دللنا عليه من أن الأئمة عليهم السلام اثنا عشر. فهذا القول يجب إطراحه، على أن هذه الفرق كلها قد انقرضت بحمد الله ولم يبق قائل يقول بقولها، وذلك دليل على بطلان هذه الأقاويل.","27/1/33/48",""],[1,33,"فصل: فأما الكلام في ولادة صاحب الزمان وصحتها فأشياء إعتبارية وأشياء إخبارية: فأما الاعتبارية فهو أنه إذا ثبت إمامته بما دللنا عليه من الاقسام، وإفساد كل قسم منها إلا القول بإمامته ثبت إمامته وعلمنا بذلك صحة ولادته إن لم يرد فيه خبر أصلا. وأيضا ما دللنا عليه من أن الائمة اثنا عشر يدل على صحة ولادته، لان العدد لا يكون إلا لموجود. وما دللنا على أن صاحب الامر لابد له من غيبتين يؤكد ذلك، لان كل ذلك مبني على صحة ولادته. وأما تصحيح ولادته من جهة الاخبار فسنذكر في هذا الكتاب طرفا مما روي فيه جملة وتفصيلا، ونذكر بعد ذلك جملة من أخبار من شاهده ورآه، لأن استيفاء ما روي في هذا المعنى يطول به الكتاب.","27/1/34/1",""],[2,33,"أخبرنا جماعة، عن أبي محمد هارون بن موسى التلعكبري، عن أحمد بن علي الرازي، قال: حدثني محمد بن علي، عن حنظلة بن زكريا، عن الثقة قال: حدثني عبد الله بن العباس العلوي-وما رأيت أصدق لهجة منه وكان خالفنا في أشياء كثيرة- قال: حدثني أبوالفضل الحسين بن الحسن العلوي، قال: دخلت على أبي محمد عليه السلام بسر من رأى فهنأته بسيدنا صاحب الزمان عليه السلام لما ولد.","27/1/34/2",""],[3,33,"محمد بن يعقوب الكليني، عن محمد بن جعفر الأسدي، قال: أحمد بن إبراهيم قال: دخلت على حكيمة بنت محمد بن علي الرضا عليهما السلام سنة اثنتين وستين ومائتين فكلمتها من وراء حجاب وسألتها عن دينها، فسمت لي من تأتم بهم، قالت فلان ابن الحسن، فسمته. فقلت لها: جعلني الله فداك معاينة أو خبرا؟ فقالت: خبرا عن أبي محمد عليه السلام كتب به إلى أمه. قلت لها: فأين الولد؟ قالت: مستور. فقلت: إلى من تفزع الشيعة؟ قالت: إلى الجدة أم أي محمد عليه السلام. فقلت: أقتدي بمن وصيته إلى امرأة. فقالت: إقتد بالحسين بن علي عليهما السلام؛ أوصى إلى أخته زينب بنت علي عليهما السلام في الظاهر، وكان ما يخرج من علي بن الحسين عليهما السلام من علم ينسب إلى زينب سترا على علي بن الحسين عليهما السلام. ثم قالت: إنكم قوم أصحاب أخبار. أما رويتم أن التاسع من ولد الحسين عليه السلام يقسم ميراثه وهو في الحياة؟","27/1/34/3",""],[4,33,"وروى هذا الخبر التلعكبري، عن الحسن بن محمد النهاوندي، عن الحسن بن جعفر بن مسلم الحنفي، عن أبي حامد المراغي قال:سألت حكيمة بنت محمد أخت أبي الحسن العسكري…وذكر مثله.","27/1/34/4",""],[5,33,"وقد تقدمت الرواية من قول أبي محمد عليه السلام حين ولد له: وزعمت الظلمة أنهم يقتلونني ليقطعوا هذا النسل. فكيف رأوا قدرة الله؟ وسماه المؤمل.","27/1/34/5",""],[6,33,"وروى محمد بن يعقوب، عن الحسين بن محمد الاشعري، عن المعلى بن محمد، عن أحمد بن محمد قال: خرج عن أبي محمد عليه السلام حين قتل الزبيري: هذا جزاء من افترى على الله وعلى أوليائه. زعم أنه يقتلني وليس لي عقب. فكيف رأى قدرة الله؟ وولد له ولد وسماه محمدا سنة ست وخمسين ومائتين.","27/1/34/6",""],[7,33,"أبوهاشم الجعفري قال: قلت لابي محمد عليه السلام:جلالتك تمنعني عن مسألتك فتأذن لي في أن أسألك؟ قال: سل، قلت: يا سيدي هل لك ولد؟ قال: نعم، قلت: فإن حدث حدث فأين أسأل عنه؟ فقال: بالمدينة.","27/1/34/7",""],[8,33,"وروى محمد بن يعقوب رفعه عن نسيم الخادم، وخادم أبي محمد عليه السلام قال:دخلت على صاحب الزمان عليه السلام بعد مولده بعشر ليال فعطست عنده. فقال: يرحمك الله. ففرحت بذلك، فقال: ألا أبشرك في العطاس؟ هو أمان من الموت ثلاث أيام.","27/1/34/8",""],[9,33,"وروى محمد بن عبد الله بن جعفر الحميري، عن أبيه، عن أحمد بن هلال، عن أمية بن علي القيسي، عن سالم بن أبي حية، عن أبي عبد الله عليه السلام قال: إذا اجتمع ثلاثة أسماء؛ محمد وعلي والحسن، فالرابع القائم.","27/1/34/9",""],[10,33,"وروى محمد بن يعقوب بإسناده، عن ضوء بن علي العجلي، عن رجل من أهل فارس- سماه- قال:أتيت سر من رأى ولزمت باب أبي محمد عليه السلام، فدعاني من غير أن أستأذنت، فلما دخلت فسلمت قال لي: يا فلان كيف حالك؟ ثم قال: اقعد يا فلان. ثم سألني عن جماعة من رجال ونساء من أهلي. ثم قال لي: ما الذي أقدمك؟ قلت:رغبة في خدمتك، قال: فالزم الدار. قال:فكنت في الدار مع الخدم ثم صرت أشتري لهم الحوائج من السوق، وكنت أدخل عليه بغير إذن إذا كان في دار الرجال. فدخلت عليه يوما وهو في دار الرجال، فسمعت حركة في البيت وناداني: مكانك لا تبرح! فلم أجسر أخرج ولا أدخل. فخرجت علي جارية معها شيء مغطى، ثم ناداني: أدخل فدخلت، ثم نادى الجارية فرجعت، فقال لها: اكشفي عما معك، فكشفت عن غلام أبيض حسن الوجه، فكشف عن بطنه، فإذا شعر نابت من لبته إلى سرته أخضر ليس بأسود، فقال: هذا صاحبكم. ثم أمرها فحملته، فما رأيته بعد ذلك حتى مضى أبو محمد عليه السلام. فقال ضوء بن علي: قلت للفارسي: كم كنت تقدر له من السنين؟ قال: سنتين. قال العبدي: فقلت لضوء:كم تقدر أنت؟ فقال: أربع عشرة سنة. قال أبوعلي وأبو عبد الله: ونحن نقدر إحدى وعشرين سنة.","27/1/34/10",""],[11,33,"وبهذا الاسناد، عن عمرو الاهوازي قال:أراني أبو محمد عليه السلام إبنه وقال:هذا صاحبكم من بعدي.","27/1/34/11",""],[12,33,"وأخبرني ابن أبي جيد، عن محمد بن الحسن بن الوليد، عن الصفار محمد بن الحسن القمي، عن أبي عبد الله المطهري، عن حكيمة بنت محمد بن علي الرضا قالت:بعث إلي أبو محمد عليه السلام سنة خمس وخمسين ومائتين في النصف من شعبان وقال: يا عمة،اجعلي الليلة إفطارك عندي. فإن الله عز وجل سيسرك بوليه وحجته على خلقه خليفتي من بعدي. قالت حكيمة: فتداخلني لذلك سرور شديد وأخذت ثيابي علي وخرجت من ساعتي حتى انتهيت إلى أبي محمد عليه السلام، وهو جالس في صحن داره، وجواريه حوله فقلت: جعلت فداك يا سيدي! الخلف ممن هو؟ قال: من سوسن. فأدرت طرفي فيهن فلم أر جارية عليها أثر غير سوسن. قالت حكيمة: فلما أن صليت المغرب والعشاء الآخرة أتيت بالمائدة، فأفطرت أنا وسوسن وبايتها في بيت واحد، فغفوت غفوة ثم استيقظت، فلم أزل مفكرة فيما وعدني أبومحمد عليه السلام من أمر ولي الله عليه السلام فقمت قبل الوقت الذي كنت أقوم في كل ليلة للصلاة، فصليت صلاة الليل حتى بلغت إلى الوتر، فوثبت سوسن فزعة وخرجت (فزعة) (وخرجت) وأسبغت الوضوء، ثم عادت فصلت صلاة الليل وبلغت إلى الوتر، فوقع في قلبي أن الفجر (قد) قرب فقمت لأنظر فإذا بالفجر الأول قد طلع، فتداخل قلبي الشك من وعد أبي محمد عليه السلام، فناداني من حجرته: لا تشكي، وكأنك بالأمر الساعة قد رأيته إن شاء الله تعالى. قالت حكيمة: فاستحييت من أبي محمد عليه السلام ومما وقع في قلبي، ورجعت إلى البيت وأنا خجلة فإذا هي قد قطعت الصلاة وخرجت فزعة فلقيتها على باب البيت فقلت:بأبي أنت (وأمي) هل تحسين شيئا؟ قالت: نعم يا عمة! إني لأجد أمرا شديدا. قلت:لا خوف عليك إن شاء الله تعالى، وأخذت وسادة فألقيتها في وسط البيت، وأجلستها عليها وجلست منها حيث تقعد المرأة من المرأة للولادة، فقبضت على كفي وغمزت غمزة شديدة ثم أنَّت أنَّة وتشهدت ونظرت تحتها، فإذا أنا بولي الله صلوات الله عليه متلقيا الارض بمساجده. فأخذت بكتفيه فأجلسته في حجري، فإذا هو نظيف مفروغ منه، فناداني أبو محمد عليه السلام: يا عمة، هلمي فأتيني بابني. فأتيته به، فتناوله وأخرج لسانه فمسحه على عينيه ففتحه، ثم أدخله في فيه فحنكه ثم (أدخله) في أذنيه وأجلسه في راحته اليسرى، فاستوى ولي الله جالسا، فمسح يده على رأسه وقال له: يا بني، انطق بقدرة الله. فاستعاذ ولي الله عليه السلام من الشيطان الرجيم واستفتح: ﴿بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. وَنُرِيدُ أَنْ نَمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ. وَنُمَكِّنَ لَهُمْ فِي الأَرْضِ وَنُرِيَ فِرْعَوْنَ وَهَامَانَ وَجُنُودَهُمَا مِنْهُمْ مَا كَانُوا يَحْذَرُونَ﴾. وصلى على رسول الله (صلى الله عليه وآله وسلم) وعلى أمير المؤمنين والأئمة (عليهم السلام)… واحدا واحدا حتى انتهى إلى أبيه. فناولنيه أبومحمد عليه السلام وقال: يا عمة، رديه إلى أمه حتى ﴿تَقَرَّ عَيْنُهَا وَلاَ تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ اللهِ حَقٌّ وَلَكِنَّ أَكْثَرَ النَّاسِ لاَ يَعْلَمُونَ﴾. فرددته إلى أمه وقد انفجر الفجر الثاني، فصليت الفريضة وعقبت إلى أن طلعت الشمس، ثم ودعت أبا محمد عليه السلام وانصرفت إلى منزلي. فلما كان بعد ثلاث اشتقت إلى ولي الله، فصرت إليهم فبدأت بالحجرة التي كانت سوسن فيها، فلم أر أثرا ولا سمعت ذكرا، فكرهت أن أسأل، فدخلت على أبي محمد عليه السلام فاستحييت أن أبدأه بالسؤال، فبدأني فقال: (هو) يا عمة،في كنف الله وحرزه وستره وغيبه حتى يأذن الله له. فإذا غيب الله شخصي وتوفاني ورأيت شيعتي قد اختلفوا،فأخبري الثقات منهم، وليكن عندك وعندهم مكتوما، فإن ولي الله يغيبه الله عن خلقه ويحجبه عن عباده فلا يراه أحد حتى يقدم له جبرئيل عليه السلام فرسه: ﴿لِيَقْضِيَ اللهُ أَمْراً كَانَ مَفْعُولاً﴾.","27/1/34/12",""],[13,33,"وبهذا الاسناد، عن محمد بن الحسن بن الوليد، عن محمد بن يحيى العطار، عن محمد بن حمويه الرازي، عن الحسين بن رزق الله، عن موسى بن محمد بن جعفر قال: حدثتني حكيمة بنت محمد عليه السلام بمثل معنى الحديث الاول، إلا أنها قالت: فقال لي أبومحمد عليه السلام: يا عمة، إذا كان اليوم السابع فأتِنا. فلما أصبحت جئت لأسلم على أبي محمد عليه السلام وكشفت عن الستر لأتفقد سيدي فلم أره، فقلت له: جعلت فداك ما فعل سيدي؟ فقال: يا عمة،استودعناه الذي استودعت أم موسى. فلما كان اليوم السابع جئت فسلمت وجلست فقال:هلموا إبني. فجئ بسيدي وهو في خرق صفر ففعل به كفعله الاول، ثم أدلى لسانه في فيه كأنما يغذيه لبنا وعسلا، ثم قال: تكلم يا بني. فقال عليه السلام: أشهد أن لا إله إلا الله… وثنى بالصلاة على محمد وعلى الائمة عليهم السلام حتى وقف على أبيه، ثم قرأ: ﴿بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. وَنُرِيدُ أَنْ نَمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ. وَنُمَكِّنَ لَهُمْ فِي الأَرْضِ وَنُرِيَ فِرْعَوْنَ وَهَامَانَ وَجُنُودَهُمَا مِنْهُمْ مَا كَانُوا يَحْذَرُونَ﴾.","27/1/34/13",""],[14,33,"أحمد بن علي الرازي، عن محمد بن علي، عن علي بن سميع بن بنان، عن محمد بن علي بـن أبـي الداري، عـن أحمـد بـن محمـد، عن أحمـد بن عبـد الله، عـن أحـمد بـن روح الاهوازي، عن محمد بن إبراهيم، عن حكيمة بمثل معنى الحديث الاول إلا أنه قال:قالت: بعث إلي أبومحمد عليه السلام ليلة النصف من شهر رمضان سنه خمس وخمسين ومائتين… (قالت) وقلت له:يا بن رسول الله من أمه؟ قال: نرجس. (قالت) فلما كان في اليوم الثالث اشتد شوقي إلى ولي الله، فأتيتهم عائدة فبدأت بالحجرة التي فيها الجارية، فإذا أنا بها جالسة في مجلس المرأة النفساء وعليها أثواب صفر، وهي معصبة الرأس،فسلمت عليها والتفت إلى جانب البيت وإذا بمهد عليه أثواب خضر، فعدلت إلى المهد ورفعت عنه الاثواب فإذا أنا بولي الله نائم على قفاه غير محزوم ولا مقموط. ففتح عينيه وجعل يضحك ويناجيني باصبعه، فتناولته وأدنيته إلى فمي لأقبله، فشممت منه رائحة ما شممت قط أطيب منها، وناداني أبومحمد عليه السلام: يا عمتي!هلمي فتاي إلي. فتناوله وقال: يا بني، انطق… وذكر الحديث.","27/1/34/14",""],[15,33,"أحمد بن علي الرازي، عن محمد بن علي، عن حنظلة بن زكريا قال: حدثني الثقة، عن محمد بن علي بن بلال، عن حكيمة بمثل ذلك.","27/1/34/15",""],[16,33,"وفي رواية أخرى عن جماعة من الشيوخ أن حكيمة حدثت بهذا الحديث وذكرت أنه كان ليلة النصف من شعبان وأن أمه نرجس،وساقت الحديث إلى قولها: فإذا أنا بحس سيدي وبصوت أبي محمد عليه السلام وهو يقول: يا عمتي، هاتي إبني. فكشفت عن سيدي فإذا هو ساجد متلقيا الارض بمساجده، وعلى ذراعه الايمن مكتوب ﴿جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقاً﴾. فضممته إلي فوجدته مفروغا منه فلففته في ثوب وحملته إلى أبي محمد عليه السلام…وذكروا الحديث إلى قوله: أشهد أن لا إله إلا الله وأن محمدا رسول الله وأن عليا أمير المؤمنين حقا، ثم لم يزل يعد السادة الاوصياء إلى أن بلغ إلى نفسه، ودعا لاوليائه بالفرج على يديه ثم أحجم. وقالت: ثم رفع بيني وبين أبي محمد عليه السلام كالحجاب فلم أر سيدي، فقلت لابي محمد: يا سيدي، أين مولاي؟ فقال: أخذه من هو أحق منك ومنا… ثم ذكروا الحديث بتمامه وزادوا فيه: فلما كان بعد أربعين يوما دخلت على أبي محمد عليه السلام فإذا مولانا الصاحب يمشي في الدار، فلم أر وجها أحسن من وجهه ولا لغة أفصح من لغته. فقال أبومحمد عليه السلام: هذا المولود الكريم على الله عز وجل. فقلت: سيدي، أرى من أمره ما أرى وله أربعون يوما! فتبسم وقال: يا عمتي، أما علمت أنا معاشر الائمة ننشؤ في اليوم ما ينشؤ غيرنا في السنة؟ فقمت فقبلت رأسه وانصرفت. ثم عدت وتفقدته فلم أره، فقلت لابي محمد عليه السلام: ما فعل مولانا؟ فقال: يا عمة،استودعناه الذي استودعت أم موسى.","27/1/34/16",""],[17,33,"أحمد بن علي الرازي، عن محمد بن علي، عن حنظلة بن زكريا قال: حدثني أحمد بن بلال بن داود الكاتب، وكان عاميا بمحل من النصب لأهل البيت عليهم السلام يظهر ذلك ولا يكتمه، وكان صديقا لي يظهر مودة بما فيه من طبع أهل العراق، فيقول- كلما لقيني- لك عندي خبر تفرح به ولا أخبرك به، فأتغافل عنه إلى أن جمعني وإياه موضع خلوة، فاستقصيت عنه وسألته أن يخبرني به، فقال: كانت دورنا بسر من رأى مقابل دار ابن الرضا-يعني أبا محمد الحسن بن علي عليهما السلام- فغبت عنها دهرا طويلا إلى قزوين وغيرها، ثم قضي لي الرجوع إليها، فلما وافيتها وقد كنت فقدت جميع من خلفته من أهلي وقراباتي إلا عجوزا كانت ربتني ولها بنت معها، وكانت من طبع الاول مستورة صائنة لا تحسن الكذب وكذلك مواليات لنا بقين في الدار. فأقمت عندهن أياما ثم عزمت الخروج، فقالت العجوزة: كيف تستعجل الانصراف وقد غبت زمانا؟ فأقم عندنا لنفرح بمكانك. فقلت لها على جهة الهزء: أريد أن أصير إلى كربلاء. وكان الناس للخروج في النصف من شعبان أو ليوم عرفة، فقالت: يا بني، أعيذك بالله أن تستهين ما ذكرت أو تقوله على وجه الهزء، فإني أحدثك بما رأيته- يعني بعد خروجك من عندنا– بسنتين: كنت في هـذا البيت نائـمة بالقرب من الدهليـز ومعي ابنتي وأنـا بين النائمة واليقظانة، إذ دخل رجل حسن الوجه نظيف الثياب طيب الرائحة، فقال:يا فلانة،يجيئك الساعة من يدعوك في الجيران، فلا تمتنعي من الذهاب معه ولا تخافي. ففزعت فناديت ابنتي وقلت لها:هل شعرت بأحد دخل البيت؟ فقالت: لا. فذكرت الله وقرأت ونمت. فجاء الرجل بعينه وقال لي مثل قوله، ففزعت وصحت بابنتي فقالت:لم يدخل البيت (أحد) فاذكري الله ولا تفزعي. فقرأت ونمت. فلما كان في (الليلة) الثالثة جاء الرجل وقال: يا فلانة، قد جاء‌ك من يدعوك ويقرع الباب فاذهبي معه. وسمعت دق الباب فقمت وراء الباب وقلت:من هذا؟ فقال: افتحي ولا تخافي. فعرفت كلامه وفتحت الباب فإذا خادم معه إزار فقال: يحتاج إليك بعض الجيران لحاجة مهمة، فادخلي. ولف رأسي بالملاء‌ة وأدخلني الدار وأنا أعرفها، فإذا بشقاق مشدودة وسط الدار ورجل قاعد بجنب الشقاق، فرفع الخادم طرفه فدخلت وإذا امرأة قد أخذها الطلق وامرأة قاعدة خلفها كأنها تقبلها. فقالت المرأة:تعينيني فيما نحن فيه؟ فعالجتها بما يعالج به مثلها فما كان إلا قليلا حتى سقط غلام فأخذته على كفي وصحت: غلام غلام! وأخرجت رأسي من طرف الشقاق أبشر الرجل القاعد، فقيل لي: لا تصيحي. فلما رددت وجهي إلى الغلام قد كنت فقدته من كفي فقالت لي المرأة القاعدة: لا تصيحي. وأخذ الخادم بيدي ولف رأسي بالملاء‌ة وأخرجني من الدار وردني إلى داري وناولني صرة وقال (لي): لا تخبري بما رأيت أحدا. فدخلت الدار ورجعت إلى فراشي في هذا البيت وابنتي نائمة (بعد) فأنبهتها وسألتها: هل علمت بخروجي ورجوعي؟ فقالت: لا، وفتحت الصرة في ذلك الوقت وإذا فيها عشرة دنانيرعددا، وما أخبرت بهذا أحدا إلا في هذا الوقت لما تكلمت بهذا الكلام على حد الهزء فحدثتك إشفاقا عليك، فإن لهؤلاء القوم عند الله عز وجل شأنا ومنزلة، وكل ما يدعونه حق. قال: فعجبت من قولها وصرفته إلى السخرية والهزء ولم أسألها عن الوقت غير أني أعلم يقينا أني غبت عنهم في سنة نيف وخمسين ومائتين ورجعت إلى سر من رأى في وقت أخبرتني العجوزة بهذا الخبر في سنة إحدى وثمانين ومائتين في وزارة عبيدالله بن سليمان لما قصدته.","27/1/34/17",""],[18,33,"قال حنظلة: فدعوت بأبي الفرج المظفر بن أحمد حتى سمع معي (منه) هذا الخبر.","27/1/34/18",""],[19,33,"محمد بن يعقوب، عن بعض أصحابنا، عن عبد الله بن جعفر الحميري، قال: اجتمعت والشيخ أبو عمرو عند أحمد بن إسحاق بن سعد الأشعري فغمزني أحمد بن إسحاق أن أسأله عن الخلف. فقلت له: يا أبا عمرو، إني لأريد أن أسألك عن شيء وما أنا بشاكٍّ فيما أريد أن أسألك عنه، فإن اعتقادي وديني أن الارض لا تخلو من حجة إلا إذا كان قبل القيامة بأربعين يوما رفع الحجة وغلق باب التوبة: فلم يكن ﴿يَنْفَعُ نَفْساً إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْراً.﴾ فأولئك شرار (من) خلق الله عز وجل وهم الذين تقوم عليهم القيامة. ولكن أحببت أن أزداد يقينا، فإن إبراهيم عليه السلام سأل ربه أن يريه كيف يحيى الموتى ﴿قَالَ: أَوَلَمْ تُؤْمِنْ؟ قَالَ: بَلَى، وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي﴾. وقد أخبرني أبوعلي أحمد بن إسحاق أنه سأل أبا الحسن صاحب العسكر عليه السلام وقال: من أعامل وعمن آخذ وقول من أقبل؟ فقال (له): العمري ثقتي، فما أدى إليك عني فعني يؤدي، وما قال لك فعني يقول، فاسمع له وأطع، فإنه الثقة المأمون. وأخبرني أبوعلي: سأل أبا محمد عليه السلام عن مثل ذلك، فقال له:العمري وإبنه ثقتان، فما أدَّيا إليك فعني يؤديان، وما قالا فعني يقولان، فاسمع لهما وأطعهما فإنهما الثقتان المأمونان. فهذا قول إمامين قد مضيا فيك. (قال) فخر أبوعمرو ساجدا وبكى ثم قال: سل(حاجتك). فقلت له:أنت رأيت الخلف من أبي محمد عليه السلام؟ فقال: إي والله ،ورقبته مثل هذا- وأومأ بيده-. فقلت: بقيت واحدة. فقال: هات! قلت: الاسم. قال: محرم عليكم أن تسألوا عن ذلك، ولا أقول هذا من عندي فليس لي أن أحلل ولا أحرم، ولكن عنه صلوات الله عليه، فإن الامر عند السلطان أن أبا محمد عليه السلام مضى ولم يخلف ولدا، وقسم ميراثه وأخذ من لا حق له، فصبر على ذلك وهو ذا عماله يجولون، فليس أحد يجسر أن يتقرب إليهم ويسألهم شيئا، وإذا وقع الاسم وقع الطلب. فالله الله! اتقوا الله وأمسكوا عن ذلك.","27/1/34/19",""],[20,33,"وروي أن بعض أخوات أبي الحسن عليه السلام كانت لها جارية ربتها تسمى نرجس،فلما كبرت دخل أبومحمد عليه السلام فنظر إليها فقالت له:أراك يا سيدي تنظر إليها؟ فقال: إني ما نظرت إليها إلا متعجبا. أما إن المولود الكريم على الله تعالى يكون منها. ثم أمرها أن تستأذن أبا الحسن عليه السلام في دفعها إليه ففعلت فأمرها بذلك.","27/1/34/20",""],[21,33,"وروى علان الكليني، عن محمد بن يحيى، عن الحسين بن علي النيشابوري الدقاق، عن إبراهيم بن محمد بن عبد الله بن موسى بن جعفر عليهما السلام، عن السياري قال:حدثني نسيم ومارية قالت: لما خرج صاحب الزمان عليه السلام من بطن أمه سقط جاثيا على ركبتيه، رافعا سبابته نحو السماء، ثم عطس فقال: الحمد لله رب العالمين وصلى الله على محمد وآله عبدا داخرا لله غير مستنكف ولا مستكبر. ثم قال: زعمت الظلمة أن حجة الله داحضة، ولو أذن لنا في الكلام لزال الشك.","27/1/34/21",""],[22,33,"وروى علان بإسناده أن السيد عليه السلام ولد في سنة ست وخمسين ومائتين من الهجرة بعد مضي أبي الحسن بسنتين.","27/1/34/22",""],[23,33,"وروى محمد بن علي الشلمغاني في كتاب الاوصياء قال:حدثني حمزة ابن نصر غلام أبي الحسن عليه السلام عن أبيه قال:لما ولد السيد عليه السلام تباشر أهل الدار بذلك، فلما نشأ خرج إلي الامر أن أبتاع في كل يوم مع اللحم قصب مخ،وقيل: إن هذا لمولانا الصغير عليه السلام.","27/1/34/23",""],[24,33,"وعنه قال: حدثني الثقة، عن إبراهيم بن إدريس قال: وجه إلي مولاي أبومحمد عليه السلام بكبش وقال: عقه عن ابني فلان، وكل وأطعم أهلك. ففعلت، ثم لقيته بعد ذلك فقال لي: المولود الذي ولد لي مات. ثم وجه إلي بكبشين وكتب: بسم الله الرحمن الرحيم. عق هذين الكبشين عن مولاك وكل، هنأك الله، وأطعم إخوانك. ففعلت، ولقيته بعد ذلك فما ذكر لي شيئاً.","27/1/34/24",""],[25,33,"وروى علان قال:حدثني ظريف أبو نصر الخادم قال:دخلت عليه-يعني صاحب الزمان عليه السلام- فقال لي: علي بالصندل الاحمر. (قال) فأتيته به، فقال عليه السلام: أتعرفني؟ قلت:نعم. قال: من أنا؟ فقلت:أنت سيدي وابن سيدي. فقال: ليس عن هذا سألتك. قال ظريف: فقلت: جعلني الله فداك، فسر لي. فقال: أنا خاتم الاوصياء، وبي يدفع الله البلاء عن أهلي وشيعتي.","27/1/34/25",""],[26,33,"جعفر بن محمد بن مالك قال: حدثني محمد بن جعفر بن عبد الله عن أبي نعيم محمد بن أحمد الانصاري قال: وجه قوم من المفوضة والمقصرة كامل بن إبراهيم المدني إلى أبي محمد عليه السلام. قال كامل:فقلت في نفسي: أسأله لا يدخل الجنة إلا من عرف معرفتي وقال بمقالتي. (قال) فلما دخلت على سيدي أبي محمد عليه السلام نظرت إلى ثياب بياض ناعمة عليه، فقلت في نفسي:ولي الله وحجته يلبس الناعم من الثياب ويأمرنا نحن بمواساة الاخوان وينهانا عن لبس مثله!فقال متبسما: يا كامل، وحسر عن ذراعيه، فإذا مسح أسود خشن على جلده، فقال: هذا لله وهذا لكم. فسلمت وجلست إلى باب عليه ستر مرخى، فجاء‌ت الريح فكشفت طرفه فإذا أنا بفتى كأنه فلقة قمر من أبناء أربع سنين أو مثلها. فقال لي: يا كامل بن إبراهيم. فاقشعررت من ذلك وألهمت أن قلت:لبيك يا سيدي. فقال: جئت إلى ولي الله وحجته وبابه تسأله هل يدخل الجنة إلا من عرف معرفتك وقال بمقالتك؟ فقلت: إي والله. قال: إذن والله يقل داخلها. والله إنه ليدخلها قوم يقال لهم الحقية. قلت: يا سيدي ومن هم؟ قال: قوم من حبهم لعلي يحلفون بحقه ولا يدرون ما حقه وفضله. ثم سكت صلوات الله عليه عني ساعة ثم قال: وجئت تسأله عن مقالة المفوضة. كذبوا! بل قلوبنا أوعية لمشيئة الله، فإذا شاء شئنا، والله يقول:﴿وَمَا تَشَآؤُونَ إِلاَّ أَنْ يَشَآءَ اللهُ﴾. ثم رجع الستر إلى حالته فلم أستطع كشفه، فنظر إلي أبومحمد عليه السلام متبسما فقال: يا كامل، ما جلوسك وقد أنبأك بحاجتك الحجة من بعدي؟ فقمت وخرجت ولم أعاينه بعد ذلك.","27/1/34/26",""],[27,33,"قال أبونعيم: فلقيت كاملا فسألته عن هذا الحديث فحدثني به.","27/1/34/27",""],[28,33,"وروى هذا الخبر أحمد بن علي الرازي، عن محمد بن علي، عن علي بن عبد الله بن عائذ الرازي، عن الحسن بن وجناء النصيبي قال: سمعت أبا نعيم محمد بن أحمد الانصاري…وذكر مثله.","27/1/34/28",""],[29,33,"محمد بن يعقوب، عن أحمد بن النضر، عن القنبري- من ولد قنبر الكبير- مولى أبي الحسن الرضا عليه السلام قال: جرى حديث جعفر فشتمه، فقلت: فليس غيره فهل رأيته؟ قال: لم أره ولكن رآه غيري. قلت:ومن رآه؟ قال: رآه جعفر مرتين، وله حديث.","27/1/34/29",""],[30,33,"وحدث عن رشيق صاحب المادراي قال:بعث إلينا المعتضد ونحن ثلاثة نفر فأمرنا أن يركب كل واحد منا فرسا ونجنب آخر ونخرج مخفين لا يكون معنا قليل ولا كثير إلا على السرج مصلى، وقال (لنا): الحقوا بسامرة. ووصف لنا محلة ودارا وقال: إذا أتيتموها تجدون على الباب خادما أسود فاكبسوا الدار، ومن رأيتم فيها فأتوني برأسه. فوافينا سامرة فوجدنا الامر كما وصفه، وفي الدهليز خادم أسود وفي يده تكة ينسجها، فسألناه عن الدار ومن فيها، فقال: صاحبها. فوالله ما التفت إلينا وقل اكتراثه بنا، فكبسنا الدار كما أمرنا، فوجدنا دارا سرية ومقابل الدار ستر ما نظرت قط إلى أنبل منه، كأن الايدي رفعت عنه في ذلك الوقت، ولم يكن في الدار أحد. فرفعنا الستر فإذا بيت كبير كأن بحرا فيه (ماء)، وفي أقصى البيت حصير قد علمنا أنه على الماء، وفوقه رجل من أحسن الناس هيئة قائم يصلي،فلم يلتفت إلينا ولا إلى شيء من أسبابنا. فسبق أحمد بن عبد الله ليتخطى البيت فغرق في الماء، وما زال يضطرب حتى مددت يدي إليه فخلصته وأخرجته وغشي عليه وبقي ساعة، وعاد صاحبي الثاني إلى فعل ذلك الفعل فناله مثل ذلك، وبقيت مبهوتا. فقلت لصاحب البيت:المعذرة إلى الله وإليك، فو الله ما علمت كيف الخبر ولا إلى من أجئ وأنا تائب إلى الله. فمـا التفـت إلى شـيء ممـا قلنـا، ومـا انفتـل عمـا كـان فيه فهالنا ذلك، وانصرفنا عنه، وقد كان المعتضد ينتظرنا وقد تقدم إلى الحجاب إذا وافيناه أن ندخل عليه في أي وقت كان. فوافيناه في بعض الليل فأدخلنا عليه فسألنا عن الخبر، فحكينا له ما رأينا، فقال: ويحكم! لقيكم أحد قبلي وجرى منكم إلى أحد سبب أو قول؟ قلنا: لا. فقال: أنا نفي من جدي. وحلف بأشد أيمان له أنه رجل إن بلغه هذا الخبر ليضربن أعناقنا، فما جسرنا أن نحدث به إلا بعد موته.","27/1/34/30",""],[31,33,"وأخبرني جماعة، عن أبي جعفر محمد بن علي بن الحسين بن بابويه رحمه الله قال: حدثنا علي بن الحسن بن الفرج المؤذن قال: حدثني محمد بن حسن الكرخي قال: سمعت أبا هارون- رجلا من أصحابنا- يقول: رأيت صاحب الزمان عليه السلام ووجهه يضيء كأنه القمر ليلة البدر، ورأيت على سرته شعرا يجري كالخط، وكشف الثوب عنه فوجدته مختونا، فسألت أبا محمد عليه السلام عن ذلك، فقال: هكذا ولد وهكذا ولدنا، ولكنا سنمر الموسى عليه لاصابة السُّنّة.","27/1/34/31",""],[32,33,"أخبرنا جماعة، عن أبي المفضل الشيباني، عن أبي نعيم نصر بن عصام بن المغيرة الفهري المعروف بقرقارة قال: حدثني أبوسعيد المراغي، قال: حدثنا أحمد بن إسحاق أنه سأل أبا محمد عليه السلام عن صاحب هذا الأمر، فأشار بيده، أي إنه حي غليظ الرقبة.","27/1/34/32",""],[33,33,"أخبرني ابن أبي جيد القمي، عن محمد بن الحسن بن الوليد، عن عبد الله بن العباس بن عبد الله بن الحسن بن علي بن علي بن الحسين بن علي بن أبي طالب عليهم السلام، عن أبي الفضل الحسين بن الحسن بن الحسين بن الحسن بن علي بن أبي طالب عليه السلام، قال :وردت على أبي محمد الحسن بن علي عليهما السلام بسر من رأى فهنأته بولادة ابنه عليه السلام.","27/1/34/33",""],[34,33,"وأخبرني جماعة، عن محمد بن علي بن الحسين قال: أخبرنا أبي ومحمد بن الحسن ومحمد بن موسى بن المتوكل، عن عبد الله بن جعفر الحميري، أنه قال: سألت محمد بن عثمان رضي الله عنه فقلت له: رأيت صاحب هذا الامر؟ فقال: نعم، وآخرعهدي به عند بيت الله الحرام وهو يقول: اللهم، أنجز لي ما وعدتني. قال محمد بن عثمان رضي الله عنه: ورأيته صلوات الله عليه متعلقا بأستار الكعبة في المستجار وهو يقول: اللهم انتقم لي من أعدائك.","27/1/34/34",""],[1,34,"وأما ما روي من الاخبار المتضمنة لمن رآه عليه السلام وهو لا يعرفه أو عرفه فيما بعد،فأكثر من أن تحصى غير أنا نذكر طرفا منها:","27/1/35/1",""],[2,34,"أخبرنا جماعة، عن أبي محمد هارون بن موسى التلعكبري، عن أحمد بن علي الرازي قال: حدثني شيخ ورد الري على أبي الحسين محمد بن جعفر الاسدي، فروى له حديثين في صاحب الزمان عليه السلام وسمعتهما منه كما سمع، وأظن ذلك قبل سنة ثلاثمائة أو قريبا منها، قال: حدثني علي بن إبراهيم الفدكي قال: قال الاودي: بينا أنا في الطواف قد طفت ستة وأريد أن أطوف السابعة فإذا أنا بحلقة عن يمين الكعبة وشاب حسن الوجه، طيب الرائحة، هيوب، ومع هيبته متقرب إلى الناس، فتكلم فلم أر أحسن من كلامه، ولا أعذب من منطقه في حسن جلوسه فذهبت أكلمه فزبرني الناس، فسألت بعضهم: من هذا؟ فقال: ابن رسول الله صلى الله عليه وآله وسلم يظهر للناس في كل سنة يوما لخواصه، فيحدثهم ويحدثونه. فقلت: مسترشد أتاك فأرشدني هداك الله. قال: فناولني حصاة فحولت وجهي، فقال لي بعض جلسائه: ما الذي دفع إليك ابن رسول الله صلى الله عليه وآله وسلم؟ فقلت: حصاة. فكشفت عن يدي، فإذا أنا بسبيكة من ذهب، (فذهبت). وإذا أنا به قد لحقني فقال: ثبتت عليك الحجة، وظهر لك الحق، وذهب عنك العمى أتعرفني؟ فقلت:اللهم لا. فقال: (أنا) المهدي، أنا قائم الزمان، أنا الذي أملاها عدلا كما ملئت ظلماً وجوراً ، إن الأرض لا تخلو من حجة ولا يبقى الناس في فترة أكثر من تيه بني إسرائيل، وقد ظهر أيام خروجي، فهذه أمانة في رقبتك فحدث بها إخوانك من أهل الحق.","27/1/35/2",""],[3,34,"وبهذا الاسناد، عن أحمد بن علي الرازي، قال:حدثني محمد بن علي، عن محمد بن أحمد بن خلف، قال:نزلنا مسجدا في المنزل المعروف بالعباسية- على مرحلتين من فسطاط مصر- وتفرق غلماني في النزول وبقي معي في المسجد غلام أعجمي(فرأيت) في زاويته شيخا كثير التسبيح،فلما زالت الشمس ركعت (وسجدت) وصليت الظهر في أول وقتها، ودعوت بالطعام وسألت الشيخ أن يأكل معي (فأجابني). فلما طعمنا سألت عن اسمه واسم أبيه وعن بلده وحرفته(ومقصده)، فذكر أن اسمه محمد بن عبد الله، وأنه من أهل قم، وذكر أنه يسيح منذ ثلاثين سنة في طلب الحق ويتنقل في البلدان والسواحل، وأنه أوطن مكة والمدينة نحو عشرين سنة يبحث عن الاخبار ويتبع الآثار. فلمـا كان في سنـة ثلاث وتسعين ومـائتين طاف بالبيت ثم صار إلى مقام إبراهيم عليه السلام فركع فيه وغلبته عينه فأنبهه صوت دعاء لم يجر في سمعه مثله، قال: فتأملت الداعي فإذا هو شاب أسمر لم أر قط في حسن صورته واعتدال قامته، ثم صلى فخرج وسعى، فاتبعته وأوقع الله عز وجل في نفسي أنه صاحب الزمان عليه السلام. فلما فرغ من سعيه قصد بعض الشعاب فقصدت أثره،فلما قربت منه إذ أنا بأسود مثل الفنيق قد اعترضني فصاح بي بصوت لم أسمع أهول منه: ما تريد عافاك الله؟ فأرعدت ووقفت، وزال الشخص عن بصري وبقيت متحيرا. فلما طال بي الوقوف والحيرة انصرفت ألوم نفسي وأعذلها بانصرافي بزجرة الاسود، فخلوت بربي عز وجل أدعوه وأسأله بحق رسوله وآله عليهم السلام أن لا يخيب سعيي وأن يظهر لي ما يثبت بهقلبي ويزيد في بصري. فلما كان بعد سنين زرت قبر المصطفى صلى الله عليه وآله فبينا أنا (أصلي) في الروضة التي بين القبر والمنبر إذ غلبتني عيني، فإذا محرك يحركني، فاستيقظت فإذا أنا بالاسود فقال: ما خبرك؟ وكيف كنت؟ فقلت: الحمد لله وأذمك. فقال: لا تفعل، فإني أمرت بما خاطبتك به، وقد أدركت خيرا كثيرا، فطب نفسا وازدد من الشكر لله عز وجل ما أدركت وعاينت، ما فعل فلان؟ وسمى بعض إخواني المستبصرين، فقلت :ببرقة. فقال: صدقت، ففلان؟ وسمى رفيقا لي مجتهدا في العبادة، مستبصرا في الديانة. فقلت: بالاسكندرية، حتى سمى لي عدة من إخواني. ثم ذكر اسما غريبا فقال: ما فعل نقفور؟ قلت: لا أعرفه، فقال: كيف تعرفه وهو رومي؟ فيهديه الله فيخرج ناصرا من قسطنطينية. ثم سألني عن رجل آخر فقلت: لا أعرفه. فقال: هذا رجل من أهل هيت من أنصار مولاي عليه السلام. إمض إلى أصحابك فقل لهم: نرجو أن يكون قد أذن الله في الانتصار للمستضعفين وفي الانتقام من الظالمين. ولقد لقيت جماعة من أصحابي وأديت إليهم وأبلغتهم ما حملت وأنا منصرف وأشير عليك أن لا تتلبس بما يثقل به ظهرك، ويتعب به جسمك وأن تحبس نفسك على طاعة ربك، فإن الامر قريب إن شاء الله تعالى. فأمرت خازني فأحضر لي خمسين دينارا وسألته قبولها فقال:يا أخي،قد حرم الله علي أن آخذ منك ما أنا مستغن عنه كما أحل لي أن آخذ منك الشيء إذا إحتجت إليه. فقلت له:هل سمع هذا الكلام منك أحد غيري من أصحاب السلطان؟ قال: نعم، (أخوك) أحمد بن الحسين الهمداني المدفوع عن نعمته بآذربيجان، وقد استأذن للحج تأميلا أن يلقى من لقيت. فحج أحمد بن الحسين الهمداني رحمه الله في تلك السنة فقتله ذكرويه بن مهرويه، وافترقنا وانصرفت إلى الثغر. ثم حججت فلقيت بالمدينة رجلا اسمه طاهر من ولد الحسين الاصغر، يقال إنه يعلم من هذا الأمر شيئا فثابرت عليه حتى أنس بي، وسكن لي ووقف على صحة عقيدتي، فقلت له:يا بن رسول الله، بحق آبائك الطاهرين عليهم السلام لما جعلتني مثلك في العلم بهذا الأمر، فقد شهد عندي من توثقه بقصد القاسم بن عبد الله بن سليمان بن وهب إياي لمذهبي واعتقادي أنه أغرى بدمي مرارا فسلمني الله منه. فقال: يا أخي اكتم ما تسمع مني الخبر في هذه الجبال، وإنما يرى العجائب الذين يحملون الزاد في الليل ويقصدون به مواضع يعرفونها، وقد نهينا عن الفحص والتفتيش. فودعته وانصرفت عنه.","27/1/35/3",""],[4,34,"وأخبرني أحمد بن عبدون المعروف بابن الحاشر، عن أبي الحسن محمد بن علي الشجاعي الكاتب، عن أبي عبد الله محمد بن إبراهيم النعماني، عن يوسف بن أحمد (محمد) الجعفري قال: حججت سنة ست وثلاثمائة، وجاورت بمكة تلك السنة وما بعدها إلى سنة تسع وثلاثمائة، ثم خرجت عنها منصرفا إلى الشام، فبينا أنا في بعض الطريق، وقد فاتتني صلاة الفجر، فنزلت من المحمل وتهيأت للصلاة، فرأيت أربعة نفر في محمل، فوقفت أعجب منهم، فقال أحدهم:مم تعجب؟ تركت صلاتك وخالفت مذهبك. فقلت للذي يخاطبني: وما علمك بمذهبي؟ فقال: تحب أن ترى صاحب زمانك؟ قلت نعم، فأومأ إلى أحد الاربعة، فقلت (له): إن له دلائل وعلامات. فقال: أيما أحب إليك أن ترى الجمل وما عليه صاعدا إلى السماء، أو ترى المحمل صاعدا إلى السماء؟ فقلت: أيهما كان فهي دلالة. فرأيت الجمل وما عليه يرتفع إلى السماء، وكان الرجل أومأ إلى رجل به سمرة، وكان لونه الذهب، بين عينيه سجادة.","27/1/35/4",""],[5,34,"أحمد بن علي الرازي، عن محمد بن علي، عن محمد بن عبد ربه الانصاري الهمداني، عن أحمد بن عبد الله الهاشمي من ولد العباس قال: حضرت دار أبي محمد الحسن بن علي عليهما السلام بسر من رأى يوم توفي، وأخرجت جنازته ووضعت، ونحن تسعة وثلاثون رجلا قعود ننتظر، حتى خرج إلينا غلام عشاري حاف عليه رداء قد تقنع به. فلما أن خرج قمنا هيبة له من غير أن نعرفه، فتقدم وقام الناس فاصطفوا خلفه، فصلى عليه ومشى، فدخل بيتا غير الذي خرج منه. قال أبوعبد الله الهمداني فلقيت بالمراغة رجلا من أهل تبريز يعرف بإبراهيم بن محمد التبريزي، فحدثني بمثل حديث الهاشمي لم يخرم منه شيء، قال: فسألت الهمداني فقلت:غلام عشاري القد أو عشاري السن، لأنه روي أن الولادة كانت سنة ست وخمسين ومائتين،وكانت غيبة أبي محمد عليه السلام سنة ستة ومائتين بعد الولادة بأربع سنين. فقال: لا أدري. هكذا سمعت. فقال لي شيخ معه حسن الفهم من أهل بلده له رواية وعلم: عشاري القد.","27/1/35/5",""],[6,34,"عنه، عن علي بن عائذ الرازي، عن الحسن بن وجناء النصيبي، عن أبي نعيم محمد بن أحمد الانصاري قال:كنت حاضرا عند المستجار(بمكة) وجماعة زهاء ثلاثين رجلا لم يكن منهم مخلص غير محمد بن القاسم العلوي، فبينا نحن كذلك في اليوم السادس من ذي الحجة سنة ثلاث وتسعين ومائتين، إذ خرج علينا شاب من الطواف عليه إزاران (فاحتج) محرم بهما، وفي يده نعلان. فلما رأيناه قمنا جميعا هيبة له، ولم يبق منا أحد إلا قام، فسلم علينا وجلس متوسطا ونحن حوله، ثم التفت يمينا وشمالا ثم قال: أتدرون ما كان أبو عبد الله عليه السلام يقول في دعاء الالحاح؟ (قلنا:وما كان يقول؟) قال: كان يقول: اللهم إني أسألك باسمك الذي به تقوم السماء، وبه تقوم الارض وبه تفرق بين الحق والباطل، وبه تجمع بين المتفرق، وبه تفرق بين المجتمع، وبه أحصيت عدد الرمال، وزنة الجبال، وكيل البحار، أن تصلي على محمد وآل محمد، وأن تجعل لي من أمري فرجا. ثم نهض ودخل الطواف فقمنا لقيامه حتى انصرف وأنسينا أن نذكره أمره، وأن نقول من هو؟ وأي شيء هو؟ إلى الغد في ذلك الوقت فخرج علينا من الطواف، فقمنا له كقيامنا بالامس، وجلس في مجلسه متوسطا، فنظر يمينا وشمالا وقال: أتدرون ما كان يقول أمير المؤمنين عليه السلام بعد صلاة الفريضة؟ فقلنا وما كان يقول؟ قال: كان يقول: إليك رفعت الاصوات (ودعيت الدعوات ولك) عنت الوجوه، ولك وضعت الرقاب، وإليك التحاكم في الاعمال، يا خير من سئل، ويا خير من أعطي، يا صادق يا بارئ، يا من لا يخلف الميعاد، يا من أمر بالدعاء ووعد بالاجابة، يا من قال: ﴿اُدْعُونِي أَسْتَجِبْ لَكُمْ﴾ يا من قال: ﴿إِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِي فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ﴾ ويا من قال: ﴿يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لاَ تَقْنَطُوا مِنْ رَحْمَةِ اللهِ إِنَّ اللهَ يَغْفِرُ الذُّنُوبَ جَمِيعاً إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ﴾ لبيك وسعديك، ها أنا ذا بين يديك المسرف، وأنت القائل: ﴿لاَ تَقْنَطُوا مِنْ رَحْمَةِ اللهِ إِنَّ اللهَ يَغْفِرُ الذُّنُوبَ جَمِيعاً﴾. ثم نظر يمينا وشمالا بعد هذا الدعاء- فقال: أتدرون ما كان أمير المؤمنين عليه السلام يقول في سجدة الشكر؟ فقلنا:وما كان يقول؟ قال: كان يقول: يا من لا يزيده كثرة الدعاء إلا سعة وعطاء، يا من لا تنفد خزائنه، يا من له خزائن السماوات والأرض، يا من له خزائن ما دق وجل لا تمنعك إساء‌تي من إحسانك، أنت تفعل بي الذي أنت أهله، (فإنك) أنت أهل الكرم والجود، والعفو والتجاوز، يا رب يا الله لا تفعل بي الذي أنا أهله، فإني أهل العقوبة وقد استحققتها، لا حجة (لي) ولا عذر لي عندك، أبوء لك بذنوبي كلها وأعترف بها كي تعفو عني، وأنت أعلم بها مني، أبوء لك بكل ذنب أذنبته، وكل خطيئة احتملتها، وكل سيئة عملتها، رب اغفر وارحم، وتجاوز عما تعلم، إنك أنت الاعز الاكرم. وقام ودخل الطواف فقمنا لقيامه، وعاد من الغد في ذلك الوقت فقمنا لاقباله كفعلنا فيما مضى، فجلس متوسطا ونظر يمينا وشمالا فقال: كان علي بن الحسين سيد العابدين عليه السلام يقول في سجوده في هذا الموضع- وأشار بيده إلى الحجر تحت الميزاب-: عبيدك بفنائك مسكينك بفنائك، فقيرك بفنائك، سائلك بفنائك يسألك ما لا يقدر عليه غيرك. ثم نظر يمينا وشمالا ونظر إلى محمد بن القاسم من بيننا، فقال: يا محمد بن القاسم أنت على خير إن شاء الله تعالى- وكان محمد بن القاسم يقول بهذا الامر-ثم قام ودخل الطواف فما بقي منا أحد إلا وقد ألهم ما ذكره من الدعاء وأنسينا أن نتذاكر أمر إلا في آخر يوم. فقال لنا أبوعلي المحمودي: يا قوم أتعرفون هذا؟ هذا والله صاحب زمانكم، فقلنا:وكيف علمت يا أبا علي؟ فذكر أنه مكث سبع سنين يدعو ربه ويسأله معاينة صاحب الزمان عليه السلام. قال: فبينا نحن يوما عشية عرفة وإذا بالرجل بعينه يدعو بدعاء وعيته فسألته ممن هو؟ فقال: من الناس، قلت: من أي الناس؟ قال: من عربها، قلت: من أي عربها؟ قال:من أشرفها، قلت:ومن هم؟ قال:بنو هاشم، قلت: (و) من أي بنو هاشم؟ فقال: من أعلاها ذروة وأسناها، قلت: ممن قال: ممن فلق الهام وأطعم الطعام وصلى والناس نيام. قال: فعلمت أنه علوي فأحببته على العلوية، ثم افتقدته من بين يدي فلم أدر كيف مضى، فسألت القوم الذين كانوا حوله تعرفون هذا العلوي؟ قالوا: نعم يحج معنا في كل سنة ماشيا، فقلت:سبحان الله (والله) ما أرى به أثر مشي قال: فانصرفت إلى المزدلفة كئيبا حزينا على فراقه، ونمت من ليلتي تلك، فإذا أنا برسول الله صلى الله عليه وآله وسلم فقال: يا أحمد رأيت طلبتك؟ فقلت: ومن ذاك يا سيدي؟ فقال: الذي رأيته في عشيتك (و) هو صاحب زمانك. قال: فلما سمعنا ذلك منه عاتبناه أن لا يكون أعلمنا ذلك، فذكر أنه كان ينسى أمره إلى وقت ما حدثنا به.","27/1/35/6",""],[7,34,"وأخبرنا جماعة، عن أبي محمد هارون بن موسى التلعكبري، عن أبي علي محمد بن همام، عن جعفر بن مالك الكوفي، عن محمد بن جعفر بن عبد الله، عن أبي نعيم محمد بن أحمد الانصاري وساق الحديث بطوله.","27/1/35/7",""],[8,34,"وأخبرنا جماعة، عن التلعكبري، عن أحمد بن علي الرازي، عن علي بن الحسين، عن رجـل- ذكر أنه من أهل قزوين لم يذكر اسـمه- عن حبيب بن محمـد بن يونس بن شاذان الصنعاني قال: دخلت إلى علي بن إبراهيم بن مهزيار الاهوازي فسألته عن آل أبي محمد عليه السلام فقال:يا أخي لقد سألت عن أمر عظيم، حججت عشرين حجة كلا أطلب به عيان الامام فلم أجد إلى ذلك سبيلا، فبينا أنا ليلة نائم في مرقدي إذ رأيت قائلا يقول: يا علي بن إبراهيم! قد أذن الله لي في الحج، فلم أعقل ليلتي حتى أصبحت، فأنا مفكر في أمري أرقب الموسم ليلي ونهاري. فلما كان وقت الموسم أصلحت أمري، وخرجت متوجها نحو المدينة، فما زلت كذلك حتى دخلت يثرب فسألت عن آل أبي محمد عليه السلام، فلم أجد له أثرا ولا سمعت له خبرا، فأقمت مفكرا في أمري حتى خرجت من المدينة أريد مكة، فدخلت الجحفة وأقمت بها يوما وخرجت منها متوجها نحو الغدير، وهو على أربعة أميال من الجحفة، فلما أن دخلت المسجد صليت وعفرت واجتهدت في الدعاء وابتهلت إلى الله لهم، وخرجت أريد عسفان، فما زلت كذلك حتى دخلت مكة فأقمت بها أياما أطوف البيت وأعتكفت. فبينا أنا ليلة في الطواف، إذا أنا بفتى حسن الوجه، طيب الرائحة، يتبختر في مشيته طائف حول البيت، فحس قلبي به، فقمت نحوه فحككته، فقال لي من أين الرجل؟ فقلت:من أهل (العراق فقال:من أي) العراق؟ قلت:من الاهواز. فقال لي: تعرف بها الخصيب؟ فقلت: رحمه الله، دعي فأجاب، فقال: رحمه الله، فما كان أطول ليلته وأكثر تبتله وأغزر دمعته، أفتعرف علي بن إبراهيم بن المازيار؟ فقلت: أنا علي بن إبراهيم. فقال: حياك الله أبا الحسن ما فعلت بالعلامة التي بينك وبين أبي محمد الحسن بن علي عليهما السلام؟ فقلت:معي قال: أخرجها، فأدخلت يدي في جيبي فاستخرجتها، فلما أن رآها لم يتمالك أن تغرغرت عيناه (بالدموع) وبكى منتحبا حتى بل أطماره، ثم قال: أذن لك الآن يا بن مازيار، صر إلى رحلك وكن على أهبة من أمرك، حتى إذا لبس الليل جلبابه، وغمر الناس ظلامه، سر إلى شعب بني عامر! فإنك ستلقاني هناك فسرت إلى منزلي. فلما أن أحسست بالوقت أصلحت رحلي وقدمت راحلتي وعكمته شديدا، وحملت وصرت في متنه وأقبلت مجدا في السير حتى وردت الشعب، فإذا أنا بالفتى قائم ينادي يا أبا الحسن إلي، فما زلت نحوه، فلما قربت بدأني بالسلام وقال لي: سر بنا يا أخ فما زال يحدثني وأحدثه حتى تخرقنا جبال عرفات، وسرنا إلى جبال منى، وانفجر الفجر الاول ونحن قد توسطنا جبال الطائف. فلمـا أن كان هنـاك أمرني بالنزول وقـال لي:إنزل فصـل صلاة الليل، فصليت، وأمرني بالوتر فأوترت، وكانت فائدة منه، ثم أمرني بالسجود والتعقيب، ثم فرغ من صلاته وركب، وأمرني بالركوب وسار وسرت معه حتى علا ذروة الطائف، فقال: هل ترى شيئا؟ قلت: نعم أرى كثيب رمل عليه بيت شعر يتوقد البيت نورا. فلما أن رأيته طابت نفسي، فقال لي: هناك الامل والرجاء، ثم قال: سر بنا يا أخ فسار وسرت بمسيره إلى أن انحدر من الذروة وسار في أسفله، فقال: إنزل فها هنا يذل كل صعب، ويخضع كل جبار، ثم قال: خل عن زمام الناقة، قلت فعلى من أخلفها؟ فقال: حرم القائم عليه السلام، لا يدخله إلا مؤمن ولا يخرج منه إلا مؤمن، فخليت من زمام راحلتي، وسار وسرت معه إلى أن دنا من باب الخباء، فسبقني بالدخول وأمرني أن أقف حتى يخرج إلي. ثم قال لي: أدخل هنأك السلامة، فدخلت فإذا أنا به جالس قد اتشح ببردة واتزر بأخرى، وقد كسر بردته على عاتقه، وهو كأقحوانة أرجوان قد تكاثف عليها الندى، وأصابها ألم الهوى، وإذا هو كغصن بان أو قضيب ريحان، سمح سخي تقي نقي، ليس بالطويل الشامخ، ولا بالقصير اللازق، بل مربوع القامة، مدور الهامة، صلت الجبين، أزج الحاجبين، أقنى الانف، سهل الخدين، على خده الايمن خال كأنه فتات مسك على رضراضة عنبر. فلما أن رأيته بدرته بالسلام، فرد علي أحسن ما سلمت عليه، وشافهني وسألني عن أهل العراق، فقلت سيدي قد ألبسوا جلباب الذلة، وهم بين القوم أذلاء فقال لي:يا بن المازيار لتملكونهم كما ملكوكم، وهم يومئذ أذلاء، فقلت، سيدي لقد بعد الوطن وطال المطلب، فقال: يا بن المازيار(أبي) أبو محمد عهد إلي أن لا أجاور قوما غضب الله عليهم (ولعنهم) ولهم الخزي في الدنيا والآخرة ولهم عذاب أليم، وأمرني أن لا أسكن من الجبال إلا وعرها، ومن البلاد إلى عفرها، والله مولاكم أظهر التقية فوكلها بي فأنا في التقية إلى يوم يؤذن لي فأخرج، فقلت يا سيدي متى يكون هذا الأمر؟ فقال:إذا حيل بينكم وبين سبيل الكعبة، واجتمع الشمس والقمر واستدار بهما الكواكب والنجوم، فقلت: متى يـا بن رسول الله؟ فقـال لي: في سنة كذا وكذا تخرج دابة الارض (من) بين الصفا والمروة، ومعه عصا موسى وخاتم سليمان، يسوق الناس إلى المحشر. قال، فأقمت عنده أياما وأذن لي بالخروج بعد أن استقصيت لنفسي وخرجت نحو منزلي، والله لقد سرت من مكة إلى الكوفة ومعي غلام يخدمني فلم أر إلا خيرا وصلى الله على محمد وآله وسلم تسليما.","27/1/35/8",""],[9,34,"وأخبرني جماعة، عن جعفر بن محمد بن قولويه وغيره، عن محمد بن يعقوب الكليني، عن علي بن قيس، عن بعض جلاوزة السواد قال: شهدت نسيما آنفا بسر من رأى، وقد كسر باب الدار فخرج إليه وبيده طبرزين، فقال ما تصنع في داري؟ قال (نسيم): إن جعفرا زعم أن أباك مضى ولا ولد له، فإن كانت دارك فقد انصرفت عنك، فخرج عن الدار. قال علي بن قيس: فقدم علينا غلام من خدام الدار فسألته عن هذا الخبر، فقال: من حدثك بهذا؟ قلت:حدثني بعض جلاوزة السواد، فقال لي: لا يكاد يخفى على الناس شيء.","27/1/35/9",""],[10,34,"وبهذا الاسناد، عن علي بن محمد، عن محمد بن إسماعيل بن موسى بن جعفرعليه السلام- وكان أسن شيخ من ولد رسول الله صلى الله عليه وآله وسلم-قال:رأيته بين المسجدين وهو غلام.","27/1/35/10",""],[11,34,"وبهذا الاسناد، عن خادم لإبراهيم بن عبدة النيسابوري قال: كنت واقفا مع إبراهيم على الصفا فجاء غلام حتى وقف على إبراهيم وقبض على كتاب مناسكه وحدثه بأشياء.","27/1/35/11",""],[12,34,"وبهذا الاسناد، عن إبراهيم بن إدريس قال: رأيته بعد مضي أبي محمد عليه السلام حين أيفع وقبلت يديه ورأسه.","27/1/35/12",""],[13,34,"وبهذا الاسناد، عن أبي علي بن مطهر قال: رأيته ووصف قده.","27/1/35/13",""],[14,34,"أحمد بن علي الرازي، عن أبي ذر أحمد بن أبي سورة- وهو محمد بن الحسن بن عبدالله التميمي وكان زيديا- قال: سمعت هذه الحكاية عن جماعة يروونها عن أبي رحمه الله أنه خرج إلى الحير قال: فلما صرت إلى الحير إذا شاب حسن الوجه يصلي، ثم إنه ودع وودعت وخرجنا، فجئنا إلى المشرعة. فقال لي: يا با سورة أين تريد؟ فقلت: الكوفة، فقال لي: مع من؟ قلت مع الناس، قال لي: لا تريد نحن جميعا نمضي، قلت: ومن معنا؟ فقال: ليس نريد معنا أحدا، قال: فمشينا ليلتنا فإذا نحن على مقابر مسجد السهلة، فقال لي: هو ذا منزلك، فإن شئت فامض. ثم قال لي: تمر إلى ابن الزراري علي بن يحيى فتقول له: يعطيك المال الذي عنده، فقلت له لا يدفعه إلي، فقال لي: قل له: بعلامة أنه كذا وكذا دينارا وكذا وكذا درهما، وهو في موضع كذا وكذا، وعليه كذا وكذا مغطى، فقلت له: ومن أنت؟ قال: أنا محمد بن الحسن، قلت:فإن لم يقبل مني وطولبت بالدلالة؟ فقال: أنا وراك، قال: فجئت إلى ابن الزراري فقلت له: فدفعني، فقلت له: (العلامات التي قال لي وقلت له:) قد قال لي: أنا وراك، فقال: ليس بعد هذا شيء، وقال لم يعلم بهذا إلا الله تعالى ودفع إلي المال.","27/1/35/14",""],[15,34,"وفي حديث آخر عنه وزاد فيه: قال أبوسورة: فسألني الرجل عن حالي فأخبرته بضيقي وبعيلتي، فلم يزل يماشيني حتى انتهينا إلى النواويس في السحر فجلسنا، ثم حفر بيده فإذا الماء قد خرج فتوضأ ثم صلى ثلاث عشرة ركعة، ثم قال (لي): امض إلى أبي الحسن علي بن يحيى، فاقرأ عليه السلام وقل له: يقول لك الرجل إدفع إلى أبي سورة من السبع مائة دينار التي مدفونة في موضع كذا وكذا مائة دينار. وإني مضيت من ساعتي إلى منزله فدققت الباب فقال: من هذا؟ فقلت قولي لابي الحسن:هذا أبو سورة، فسمعته يقول: ما لي ولابي سورة، ثم خرج إلي فسلمت عليه وقصصت عليه الخبر، فدخل وأخرج إلي مائة دينار فقبضتها، فقال لي: صافحته؟ فقلت: نعم، فأخذ يدي فوضعها على عينيه ومسح بها وجهه.","27/1/35/15",""],[16,34,"قال أحمد بن علي: وقد روي هذا الخبر عن محمد بن علي الجعفري وعبدالله بن الحسن بن بشر الخزاز وغيرهما، وهو مشهور عندهم.","27/1/35/16",""],[17,34,"وروى محمد بن يعقوب رفعه، عن الزهري قال: طلبت هذا الامر طلبا شاقا حتى ذهب لي فيه مال صالح، فوقعت إلى العمري وخدمته ولزمته وسألته بعد ذلك عن صاحب الزمان عليه السلام، فقال لي: ليس إلى ذلك وصول، فخضعت فقال لي: بكر بالغداة، فوافيت فاستقبلني ومعه شاب من أحسن الناس وجها، وأطيبهم رائحة بهيئة التجار، وفي كمه شيء كهيئة التجار. فلما نظرت إليه دنوت من العمري فأومأ إلي، فعدلت إليه وسألته فأجابني عن كل ما أردت، ثم مر ليدخل الدار-وكانت من الدور التي لا يكترث لها- فقال العمري إن أردت أن تسأل سل فإنك لا تراه بعد ذا، فذهبت لأسأل فلم يسمع ودخل الدار، وما كلمني بأكثر من أن قال: ملعون ملعون من أخر العشاء إلى أن تشتبك النجوم، ملعون ملعون من أخر الغداة إلى أن تنقضي النجوم ودخل الدار.","27/1/35/17",""],[18,34,"أحمد بن علي الرازي، عن محمد بن علي، عن عبدالله بن محمد بن خاقان الدهقان، عن أبي سليمان داد بن غسان البحراني قال: قرأت على أبي سهل إسماعيل بن علي النوبختي (قال:) مولد محمد بن الحسن بن علي بن محمد بن علي الرضا بن موسى بن جعفر الصادق بن محمد الباقر بن علي بن الحسين بن علي بن أبي طالب صلوات الله عليهم أجمعين. ولد عليه السلام بسامراء سنة ست وخمسين ومائتين، أمه صقيل ويكنى أبا القاسم، بهذه الكنية أوصى النبي صلى الله عليه وآله أنه قال: اسمه كاسمي وكنيته كنيتي، لقبه المهدي، وهو الحجة، وهو المنتظر، وهو صاحب الزمان عليه السلام. قال إسماعيل بن علي: دخلت على أبي محمد الحسن بن علي عليهما السلام في المرضة التى مات فيها وأنا عنده، إذ قال لخادمه عقيد-وكان الخادم أسود نوبيا قد خدم من قبله علي بن محمد وهو ربيب الحسن عليه السلام- فقال (له) يا عقيد إغل لي ماء بمصطكي،فأغلى له ثم جاء‌ت به صقيل الجارية أم الخلف عليه السلام. فلما صار القدح في يديه وهم بشربه فجعلت يده ترتعد حتى ضرب القدح ثنايا الحسن عليه السلام، فتركه من يده، وقال لعقيد: أدخل البيت فإنك ترى صبيا ساجدا فأتني به. قال أبوسهل: قال عقيد:فدخلت أتحرى فإذا أنا بصبي ساجد رافع سبابته نحو السماء، فسلمت عليه فأوجز في صلاته فقلت: إن سيدي يأمرك بالخروج إليه، إذا جاء‌ت أمه صقيل فأخذت بيده وأخرجته إلى أبيه الحسن عليه السلام. قـال أبوسهل: فلمـا مثل الصبي بين يديه سلم وإذا هو دري اللون، وفي شعر رأسه قطط، مفلج الاسنان، فلما رآه الحسن عليه السلام بكى وقال: يا سيد أهل بيته إسقني الماء فإني ذاهب إلى ربي. وأخذ الصبي القدح المغلي بالمصطكي بيده ثم حرك شفتيه ثم سقاه فلما شربه قال: هيئوني للصلاة. فطرح في حجره منديل فوضأه الصبي واحدة واحدة ومسح على رأسه وقدميه. فقال له أبومحمد عليه السلام: إبشر يا بني فأنت صاحب الزمان، وأنت المهدي، وأنت حجة الله على أرضه، وأنت ولدي ووصيي وأنا ولدتك وأنت محمد بن الحسن بن علي بن محمد بن علي بن موسى بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب عليهم السلام. ولدك رسول الله صلى الله عليه وآله، وأنت خاتم (الاوصياء) الائمة الطاهرين، وبشر بك رسول الله صلى الله عليه وآله، وسماك وكناك، بذلك عهد إلي أبي عن آبائك الطاهرين صلى الله على أهل البيت، ربنا إنه حميد مجيد. ومات الحسن بن علي من وقته صلوات الله عليهم أجمعين.","27/1/35/18",""],[19,34,"عنه، عن أبي الحسين محمد بن جعفر الأسدي قال:حدثني الحسين بن محمد بن عامر الاشعري القمي، قال: حدثني يعقوب بن يوسف الضراب الغساني-في منصرفه من إصفهان- قال:حججت في سنة إحدى وثمانين ومائتين وكنت مع قوم مخالفين من أهل بلدنا. فلما قدمنا مكة تقدم بعضهم فاكترى لنا دارا في زقاق بين سوق الليل، وهي دار خديجة عليها السلام تسمى دار الرضا عليه السلام، وفيها عجوز سمراء فسألتها- لما وقفت على أنها دار الرضا عليه السلام- ما تكونين من أصحاب هذه الدار؟ ولم سميت دار الرضا؟ فقالت: أنا من مواليهم وهذه دار الرضا علي بن موسى عليهما السلام، أسكنيها الحسن بن علي عليهما السلام، فإني كنت من خدمه. فلما سمعت ذلك منها آنست بها وأسررت الأمر عن رفقائي المخالفين، فكنت إذا انصرفت من الطواف بالليل أنام معهم في رواق في الدار، ونغلق الباب ونلقي خلف الباب حجرا كبيرا كنا ندير خلف الباب. فرأيت غير ليلة ضوء السراج في الرواق الذي كنا فيه شبيها بضوء المشعل، ورأيت الباب قد انفتح ولا أرى أحدا فتحه من أهل الدار، ورأيت رجلا ربعة أسمر إلى الصفرة ما هو قليل اللحم، في وجهه سجادة عليه قميصان وإزار رقيق قد تقنع به وفي رجله نعل طاق فصعد إلى الغرفة في الدار حيث كانت العجوز تسكن، وكانت تقول لنا إن في الغرفة ابنـة لا تـدع أحدا يصعـد إليها، فكنت أرى الضوء الذي رأيته يضئ في الرواق على الدرجة عند صعود الرجل إلى الغرفة التي يصعدها، ثم أراه في الغرفة من غير أن أرى السراج بعينه، وكان الذين معي يرون مثل ما أرى فتوهموا أن يكون هذا الرجل يختلف إلى إبنة العجوز، وأن يكون قد تمتع بها فقالوا:هؤلاء العلوية يرون المتعة، وهذا حرام لا يحل فيما زعموا، وكنا نراه يدخل ويخرج ونجئ إلى الباب وإذا الحجر على حاله الذي تركناه، وكنا نغلق هذا الباب خوفا على متاعنا، وكنا لا نرى أحدا يفتحه ولا يغلقه، والرجل يدخل ويخرج والحجر خلف الباب إلى وقت ننحيه إذا خرجنا. فلما رأيت هذه الاسباب ضرب على قلبي ووقعت في قلبي فتنة فتلطفت العجوز وأحببت أن أقف على خبر الرجل، فقلت لها: يا فلانة إني أحب أن أسألك وأفاوضك من غير حضور من معي فلا أقدر عليه، فأنا أحب إذا رأيتني في الدار وحدي أن تنزلي إلي لاسألك عن أمر، فقالت لي مسرعة: وأنا أريد أن أسر إليك شيئا فلم يتهيأ لي ذلك من أجل من معك، فقلت ما أردت أن تقولي؟ فقالت: يقول لك-ولم تذكر أحدا-لا تخاشن أصحابك وشركاء‌ك ولا تلاحهم، فإنهم أعداؤك ودارهم، فقلت لها:من يقول؟ فقالت:أنا أقول، فلم أجسر لما دخل قلبي من الهيبة أن أراجعها، فقلت أي أصحابي تعنين؟ فظننت أنها تعني رفقائي الذين كانوا حجاجا معي قالت: شركاؤك الذين في بلدك وفي الدار معك، وكان جرى بيني وبين الذين معي في الدار عنت في الدين، فسعوا بي حتى هربت واستترت بذلك السبب فوقفت على أنها عنت أولئك، فقلت لها ما تكونين أنت من الرضا؟ فقالت كنت خادمة للحسن بن علي عليهما السلام، فلما استيقنت ذلك قلت: لاسألنها عن الغائب عليه السلام، فقلت: بالله عليك رأيته بعينك، فقالت:يا أخي لم أره بعيني فإني خرجت وأختي حبلى وبشرني الحسن بن علي عليهما السلام بأني سوف أراه في آخر عمري، وقال لي:تكونين له كما كنت لي. وأنا اليوم منذ كذا بمصر وإنما قدمت الآن بكتابة ونفقة وجه بها إلي على يدي رجل من أهل خراسان لا يفصح بالعربية، وهي ثلاثون دينارا وأمرني أن أحج سنتي هذه فخرجت رغبة مني في أن أراه فوقع في قلبي أن الرجل الذي كنت أراه يدخل ويخرج هو هو. فأخذت عشرة دراهم صحاحا، فيها ستة رضوية من ضرب الرضا عليه السلام قد كنت خبأتها لالقيها في مقام إبراهيم عليه السلام، وكنت نذرت ونويت ذلك، فدفعتها إليها وقلت في نفسي أدفعها إلى قوم من ولد فـاطمة عليهـا السـلام أفضـل ممـا ألقيها في المقام وأعظم ثوابا، فقلت لها: إدفعي هذه الدراهم إلى من يستحقها من ولد فاطمة عليها السلام، وكان في نيتي أن الذي رأيته هو الرجل، وإنما تدفعها إليه، فأخذت الدراهم وصعدت وبقيت ساعة ثم نزلت، فقالت: يقول لك:ليس لنا فيها حق إجعلها في الموضع الذي نويت، ولكن هذه الرضوية خذ منا بدلها وألقها في الموضع الذي نويت، ففعلت وقلت في نفسي:الذي أمرت به عن الرجل. ثم كان معي نسخة توقيع خرج إلى القاسم بن العلاء بآذربيجان فقلت لها:تعرضين هذه النسخة على إنسان قد رأى توقيعات الغائب، فقالت ناولني فإني أعرفها، فأريتها النسخة وظننت أن المرأة تحسن أن تقرأ فقالت:لا يمكنني أن أقرا في هذا المكان فصعدت الغرفة ثم أنزلته فقالت: صحيح وفي التوقيع أبشركم ببشرى ما بشرت به (إياه) وغيره. ثم قالت: يقول لك إذا صليت على نبيك صلى الله عليه وآله. كيف تصلي (عليه)؟ فقلت أقول:اللهم صل على محمد وآل محمد وبارك على محمد وآل محمد كأفضل ما صليت وباركت وترحمت على إبراهيم وآل إبراهيم إنك حميد مجيد. فقال: لا، إذا صليت عليهم فصل عليهم كلهم وسمهم. فقلت: نعم، فلما كانت من الغد نزلت ومعها دفتر صغير، فقالت: يقول لك: إذا صليت على النبي فصل عليه وعلى أوصيائه على هذه النسخة، فأخذتها وكنت أعمل بها، ورأيت عدة ليال قد نزل من الغرفة وضوء السراج قائم. وكنت أفتح الباب وأخرج على أثر الضوء وأنا أراه-أعني الضوء-ولا أرى أحد حتى يدخل المسجد، وأرى جماعة من الرجال من بلدان شتى يأتون باب هذه الدار، فبعضهم يدفعـون إلى العجـوز رقاعـا معهم، ورأيت العجوز قد دفعت إليهـم كذلك الرقـاع فيكلمونها وتكلمهم ولا أفهم عنهم، ورأيت منهم في منصرفنا جماعة في طريقي إلى أن قدمت بغداد. نسخة الدفتر الذي خرج: بسم الله الرحمن الرحيم، اللهم صل على محمد سيد المرسلين، وخاتم النبيين، وحجة رب العالمين، المنتجب في الميثاق، المصطفى في الظلال، المطهر من كل آفة، البرئ من كل عيب، المؤمل للنجاة، المرتجى للشفاعة، المفوض إليه دين الله. اللهم شرف بنيانه، وعظم برهانه، وأفلج حجته وارفع درجته، وأضئ نوره، وبيض وجهه، وأعطه الفضل والفضيلة، والدرجة والوسيلة الرفيعة، وابعثه مقاما محمودا، يغبطه به الاولون والآخرون. وصل على أمير المؤمنين ووارث المرسلين، وقائد الغر المحجلين، وسيد الوصيين وحجة رب العالمين. وصل على الحسن بن علي إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على الحسين بن علي إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على علي بن الحسين إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على محمد بن علي إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على جعفر بن محمد إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على موسى بن جعفر إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على علي بن موسى إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على محمد بن علي إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على علي بن محمد إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. وصل على الحسن بن علي إمام المؤمنين، ووارث المرسلين وحجة رب العالمين. وصل على الخلف الصالح الهادي المهدي إمام المؤمنين، ووارث المرسلين، وحجة رب العالمين. اللهم صل على محمد وأهل بيته الائمة الهادين المهديين العلماء الصادقين، الابرار المتقين، دعائم دينك، وأركان توحيدك، وتراجمة وحيك، وحججك على خلقك، وخلفاء‌ك في أرضك، الذين اخترتهم لنفسك واصطفيتهم على عبادك، وارتضيتهم لدينك، وخصصتهم بمعرفتك، وجللتهم بكرامتك وغشيتهم برحمتك، وربيتهم بنعمتك، وغذيتهم بحكمتك، وألبستهم نورك، ورفعتهم في ملكوتك، وحففتهم بملائكتك، وشرفتهم بنبيك. اللهم صل على محمد وعليهم صلاة كثيرة دائمة طيبة، لا يحيط بها إلا أنت، ولا يسعها إلا علمك، ولا يحصيها أحد غيرك. اللهم صل على وليك المحيي سنتك، القائم بأمرك، الداعي إليك الدليل عليك، وحجتك على خلقك، وخليفتك في أرضك، وشاهدك على عبادك. اللهم أعز نصره، ومد في عمره، وزين الارض بطول بقائه. اللهم اكفه بغي الحاسدين وأعذه من شر الكائدين، وادحر عنه إرادة الظالمين. وتخلصه من أيدي الجبارين. اللهم أعطه في نفسه وذريته وشيعته ورعيته وخاصته وعامته وعدوه وجميع أهل الدنيا ما تقر به عينه، وتسر به نفسه، وبلغه أفضل أمله في الدنيا والآخرة، إنك على كل شيء قدير. اللهم جدد به ما محي من دينك، وأحي به ما بدل من كتابك وأظهر به ما غير من حكمك، حتى يعود دينك به وعلى يديه غضا جديدا، خالصا مخلصا لا شك فيه ولا شبهة معه، ولا باطل عنده، ولا بدعة لديه. اللهم نور بنوره كل ظلمة، وهد بركنه كل بدعة، وأهدم بعزته كل ضلالة، واقصم به كل جبار، واخمد بسيفه كل نار، وأهلك بعدله كل جبار، وأجر حكمه على كل حكم وأذل لسلطانه كل سلطان. اللهم أذل كل من ناواه، وأهلك كل من عاداه وامكر بمن كاده، واستأصل من جحد حقه، واستهان بأمره، وسعى في إطفاء نوره وأراد إخماد ذكره. اللهم صل على محمد المصطفى، وعلي المرتضى، وفاطمة الزهراء،(و) الحسن الرضا، والحسين المصطفى، وجميع الاوصياء، مصابيح الدجى، وأعلام الهدى، ومنار التقى، والعروة الوثقى، والحبل المتين، والصراط المستقيم، وصل على وليك وولاة عهده، والائمة من ولده، ومد في أعمارهم، وأزد في آجالهم، وبلغهم أقصى آمالهم (دين)، دنيا وآخرة إنك على كل شيء قدير.","27/1/35/19",""],[1,35,"وأما ظهور المعجزات الدالة على صحة إمامته في زمان الغيبة فهي أكثر من أن تحصى غير أنا نذكر طرفا منها:","27/1/36/1",""],[2,35,"أخبرنا جماعة، عن أبي القاسم جعفر بن محمد بن قولويه، عن محمد بن يعقوب رفعه إلى محمد بن إبراهيم بن مهزيار قال: شككت عند مضي أبي محمد عليه السلام، وكان اجتمع عند أبي مال جليل فحمله وركب السفينة، وخرجت معه مشيعا له، فوعك وعكا شديدا. فقال: يا بني ردني (ردني) فهو الموت، واتق الله في هذا المال، وأوصى إلي ومات. فقلت في نفسي: لم يكن أبي ليوصي بشيء غير صحيح، أحمل هذا المال إلى العراق وأكتري دارا على الشط، ولا أخبر أحدا، فإن وضح لي شيء كوضوحه أيام أبي محمد عليه السلام أنفذته وإلا تصدقت به. فقدمت العراق واكتريت دارا على الشط وبقيت أياما، فإذا أنا برسول معه رقعة فيها: يا محمد معك كذا (وكذا) في جوف كذا وكذا حتى قص علي جميع ما معي مما لم أحط به علما، فسلمت المال إلى الرسول وبقيت أياما لا يرفع بي رأس، فاغتممت. فخرج إلي:قد أقمناك مقام أبيك فاحمد الله.","27/1/36/2",""],[3,35,"وبهذا الاسناد، عن الحسن بن الفضل بن يزيد اليماني قال:كتبت في معنيين وأردت أن أكتب في الثالث وامتنعت منه مخافة أن يكره ذلك، فورد جواب المعنيين والثالث الذي طويته مفسرا.","27/1/36/3",""],[4,35,"وبهذا الاسناد، عن بدر-غلام أحمد بن الحسن-قال:وردت الجبل وأنا لا أقول بالامامة، أحبهم جملة إلى أن مات يزيد بن عبدالملك، فأوصى إلي في علته أن يدفع الشهري السمند وسيفه ومنطقته إلى مولاه فخفت إن لم أدفع الشهري إلى إذ كوتكين نالني منه استخفاف، فقومت الدابة والسيف والمنطقة بسبعمـائة دينـار في نفسي، ولم أطلع عليه أحدا، فإذا الكتاب قد ورد علي من العراق أن وجه السبعمائة دينار التي لنا قبلك من ثمن الشهري السمند والسيف والمنطقة.","27/1/36/4",""],[5,35,"وبهذا الاسناد، عن علي، عمن حدثه قال:ولد لي مولود فكتبت أستأذن في تطهيره(في) اليوم السابع، فورد لا تفعل، فمات اليوم السابع أو الثامن، ثم كتبت بموته فورد سيخلف الله غيره وتسميه أحمد ومن بعد أحمد جعفر، فجاء كما قال.","27/1/36/5",""],[6,35,"وبهذا الاسناد، عن علي بن محمد، عن أبي عقيل عيسى بن نصر قال: كتب علي بن زياد الصيمري يلتمس كفنا، فكتب إليه: إنك تحتاج (إليه) في سنة ثمانين. فمات في سنة ثمانين، وبعث إليه بالكفن قبل موته.","27/1/36/6",""],[7,35,"محمد بن يعقوب، عن علي بن محمد قال: خرج نهي عن زيارة مقابر قريش والحير. فلما كان بعد أشهر، دعا الوزير الباقطاني فقال له: إلق بني الفرات والبرسيين وقل لهم لا تزوروا مقابر قريش، فقد أمر الخليفة أن يتفقد كل من زار فيقبض عليه. وأما ما ظهر من جهته عليه السلام من التوقيعات فكثيرة نذكر طرفا منها.","27/1/36/7",""],[1,36,"أخبرني جماعة، عن أبي محمد التلعكبري، عن أحمد بن علي الرازي، عن الحسين بن علي القمي، قال: حدثني محمد بن علي بن بنان الطلحي الآبي، عن علي بن محمد بن عبدة النيسابوري، قال: حدثني علي بن إبراهيم الرازي، قال: حدثني الشيخ الموثوق به بمدينة السلام قال: تشاجر ابن أبي غانم القزويني وجماعة من الشيعة في الخلف، فذكر ابن أبي غانم أن أبا محمد عليه السلام مضى ولا خلف له، ثم إنهم كتبوا في ذلك كتابا وأنفذوه إلى الناحية، وأعلموه بما تشاجروا فيه، فورد جواب كتابهم بخطه عليه وعلى آبائه السلام: بسم الله الرحمن الرحيم. عافانا الله وإياكم من الضلالة والفتن، ووهب لنا ولكم روح اليقين، وأجارنا وإياكم من سوء المنقلب أنه أنهي إلي ارتياب جماعة منكم في الدين، وما دخلهم من الشك والحيرة في ولاة أمورهم، فغمنا ذلك لكم لا لنا، وساء‌نا فيكم لا فينا، لان الله معنا ولا فاقة بنا إلى غيره، والحق معنا فلن يوحشنا من قعد عنا، ونحن صنائع ربنا، والخلق بعد صنائعنا. يا هؤلاء! ما لكم في الريب تترددون، وفي الحيرة تنعكسون؟ أو ما سمعتم الله عز وجل يقول: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الأَمْرِ مِنْكُمْ﴾؟ أوما علمتم ما جاء‌ت به الآثار مما يكون ويحدث في أئمتكم عن الماضين والباقين منهم عليهم السلام؟ أوما رأيتم كيف جعل الله لكم معاقل تأوون إليها، وأعلاما تهتدون بها من لدن آدم عليه السلام إلى أن ظهر الماضي عليه السلام، كلما غاب علم بدا علم، وإذا أفل نجم طلع نجم؟ فلما قبضه الله إليه ظننتم أن الله تعالى أبطل دينه، وقطع السبب بينه وبين خلقه، كلا ما كان ذلك ولا يكون حتى تقوم الساعة، ويظهر أمر الله سبحانه وهم كارهون. وإن الماضي عليه السلام مضى سعيدا فقيدا على منهاج آبائه عليهم السلام حذو النعل بالنعل، وفينا وصيته وعلمه، ومن هو خلفه ومن هو يسد مسده، لا ينازعنا موضعه إلا ظالم آثم، ولا يدعيه دوننا إلا جاحد كافر، ولولا أن أمر الله تعالى لا يغلب، وسره لا يظهر ولا يعلن، لظهر لكم من حقنا ما تبين منه عقولكم، ويزيل شكوككم، لكنه ما شاء الله كان، ولكل أجل كتاب. فاتقوا الله وسلموا لنا، وردوا الامر إلينا، فعلينا الاصدار كما كان منا الايراد، ولا تحاولوا كشف ما غطي عنكم ولا تميلوا عن اليمين، وتعدلوا إلى الشمال، واجعلوا قصدكم إلينا بالمودة على السنة الواضحة، فقد نصحت لكم، والله شاهد علي وعليكم، ولولا ما عندنا من محبة صلاحكم ورحمتكم، والاشفاق عليكم، لكنا عن مخاطبتكم في شغل فيما قد امتحنا به من منازعة الظالم العتل الضال المتتابع في غيه، المضاد لربه، الداعي ما ليس له، الجاحد حق من افترض الله طاعته، الظالم الغاصب. وفي ابنة رسول الله صلى الله عليه وآله لي أسوة حسنة وسيردي الجاهل رداء‌ة عمله، وسيعلم الكافر لمن عقبى الدار، عصمنا الله وإياكم من المهالك والاسواء، والآفات والعاهات كلها برحمته، فإنه ولي ذلك والقادر على ما يشاء، وكان لنا ولكم وليا وحافظا، والسلام على جميع الاوصياء والاولياء والمؤمنين ورحمة الله وبركاته، وصلى الله على محمد وآله وسلم تسليما.","27/1/37/1",""],[2,36,"وبهذا الاسناد، عن أبي الحسين محمد بن جعفر الاسدي رضي الله عنه، عن سعد بن عبدالله الأشعري قال: حدثنا الشيخ الصدوق أحمد بن إسحاق بن سعد الاشعري رحمه الله، أنه جاء‌ه بعض أصحابنا يعلمه أن جعفر بن علي كتب إليه كتابا يعرفه فيه نفسه، ويعلمه أنه القيم بعد أخيه، وأن عنده من علم الحلال والحرام ما يحتاج إليه وغير ذلك من العلوم كلها. قال أحمد بن إسحاق: فلما قرأت الكتاب كتبت إلى صاحب الزمان عليه السلام وصيرت كتاب جعفر في درجه، فخرج الجواب إلي في ذلك: بسم الله الرحمن الرحيم. أتاني كتابك أبقاك الله، والكتاب الذي أنفذته درجه وأحاطت معرفتي بجميع ما تضمنه على اختلاف ألفاظه، وتكرر الخطأ فيه، ولو تدبرته لوقفت على بعض ما وقفت عليه منه، والحمد لله رب العالمين حمدا لا شريك له على إحسانه إلينا، وفضله علينا، أبى الله عز وجل للحق إلا إتمام، وللباطل إلا زهوقا، وهو شاهد علي بما أذكره، ولي عليكم بما أقوله، إذا اجتمعنا ليوم لا ريب فيه ويسألنا عما نحن فيه مختلفون، إنه لم يجعل لصاحب الكتاب على المكتوب إليه ولا عليك ولا على أحد من الخلق جميعا إمامة مفترضة، ولا طاعة ولا ذمة، وسأبين لكم جملة تكتفون بها إن شاء الله تعالى. يا هذا يرحمك الله، إن الله تعالى لم يخلق الخلق عبثا، ولا أهملهم سدى، بل خلقهم بقدرته، وجعل لهم أسماعا وأبصارا وقلوبا وألبابا، ثم بعث إليهم النبيين عليهم السلام مبشرين ومنذرين، يأمرونهم بطاعته وينهونهم عن معصيته، ويعرفونهم ما جهلوه من أمر خالقهم ودينهم، وأنزل عليهم كتابا، وبعث إليهم ملائكة يأتين بينهم وبين من بعثهم إليهم بالفضل الذي جعله لهم عليهم، وما آتاهم من الدلائل الظاهرة والبراهين الباهرة، والآيات الغالبة. فمنهم من جعل النار عليه بردا وسلاما واتخذه خليلا، ومنهم من كلمه تكليما وجعل عصاه ثعبانا مبينا، ومنهم من أحيى الموتى بإذن الله، وأبرأ الاكمه والابرص بإذن الله، ومنهم من علمه منطق الطير وأوتي من كل شيء، ثم بعث محمدا صلى الله عليه وآله وسلم رحمة للعالمين، وتمم به نعمته، وختم به أنبياء‌ه، وأرسله إلى الناس كافة، وأظهر من صدقه ما أظهر، وبين من آياته وعلاماته ما بين. ثم قبـضه صـلى الله عـليه وآلـه حميـدا فقيـدا سعيـدا، وجعـل الامـر (مـن) بعـده إلى أخيـه وابن عمـه ووصيـه ووارثـه علـي بن أبـي طـالب عـليـه السلام ثم إلى الاوصياء من ولده واحدا واحدا، أحيى بهم دينه، وأتم بهم نوره، وجعل بينهم وبين إخوانهم وبني عمهم والادنين فالادنين من ذوي أرحامهم فرقان بينا يعرف به الحجة من المحجوج، والامام من المأموم بأن عصمهم من الذنوب، وبرأهم من العيوب، وطهرهم من الدنس، ونزههم من اللبس، وجعلهم خزان علمه، ومستودع حكمته، وموضع سره، وأيدهم بالدلائل، ولولا ذلك لكان الناس على سواء ولادعى أمر الله عز وجل كل أحد، ولما عرف الحق من الباطل، ولا العالم من الجاهل.وقد ادعى هذا المبطل المفتري على الله الكذب بما ادعاه، فلا أدري بأية حالة هي له رجاء أن يتم دعواه، أبفقه في دين الله؟ فو الله ما يعرف حلالا من حرام ولا يفرق بين خطأ وصواب، أم بعلم فما يعلم حقا من باطل، ولا محكما من متشابه ولا يعرف حد الصلاة ووقتها، أم بورع فالله شهيد على تركه الصلاة الفرض أربعين يوما، يزعم ذلك لطلب الشعوذة، ولعل خبره قد تأدى إليكم، وهاتيك ظروف مسكره منصوبة، وآثار عصيانه لله عز وجل مشهورة قائمة، أم بآية فليأت بها، أم بحجة فليقمها، أو بدلالة فليذكرها. قال الله عز وجل في كتابه:﴿بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. حۤم تَنْزِيلُ الْكِتَابِ مِنَ اللهِ الْعَزِيزِ الْحَكِيمِ. مَا خَلَقْنَا السَّمَاوَاتِ وَالأَرْضَ وَمَا بَيْنَهُمَا إِلاَّ بِالْحَقِّ وَأَجَلٍ مُسَمًّى وَالَّذِينَ كَفَرُوا عَمَّا أُنْذِرُوا مُعْرِضُونَ. قُلْ أَرَأَيْتُمْ مَا تَدْعُونَ مِنْ دُونِ اللَّهِ أَرُونِي مَاذَا خَلَقُوا مِنْ الْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِي السَّمَاوَاتِ اِئْتُونِي بِكِتَابٍ مِنْ قَبْلِ هَذَا أَوْ أَثَارَةٍ مِنْ عِلْمٍ إِنْ كُنْتُمْ صَادِقِينَ.وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لَا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ.وَإِذَا حُشِرَ النَّاسُ كَانُوا لَهُمْ أَعْدَاءً وَكَانُوا بِعِبَادَتِهِمْ كَافِرِينَ.﴾ فالتمس تولى الله توفيقك من هذا الظالم ما ذكرت لك، وامتحنه وسله عن آية من كتاب الله يفسرها أو صلاة فريضة يبين حدودها وما يجب فيها، لتعلم حاله ومقداره، ويظهر لك عواره ونقصانه، والله حسيبه. حفظ الله الحق على أهله، وأقره في مستقره، وقد أبى الله عز وجل أن تكون الامامة في أخوين بعد الحسن والحسين عليهما السلام، وإذا أذن الله لنا في القول ظهر الحق، واضمحل الباطل، وانحسر عنكم، وإلى الله أرغب في الكفاية، وجميل الصنع والولاية، وحسبنا الله ونعم الوكيل وصلى الله على محمد وآل محمد.","27/1/37/2",""],[3,36,"وأخبرني جماعة، عن جعفر بن محمد بن قولويه وأبي غالب الزراري (وغيرهما) عن محمد بن يعقوب الكليني، عن إسحاق بن يعقوب قال:سألت محمد بن عثمان العمري رحمه الله أن يوصل لي كتابا قد سئلت فيه عن مسائل أشكلت علي، فورد التوقيع بخط مولينا صاحب الدار عليه السلام: أما ما سألت عنه أرشد الله وثبتك من أمر المنكرين لي من أهل بيتنا وبني عمنا، فاعلم أنه ليس بين الله عز وجل وبين أحد قرابة، ومن أنكرني فليس مني، وسبيله سبيل ابن نوح عليه السلام. وأما سبيل عمي جعفر وولده، فسبيل إخوة يوسف على نبينا وآله وعليه السلام. وأما الفقاع فشربه حرام ولا بأس بالشلماب. وأما أموالكم فما نقبلها إلا لتطهروا فمن شاء فليصل، ومن شاء فليقطع، فما آتانا الله خير مما آتاكم. وأما ظهور الفرج فإنه إلى الله عز وجل، كذب الوقاتون. وأما قول من زعم أن الحسين عليه السلام لم يقتل، فكفر وتكذيب وضلال. وأما الحوادث الواقعة فارجعوا فيها إلى رواة حديثنا، فإنهم حجتي عليكم وأنا حجة الله (عليكم). وأما محمد بن عثمان العمري رضي الله عنه وعن أبيه من قبل، فإنه ثقتي وكتابه كتابي. وأما محمد بن علي بن مهزيار الاهوازي فسيصلح الله قلبه، ويزيل عنه شكه. وأما ما وصلتنا به فلا قبول عندنا إلا لما طاب وطهر، وثمن المغنية حرام. وأما محمد بن شاذان بن نعيم فإنه رجل من شعيتنا أهل البيت. وأما أبوالخطاب محمد بن(أبي) زينب الاجدع (فإنه) ملعون وأصحابه ملعونون، فلا تجالس أهل مقالتهم وإني منهم برئ وآبائي عليهم السلام منهم براء. وأما المتلبسون بأموالنا فمن استحل منها شيئا فأكله فإنما يأكل النيران. وأما الخمس فقد أبيح لشيعتنا وجعلوا منه في حل إلى وقت ظهور أمرنا لتطيب ولادتهم ولا تخبث. وأما ندامة قوم قد شكوا في دين الله على ما وصلونا به فقد أقلنا من استقال ولا حاجة لنا في صلة الشاكين. وأما علة ما وقع من الغيبة فإن الله عز وجل يقول:﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾. إنه لم يكن أحد من آبائي إلا وقد وقعت في عنقه بيعة لطاغية زمانه، وإني أخرج حين أخرج ولا بيعة لاحد من الطواغيت في عنقي. وأما وجه الانتفاع في غيبتي فكالانتفاع بالشمس إذا غيبتها عن الابصار السحاب، وإني لامان أهل الارض كما أن النجوم أمان لاهل السماء، فاغلقوا (أبواب) السؤال عما لا يعنيكم، ولا تتكلفوا على ما قد كفيتم، وأكثروا الدعاء بتعجيل الفرج فإن ذلك فرجكم. والسلام عليك يا إسحاق بن يعقوب وعلى من اتبع الهدى.","27/1/37/3",""],[4,36,"وأخبرنا الحسين بن إبراهيم، عن أبي العباس أحمد بن علي بن نوح، عن أبي نصر هبة الله بن محمد الكاتب قال: حدثني أبوالحسن أحمد بن محمد بن تربك الرهاوي، قال: حدثني أبوجعفر محمد بن علي بن الحسين بن موسى بن بابويه أو قال أبوالحسن (علي بن) أحمد الدلال القمي قال: إختلف جماعة من الشيعة في أن الله عز وجل فوض إلى الائمة صلوات الله عليهم أن يخلقوا أو يرزقوا؟ فقال قوم: هذا محال! لا يجوز على الله تعالى، لان الاجسام لا يقدر على خلقها غير الله عز وجل. وقال آخرون: بل الله تعالى أقدر الائمة على ذلك وفوضه إليهم، فخلقوا ورزقوا.وتنازعوا في ذلك تنازعا شديدا. فقال قائل: ما بالكم لا ترجعون إلى أبي جعفر محمد بن عثمان العمري فتسألونه عن ذلك فيوضح لكم الحق فيه، فإنه الطريق إلى صاحب الامر عجل الله فرجه؟ فرضيت الجماعة بأبي جعفر وسلمت وأجابت إلى قوله، فكتبوا المسألة وأنفذوها إليه، فخرج إليهم من جهته توقيع نسخته: إن الله تعالى هو الذي خلق الاجسام وقسم الارزاق، لانه ليس بجسم ولا حال في جسم: ليس كمثله شيء وهو السميع العليم. وأما الأئمة عليهم السلام فإنهم يسألون الله تعالى فيخلق ويسألونه فيرزق، إيجابا لمسألتهم وإعظاما لحقهم.","27/1/37/4",""],[5,36,"وبهذا الاسناد، عن أبي نصر هبة الله بن محمد بن ابن بنت أم كلثوم بنت أبي جعفر العمري قال: حدثني جماعة من بني نوبخت، منهم أبوالحسن بن كثير النوبختي رحمه الله، وحدثتني به أم كلثوم بنت أبي جعفر محمد بن عثمان العمري رضي الله عنه أنه حمل إلى أبي (جعفر) رضي الله عنه في وقت من الاوقات ما ينفذه إلى صاحب الامر عليه السلام من قم ونواحيها. فلما وصل الرسول إلى بغداد ودخل إلى أبي جعفر وأوصل إليه ما دفع إليه وودعه وجاء لينصرف، قال له أبوجعفر: قد بقي شيء مما استودعته فأين هو؟ فقال له الرجل: لم يبق شيء يا سيدي في يدي إلا وقد سلمته، فقال له أبو جعفر: بلى قد بقي شيء فارجع إلى ما معك وفتشه وتذكر ما دفع إليك. فمضى الرجل، فبقي أياما يتذكر ويبحث ويفكر فلم يذكر شيئا ولا أخبره من كان في جملته، فرجع إلى أبي جعفر فقال له: لم يبق شيء في يدي مما سلم إلي (وقد حملته) إلى حضرتك، فقال له أبوجعفر: فإنه يقال: لك الثوبان السردانيان اللذان دفعهما إليك فلان بن فلان ما فعلا؟ فقال له الرجل: إي والله يا سيدي لقد نسيتهما حتى ذهبا عن قلبي ولست أدري الآن أين وضعتهما، فمضى الرجل، فلم يبق شيء كان معه إلا فتشه وحله وسأل من حمل إليه شيئا من المتاع أن يفتش ذلك فلم يقف لهما على خبر، فرجع إلى أبي جعفر (فأخبره). فقال له أبوجعفر يقال لك: إمض إلى فلان بن فلان القطان الذي حملت إليه العدلين القطن في دار القطن، فافتق أحدهما وهو الذي عليه مكتوب كذا وكذا فإنهم في جانبه، فتحير الرجل مما أخبر به أبوجعفر، ومضى لوجهه إلى الموضع، ففتق العدل الذي قال له: افتقه، فإذا الثوبان في جانبه قد اندسا مع القطن فأخذهما وجاء (بهما) إلى أبي جعفر، فسلمهم إليه وقال له: لقد نسيتهم لاني لما شددت المتاع بقيا فجعلتهما في جانب العدل ليكون ذلك أحفظ لهما.","27/1/37/5",""],[6,36,"وأخبرني جماعة، عن أبي جعفر محمد بن علي بن الحسين قال:أخبرنا علي بن أحمد بن موسى الدقاق ومحمد بن أحمد السناني والحسين بن إبراهيم بن أحمد بن هشام المؤدب، عن أبي الحسين محمد بن جعفر الأسدي الكوفي رضي الله عنه أنه ورد عليه فيما ورد من جواب مسائله عن محمد بن عثمان العمري قدس سره: وأما ما سألت عنه من الصلاة عند طلوع الشمس وعند غروبها، فلئن كان كما يقول الناس: إن الشمس تطلع بين قرني شيطان، وتغرب بين قرني شيطان، فما أرغم أنف الشيطان بشيء أفضل من الصلاة فصلها وارغم (أنف) الشيطان.","27/1/37/6",""],[7,36,"(و) قال أبوجعفر بن بابويه في الخبر الذي روي فيمن أفطر يوما في شهر رمضان متعمدا أن عليه ثلاث كفارات: فإني أفتي به فيمن أفطر بجماع محرم عليه أو بطعام محرم عليه، لوجود ذلك في روايات أبي الحسين الاسدي فيما ورد عليه من الشيخ أبي جعفر بن عثمان العمري رضي الله عنه.","27/1/37/7",""],[8,36,"أخبرني جماعة، عن أبي محمد هارون، عن أبي علي محمد بن همام، قال أبوعلي: وعلى خاتم أبي جعفر السمان رضي الله عنه: لا إله إلا الله الملك الحق المبين، فسألته عنه فقال: حدثني أبو محمد-يعني صاحب العسكر عليه السلام-عن آبائه عليهم السلام (أنهم) قالوا: كان لفاطمة عليها السلام خاتم فصه عقيق، فلما حضرتها الوفاة دفعته إلى الحسن عليه السلام، فلما حضرته الوفاة دفعه إلى الحسين عليه السلام. قال الحسين عليه السلام: فاشتهيت أن أنقش عليه شيئا، فرأيت في النوم المسيح عيسى بن مريم على نبينا وآله وعليه السلام، فقلت له: يا روح الله،ما أنقش على خاتمي هذا؟ قال:انقش عليه: لاَ إِلَهَ إِلاَّ اللهُ الْمَلِكُ الْحَقُّ الْمُبِينُ. فإنه أول التوراة وآخر الإنجيل.","27/1/37/8",""],[9,36,"وأخبرنا جماعة، عن أبي محمد الحسن بن حمزة بن علي بن عبدالله بن محمد بن الحسن بن الحسين بن علي بن الحسين بن علي بن أبي طالب عليهم السلام قال:حدثنا، علي بن محمد الكليني، قال:كتب محمد بن زياد الصيمري يسأل صاحب الزمان عجل الله فرجه كفنا يتيمن بما يكون من عنده، فورد: إنك تحتاج إليه سنة إحدى وثمانين. فمات رحمه الله في (هذ) الوقت الذي حده وبعث إليه بالكفن قبل موته بشهر.","27/1/37/9",""],[10,36,"وأخبرني جماعة، عن أحمد بن محمد بن عياش، قال:حدثني ابن مروان الكوفي، قال: حدثني ابن أبي سورة قال:كنت بالحائر زائرا عشية عرفة فخرجت متوجها على طريق البر، فلما انتهيت (إلى) المسناة جلست إليها مستريحا، ثم قمت أمشي وإذا رجل على ظهر الطريق فقال لي: هل لك في الرفقة؟ فقلت: نعم فمشينا معا يحدثني وأحدثه وسألني عن حالي، فأعلمته أني مضيق لا شيء معي ولا في يدي، فالتفت إلي فقال لي: إذا دخلت الكوفة فائت (دار) أبا طاهر الزراري فاقرع عليه بابه، فإنه سيخرج إليك وفي يده دم الاضحية، فقل له: يقال لك إعط هذا الرجل الصرة الدنانير التي عند رجل السرير، فتعجبت من هذا، ثم فارقني ومضى لوجهه لا أدري أين سلك. ودخلت الكوفة فقصدت (دار) أبا طاهر محمد بن سليمان الزراري، فقرعت (عليه) بابه كما قال لي وخرج إلي وفي يده دم الاضحية فقلت له: يقال لك إعط هذا الرجل الصرة الدنانير التي عند رجل السرير، فقال: سمعا وطاعة ودخل فأخرج إلي الصرة فسلمها إلي فأخذتها وانصرفت.","27/1/37/10",""],[11,36,"وأخبرني جماعة، عن أبي غالب أحمد بن محمد الزراري قال: حدثني أبو عبد الله محمد بن زيد بن مروان، قال: حدثني أبوعيسى محمد بن علي الجعفري وأبو الحسين محمد بن علي بن الرقام قالا: حدثنا أبوسورة- قال أبو غالب: وقد رأيت ابنا لابي سورة، وكان أبوسورة أحد مشايخ الزيدية المذكورين. قال أبوسورة: خرجت إلى قبر أبي عبدالله عليه السلام أريد يوم عرفة فعرفت يوم عرفة، فلما كان وقت عشاء الآخرة صليت وقمت فابتدأت أقرأ من الحمد، وإذا شاب حسن الوجه عليه جبة سيفي، فابتدأ أيضا من الحمد وختم قبلي أو ختمت قبله، فلما كان الغداة خرجنا جميعا من باب الحائر، فلما صرنا إلى شاطئ الفرات قال لي الشاب: أنت تريد الكوفة فامض فمضيت طريق الفرات، وأخذ الشاب طريق البر. قـال أبـو سـورة:ث ـم أسـفت عـلى فـراقه فـاتبعته فقـال لي:تعال فجئنا جميعا إلى أصل حصن المسناة فنمنا جميعا وانتبهنا فإذا نحن على العوفي على جبل الخندق، فقال لي: أنت مضيق وعليك عيال، فامض إلى أبي طاهر الزراري فيخرج إليك من منزله وفي يده الدم من الاضحية فقل له: شاب من صفته كذا يقول:لك صرة فيها عشرون دينارا جاء‌ك بها بعض إخوانك فخذها منه. قال أبوسورة: فصرت إلى أبي طاهر (بن) الزراري كما قال الشاب ووصفته له فقال:الحمد لله ورأيته، فدخل وأخرج إلي الصرة الدنانير فدفعها إلي وانصرفت. قال أبوعبدالله محمد بن زيد بن مروان-وهو أيضا من أحد مشايخ الزيدية- حدثت بهذا الحديث أبا الحسن محمد بن عبيدالله العلوي ونحن نزول بأرض الهر، فقال: هذا حق جاء‌ني رجل شاب فتوسمت في وجهه سمة فانصرف الناس كلهم، وقلت له: من أنت؟ فقال: أنا رسول الخلف عليه السلام إلى بعض إخوانه ببغداد فقلت له:معك راحلة فقال: نعم في دار الطلحيين، فقلت له: قم فجئ بها، ووجهت معه غلاما فأحضر راحلته وأقام عندي يومه ذلك، وأكل من طعامي وحدثني بكثير من سري وضميري، قال: فقلت له على أي طريق تأخذ؟ قال: أنزل إلى هذه النجفة ثم آتي وادي الرملة، ثم آتي الفسطاط (واتبع الراحلة) فأركب إلى الخلف عليه السلام إلى المغرب. قال أبو الحسن محمد بن عبيد الله: فلما كان من الغد ركب راحلته وركبت معه حتى صرنا إلى قنطرة دار صالح فعبر الخندق وحده وأنا أراه حتى نزل النجف وغاب عن عيني. قال: أبوعبدالله محمد بن زيد: فحدثت أبا بكر محمد بن أبي دارم اليمامي-وهو(من) أحد مشايخ الحشوية- بهذين الحديثين فقال: هذا حق جاء‌ني منذ سنيات ابن أخت أبي بكر (بن) النخالي العطار-وهو صوفي يصحب الصوفية- فقلت من أنت وأين كنت؟ فقال لي: أنا مسافر(منذ) سبع عشرة سنة، فقلت له: فأيش أعجب ما رأيت؟ فقال: نزلت في الاسكندرية في خان ينزله الغرباء، وكان في وسط الخان مسجد يصلي فيه أهل الخان وله إمام وكان شاب يخرج من بيت له (أو) غرفة فيصلي خلف الإمام ويرجع من وقته إلى بيته ولا يلبث مع الجمـاعة. قـال: فقـلت: -لمـا طـال ذلك علي ورأيت منظره شاب نظيف عليه عباء -أنا والله أحب خدمتك والتشرف بين يديك، فقال: شأنك فلم أزل أخدمه حتى أنس بي الانس التام، فقلت له ذات يوم: من أنت أعزك الله؟ قال: أنا صاحب الحق، فقلت له: يا سيدي متى تظهر؟ فقال: ليس هذا أوان ظهوري، وقد بقي مدة من الزمان، فلم أزل على خدمته تلك وهو على حالته من صلاة الجماعة وترك الخوض فيما لا يعنيه إلى أن قال: أحتاج إلى السفر فقلت له: أنا معك.ثم قلت له: يا سيدي متى يظهر أمرك؟ قال: علامة ظهور أمري كثرة الهرج والمرج والفتن، وآتي مكة فأكون في المسجد الحرام فيقول الناس: إنصبوا لنا إماما ويكثر الكلام حتى يقوم رجل من الناس فينظر في وجهي ثم يقول: يا معشر الناس هذا المهدي انظروا إليه، فيأخذون بيدي وينصبوني بين الركن والمقام، فيبايع الناس عند إياسهم عني ، قال: وسرنا إلى ساحل البحر فعزم على ركوب البحر فقلت له: يا سيدي أنا والله أفرق من (ركوب) البحر، فقال:ويحك تخاف وأنا معك، فقلت: لا ولكن أجبن، قال:فركب البحر وانصرفت عنه.","27/1/37/11",""],[12,36,"أخبرني جماعة، عن أبي عبد الله أحمد بن محمد بن عياش، عن أبي غالب الزراري قال:قدمت من الكوفة وأنا شاب إحدى قدماتي ومعي رجل من إخواننا قد ذهب على أبي عبد الله اسمه، وذلك في أيام الشيخ أبي القاسم الحسين بن روح رحمه الله واستتاره ونصبه أبا جعفر محمد بن علي المعروف بالشلمغاني، وكان مستقيما لم يظهر منه ما ظهر (منه)من الكفر والإلحاد، وكان الناس يقصدونه ويلقونه لأنه كان صاحب الشيخ أبي القاسم الحسين بن روح سفيرا بينهم وبينه في حوائجهم ومهماتهم.فقال لي صاحبي: هل لك أن تلقى أبا جعفر وتحدث به عهدا، فإنه المنصوب اليوم لهذه الطائفة، فإني أريد أن أسأله شيئا من الدعاء يكتب به إلى الناحية، قال: فقلت: [له] نعم، فدخلنا إليه فرأينا عنده جماعة من أصحابنا فسلمنا عليه وجلسنـا، فأقبل على صـاحبي فقـال: من هذا الفتى معك؟ فقال له: رجل من آل زرارة بن أعين، فأقبل علي فقال: من أي زرارة أنت؟ فقلت: يا سيدي أنا من ولد بكير بن أعين أخي زرارة، فقال: أهل بيت جليل عظيم القدر في هذا الأمر، فأقبل عليه صاحبي فقال له: يا سيدنا أريد المكاتبة في شئ من الدعاء، فقال: نعم. قال: فلما سمعت هذا اعتقدت أن أسأل أنا أيضا مثل ذلك، وكنت اعتقدت في نفسي ما لم أبده لاحد من خلق الله حال والدة أبي العباس ابني، وكانت كثيرة الخلاف والغضب علي، وكانت مني بمنزلة، فقلت في نفسي أسأل الدعاء لي في أمر قد أهمني ولا أسميه، فقلت أطال الله بقاء سيدنا وأنا أسأل حاجة، قال: وما هي؟ قلت: الدعاء لي بالفرج من أمر قد أهمني، قال: فأخذ درجا بين يديه كان أثبت فيه حاجة الرجل فكتب: (و) الزراري يسأل الدعاء له في أمر قد أهمه، قال: ثم طواه فقمنا وانصرفنا.فلما كان بعد أيام قال لي صاحبي:ألا نعود إلى أبي جعفر فنسأله عن حوائجنا التي كنا سألناه، فمضيت معه ودخلنا عليه فحين جلسنا عنده أخرج الدرج، وفيه مسائل كثيرة قد أجيب في تضاعيفها، فأقبل على صاحبي فقرأ عليه جواب ما سأل، ثم أقبل علي وهو يقرأ [فقال:].وأما الزراري وحال الزوج والزوجة فأصلح الله ذات بينهما، قال فورد علي أمر عظيم، وقمنا فانصرفت ، فقال لي: قد ورد عليك هذا الامر فقلت:أعجب منه قال:مثل أي شئ؟ فقلت: لأنه سر لم يعلمه إلا الله تعالى وغيري فقد أخبرني به، فقال: أتشك في أمر الناحية؟ أخبرني الآن ما هو فأخبرته فعجب منه. ثم قضى أن عدنا إلى الكوفة فدخلت داري وكانت أم أبي العباس مغاضبة لي في منزل أهلها فجاءت إلي فاسترضتني واعتذرت ووافقتني ولم تخالفني حتى فرق الموت بيننا.","27/1/37/12",""],[13,36,"وأخبرني بهذه الحكاية جماعة عن أبي غالب أحمد بن محمد بن سليمان الزراري رحمه الله إجازة وكتب عنه ببغداد أبو الفرج محمد بن المظفر في منزله بسويقة غالب في يوم الأحد لخمس خلون من ذي القعدة سنة ست وخمسين وثلاثمائة قال: كنت تزوجت بأم ولدي وهي أول امرأة تزوجتها، وأنا حينئذ حدث السن وسني إذ ذاك دون العشرين سنة، فدخلت بها في منزل أبيها، فأقامت في منزل أبيها سنين وأنا أجتهد بهم في أن يحولوها إلى منزلي وهم لا يجيبوني إلى ذلك، فحمـلت مني في هـذه المدة وولـدت بنتـا فعاشت مدة ثم ماتت ولم أحضر في ولادتها ولا في موتها ولم أرها منذ ولدت إلى أن توفيت للشرور التي كانت بيني وبينهم. ثم اصطلحنا على أنهم يحملونها إلى منزلي، فدخلت إليهم في منزلهم ودافعوني في نقل المرأة إلي وقدر أن حملت المرأة مع هذه الحال، ثم طالبتهم بنقلها إلى منزلي على ما اتفقنا عليه، فامتنعوا من ذلك، فعاد الشر بيننا وانتقلت عنهم، وولدت وأنا غائب عنها بنتا وبقينا على حال الشر والمضارمة سنين لا آخذها. ثم دخلت بغداد وكان الصاحب بالكوفة في ذلك الوقت أبو جعفر محمد بن أحمد الزجوزجي رحمه الله، وكان لي كالعم أو الوالد، فنزلت عنده ببغداد وشكوت إليه ما أنا فيه من الشرور الواقعة بيني وبين الزوجة وبين الأحماء، فقال لي: تكتب رقعة وتسأل الدعاء فيها. فكتبت رقعة (و) ذكرت فيها حالي وما أنا فيه من خصومة القوم لي وامتناعهم من حمل المرأة إلى منزلي، ومضيت بها أنا وأبو جعفر رحمه الله إلى محمد بن علي، وكان في ذلك الواسطة بيننا وبين الحسين بن روح رضي الله عنه وهو إذ ذاك الوكيل، فدفعناها إليه وسألناه إنفاذها، فأخذها مني وتأخر الجواب عني أياما، فلقيته فقلت له: قد ساءني تأخر الجواب عني، فقال (لي) لا يسؤوك (هذا) فإنه أحب (لي ولك، وأومأ) إلي أن الجواب إن قرب كان من جهة الحسين بن روح رضي الله عنه، وإن تأخر كان من جهة الصاحب عليه السلام، فانصرفت.فلما كان بعد ذلك- ولا أحفظ المدة إلا أنها كانت قريبة- فوجه إلي أبو جعفر الزجوزجي رحمه الله يوما من الأيام، فصرت إليه، فأخرج لي فصلا من رقعة وقال لي: هذا جواب رقعتك فإن شئت أن تنسخه فانسخه ورده فقرأته فإذا فيه والزوج والزوجة فأصلح الله ذات بينهما، ونسخت اللفظ ورددت عليه الفصل، ودخلنا الكوفة فسهل الله لي نقل المرأة بأيسر كلفة، وأقامت معي سنين كثيرة ورزقت مني أولادا وأسأت إليها إساءات واستعملت معها كل ما لا تصبر النساء عليه، فما وقعت بيني وبينها لفظة شر ولا بين أحد من أهلها إلى أن فرق الزمان بيننا. قالوا:قال أبو غالب رحمه الله: وكنت قديما قبل هذه الحال قد كتبت رقعة أسأل فيها أن يقبل ضيعتي، ولم يكن اعتقادي في ذلك الوقت التقرب إلى الله عز وجل بهذه الحال، وإنما كان شهوة مني للاختلاط بالنوبختيين والدخول معهم فيما كانوا (فيه) من الدنيا، فلم أجب إلى ذلك وألححت في ذلك، فكتب إلي أن اختر من تثق به فاكتب الضيعة باسمه فإنك تحتاج إليها. فكتبتها باسم أبي القاسم موسى بن الحسن الزجوزجي ابن أخي أبي جعفر رحمه الله لثقتي به وموضعه من الديانة والنعمة.فلم تمض الأيام حتى أسروني الاعراب ونهبوا الضيعة التي كنت أملكها، وذهب مني فيها من غلاتي ودوابي وآلتي نحو من ألف دينار، وأقمت في أسرهم مدة إلى أن اشتريت نفسي بمائة دينار وألف وخمسمائة درهم، (و)لزمني في أجرة الرسل نحو من خمسمائة درهم، فخرجت واحتجت إلى الضيعة فبعتها.","27/1/37/13",""],[14,36,"وأخبرني الحسين بن عبيد الله، عن أبي الحسن محمد بن أحمد بن داود القمي رحمه الله، عن أبي علي بن همام قال: أنفذ محمد بن علي الشلمغاني العزاقري إلى الشيخ الحسين بن روح يسأله أن يباهله وقال: أنا صاحب الرجل وقد أمرت بإظهار العلم، وقد أظهرته باطنا وظاهرا، فباهلني فأنفذ إليه الشيخ رضي الله عنه في جواب ذلك أينا تقدم صاحبه فهو المخصوم، فتقدم العزاقري فقتل وصلب وأخذ معه ابن أبي عون، وذلك في سنة ثلاث وعشرين وثلاثمائة.","27/1/37/14",""],[15,36,"قال ابن نوح:وأخبرني جدي محمد بن أحمد بن العباس بن نوح رضي الله عنه قال: أخبرنا أبو محمد الحسن بن جعفر بن إسماعيل بن صالح الصيمري قال: لما أنفذ الشيخ أبو القاسم الحسين بن روح رضي الله عنه التوقيع في لعن ابن أبي العزاقر أنفذه من محبسه في دار المقتدر إلى شيخنا أبي علي بن همام رحمه الله في ذي الحجة سنة اثنتي عشرة وثلاثمائة وأملاه أبو علي رحمه الله علي وعرفني أن أبا القاسم رضي الله عنه راجع في ترك إظهاره، فإنه في يد القوم و(في) حبسهم فأمر بإظهاره وأن لا يخشى ويأمن، فتخلص فخرج من الحبس بعد ذلك بمدة يسيرة والحمد لله.","27/1/37/15",""],[16,36,"قال: ووجدت في أصل عتيق كتب بالأهواز في المحرم سنة سبع عشرة وثلاثمائة: أبو عبد الله، قال: حدثنا أبو محمد الحسن بن علي بن إسماعيل بن جعفر بن محمد بن عبد الله بن محمد (بن عمر) بن علي بن أبي طالب الجرجاني قال: كنت بمدينة قم فجرى بين إخواننا كلام في أمر رجل أنكر ولده، فانفذوا رجلا إلى الشيخ صانه الله.وكنت حاضرا عنده أيده الله فدفع إليه الكتاب فلم يقرأه وأمره أن يذهب إلى أبي عبد الله البزوفري أعزه الله ليجيب عن الكتاب فصار إليه وأنا حاضر، فقال [له] أبو عبد الله:الولد ولده وواقعها في يوم كذا وكذا في موضع كذا وكذا فقل له:فيجعل اسمه محمدا فرجع الرسول إلى البلد وعرفهم ووضح عندهم القول وولد الولد وسمي محمدا.","27/1/37/16",""],[17,36,"قال ابن نوح: وحدثني أبو عبد الله الحسين محمد بن سورة القمي رحمه الله حين قدم علينا حاجا، قال حدثني علي بن الحسن بن يوسف الصائغ القمي ومحمد بن أحمد بن محمد الصيرفي المعروف بابن الدلال وغيرهما من مشايخ أهل قم أن علي بن الحسين بن موسى بن بابويه كانت تحته بنت عمه محمد بن موسى بن بابويه فلم يرزق منها ولدا.فكتب إلى الشيخ أبي القاسم الحسين بن روح رضي الله عنه أن يسأل الحضرة أن يدعو الله أن يرزقه أولادا فقهاء، فجاء الجواب: \"إنك لا ترزق من هذه وستملك جارية ديلمية وترزق منها ولدين فقيهين \".قال: وقال لي أبو عبد الله بن سورة حفظه الله:ولأبي الحسن بن بابويه رحمه الله ثلاثة أولاد، محمد والحسين فقيهان ماهران في الحفظ، ويحفظان ما لا يحفظ غيرهما من أهل قم، ولهما أخ اسمه الحسن وهو الأوسط مشتغل بالعبادة والزهد، لا يختلط بالناس ولا فقه له. قال ابن سورة:كلما روى أبو جعفر، وأبو عبد الله ابنا علي بن الحسين شيئا يتعجب الناس من حفظهما ويقولون لهما: هذا الشأن خصوصية لكما بدعوة الامام لكما، وهذا أمر مستفيض في أهل قم.","27/1/37/17",""],[18,36,"(قال) وسمعت أبا عبد الله بن سورة القمي يقول: سمعت سرورا- وكان رجلا عابدا مجتهدا لقيته بالأهواز غير أني نسيت نسبه- يقول: كنت أخرس لا أتكلم، فحملني أبي وعمي في صباي وسني، إذ ذاك ثلاثة عشر أو أربعة عشر إلى الشيخ أبي القاسم بن روح رضي الله عنه، فسألاه أن يسأل الحضرة أن يفتح الله لساني. فذكر الشيخ أبو القاسم الحسين بن روح أنكم أمرتم بالخروج إلى الحائر. قال سرور: فخرجنا أنا وأبي وعمي إلى الحائر فاغتسلنا وزرنا ، قال: فصاح بي أبي وعمي: يا سرور فقلت بلسان فصيح: لبيك فقال لي: ويحك تكلمت فقلت: نعم. قال أبو عبد الله بن سورة (و) كان سرور هذا (رجلا) ليس بجهوري الصوت.","27/1/37/18",""],[19,36,"أخبرني محمد بن محمد بن النعمان والحسين بن عبيد الله، عن محمد بن أحمد الصفواني رحمه الله قال: رأيت القاسم بن العلاء وقد عمر مائة سنة وسبع عشرة سنة منها ثمانون سنة صحيح العينين، لقي مولانا أبا الحسن وأبا محمد العسكريين عليهما السلام. وحجب بعد الثمانين، وردت عليه عينـاه قبل وفاته بسبـعة أيـام. وذلك أنـي كنت مقيمـا عنده بمدينة الران من أرض آذربايجان، وكان لا تنقطع توقيعات مولانا صاحب الزمان عليه السلام على يد أبي جعفر محمد بن عثمان العمري وبعده على [يد] أبي القاسم [الحسين] بن روح قدس الله روحهما، فانقطعت عنه المكاتبة نحوا من شهرين، فقلق رحمه الله لذلك. فبينا نحن عنده نأكل إذ دخل البواب مستبشرا، فقال له: فيج العراق لا يسمى بغيره- فاستبشر القاسم وحول وجهه إلى القبلة، فسجد ودخل كهل قصير يرى أثر الفيوج عليه، وعليه جبة مصرية، وفي رجله نعل محاملي، وعلى كتفه مخلاة. فقام القاسم فعانقه ووضع المخلاة عن عنقه، ودعا بطشت وماء فغسل يده وأجلسه إلى جانبه، فأكلنا وغسلنا أيدينا، فقام الرجل فأخرج كتابا أفضل من النصف المدرج ، فناوله القاسم، فأخذه وقبله ودفعه إلى كاتب له يقال له ابن أبي سلمة، فأخذه أبو عبد الله ففضه وقرأه حتى أحس القاسم بنكاية. فقال: يا أبا عبد الله خير، فقال: خير، فقال: ويحك خرج في شئ فقال أبو عبد الله: ما تكره فلا، قال القاسم: فما هو؟ قال: نعي الشيخ إلى نفسه بعد ورود هذا الكتاب بأربعين يوما، وقد حمل إليه سبعة أثواب فقال القاسم: في سلامة من ديني؟ فقال: في سلامة من دينك، فضحك رحمه الله فقال:ما أؤمل بعد هذا العمر. فقال الرجل الوارد: فأخرج من مخلاته ثلاثة أزر وحبرة يمانية حمراء وعمامة وثوبين ومنديلا فأخذه القاسم، وكان عنده قميص خلعه عليه مولانا الرضا أبو الحسن عليه السلام، وكان له صديق يقال له عبد الرحمن بن محمد البدري ، وكان شديد النصب، وكان بينه وبين القاسم نضر الله وجهه مودة في أمور الدنيا شديدة، وكان القاسم يوده، و (قد) كان عبد الرحمن وافى إلى الدار لاصلاح بين أبي جعفر بن حمدون الهمداني وبين ختنة ابن القاسم. فقال القاسم لشيخين من مشايخنا المقيمين معه أحدهما يقال له أبو حامد عمران بن المفلس والآخر أبو علي بن جحدر: أن اقرئا هذا الكتاب عبد الرحمن بن محمد فإني أحب هدايته وأرجو [أن] يهديه الله بقراءة هذا الكتاب، فقالا له: الله الله الله فإن هذا الكتاب لا يحتمل ما فيه خلق من الشيعة فكيف عبد الرحمن بن محمد.فقال: أنا أعلم أني مفش لسر لا يجوز لي إعلانه، لكن من محبتي لعبد الرحمن بن محمد وشهوتي أن يهديه الله عز وجل لهذا الأمر هوذا، إقرأه الكتاب. فلما مر [في] ذلك اليوم- وكان يوم الخميس لثلاث عشرة خلت من رجب- دخل عبد الرحمن بن محمد وسلم عليه، فأخرج القاسم الكتاب فقال له: إقرأ هذا الكتاب وانظر لنفسك، فقرأ عبد الرحمن الكتاب فلما بلغ إلى موضع النعي رمى الكتاب عن يده وقال للقاسم: يا با محمد اتق الله فإنك رجل فاضل في دينك، متمكن من عقلك، والله عز وجل يقول: ﴿وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَداً وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ﴾ .وقال: ﴿عَالِمُ الْغَيْبِ فَلاَ يظْهرُ عَلَى غَيْبِهِ أَحَداً﴾. فضحك القاسم وقال له: أتم الآية: ﴿إِلاَّ مَنِ ارْتَضَى مِنْ رَسُولٍ﴾ ومولاي عليه السلام هو الرضا من الرسول، وقال: قد علمت أنك تقول هذا ولكن أرخ اليوم، فإن أنا عشت بعد هذا اليوم المؤرخ في هذا الكتاب فاعلم أني لست على شئ، وإن أنا مت فانظر لنفسك، فورخ عبد الرحمن اليوم وافترقوا. وحم القاسم يوم السابع من ورود الكتاب، واشتدت به في ذلك اليوم العلة، واستند في فراشه إلى الحائط، وكان ابنه الحسن بن القاسم مدمنا على شرب الخمر، وكان متزوجا إلى أبي عبد الله بن حمدون الهمداني، وكان جالسا ورداؤه مستورعلى وجهه في ناحية من الدار، وأبو حامد في ناحية، وأبو علي بن جحدر وأنا وجماعة من أهل البلد نبكي، إذ اتكى القاسم على يديه إلى خلف وجعل يقول: يا محمد يا علي يا حسن يا حسين يا موالي كونوا شفعائي إلى الله عز وجل وقالها الثانية، وقالها الثالثة. فلما بلغ في الثالثة: يا موسى يا علي تفرقعت أجفان عينيه كما يفرقع الصبيان شقائق النعمان، وانتفخت حدقته، وجعل يمسح بكمه عينيه، وخرج من عينيه شبيه بماء اللحم مد طرفه إلى ابنه، فقال: يا حسن إلي يا با حامد [إلي] يا با علي (إلي)، فاجتمعنا حوله ونظرنا إلى الحدقتين صحيحتين، فقال له أبو حامد: تراني وجعل يده على كل واحد منا، وشاع الخبر في الناس والعامة، و(انتابه) الناس من العوام ينظرون إليه. وركب القاضي إليه وهو أبو السائب عتبة بن عبيد الله المسعودي وهو قاضي القضاة ببغداد ، فدخل عليه فقال له: يا با محمد ما هذا الذي بيدي وأراه خاتما فصه فيروزج، فقربه منه فقال:عليه ثلاثة أسطر فتناوله القاسم رحمه الله فلم يمكنه قراءته وخرج الناس متعجبين يتحدثون بخبره، والتفت القاسم إلى ابنه الحسن فقال له: إن الله منزلك منزلة ومرتبك مرتبة فاقبلها بشكر، فقال له الحسن: يا أبه قد قبلتها، قال القاسم: على ماذا؟ قال:على ما تأمرني به يا أبه، قال: على أن ترجع عما أنت عليه من شرب الخمر، قال الحسن: يا أبه وحق من أنت في ذكره لأرجعن عن شرب الخمر، ومع الخمر أشياء لا تعرفها، فرفع القاسم يده إلى السماء وقال: اللهم ألهم الحسن طاعتك، وجنبه معصيتك ثلاث مرات، ثم دعا بدرج فكتب وصيته بيده رحمه الله وكانت الضياع التي في يده لمولانا وقف وقفه (أبوه). وكان فيما أوصى الحسن أن قال: يا بني إن أهلت لهذا الأمر يعني الوكالة لمولانا فيكون قوتك من نصف ضيعتي المعروفة بفرجيذه، وسائرها ملك لمولاي، وإن لم تؤهل له فاطلب خيرك من حيث يتقبل الله، وقبل الحسن وصيته على ذلك.فلما كان في يوم الأربعين وقد طلع الفجر مات القاسم رحمه الله، فوافاه عبد الرحمن يعدو في الأسواق حافيا حاسرا وهو يصيح:وا سيداه، فاستعظم الناس ذلك منه وجعل الناس يقولون: ما الذي تفعل بنفسك، فقال: اسكنوا فقد رأيت ما لم تروه، وتشيع ورجع عما كان عليه، ووقف الكثير من ضياعه. وتولى أبو علي بن جحدر غسل القاسم وأبو حامد يصب عليه الماء، وكفن في ثمانية أثواب على بدنه قميص مولاه أبي الحسن وما يليه السبعة الأثواب التي جاءته من العراق. فلما كان بعد مدة يسيرة ورد كتاب تعزية على الحسن من مولانا عليه السلام في آخره دعاء \"ألهمك الله طاعته وجنبك معصيته\" وهو الدعاء الذي كان دعا به أبوه، وكان آخره \"قد جعلنا أباك إماما لك وفعاله لك مثالا\".","27/1/37/19",""],[20,36,"وبهذا الاسناد، عن الصفواني قال: وافى الحسن بن علي الوجناء النصيبي سنة سبع وثلاثمائة ومعه محمد بن الفضل الموصلي، وكان رجلا شيعيا غير أنه ينكر وكالة أبي القاسم بن روح رضي الله عنه ويقول: إن هذه الأموال تخرج في غير حقوقها. فقال الحسن بن علي الوجناء لمحمد بن الفضل:يا ذا الرجل اتق الله فإن صحة وكالة أبي القاسم كصحة وكالة أبي جعفر محمد بن عثمان العمري، وقد كانا نزلا ببغداد على الزاهر، وكنا حضرنا للسلام عليهما، وكان قد حضر هناك شيخ لنا يقال له أبو الحسن بن ظفر وأبو القاسم بن الأزهر، فطال الخطاب بين محمد بن الفضل وبين الحسن (بن علي، فقال محمد بن الفضل للحسن): من لي بصحة ما تقول وتثبت وكالة الحسين بن روح؟ فقال الحسن بن علي الوجناء: أبين لك ذلك بدليل يثبت في نفسك، وكان مع محمد بن الفضل دفتر كبير فيه ورق طلحي مجلد بأسود فيه حسباناته ، فتناول الدفتر الحسن وقطع منه نصف ورقة كان فيه بياض، وقال لمحمد بن الفضل: أبروا لي قلما فبرى قلما واتفقا على شئ بينهما لم أقف أنا عليه واطلع عليه أبا الحسن بن ظفر وتناول الحسن بن علي الوجناء القلم، وجعل يكتب ما اتفقا عليه في تلك الورقة بذلك القلم المبري بلا مداد، ولا يؤثر فيه حتى ملا الورقة. ثم ختمه وأعطاه لشيخ كان مع محمد بن الفضل أسود يخدمه، وأنفذ بها إلى أبي القاسم الحسين بن روح ومعنا ابن الوجناء لم يبرح، وحضرت صلاة الظهر فصلينا هناك، ورجع الرسول فقال: قال لي: إمض فإن الجواب يجئ، وقدمت المائدة فنحن في الأكل إذ ورد الجواب في تلك الورقة مكتوب بمداد عن فصل فصل، فلطم محمد بن الفضل وجهه ولم يتهنأ بطعامه، وقال لابن الوجناء: قم معي، فقام معه حتى دخل على أبي القاسم بن روح رضي الله عنه وبقي يبكي ويقول:يا سيدي أقلني أقالك الله، فقال أبو القاسم يغفر الله لنا ولك إن شاء الله.","27/1/37/20",""],[21,36,"أخبرنا جماعة، عن أبي جعفر محمد بن علي بن الحسين بن بابويه قال: أخبرنا أبو محمد الحسن بن محمد بن يحيى العلوي ابن أخي طاهر ببغداد طرف سوق القطن في داره قال: قدم أبو الحسن علي بن أحمد بن علي العقيقي بغداد إلى علي بن عيسى بن الجراح - وهو يومئذ وزير في أمر ضيعة له -فسأله فقال له: إن أهل بيتك في هذا البلد كثير، فإن ذهبنا نعطي كلما سألونا، طال ذلك، أو كما قال. فقال له العقيقي: فإني أسأل من في يده قضاء حاجتي، فقال له علي بن عيسى: من هو ذلك؟ فقال: الله جل ذكره، فخرج وهو مغضب، قال: فخرجت وأنا أقول في الله عزاء من كل هالك، ودرك من كل مصيبة، قال فانصرفت، فجاءني الرسول من عند الحسين بن روح رضي الله عنه فشكوت إليه فذهب من عندي فأبلغه فجاءني الرسول بمائة درهم عدد ووزن مائة درهم ومنديل وشئ من حنوط وأكفان وقال لي:مولاك يقرئك السـلام ويقـول:إذا همـك أمـر أو غـم فامسـح بهـذا المنـديل وجهـك فـإن هذا منديل مولاك، وخذ هذه الدراهم وهذا الحنوط وهذه الأكفان، وستقضى حاجتك في هذه الليلة، فإذا قدمت إلى مصر مات محمد بن إسماعيل من قبلك بعشرة أيام، ثم مت بعده، فيكون هذا كفنك وهذا حنوطك وهذا جهازك. [قال:] فأخذت ذلك وحفظته وانصرف الرسول، وإذا أنا بالمشاعل على بابي والباب يدق، فقلت لغلامي خير:يا خير أنظر أي شئ هو ذا؟ فقال: هذا غلام حميد بن محمد الكاتب ابن عم الوزير فأدخله إلي، فقال لي: قد طلبك الوزير ويقول لك مولاي حميد: اركب إلي. [قال:] فركبت وفتحت الشوارع والدروب [وجئت] إلى شارع الوزانين، فإذا بحميد قاعد ينتظرني، فلما رآني أخذ بيدي وركبنا فدخلنا على الوزير، فقال لي الوزير: يا شيخ قد قضى الله حاجتك، واعتذر إلي ودفع إلي الكتب مكتوبة مختومة قد فرغ منها، قال:فأخذت ذلك وخرجت. قال: وقال أبو محمد الحسن بن محمد:فحدثنا أبو الحسن علي بن أحمد العقيقي بنصيبين بهذا وقال لي:ما خرج هذا الحنوط إلا إلى عمتي فلانة فلم يسمها وقد نعيت إلي نفسي، وقد قال لي الحسين بن روح رحمه الله:إني أملك الضيعة وقد كتب لي بالذي أردت فقمت إليه وقبلت رأسه وعينيه وقلت له:يا سيدي أرني الأكفان والحنوط والدراهم، قال: فاخرج لي الأكفان، فإذا فيه برد حبر مسهم من نسج اليمن وثلاثة أثواب مروي وعمامة وإذا الحنوط في خريطة، فأخرج الدراهم فوزنها مائة درهم وعددها مائة درهم.فقلت له:يا سيدي هب لي منها درهما أصوغه خاتما، فقال (و) كيف يكون ذلك، خذ من عندي ما شئت، فقلت:أريد من هذه وألححت عليه وقبلت رأسه (وعينيه)، فأعطاني درهما شددته في منديلي وجعلته في كمي.فلما صرت إلى الخان فتحت زنفيلجة معي، وجعلت المنديل في الزنفيلجة وفيه الدرهم مشدود، وجعلت كتبي ودفاتري (فيها) وأقمت أياما ثم جئت أطلب الدرهم فإذا الصرة مصرورة بحالها ولا شئ فيها، فأخذني شبه الوسواس، فصرت إلى باب العقيقي، فقلت لغلامه خير، أريد الدخول إلى الشيخ، فأدخلني إليه فقال لي: مالك يا سيدي؟ فقلت: الدرهم الذي أعطيتني ما أصبته في الصرة، فدعا بزنفيلجة وأخرج الدراهم فإذا هي مائة عددا ووزنا، ولم يكن معي أحد اتهمه فسألته رده إلي، ثم خرج إلى مصر وأخذ الضيعة، ومات قبله محمد بن إسماعيل بعشرة كما قيل ثم توفي رحمه الله وكفن في الأكفان التي دفعت إليه.","27/1/37/21",""],[22,36,"وأخبرنا جماعة، عن أبي جعفر محمد بن علي بن الحسين بن موسى بن بابويه وأبي عبد الله الحسين بن علي أخيه قالا: حدثنا أبو جعفر محمد بن علي الأسود رحمه الله قال سألني علي بن الحسين بن موسى بن بابويه رضي الله عنه بعد موت محمد بن عثمان العمري قدس سره أن أسأل أبا القاسم الروحي قدس الله روحه أن يسأل مولانا صاحب الزمان عليه السلام أن يدعو الله أن يرزقه ولدا (ذكرا) .قال: فسألته فأنهى ذلك، ثم أخبرني بعد ذلك بثلاثة أيام أنه قد دعا لعلي بن الحسين رحمه الله فإنه سيولد له ولد مبارك ينفع الله به، وبعده أولاد. قال أبو جعفر محمد بن علي الأسود وسألته في أمر نفسي أن يدعو لي أن أرزق ولدا (ذكرا) فلم يجبني إليه وقال لي ليس إلى هذا سبيل قال: فولد لعلي بن الحسين رضي الله عنه تلك السنة [ابنه] محمد بن علي وبعده أولاد، ولم يولد لي.قال أبو جعفر بن بابويه: وكان أبو جعفر محمد بن علي الأسود كثيرا ما يقول لي- إذا رآني أختلف إلى مجلس شيخنا محمد بن الحسن بن الوليد رضي الله عنه وأرغب في كتب العلم وحفظه-: ليس بعجب أن تكون لك هذه الرغبة في العلم وأنت ولدت بدعاء الإمام عليه السلام .","27/1/37/22",""],[23,36,"وقال أبو عبد الله بن بابويه:عقدت المجلس ولي دون العشرين سنة، فربما كان يحضر مجلسي أبو جعفر محمد بن علي الأسود، فإذا نظر إلى إسراعي في الأجوبة في الحلال والحرام يكثر التعجب لصغر سني ثم يقول لا عجب لأنك ولدت بدعاء الإمام عليه السلام.","27/1/37/23",""],[24,36,"وأخبرنا جماعة، عن محمد بن علي بن الحسين بن موسى بن بابويه قال: أخبرنا محمد بن علي بن متيل قال: كانت امرأة يقال لها زينب من أهل آبة، وكانت امرأة محمد بن عبديل الآبي معهـا ثلاثمـائة دينـار، فصـارت إلى عـمي جـعفر بن أحـمد بن متيـل وقـالت: أحب أن يسلم هذا المال من يدي إلى يد أبي القاسم بن روح رضي الله عنه قال:فانفذني معها أترجم عنها فلما دخلت على أبي القاسم بن روح رضي الله عنه أقبل عليها بلسان آبي فصيح فقال لها: \"زينب چونا چون بدا كوليه جونسته \"ومعناه كيف أنت وكيف كنت وما خبر صبيانك؟ فاستغنت من الترجمة وسلمت المال ورجعت.","27/1/37/24",""],[25,36,"وأخبرني جماعة، عن أبي جعفر محمد بن علي بن الحسين بن موسى بن بابويه قال: حدثني محمد بن إبراهيم بن إسحاق الطالقاني قال: كنت عند الشيخ أبي القاسم بن روح رضي الله عنه مع جماعة فيهم علي بن عيسى القصري، فقام إليه رجل فقال: إني أريد أن أسألك عن شئ، فقال له:سل عما بدا لك وذكر مسائل ذكرناها في غير هذا الموضع. قال محمد بن إبراهيم بن إسحاق: فعدت إلى الشيخ أبي القاسم بن روح رضي الله عنه من الغد وأنا أقول في نفسي: أتراه ذكر لنا أمس من عند نفسه؟ فابتدأنا فقال: يا محمد بن إبراهيم لئن أخر من السماء فتخطفني الطير أو تهوي بي الريح من مكان سحيق أحب إلي من [أن] أقول في دين الله عز وجل برأيي ومن عند نفسي، بل ذلك عن الأصل، ومسموع من الحجة عليه السلام.","27/1/37/25",""],[26,36,"وأخبرني جماعة، عن أبي عبد الله الحسين بن علي بن الحسين بن موسى بن بابويه، قال: حدثني جماعة من أهل بلدنا المقيمين كانوا ببغداد في السنة التي خرجت القرامطة على الحاج، وهي سنة (تنأثر) الكواكب أن والدي رضي الله عنه كتب إلى الشيخ أبي القاسم الحسين بن روح رضي الله عنه يستأذن في الخروج إلى الحج. فخرج في الجواب: لا تخرج في هذه السنة. فأعاد فقال: هو نذر واجب أفيجوز لي القعود عنه؟ فخرج الجواب: إن كان لابد فكن في القافلة الأخيرة. فكان في القافلة الأخيرة فسلم بنفسه وقتل من تقدمه في القوافل الاخر.","27/1/37/26",""],[27,36,"وأخبرني جماعة، عن محمد بن علي بن الحسين قال: حدثنا أبو محمد عمار بن الحسين بن إسحاق الأسروشني ، قال: حدثنا أبو العباس أحمد بن الحسن بن أبي صالح الخجندي وكان قد ألح في الفحص والطلب، وسار في البلاد، وكتب على يد الشيخ أبي القاسم بن روح رضي الله عنه إلى الصاحب عليه السلام يشكو تعلق قلبه واشتغاله بالفحص والطلب، ويسأل الجواب بما تسكن إليه نفسه، ويكشف له عما يعمل عليه قال: فخرج إلى توقيع نسخته: \"من بحث فقد طلب، ومن طلب فقد ذل ومن ذل فقد أشاط ومن أشاط فقد أشرك \".قال:فكففت عن الطلب وسكنت نفسي، وعدت إلى وطني مسرورا والحمد لله.","27/1/37/27",""],[28,36,"وأخبرني جماعة، عن أبي غالب أحمد بن محمد الزراري قال:جرى بيني وبين والدة أبي العباس -يعني ابنه -من الخصومة والشر أمر عظيم ما لا يكاد أن يتفق، وتتابع ذلك وكثر إلى أن ضجرت به، وكتبت على يد أبي جعفر أسأل الدعاء فأبطأ عني الجواب مدة، ثم لقيني أبو جعفر فقال:قد ورد جواب مسألتك، فجئته فأخرج إلي مدرجا فلم يزل يدرجه إلى أن أراني فصلا منه فيه:وأما الزوج والزوجة فأصلح الله بينهما، فلم تزل على حال الاستقامة ولم يجر بيننا بعد ذلك شئ مما كان يجري، وقد كنت أتعمد ما يسخطها فلا يجري [فيه] منها شئ، هذا معنى لفظ أبي غالب رضي الله عنه أو قريب منه.","27/1/37/28",""],[29,36,"قال ابن نوح: وكان عندي أنه كتب على يد أبي جعفر بن أبي العزاقر- قبل تغيره وخروج لعنه على ما حكاه ابن عياش إلى أن حدثني بعض من (سمع ذلك معي) أنه إنما عنى أبا جعفر الزجوزجي رضي الله عنه وأن الكتاب إنما كان من الكوفة، وذلك أن أبا غالب قال لنا: كنا نلقي أبا القاسم الحسين بن روح رضي الله عنه قبل أن يقضي الامر إليه صرنا نلقي أبا جعفر بن الشلمغاني ولا نلقاه.وحدثنا بهاتين الحكايتين مذاكرة لم أقيدهما. [بالكتابة] وقيدهما غيري، إلا أنه كان يكثر ذكرهما والحديث بهما حتى سمعتهما منه ما لا أحصي، والحمد لله شكرا دائما وصلى الله على محمد وآله وسلم.","27/1/37/29",""],[30,36,"وأخبرني جماعة، عن أبي جعفر محمد بن علي بن الحسين قال: حدثني محمد بن إبراهيم بن إسحاق الطالقاني رحمه الله قال: كنت عند الشيخ أبي القاسم الحسين بن روح رضي الله عنه مع جماعة (منهم) علي بن عيسى القصري فقام إليه رجل فقال إني أريد أن أسألك عن شئ فقال له: سل عما بدا لك، فقال الرجل: أخبرني عن الحسين عليه السلام أهو ولي الله؟ قال: نعم، قال: أخبرني عن قاتله لعنه الله أهو عدو الله؟ قال: نعم، قال الرجل: فهل يجوز أن يسلط الله عز وجل عدوه على وليه؟ فقال له أبو القاسم قدس سره: إفهم عني ما أقول لك إعلم أن الله تعالى لا يخاطب الناس بمشاهدة العيان، ولا يشافههم بالكلام، ولكنه جلت عظمته يبعث إليهم رسلا من أجناسهم وأصنافهم بشرا مثلهم، ولو بعث إليه رسلا من غير صفتهم وصورهم لنفروا عنهم، ولم يقبلوا منهم، فلما جاؤوهم وكانوا من جنسهم يأكلون ويمشون في الأسواق قالوا لهم: أنتم مثلنا لا نقبل منكم حتى تأتوا بشئ نعجز عن أن نأتي بمثله فنعلم أنكم مخصوصون دوننا بما لا نقدرعليه، فجعل الله عز وجل لهم المعجزات التي يعجز الخلق عنها.فمنهم: من جاء بالطوفان بعد الاعذار والانذار، ففرق جميع من طغى وتمرد، ومنهم:من ألقي في النار فكانت عليه بردا وسلاما، ومنهم: من أخرج من الحجر الصلد الناقة وأجرى من ضرعها لبنا، ومنهم: (من) فلق له البحر، وفجر له (من الحجر) العيون، وجعل له العصا اليابسة ثعبانا تلقف ما يأفكون، ومنهم:من أبرأ الأكمه [والأبرص] وأحيى الموتى بإذن الله، وأنبأهم بما يأكلون وما يدخرون في بيوتهم، ومنهم:من انشق له القمر وكلمته البهائم مثل البعير والذئب وغير ذلك.فلما أتوا بمثل ذلك، وعجز الخلق من أممهم أن يأتوا بمثله كان من تقدير الله جل جلاله ولطفه بعباده وحكمته أن جعل أنبياءه مع هذه المعجزات في حال غالبين، وأخرى مغلوبين، وفي حال قاهرين، وأخرى مقهورين، ولو جعلهم عز وجل في جميع أحوالهم غالبين وقاهرين، ولم يبتلهم ولم يمتحنهم، لأتخذهم الناس آلهة من دون الله عز وجل، ولما عرف فضل صبرهم على البلاء والمحن والاختبار. ولكنه جعل أحوالهم في ذلك كأحوال غيرهم، ليكونوا في حال المحنة والبلوى صابرين وفي [حال] العافية والظهور على الأعداء شاكرين، ويكونوا في جميع أحوالهم متواضعين، غير شامخين ولا متجبرين، وليعلم العباد أن لهم عليهم السلام إلها هو خالقهم ومدبرهم فيعبدوه ويطيعوا رسله، ويكونوا حجة لله ثابتة على من تجاوز الحد فيهم وادعى لهم الربوبية، أو عاند وخالف وعصى، وجحد بما أتت به الأنبياء والرسل، وليهلك من هلك عن بينة ويحيى من حي عن بينة. قال محمد بن إبراهيم بن إسحاق رضي الله عنه: فعدت إلى الشيخ أبي القاسم الحسين بن روح قدس سره من الغد وأنا أقول في نفسي: أتراه ذكر لنا يوم أمس [من]عند نفسه؟ فابتدأني فقال: يا محمد بن إبراهيم لئن أخر من السماء فتخطفني الطير أو تهوي بي الريح من مكان سحيق أحب إلي من أن أقول في دين الله برأيي ومن عند نفسي، بل ذلك من الأصل ومسموع من الحجة صلوات الله وسلامه عليه.","27/1/37/30",""],[31,36,"(و)قد ذكرنا طرفا من الأخبار الدالة على إمامة ابن الحسن عليه السلام وثبوت غيبته ووجود عينه ، لأنهـا أخبـار تضمنت الاخبـار بالغايبـات وبالشئ قبل كونـه على وجـه خارق للعادة، لا يعلم ذلك إلا من أعلمه الله على لسان نبيه صلى الله عليه وآله وسلم، ووصل إليه من جهة من دل الدليل على صدقه، ولولا صدقهم لما كان كذلك، لان المعجزات لا تظهر على يد الكذابين، وإذا ثبت صدقهم دل على وجود من أسندوا ذلك إليه، ولم نستوف ما ورد في هذا المعنى لئلا يطول به الكتاب وهو موجود في الكتب.","27/1/37/31",""],[1,37,"لا علة تمنع من ظهوره إلا خوفه على نفسه من القتل، لانه لو كان غير ذلك لما ساغ له الاستتار، وكان يتحمل المشاق والاذى، فإن منازل الائمة وكذلك الانبياء عليهم السلام إنما تعظم لتحملهم المشاق العظيمة في ذات الله تعالى.","27/1/38/1",""],[2,37,"فإن قيل: هلا منع الله من قتله بما يحول بينه وبين من يريد قتله؟ قلنا: المنع الذي لا ينافي التكليف هو النهي عن خلافه والامر بوجوب اتباعه ونصرته والتزام الانقياد له، وكل ذلك فعله تعالى، وأما الحيلولة بينهم وبينه فإنه ينافي التكليف، وينقض الغرض (به)، لان الغرض بالتكليف استحقاق الثواب، والحيلولة ينافي ذلك، وربما كان في الحيلولة والمنع من قتله بالقهر مفسدة للخلق، فلا يحسن من الله فعلها. وليس هذا كما قال بعض أصحابنا:إنه لا يمتنع أن يكون في ظهوره مفسدة وفي استتاره مصلحة، لأن الذي قاله يفسد طريق وجوب الرسالة في كل حال وتطرق القول بأنها تجري مجرى الالطاف التي تتغير بالازمان والاوقات، والقهر والحيلولة ليس كذلك، ولا يمتنع أن يقال: (إن) في ذلك مفسدة ولا يؤدي إلى إفساد وجوب الرئاسة.","27/1/38/2",""],[3,37,"إن قيل: أليس آباؤه عليهم السلام كانوا ظاهرين ولم يخافوا ولا صاروا بحيث لا يصل إليهم أحد؟ قلنا: آباؤه عليهم السلام حالهم بخلاف حاله، لأنه كان المعلوم من حال آبائه لسلاطين الوقت وغيرهم أنهم لا يرون الخروج عليهم، ولا يعتقدون أنهم يقومون بالسيف ويزيلون الدول، بل كان المعلوم من حالهم أنهم ينتظرون مهديا لهم، وليس يضر السلطان اعتقاد من يعتقد إمامتهم إذا أمنوهم على مملكتهم (ولم يخافوا جانبهم). وليس كذلك صاحب الزمان عليه السلام، لأن المعلوم منه أنه يقوم بالسيف ويزيل الممالك ويقهر كل سلطان ويبسط العدل ويميت الجور، فمن هذه صفته يخاف جانبه ويتقي فورته، فيتتبع ويرصد، ويوضع العيون عليه، ويعنى به خوفا من وثبته وريبة من تمكنه فيخاف حينئذ ويحوج إلى التحرز والاستظهار، بأن يخفي شخصه عن كل من لا يأمنه من ولي وعدو إلى وقت خروجه. وأيضا فأبآؤه عليهم السلام إنما ظهروا لأنه كان المعلوم أنه لو حدث بهم حادث لكان هناك من يقوم مقامه ويسد مسده من أولادهم، وليس كذلك صاحب الزمان عليه السلام، لان المعلوم أنه ليس بعده من يقوم مقامه قبل حضور وقت قيامه بالسيف، فلذلك وجب استتاره وغيبته، وفارق حاله حال آبائه عليهم السلام، وهذا واضح بحمد الله. فإن قيل: بأي شيء يعلم زوال الخوف وقت ظهوره أبوحي من الله؟ فالإمام لا يوحى إليه، أو بعلم ضروري؟ فذلك ينافي التكليف، أو بأمارة توجب عليه الظن؟ ففي ذلك تغرير بالنفس.","27/1/38/3",""],[4,37,"قلنا: عن ذلك جوابان: أحدهما أن الله تعالى أعلمه على لسان نبيه صلى الله عليه وآله، وأوقفه عليه من جهة آبائه عليهم السلام زمان غيبته المخوفة، وزمان زوال الخوف عنه، فهو يتبع في ذلك ما شرع له وأوقف عليه، وإنما أخفي ذلك عنا لما فيه من المصلحة، فأما هو فهو عالم به لا يرجع (فيه) إلى الظن. والثاني أنه لا يمتنع أن يغلب على ظنه بقوة الإمارات بحسب العادة قوة سلطانه، فيظهر عند ذلك ويكون قد أعلم أنه متى غلب في ظنه كذلك وجب عليه، ويكون الظن شرطا والعمل عنده معلوما، كما نقوله في تنفيذ الحكم عند شهادة الشهود، والعمل على جهات القبلة بحسب الامارات والظنون، وإن كان وجوب التنفيذ للحكم والتوجه إلى القبلة معلومين، وهذا واضح بحمد الله. وقد ورد بهذه الجملة التي ذكرناها أيضا أخبار تعضد ما قلناه، نذكر طرفا منها ليستأنس به إن شاء الله تعالى.","27/1/38/4",""],[5,37,"أخبرني الحسين بن عبيدالله، عن أبي جعفر بن سفيان البزوفري، عن أحمد بن إدريس، عن علي بن محمد بن قتيبة، عن الفضل بن شاذان النيشابوري، عن الحسن بن محبوب، عن علي بن رئاب، عن زرارة قال: إن للقائم غيبة قبل ظهوره. قلت (و) لم؟ قال: يخاف القتل.","27/1/38/5",""],[6,37,"وروي أن في صاحب الامر عليه السلام سنة من موسى عليه السلام،قلت: وما هي؟ قال: دام خوفه وغيبته مع الولاة إلى أن أذن الله تعالى بنصره. ولمثل ذلك اختفى رسول الله صلى الله عليه وآله في الشعب تارة، وأخرى في الغار، وقعد أمير المؤمنين عليه السلام عن المطالبة بحقه.","27/1/38/6",""],[7,37,"وروى سعد بن عبدالله، عن محمد بن الحسين بن أبي الخطاب، عن صفوان بن يحيى، عن عبـدالله بن مسكان، عن محمـد بن علي الحلبي، عن أبي عبدالله عليه السلام قال: إكتتم رسول الله صلى الله عليه وآله بمكة مستخفيا خائفا خمس سنين، ليس يظهر، وعلي عليه السلام معه وخديجة، ثم أمره الله تعالى أن يصدع بما يؤمر، فظهر وأظهر أمره.","27/1/38/7",""],[8,37,"سعد، عن أحمد بن محمد بن عيسى ومحمد بن الحسين بن أبي الخطاب، عن الحسن بن محبوب، عن علي بن رئاب، عن عبيدالله بن علي الحلبي قال: سمعت أبا عبدالله عليه السلام يقول: مكث رسول الله صلى الله عليه وآله وسلم بمكة بعدما جاء‌ه الوحي عن الله تعالى ثلاث عشرة سنة، منها ثلاث سنين مستخفيا خائفا لا يظهر حتى أمره الله تعالى أن يصدع بما يؤمر، فأظهر حينئذ الدعوة.","27/1/38/8",""],[9,37,"وروى أحمد بن محمد بن عيسى الاشعري، عن محمد بن سنان، عن محمد بن يحيى الخثعمي، عن ضريس الكناسي، عن أبي خالد الكابلي في حديث له اختصرناه قال: سألت أبا جعفر عليه السلام أن يسمي القائم حتى أعرفه باسمه، فقال:يا أبا خالد! سألتني عن أمر لو أن بني فاطمة عرفوه لحرصوا على أن يقطعوه بضعة بضعة.","27/1/38/9",""],[10,37,"وروى سعد بن عبد الله، عن جماعة من أصحابنا، عن عثمان بن عيسى، عن خالد بن نجيح، عن زرارة بن أعين قال: سمعت أبا عبدالله عليه السلام يقول: إن للغلام غيبة قبل أن يقوم. قلت: ولم؟ قال: يخاف وأومأ بيده إلى بطنه. ثم قال: يا زرارة! وهو المنتظر، وهو الذي يشك الناس في ولادته، منهم من يقول: إذا مات أبوه فلا خلف (له)، ومنهم من يقول: هو حمل، ومنهم من يقول: هو غائب، ومنهم من يقول: (ما ولد ومنهم من يقول:) قد ولد قبل وفاة أبيه بسنتين، وهو المنتظر غير أن الله تعالى يحب أن يمتحن الشيعة، فعند ذلك يرتاب المبطلون. قال: فقلت جعلت فداك وإن أدركت ذلك الزمان فأي شيء أعمل؟ فقال: يا زرارة،إن أدركت ذلك الزمان فادع بهذا الدعاء: اللهم عرفني نفسك، فإنك إن لم تعرفني نفسك لم أعرف نبيك… إلى آخره.","27/1/38/10",""],[11,37,"وروى سليم بن قيس الهلالي، عن جابر بن عبدالله الانصاري وعبدالله بن عباس قالا: قال رسول الله صلى الله عليه وآله في وصيته لاميرالمؤمنين: يا أخي، إن قريشا ستظاهر عليك وتجتمع كلمتهم على ظلمك وقهرك، فإن وجدت أعوانا فجاهدهم وإن لم تجد أعوانا فكف يدك واحقن دمك فإن الشهادة من ورائك.","27/1/38/11",""],[1,38,"وأما ما روي من الاخبار من امتحان الشيعة في حال الغيبة، وصعوبة الامر عليهم، واختبارهم للصبر عليه، فالوجه فيها الاخبار عما يتفق من ذلك من الصعوبة والمشاق، لا أن الله تعالى غيب الامام ليكون ذلك، وكيف يريد الله ذلك، وما ينال المؤمنين من جهة الظالمين ظلم منهم لهم ومعصية، والله تعالى لا يريد ذلك. بل سبب الغيبة هو الخوف على ما قلناه، وأخبروا بما يتفق في هذه الحال، وما للمؤمن من الثواب على الصبر على ذلك، والتمسك بدينه إلى أن يفرج الله تعالى عنهم. وأنا أذكر طرفا من الاخبار الواردة في هذا المعنى.","27/1/39/1",""],[2,38,"أخبرنا الحسين بن عبيدالله، عن أبي جعفر محمد بن سفيان البزوفري، عن أحمد بن إدريس قال:حدثني علي بن محمد بن قتيبة، عن الفضل بن شاذان النيشابوري، عن ابن أبي نجران، عن محمد بن منصور، عن أبيه قال: كنا عند أبي عبدالله عليه السلام جماعة نتحدث، فالتفت إلينا فقال: في أي شيء أنتم؟ أيهات أيهات! لا والله، لا يكون ما تمدون إليه أعينكم حتى تغربلوا، لا والله لا يكون ما تمدون إليه أعينكم حتى تميزوا (لا والله لا يكون ما تمدون إليه أعينكم حتى يتمحصوا) لا والله لا يكون ما تمدون إليه أعينكم إلا بعد إياس، لا والله لا يكون ما تمدون إليه أعينكم حتى يشقى من شقي ويسعد من سعد.","27/1/39/2",""],[3,38,"وروى سعد بن عبدالله الاشعري، عن محمد بن الحسين بن أبي الخطاب، عن الحسن بن علي بن فضال عن ثعلبة بن ميمون، عن مالك الجهني، عن الاصبغ بن نباتة قال: أتيت أمير المؤمنين عليه السلام فوجدته متفكرا ينكت في الارض فقلت: يا أمير المؤمنين، ما لي أراك متفكرا تنكت في الارض؟ أرغبة منك فيها؟ فقال: لا، والله. ما رغبت فيها ولا في الدنيا يوما قط، ولكن فكرت في مولود يكون من ظهر الحادي عشر من ولدي هو المهدي، الذي يملأها قسطاً وعدلاً كما ملئت ظلماً وجوراً ، تكون له حيرة وغيبة يضل فيها أقوام ويهتدي فيها آخرون.","27/1/39/3",""],[4,38,"أحمد بن إدريس، عن علي بن محمد بن قتيبة، عن الفضل بن شاذان، عن أحمد بن محمد بن أبي نصر قال: قال أبوالحسن عليه السلام: أما والله، لا يكون الذي تمدون إليه أعينكم حتى تميزوا أو تمحصوا، حتى لا يبقى منكم إلا الأندر. ثم تلا: ﴿أَمْ حَسِبْتُمْ أَنْ تُتْرَكُوا وَلَمَّا يَعْلَمِ اللهُ الَّذِينَ جَاهَدُوا مِنْكُمْ وَيَعْلَم الصَّابِرِينَ﴾.","27/1/39/4",""],[5,38,"سعد بن عبدالله، عن الحسين بن عيسى العلوي، عن أبيه، عن جده، عن علي بن جعفر، عن أخيه موسى بن جعفر عليهما السلام قال: إذا فقد الخامس من ولد السابع من الائمة فالله الله في أديانكم لا يزيلنكم عنها أحد. يا بني إنه لابد لصاحب هذا الامر من غيبة حتى يرجع عن هذا الامر من كان يقول به، إنما هي محنة من الله امتحن(الله تعالى) بها خلقه. s","27/1/39/5",""],[6,38,"وروى محمد بن جعفر الاسدي، عن أبي سعيد الادمي، عن محمد بن الحسين، عن محمد بن أبي عمير، عن أبي أيوب، عن محمد بن مسلم وأبي بصير قالا: سمعنا أبا عبدالله عليه السلام يقول: لا يكون هذا الأمر حتى يذهب ثلثا الناس. فقلنا: إذا ذهب ثلثا الناس فمن يبقى؟ فقال: أما ترضون أن تكونوا في الثلث الباقي؟","27/1/39/6",""],[7,38,"وروي عن جابر الجعفي قال: قلت لأبي جعفر عليه السلام: متى يكون فرجكم؟ فقال: هيهات هيهات! لا يكون فرجنا حتى تغربلوا ثم تغربلوا ثم تغربلوا، يقولها ثلاثا، حتى يذهب (الله تعالى) الكدر ويبقى الصفو.","27/1/39/7",""],[8,38,"وروى محمد بن عبدالله بن جعفر الحميري، عن أبيه، عن يعقوب بن يزيد، عن حماد بن عيسى، عن إبراهيم بن عمر اليماني، عن رجل، عن أبي جعفر عليه السلام أنه قال: (والله) لتمحصن يا معشر الشيعة شيعة آل محمد كمخيض الكحل في العين، لان صاحب الكحل يعلم متى يقع في العين ولا يعلم متى يذهب، فيصبح أحدكم وهو يرى أنه على شريعة من أمرنا فيمسي وقد خرج منها، ويمسي وهو على شريعة من أمرنا فيصبح وقد خرج منها.","27/1/39/8",""],[9,38,"و عنه، عن أبيه، عن أيوب بن نوح، عن العباس بن عامر، عن الربيع بن محمد المسلي قال: قال (لي) أبوعبدالله عليه السلام: والله لتكسرن كسر الزجاج، وإن الزجاج يعاد فيعود كما كان، والله لتكسرن كسر الفخار، وإن الفخار لا يعود كما كان، (والله لتميزن) والله لتمحصن والله لتغربلن كما يغربل الزؤان من القمح.","27/1/39/9",""],[10,38,"وروى جعفر بن محمد بن مالك الكوفي، عن إسحاق بن محمد، عن أبي هاشم، عن فرات بن أحنف قال: قال أمير المؤمنين عليه السلام وذكر القائم عليه السلام فقال: ليغيبن عنهم حتى يقول الجاهل ما لله في آل محمد حاجة.","27/1/39/10",""],[11,38,"عنه، عن محمد بن الحسين بن أبي الخطاب، عن محمد بن إسماعيل بن بزيع، عن عبدالله بن عبدالرحمن الاصم، عن عبدالرحمن بن سيابة، عن عمران بن ميثم، عن عباية بن ربعي الأسدي قال:سمعت أمير المؤمنين عليه السلام يقول: (كيف) أنتم إذا بقيتم بلا إمام هدى ولا علم يرى يبرأ بعضكم من بعض.","27/1/39/11",""],[12,38,"وقد روي (عن) علي بن يقطين قال :قال لي أبوالحسن عليه السلام: يا علي (إن) الشيعة تربى بالأماني منذ مائتي سنة. وقال يقطين لابنه علي: ما بالنا قيل لنا فكان وقيل لكم فلم يكن؟ فقال له علي:إن الذي قيل لكم ولنا من مخرج واحد غير أن أمركم حضركم فأعطيتم محضه، وكان كما قيل لكم، وإن أمرنا لم يحضر فعللنا بالأماني. ولو قيل (لنا) إن هذا الامر لا يكون إلى مائتي سنة أو ثلاثمائة سنة لقست القلوب ولرجعت عامة الناس عن الإسلام، ولكن قالوا:ما أسرعه وما أقربه! تألفاً لقلوب الناس وتقريبا للفرج.","27/1/39/12",""],[13,38,"وروى الشلمغاني في كتاب الأوصياء: أبوجعفر المروزي قال: خرج جعفر بن محمد بن عمر(و) وجماعة إلى العسكر ورأوا أيام أبي محمد عليه السلام في الحياة، وفيهم علي بن أحمد بن طنين، فكتب جعفر بن محمد بن عمر(و) يستأذن في الدخول إلى القبر، فقال له علي بن أحمد: لا تكتب إسمي فإني لا أستأذن، فلم يكتب إسمه، فخرج إلى جعفر: أدخل أنت ومن لم يستأذن.","27/1/39/13",""],[1,39,"وقبل ذكر من كان سفيرا حال الغيبة نذكر طرفا من أخبار من كان يختص بكل إمام، ويتولى له الامر على وجه من الايجاز، ونذكر من كان ممدوحا منهم حسن الطريقة، ومن كان مذموما سيئ المذهب ليعرف الحال في ذلك.","27/1/40/1",""],[2,39,"وقد روي في بعض الاخبار أنهم عليهم السلام قالوا: خدامنا وقوامنا شرار خلق الله.","27/1/40/2",""],[3,39,"وقد روى محمد بن عبدالله بن جعفر الحميري، عن أبيه، عن محمد بن صالح الهمداني قال: كتبت إلى صاحب الزمان عليه السلام: إن أهل بيتي يؤذوني ويقرعوني بالحديث الذي روي عن آبائك عليهم السلام أنهم قالوا: خدامنا وقوامنا شرار خلق الله. فكتب: ويحكم! أما تقرؤن ما قال الله تعالى: ﴿وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّتِي بَارَكْنَا فِيهَا قُرًى ظَاهِرَةً﴾؟ فنحن والله القرى التي بارك (الله) فيها وأنتم القرى الظاهرة.","27/1/40/3",""],[1,40,"فمن المحمودين حمران بن أعين:","27/1/41/1",""],[2,40,"أخبرنا الحسين بن عبيد الله، عن أبي جعفر محمد بن سفيان البزوفري، عن أحمد بن إدريس، عن أحمد بن محمد بن عيسى، عن الحسن بن علي بن فضال، عن عبدالله بن بكير، عن زرارة قال: قال أبوجعفر عليه السلام-وذكرنا حمران بن أعين- فقال: لا يرتد والله أبدا، ثم أطرق هنيئة، ثم قال: أجل لا يرتد والله أبدا.","27/1/41/2",""],[3,40,"ومنهم المفضل بن عمر:","27/1/41/3",""],[4,40,"بهذا الاسناد، عن أحمد بن إدريس، عن أحمد بن محمد بن عيسى، عن الحسين بن سعيد، عن محمد بن أبي عمير، عن الحسين بن أحمد المنقري، عن أسد بن أبي علاء، عن هشـام بن أحمـر قـال: دخلت على أبي عبدالله عليه السلام وأنا أريد أن أسأله عن المفضل بن المفضل بن عمر، وهو في ضيعة له في يوم شديد الحر والعرق يسيل على صدره فابتدأني فقال: نعم والله الذي لا إله إلا هو، الرجل المفضل بن عمر الجعفي، نعم والله الذي لا إله إلا هو، الرجل(هو) المفضل بن عمر الجعفي. حتى أحصيت بضعا وثلاثين مرة يكررها وقال: إنما هو والد بعد والد.","27/1/41/4",""],[5,40,"وروي عن هشام بن أحمر قال:حملت إلى أبي إبراهيم عليه السلام إلى المدينة أموالا فقال: ردها فادفعها إلى المفضل بن عمر، فرددتها إلى جعفي فحططتها على باب المفضل.","27/1/41/5",""],[6,40,"وروي عن موسى بن بكر قال: كنت في خدمة أبي الحسن عليه السلام فلم أكن أرى شيئا يصل إليه إلا من ناحية المفضل، ولربما رأيت الرجل يجئ بالشيء فلا يقبله منه ويقول: أوصله إلى المفضل.","27/1/41/6",""],[7,40,"ومنهم المعلى بن خنيس، وكان من قوام أبي عبدالله عليه السلام، وإنما قتله داود بن علي بسببه، وكان محمودا عنده، ومضى على منهاجه، وأمره مشهور.","27/1/41/7",""],[8,40,"فروي عن أبي بصير قال: لما قتل داود بن (علي) المعلى بن خنيس فصلبه، عظم ذلك على أبي عبد الله عليه السلام واشتد عليه وقال له: يا داود!على ما قتلت مولاي وقيمي في مالي وعلى عيالي؟ والله إنه لأوجه عند الله منك… في حديث طويل.","27/1/41/8",""],[9,40,"وفي خبر آخر أنه قال: أما والله لقد دخل الجنة.","27/1/41/9",""],[10,40,"ومنهم نصر بن قابوس اللخمي:","27/1/41/10",""],[11,40,"فروي أنه كان وكيلا لابي عبدالله عشرين سنة، ولم يعلم أنه وكيل، وكان خيرا فاضلا، وكان عبدالرحمن بن الحجاج وكيلا لابي عبدالله عليه السلام، ومات في عصر الرضا عليه السلام على ولايته.","27/1/41/11",""],[12,40,"ومنهم عبدالله بن جندب البجلي، وكان وكيلا لأبي إبراهيم وأبي الحسن الرضا عليه السلام، وكان عابدا رفيع المنزلة لديهما، على ما روي في الأخبار.","27/1/41/12",""],[13,40,"ومنهم ما رواه أبوطالب القمي قال: دخلت على أبي جعفر الثاني عليه السلام في آخـرعمره فسمعته يقول: جزى الله صفوان بن يحيى، ومحمد بن سنان، وزكريا بن آدم وسعد بن سعد عني خيرا، فقد وفوا لي، وكان زكريا بن آدم ممن تولاهم.","27/1/41/13",""],[14,40,"وخرج (فيه) عن أبي جعفر عليه السلام: ذكرت ما جرى من قضاء الله في الرجل المتوفى رحمه الله تعالى يوم ولد ويوم يموت ويوم يبعث حيا، فقد عاش أيام حياته عارفا بالحق قائلا به، صابرا محتسبا (للحق)، قائما بما يجب لله ولرسوله عليه، ومضى رحمه الله غير ناكث ولا مبدل، فجزاه الله أجر نيته وأعطاه جزاء سعيه.","27/1/41/14",""],[15,40,"وأما محمد بن سنان فإنه روي عن علي بن الحسين بن داود قال: سمعت أبا جعفر الثاني عليه السلام يذكر محمد بن سنان بخير ويقول: رضي الله عنه برضائي عنه فما خالفني وما خالف أبي قط.","27/1/41/15",""],[16,40,"ومنهم عبدالعزيز بن المهتدي القمي الأشعري:","27/1/41/16",""],[17,40,"خرج فيه عن أبي جعفر عليه السلام: قبضت والحمد لله وقد عرفت الوجوه التي صارت إليك منها غفر الله لك ولهم الذنوب ورحمنا وإياكم.","27/1/41/17",""],[18,40,"وخرج فيه: غفر الله لك ذنبك ورحمنا وإياك ورضي عنك برضائي عنك.","27/1/41/18",""],[19,40,"ومنهم علي بن مهزيار الاهوازي وكان محمودا:","27/1/41/19",""],[20,40,"أخبرني جماعة، عن التلعكبري، عن أحمد بن علي الرازي، عن الحسين بن علي، عن أبي الحسن البلخي، عن أحمد بن مابندار الاسكافي، عن العلاء النداري، عن الحسن بن شمون قال: قرأت هذه الرسالة على علي بن مهزيار عن أبي جعفر الثاني بخطه: بسـم الله الرحمـن الرحيـم. يـا علي، أحسـن الله جـزاك، وأسكنك جنته، ومنعك مـن الخـزي في الدنيـا والآخـرة، وحشـرك الله معنـا. يـا علي، قد بلوتك وخبرتك في النصيحة والطاعة والخدمة، والتوقير والقيام بما يجب عليك، فلو قلت إني لم أر مثلك لرجوت أن أكون صادقا، فجزاك الله جنات الفردوس نزلا، فما خفي علي مقامك ولا خدمتك في الحر والبرد، في الليل والنهار، فأسأل الله إذا جمع الخلائق للقيامة أن يحبوك برحمة تغتبط بها، إنه سميع الدعاء.","27/1/41/20",""],[21,40,"ومنهم أيوب بن نوح بن دراج:","27/1/41/21",""],[22,40,"ذكر عمرو بن سعيد المدائني-وكان فطحيا- قال: كنت عند أبي الحسن العسكري عليه السلام بصري إذ دخل أيوب بن نوح ووقف قدامه فأمره بشيء، ثم انصرف، والتفت إلي أبوالحسن عليه السلام وقال: يا عمرو إن أحببت أن تنظر إلى رجل من أهل الجنة فانظر إلى هذا.","27/1/41/22",""],[23,40,"ومنهم علي بن جعفر الهماني، وكان فاضلا مرضيا من وكلاء أبي الحسن وأبي محمد عليهما السلام.","27/1/41/23",""],[24,40,"روى أحمد بن علي الرازي، عن علي بن مخلد الايادي قال: حدثني أبوجعفر العمري رضي الله عنه قال: حج أبو طاهر بن بلال فنظر إلى علي بن جعفر وهو ينفق النفقات العظيمة، فلما انصرف كتب بذلك إلى أبي محمد عليه السلام فوقع في رقعته: قد كنا أمرنا له بمائة ألف دينار، ثم أمرنا له بمثلها فأبى قبوله إبقاء علينا، ما للناس والدخول في أمرنا فيما لم ندخلهم فيه؟ قال: ودخل على أبي الحسن العسكري عليه السلام فأمر له بثلاثين ألف دينار.","27/1/41/24",""],[25,40,"ومنهم أبوعلي بن راشد:","27/1/41/25",""],[26,40,"أخبرني ابن أبي جيد، عن محمد بن الحسن بن الوليد، عن الصفار، عن محمد بن عيسى قال: كتب أبوالحسن العسكري عليه السلام إلى الموالي ببغداد والمدائن والسواد وما يليها: قد أقمت أبا علي بن راشد مقام علي بن الحسين بن عبد ربه ومن قبله من وكلائي، وقد أوجبت في طاعته طاعتي، وفي عصيانه الخروج إلى عصياني، وكتبت بخطي.","27/1/41/26",""],[27,40,"وروى محمد بن يعقوب رفعه إلى محمد بن فرج قال: كتبت إليه أسأله عن أبي علي بن راشد وعن عيسى بن جعفر (بن عاصم) وعن ابن بند، وكتب إلي: ذكرت ابن راشد رحمه الله فإنه عاش سعيدا ومات شهيدا، ودعا لابن بند والعاصمي وابن بند ضرب بعمود وقتل، وابن عاصم ضرب بالسياط على الجسر ثلاثمائة سوط ورمي به في الدجلة.","27/1/41/27",""],[28,40,"فهؤلاء جماعة المحمودين، وتركنا ذكر استقصائهم لأنهم معروفون مذكورون في الكتب.","27/1/41/28",""],[1,41,"فروى علي بن إبراهيم بن هاشم، عن أبيه قال: كنت عند أبي جعفر الثاني عليه السلام إذ دخل عليه صالح بن محمد بن سهل الهمداني- وكان يتولى له- فقال له: جعلت فداك اجعلني من عشرة آلاف درهم في حل فإني أنفقتها، فقال له أبوجعفر: أنت في حل. فلما خرج صالح من عنده قال أبو جعفر عليه السلام: أحدهم يثب على (أموال حق) آل محمد وفقرائهم ومساكينهم وأبناء سبيلهم، فيأخذه ثم يقول: إجعلني في حل، أتراه ظن (بي) أني أقول له لا أفعل؟ والله ليسألنهم الله يوم القيامة عن ذلك سؤالا حثيثا.","27/1/42/1",""],[2,41,"ومنهم علي بن أبي حمزة البطائني وزياد بن مروان القندي وعثمان بن عيسى الرواسي، كلهم كانوا وكلاء لابي الحسن موسى عليه السلام، وكان عندهم أموال جزيلة، فلما مضى أبوالحسن موسى عليه السلام وقفوا طمعا في الاموال، ودفعوا إمامة الرضا عليه السلام وجحدوه. وقد ذكرنا ذلك فيما مضى فلا نطول بإعادته.","27/1/42/2",""],[3,41,"ومنهم فارس بن حاتم بن ماهويه القزويني:","27/1/42/3",""],[4,41,"على ما رواه عبدالله بن جعفر الحميري قال:كتب أبوالحسن العسكري عليه السلام إلى علي بن عمرو القزويني بخطه: إعتقد فيما تدين الله تعالى به أن الباطن عندي حسب ما أظهرت لك فيمن استنبأت عنه، وهو فارس لعنه الله فإنه ليس يسعك إلا الاجتهاد في لعنه، وقصده ومعاداته، والمبالغة في ذلك بأكثر ما تجد السبيل إليه. ما كنت آمر أن يدان الله بأمر غير صحيح، فجد وشد في لعنه وهتكه، وقطع أسبابه، وصد أصحابنا عنه، وإبطال أمره وأبلغهم ذلك مني، واحكه لهم عني، وإني سائلكم بين يدي الله عن هذا الامر المؤكد، فويل للعاصي وللجاحد. وكتبت بخطي ليلة الثلاثاء لتسع ليال من شهر ربيع الاول سنة خمسين ومائتين، وأنا أتوكل على الله وأحمده كثيرا.","27/1/42/4",""],[5,41,"ومنهم أحمد بن هلال العبرتائي:","27/1/42/5",""],[6,41,"روى محمد بن يعقوب قال:خرج إلى العمري في توقيع طويل إختصرناه: ونحن نبرأ إلى الله تعالى من ابن هلال لا رحمه الله، وممن لا يبرأ منه، فأعلم الاسحاقي وأهل بلده مما أعلمناك من حال هذا الفاجر، وجميع ما كان سألك ويسألك عنه.","27/1/42/6",""],[7,41,"ومنهم أبو طاهر محمد بن علي بن بلال وغيرهم مما لا نطول بذكرهم، لأن ذلك مشهور موجود في الكتب.","27/1/42/7",""],[1,42,"فأولهم: من نصبه أبوالحسن علي بن محمد العسكري وأبومحمد الحسن بن علي بن محمد إبنه عليهم السلام، وهو الشيخ الموثوق به أبوعمرو عثمان بن سعيد العمري رحمه الله وكان أسديا وإنما سمي العمري:","27/1/43/1",""],[2,42,"لما رواه أبونصر هبة الله بن محمد بن أحمد الكاتب ابن بنت أبي جعفر العمري رحمه الله، قال أبو نصر: كان أسديا فنسب إلى جده فقيل العمري، وقد قال قوم من الشيعة:إن أبا محمد الحسن بن علي عليه السلام (قال: لا يجمع على امرئ بين عثمان وأبو عمرو) وأمر بكسر كنيته، فقيل العمري، ويقال له: العسكري أيضا، لأنه كان من عسكر سر من رأى، ويقال له: السمان، لانه كان يتجر في السمن تغطية على الامر.","27/1/43/2",""],[3,42,"وكان الشيعة إذا حملوا إلى أبي محمد عليه السلام ما يجب عليهم حمله من الأموال أنفذوا إلى أبي عمرو، فيجعله في جراب السمن وزقاقه ويحمله إلى أبي محمد عليه السلام تقية وخوف.","27/1/43/3",""],[4,42,"فأخبرني جماعة، عن أبي محمد هارون بن موسى، عن أبي علي محمد بن همام الاسكافي، قال: حدثنا عبد الله بن جعفر الحميري، قال: حدثنا أحمد بن إسحاق بن سعد القمي قال: دخلت على أبي الحسن علي بن محمد صلوات الله عليه في يوم من الايام فقلت: يا سيدي أنا أغيب وأشهد ولا يتهيأ لي الوصول إليك إذا شهدت في كل وقت، فقول من نقبل؟ وأمر من نمتثل؟ فقال لي صلوات الله عليه: هذا أبو عمرو الثقة الامين ما قاله لكم فعني يقوله، وما أداه إليكم فعني يؤديه. فلما مضى أبوالحسن عليه السلام وصلت إلى أبي محمد إبنه الحسن العسكري عليه السلام ذات يوم فقلت له عليه السلام مثل قولي لابيه، فقال لي: هذا أبوعمرو الثقة الامين ثقة الماضى وثقتي في المحي والممات، فما قاله لكم فعني يقوله، وما أدى إليكم فعني يؤديه. قال أبومحمد هارون: قال أبوعلي: قال أبوالعباس الحميري: فكنا كثيرا ما نتذاكر هذا القول ونتواصف جلالة محل أبي عمرو.","27/1/43/4",""],[5,42,"وأخبرنا جماعة، عن أبي محمد هارون، عن محمد بن همام، عن عبد الله بن جعفر قال: حججنا في بعض السنين بعد مضي أبي محمد عليه السلام فدخلت على أحمد بن إسحاق بمدينة السلام فرأيت أبا عمرو عنده، فقلت: إن هذا الشيخ- وأشرت إلى أحمد بن إسحاق-وهو عندنا الثقة المرضي، حدثنا فيك بكيت وكيت، واقتصصت عليه ما تقدم يعني ما ذكرناه عنه من فضل أبي عمرو ومحله، وقلت: أنت الآن ممن لا يشك في قوله وصدقه فأسألك بحق الله وبحق الامامين اللذين وثقاك هل رأيت ابن أبي محمد الذي هو صاحب الزمان عليه السلام؟ فبكى، ثم قال:على أن لا تخبر بذلك أحدا وأنا حي؟قلت: نعم. قال: قد رأيته عليه السلام وعنقه هكذا- يريد أنها أغلظ الرقاب حسنا وتماما–. قلت: فالاسم؟ قال: نهيتم عن هذا.","27/1/43/5",""],[6,42,"وروى أحمد بن علي بن نوح أبوالعباس السيرافي، قال:أخبرنا أبو نصر هبة الله بن محمد بن أحمد المعروف بابن برينة الكاتب، قال: حدثني بعض الشراف من الشيعة الامامية أصحاب الحديث، قال: حدثني أبومحمد العباس بن أحمد الصائغ قال: حدثني الحسين بن أحمد الخصيبي قال: حدثني محمد بن إسماعيل وعلي بن عبد الله الحسنيان قالا: دخلنا على أبي محمد الحسن عليه السلام بسر من رأى وبين يديه جماعة من أوليائه وشيعته، حتى دخل عليه بدر خادمه فقال: يا مولاي، بالباب قوم شعث غبر. فقال لهم: هؤلاء نفر من شيعتنا باليمن… في حديث طويل يسوقانه إلى أن ينتهي إلى أن قال الحسن عليه السلام لبدر: فامض فائتنا بعثمان بن سعيد العمري. فما لبثنا إلا يسيرا حتى دخل عثمان، فقال له سيدنا أبومحمد عليه السلام: امض يا عثمان، فإنك الوكيل والثقة المأمون على مال الله، واقبض من هؤلاء النفر اليمنيين ما حملوه من المال.","27/1/43/6",""],[7,42,"ثم ساق الحديث إلى أن قالا: ثم قلنا بأجمعنا:يا سيدنا! والله إن عثمان لمن خيار شيعتك، ولقد زدتنا علما بموضعه من خدمتك، وأنه وكيلك وثقتك على مال الله تعالى. قال: نعم واشهدوا على أن عثمان بن سعيد العمري وكيلي وأن ابنه محمدا وكيل ابني مهديكم.","27/1/43/7",""],[8,42,"عنه، عن أبي نصر هبة الله (بن محمد) بن أحمد الكاتب ابن بنت أبي جعفر العمري قدس الله روحه وأرضاه، عن شيوخه أنه لما مات الحسن بن علي عليهما السلام حضر غسله عثمان بن سعيد رضي الله عنه وأرضاه وتولى جميع أمره في تكفينه وتحنيطه وتقبيره، مأمورا بذلك للظاهر من الحال التي لا يمكن جحدها ولا دفعها إلا بدفع حقائق الاشياء في ظواهرها.","27/1/43/8",""],[9,42,"وكانت توقيعات صاحب الامر عليه السلام تخرج على يدي عثمان بن سعيد وابنه أبي جعفر محمد بن عثمان إلى شيعته وخواص أبيه أبي محمد عليه السلام بالامر والنهي والاجوبة عما يسأل الشيعة عنه إذا احتاجت إلى السؤال فيه بالخط الذي كان يخرج في حياة الحسن عليه السلام، فلم تزل الشيعة مقيمة على عدالتهما إلى أن توفي عثمان بن سعيد رحمه الله ورضي عنه وغسله ابنه أبوجعفر وتولى القيام به وحصل الامر كله مردودا إليه، والشيعة مجتمعة على عدالته وثقته وأمانته، لما تقدم له من النص عليه بالامانة والعدالة والامر بالرجوع إليه في حياة الحسن عليه السلام وبعد موته في حياة أبيه عثمان رحمة الله عليه.","27/1/43/9",""],[10,42,"قال: وقال جعفر بن محمد بن مالك الفزاري البزاز، عن جماعة من الشيعة منهم علي بن بلال وأحمد بن هلال ومحمد بن معاوية بن حكيـم والحسـن بن أيوب بن نوح في خبـر طويل مشهور قالوا جميعا: إجتمعنا إلى أبي محمد الحسن بن علي عليهما السلام نسأله عن الحجة من بعده، وفي مجلسه عليه السلام أربعون رجلا، فقام إليه عثمان بن سعيد بن عمرو العمري فقال له: يا بن رسول الله أريد أن أسألك عن أمر أنت أعلم به مني. فقال له: إجلس يا عثمان. فقام مغضبا ليخرج فقال: لا يخرجن أحد. فلم يخرج منا أحد إلى (أن) كان بعد ساعة، فصاح عليه السلام بعثمان، فقام على قدميه فقال:أخبركم بما جئتم؟ قالوا: نعم يا بن رسول الله. قال: جئتم تسألوني عن الحجة من بعدي. قالوا: نعم. فإذا غلام كأنه قطع قمر أشبه الناس بأبي محمد عليه السلام فقال: هذا إمامكم من بعدي وخليفتي عليكم أطيعوه ولا تتفرقوا من بعدي فتهلكوا في أديانكم، ألا وإنكم لا ترونه من بعد يومكم هذا حتى يتم له عمر، فاقبلوا من عثمان ما يقوله، وانتهوا إلى أمره، واقبلوا قوله، فهو خليفة إمامكم والأمر إليه… في حديث طويل.","27/1/43/10",""],[11,42,"قال أبونصر هبة الله بن محمد: وقبر عثمان بن سعيد بالجانب الغربي من مدينة السلام، في شارع الميدان، في أول الموضع المعروف (في الدرب المعروف) بدرب جبلة في مسجد الدرب يمنة الداخل إليه، والقبر في نفس قبلة المسجد رحمه الله.","27/1/43/11",""],[12,42,"قال محمد بن الحسن مصنف هذا الكتاب: رأيت قبره في الموضع الذي ذكره وكان بني في وجهه حائط وبه محراب المسجد، وإلى جنبه باب يدخل إلى موضع القبر في بيت ضيق مظلم، فكنا ندخل إليه ونزوره مشاهرة، وكذلك من وقت دخولي إلى بغداد، وهي سنة ثمان وأربعمائة إلى سنة نيف وثلاثين وربعمائة. ثم نقض ذلك الحائط الرئيس أبو منصور محمد بن الفرج وأبرز القبر إلى برا وعمل عليه صندوقا وهو تحت سقف يدخل إليه من أراده ويزوره، ويتبرك جيران المحلة بزيارته ويقولون هو رجل صالح، وربما قالوا:هو ابن داية الحسين عليه السلام ولا يعرفون حقيقة الحال فيه، وهو إلى يومنا هذا-وذلك سنة سبع وأربعين وأربعمائة- على ما هو عليه.","27/1/43/12",""],[13,42,"فلما مضى أبوعمرو عثمان بن سعيد قام ابنه أبوجعفر محمد بن عثمان مقامه بنص أبي محمد عليه السلام عليه ونص أبيه عثمان عليه بأمر القائم عليه السلام.","27/1/43/13",""],[14,42,"فأخبرني جماعة عن أبي الحسن محمد بن أحمد بن داود القمي وابن قولويه (عن أبيه) عن سعد بن عبد الله، قال: حدثنا الشيخ الصدوق أحمد بن إسحاق بن سعد الأشعري رحمه الله، وذكر الحديث الذي قدمنا ذكره.","27/1/43/14",""],[15,42,"وأخبرنا جماعة، عن أبي القاسم جعفر بن محمد بن قولويه، وأبي غالب الزراري وأبي محمد التلعكبري، كلهم عن محمد بن يعقوب الكليني رحمه الله تعالى، عن محمد بن عبد الله ومحمد بن يحيى، عن عبد الله بن جعفر الحميري قال: إجتمعت أنا والشيخ أبوعمرو عند أحمد بن إسحاق بن سعد الاشعري القمي، فغمزني أحمد (بن إسحاق) أن أسأله عن الخلف. فقلت له: يا با عمرو إني أريد (أن) أسألك وما أنا بشاك فيما أريد أن أسألك عنه، فإن اعتقادي وديني أن الارض لا تخلو من حجة إلا إذا كان قبل (يوم) القيامة بأربعين يوما، فإذا كان ذلك وقعت الحجة وغلق باب التوبة فلم يكن ﴿يَنْفَعُ نَفْساً إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْراً﴾ فأولئك أشرار من خلق الله عز وجل، وهم الذين تقوم عليهم القيامة ولكن أحببت أن أزداد يقينا، فإن إبراهيم عليه السلام سأل ربه أن يريه كيف يحيي الموتى فـ ﴿قَالَ:أَوَلَمْ تُؤْمِنْ؟ قَالَ: بَلَى، وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي﴾ وقد أخبرنا أحمد بن إسحاق أبوعلي عن أبي الحسن عليه السلام قال: سألته فقلت له:لمن أعامل وعمن آخذ وقول من أقبل؟ فقال له: العمري ثقتي فما أدى إليك فعني يؤدي، وما قال لك فعني يقول فاسمع له وأطع، فإنه الثقة المأمون. قال: وأخبرني أبوعلي أنه سأل أبا محمد الحسن بن علي عن مثل ذلك فقال له: العمري وابنه ثقتان، فما أديا إليك فعني يؤديان، وما قالا لك فعني يقولان، فاسمع لهما وأطعهما فإنهما الثقتان المأمونان. فهذا قول إمامين قد مضيا فيك. قال: فخر أبوعمرو ساجدا وبكى، ثم قال:سل. فقلت له:أنت رأيت الخلف من أبي محمد عليه السلام؟ فقال: أي والله،ورقبته مثل ذا. وأومأ بيديه، فقلت له: فبقيت واحدة. فقال لي: هـات. قـلت: فالاسـم. قـال:محرم عليكم أن تسألوا عن ذلك، ولا أقول هذا من عندي وليس لي أن أحلل وأحرم ولكن عنه عليه السلام، فإن الامر عند السلطان أن أبا محمد عليه السلام مضى ولم يخلف ولدا وقسم ميراثه، وأخذه من لا حق له، وصبر على ذلك، وهو ذا عياله يجولون وليس أحد يجسر أن يتعرف إليهم أو ينيلهم شيئا، وإذا وقع الاسم وقع الطلب، فاتقوا الله وأمسكوا عن ذلك.","27/1/43/15",""],[16,42,"قال الكليني: وحدثني شيخ من أصحابنا ذهب عني اسمه أن أبا عمرو سئل عن أحمد بن إسحاق عن مثل هذا، فأجاب بمثل هذا، وقد قدمنا هذه الرواية فيما مضى من الكتاب.","27/1/43/16",""],[17,42,"وأخبرنا جماعة، عن محمد بن علي بن الحسين بن موسى بن بابويه، عن أحمد بن هارون الفامي قال: حدثنا محمد بن عبد الله بن جعفر الحميري، عن أبيه عبد الله بن جعفر الحميري قال: خرج التوقيع إلى الشيخ أبي جعفر محمد بن عثمان بن سعيد العمري قدس الله روحه في التعزية بأبيه رضي الله تعالى عنه. وفي فصل من الكتاب: إنا لله وإنا إليه راجعون تسليما لامره ورضي بقضائه، عاش أبوك سعيدا ومات حميدا فرحمه الله وألحقه بأوليائه ومواليه عليهم السلام، فلم يزل مجتهدا في أمرهم، ساعيا فيما يقربه إلى الله عز وجل وإليهم، نضر الله وجهه، وأقاله عثرته. وفي فصل آخر: أجزل الله لك الثواب وأحسن لك العزاء، رزئت ورزئنا وأوحشك فراقه وأوحشنا، فسره الله في منقلبه، (و) كان من كمال سعادته أن رزقه الله تعالى ولدا مثلك يخلفه من بعده، ويقوم مقامه بأمره، ويترحم عليه، وأقول الحمد لله، فإن الانفس طيبة بمكانك، وما جعله الله عز وجل فيك وعندك، أعانك الله وقواك وعضدك ووفقك، وكان لك وليا وحافظا وراعيا وكافيا.","27/1/43/17",""],[18,42,"وأخبرني جماعة، عن هارون بن موسى، عن محمد بن همام قال: قال لي عبد الله بن جعفر الحميري: لما مضى أبوعمرو رضي الله تعالى عنه أتتنا الكتب بالخط الذي كنا نكاتب به بإقامة أبي جعفر رضي الله عنه مقامه.","27/1/43/18",""],[19,42,"وبهذا الاسناد عن محمد بن همام، قال: حدثني محمد بن حمويه بن عبدالعزيز الرازي في سنة ثمانين ومائتين قال: حدثنا محمد بن إبراهيم بن مهزيار الاهوازي أنه خرج إليه بعد وفـاة أبي عمرو: والابن- وقاه الله- لم يزل ثقتنا في حياة الأب رضي الله عنه وأرضاه ونضر وجهه، يجري عندنا مجراه، ويسد مسده، وعن أمرنا يأمر الابن وبه يعمل، تولاه الله، فانته إلى قوله وعرف معاملتنا ذلك.","27/1/43/19",""],[20,42,"وأخبرنا جماعة، عن أبي القاسم جعفر بن محمد بن قولويه وأبي غالب الزراري وأبي محمد التلعكبري كلهم، عن محمد بن يعقوب، عن إسحاق بن يعقوب قال:سألت محمد بن عثمان العمري رحمه الله أن يوصل لي كتابا قد سئلت فيه عن مسائل أشكلت علي. فوقع التوقيع بخط مولانا صاحب الدار عليه السلام:- وذكرنا الخبر فيما تقدم–وأما محمد بن عثمان العمري فرضي الله تعالى عنه وعن أبيه من قبل فإنه ثقتي وكتابه كتابي.","27/1/43/20",""],[21,42,"قال أبوالعباس: وأخبرني هبة الله بن محمد ابن بنت أم كلثوم بنت أبي جعفر العمري رضي الله عنه عن شيوخه قالوا: لم تزل الشيعة مقيمة على عدالة عثمان بن سعيد (ومحمد بن عثمان رحمها الله تعالى إلى أن توفي أبوعمرو عثمان ابن سعيد) رحمه الله تعالى وغسله ابنه أبوجعفر محمد بن عثمان، وتولى القيام به، وجعل الامر كله مردودا إليه، والشيعة مجتمعة على عدالته وثقته وأمانته لما تقدم له من النص عليه بالامانة والعدالة، والامر بالرجوع إليه في حياة الحسن عليه السلام وبعد موته في حياة أبيه عثمان بن سعيد، لا يختلف في عدالته، ولا يرتاب بأمانته، والتوقيعات تخرج على يده إلى الشيعة في المهمات طول حياته بالخط الذي كانت تخرج في حياة أبيه عثمان، لا يعرف الشيعة في هذا الامر غيره ولا يرجع إلى أحد سواه.","27/1/43/21",""],[22,42,"وقد نقلت عنه دلائل كثيرة، ومعجزات الامام ظهرت على يده، وأمور أخبرهم بها عنه زادتهم في هذا الامر بصيرة، وهي مشهورة عند الشيعة، وقد قدمنا طرفا منها فلا نطول بإعادتها، فإن في ذلك كفاية للمنصف إن شاء الله تعالى.","27/1/43/22",""],[23,42,"قال ابن نوح: أخبرني أبونصر هبة الله ابن بنت أم كلثوم بنت أبي جعفر العمري قال: كان لأبي جعفر محمد بن عثمان العمري كتب مصنفة في الفقه مما سمعها من أبي محمد الحسن عليه السلام، ومن الصاحب عليه السلام، ومن أبيه عثمان بن سعيد، عن أبي محمد وعن أبيه علي بن محمد عليهما السلام فيها كتب ترجمتها كتب الأشربة. ذكرت الكبيرة أم كلثوم بنت أبي جعفر رضي الله عنها أنها وصلت إلى أبي القاسم الحسين بن روح رضي الله عنه عند الوصية إليه، وكانت في يده. قال أبونصر:وأظنها قالت وصلت بعد ذلك إلى أبي الحسن السمري رضي الله عنه وأرضاه.","27/1/43/23",""],[24,42,"قال أبوجعفر بن بابويه روي(عن) محمد بن عثمان العمري قدس سره أنه قال: والله إن صاحب هذا الامر ليحضر الموسم كل سنة يرى الناس ويعرفهم ويرونه ولا يعرفونه.","27/1/43/24",""],[25,42,"وأخبرني جماعة، عن محمد بن علي بن الحسين قال:أخبرنا أبي ومحمد بن الحسن ومحمد بن موسى بن المتوكل، عن عبد الله بن جعفر الحميري أنه قال: سألت محمد بن عثمان رضي الله عنه فقلت له:رأيت صاحب هذا الامر؟ قال: نعم، وآخر عهدي به عند بيت الله الحرام وهو عليه السلام يقول: اللهم أنجز لي ما وعدتني. قال محمد بن عثمان رضي الله عنه: ورأيته صلوات الله عليه متعلقا بأستار الكعبة في المستجار وهو يقول: اللهم انتقم لي من أعدائك.","27/1/43/25",""],[26,42,"وبهذا الاسناد، عن محمد بن علي، عن أبيه، قال: حدثنا علي بن سليمان الزراري، عن علي بن صدقة القمي رحمه الله قال: خرج إلى محمد بن عثمان العمري رضي الله عنه ابتداء من غير مسألة ليخبر الذين يسألون عن الاسم: إما السكوت والجنة، وإما الكلام والنار، فإنهم إن وقفوا على الاسم أذاعوه، وإن وقفوا على المكان دلوا عليه.","27/1/43/26",""],[27,42,"قال ابن نوح: أخبرني أبونصر هبة الله بن محمد، قال: حدثني (أبو) علي بن أبي جيد القمي رحمه الله قال:حدثنا أبوالحسن علي بن أحمد الدلال القمي قال:دخلت على أبي جعفر محمد بن عثمان رضي الله عنه يوما لاسلم عليه، فوجدته وبين يديه ساجة ونقاش ينقش عليها ويكتب آيا من القرآن وأسماء الائمة عليهم السلم على حواشيها. فقلت له: يا سيدي ما هذه الساجة؟ فقال لي: هذه لقبري تكون فيه، أو ضع عليها،أو قال: أسند إليها،وقد عرفت منه، وأنا في كل يوم أنزل فيه فأقرأ جزء‌ا من القرآن(فيه) فاصعد، وأظنه قال: فأخذ بيدي وأرانيه، فإذا كان يوم كذا وكذا من شهر كذا وكذا من سنة كذا وكذا صرت إلى الله عز وجل ودفنت فيه وهذه الساجة (معي). فلما خرجت من عنده أثبت ما ذكره ولم أزل مترقبا به ذلك فما تأخر الامر حتى اعتل أبوجعفر، فمات في اليوم الذي ذكره من الشهر الذي قاله من السنة التي ذكرها، ودفن فيه. قال أبونصر هبة الله: وقد سمعت هذا الحديث من غير (أبي) علي وحدثتني به أيضا أم كلثوم بنت أبي جعفر رضي الله تعالى عنهما.","27/1/43/27",""],[28,42,"وأخبرني جماعة، عن أبي جعفر محمد بن علي بن الحسين رضي الله عنه قال:حدثني محمد بن علي بن الاسود القمي أن أبا جعفر العمري قدس سره حفر لنفسه قبرا وسواه بالساج، فسألته عن ذلك فقال: للناس أسباب. و سألته عن ذلك، فقال:قد أمرت أن أجمع أمري. فمات بعد ذلك بشهرين رضي الله عنه وأرضاه.","27/1/43/28",""],[29,42,"وقال أبو نصر هبة الله: وجدت بخط أبي غالب الزراري رحمه الله وغفر له أن أبا جعفر محمد بن عثمان العمري رحمه الله مات في آخر جمادي الأولى سنة خمس وثلاثمائة. وذكر أبونصر هبة الله (بن) محمد بن أحمد أن أبا جعفر العمري رحمه الله مات في سنة أربع وثلاثمائة، وأنه كان يتولى هذا الأمر نحوا من خمسين سنة يحمل الناس إليه أموالهم، ويخرج إليهم التوقيعات بالخط الذي كان كان يخرج في حياة الحسن عليه السلام إليهم بالمهمات في أمر الدين والدنيا وفيما يسألونه من المسائل بالاجوبة العجيبة رضي الله عنه وأرضاه. قال أبونصرهبة الله: إن قبر أبي جعفر محمد بن عثمان عند والدته في شارع باب الكوفة في الموضع الذي كانت دوره ومنازله (فيه) وهو الآن في وسط الصحراء قدس سره.","27/1/43/29",""],[30,42,"أخبرني الحسين بن إبراهيم القمي قال:أخبرني أبو العباس أحمد بن علي بن نوح قال: أخبرني أبوعلي أحمد بن جعفر بن سفيان البزوفري رحمه الله قال: حدثني أبوعبد الله جعفر بن محمد المدائني المعروف بابن قزدا في مقابر قريش قال: كان من رسمي إذا حملت المال الذي في يدي إلى الشيخ أبي جعفر محمد بن عثمان العمري قدس سره أن أقول له: ما لم يكن أحد يستقبله بمثله: هذا المال ومبلغه كذا وكذا للإمام عليه السلام، فيقول لي:نعم دعه فأراجعه، فأقول له:تقول لي: إنه للامام؟ فيقول: نعم للإمام عليه السلام فيقبضه. فصرت إليه آخر عهدي به قدس سره ومعي أربعمائة دينار، فقلت له على رسمي، فقال لي: امض بها إلى الحسين بن روح، فتوقفت فقلت: تقبضها أنت مني على الرسم؟ فرد علي كالمنكر لقولي وقال: قم عافاك الله فادفعها إلى الحسين بن روح. فلمـا رأيت في وجـهه غضبا خرجت وركبت دابتي فلما بلغت بعض الطريق رجعت كالشاك فدققت الباب فخرج إلي الخادم فقال من هذا فقلت أنا فلان فاستأذن لي فراجعني وهو منكر لقولي ورجوعي فقلت له ادخل فاستأذن لي فإنه لا بد من لقائه فدخل فعرفه خبر رجوعي وكان قد دخل إلى دار النساء فخرج وجلس على سرير ورجلاه في الأرض وفيهما نعلان يصف حسنهما وحسن رجليه.فقال لي ما الذي جرأك على الرجوع ولم لم تمتثل ما قلته لك فقلت لم أجسر على ما رسمته لي فقال لي وهو مغضب قم عافاك الله فقد أقمت أبا القاسم حسين بن روح مقامي ونصبته منصبي فقلت بأمر الإمام فقال قم عافاك الله كما أقول لك فلم يكن عندي غير المبادرة. فصرت إلى أبي القاسم بن روح وهو في دار ضيقة فعرفته ما جرى فسر به وشكر الله عز وجل ودفعت إليه الدنانير وما زلت أحمل إليه ما يحصل في يدي بعد ذلك من الدنانير.","27/1/43/30",""],[31,42,"قال وسمعت أبا الحسن علي بن بلال بن معاوية المهلبي يقول في حياة جعفر بن محمد بن قولويه سمعت أبا القاسم جعفر بن محمد بن قولويه القمي يقول:سمعت جعفر بن أحمد بن متيل القمي يقول: كان محمد بن عثمان أبو جعفر العمري رضي الله عنه له من يتصرف له ببغداد نحو من عشرة أنفس، وأبو القاسم بن روح رضي الله عنه فيهم،وكلهم كانوا أخص به من أبي القاسم بن روح حتى أنه كان إذا احتاج إلى حاجة أو إلى سبب ينجزه على يد غيره لما لم يكن له تلك الخصوصية فلما كان وقت مضي أبي جعفر رضي الله عنه وقع الاختيار عليه وكانت الوصية إليه.","27/1/43/31",""],[32,42,"قال: وقال مشايخنا: كنا لا نشك أنه إن كانت كائنة من أمر أبي جعفر لا يقوم مقامه إلا جعفر بن أحمد بن متيل أو أبوه لما رأينا من الخصوصية به وكثرة كينونته في منزله حتى بلغ أنه كان في آخر عمره لا يأكل طعاما إلا ما أصلح في منزل جعفر بن أحمد بن متيل وأبيه بسبب وقع له وكان طعامه الذي يأكله في منزل جعفر وأبيه. وكان أصحابنا لا يشكون إن كانت حادثة لم تكن الوصية إلا إليه من الخصوصية به فلما كان عند ذلك ووقع الاختيار على أبي القاسم سلموا ولم ينكروا وكانوا معه وبين يديه كما كانوا مع أبي جعفر رضي الله عنه ولم يزل جعفر بن أحمد بن متيل في جملة أبي القاسم رضي الله عنه وبين يديه كتصرفه بين يدي أبي جعفر العمري إلى أن مات رضي الله عنه فكل من طعن على أبي القاسم فقد طعن على أبي جعفر وطعن على الحجة صلوات الله عليه.","27/1/43/32",""],[33,42,"وأخبرنا جماعة عن أبي جعفر محمد بن علي بن الحسين بن بابويه قال: حدثنا أبو جعفر محمد بن علي الأسود رحمه الله قال: كنت أحمل الأموال التي تحصل في باب الوقف إلى أبي جعفر محمد بن عثمان العمري رحمه الله فيقبضها مني، فحملت إليه يوما شيئا من الأموال في آخر أيامه قبل موته بسنتين أو ثلاث سنين، فأمرني بتسليمه إلى أبي القاسم الروحي رضي الله عنه، فكنت أطالبه بالقبوض فشكا ذلك إلى أبي جعفر رضي الله عنه فأمرني أن لا أطالبه بالقبوض وقال: كل ما وصل إلى أبي القاسم فقد وصل إلي. فكنت أحمل بعد ذلك الأموال إليه ولا أطالبه بالقبوض.","27/1/43/33",""],[34,42,"وبهذا الإسناد عن محمد بن علي بن الحسين قال: أخبرنا علي بن محمد بن متيل عن عمه جعفر بن أحمد بن متيل قال: لما حضرت أبا جعفر محمد بن عثمان العمري رضي الله عنه الوفاة كنت جالسا عند رأسه أسأله وأحدثه وأبو القاسم بن روح عند رجليه. فالتفت إلي ثم قال: أمرت أن أوصي إلى أبي القاسم الحسين بن روح.قال: فقمت من عند رأسه وأخذت بيد أبي القاسم وأجلسته في مكاني وتحولت إلى عند رجليه.","27/1/43/34",""],[35,42,"وقال ابن نوح: وحدثني أبو عبد الله الحسين بن علي بن بابويه القمي قدم علينا البصرة في شهر ربيع الأول سنة ثمان وسبعين وثلاثمائة قال: سمعت علوية الصفار والحسين بن أحمد بن إدريس رضي الله عنهما يذكران هذا الحديث وذكرا أنهما حضرا بغداد في ذلك الوقت وشاهدا ذلك.","27/1/43/35",""],[36,42,"وأخبرنا جماعة عن أبي محمد هارون بن موسى قال: أخبرني أبو علي محمد بن همام رضي الله عنه وأرضاه أن أبا جعفر محمد بن عثمان العمري قدس الله روحه جمعنا قبل موته وكنا وجوه الشيعة وشيوخها فقال لنا: إن حدث علي حدث الموت فالأمر إلى أبي القاسم الحسين بن روح النوبختي، فقدت أمرت أن أجعله في موضعي بعدي فارجعوا إليه وعولوا في أموركم عليه.","27/1/43/36",""],[37,42,"وأخبرني الحسين بن إبراهيم عن ابن نوح عن أبي نصر هبة الله بن محمد قال: حدثني خالي أبو إبراهيم جعفر بن أحمد النوبختي قال: قال لي أبي أحمد بن إبراهيم وعمي أبو جعفر عبد الله بن إبراهيم وجماعة من أهلنا- يعني بني نوبخت- أن أبا جعفر العمري لما اشتدت حاله اجتمع جماعة من وجوه الشيعة منهم أبو علي بن همام وأبو عبد الله بن محمد الكاتب وأبو عبد الله الباقطاني وأبو سهل إسماعيل بن علي النوبختي وأبو عبد الله بن الوجناء وغيرهم من الوجوه والأكابر فدخلوا على أبي جعفر رضي الله عنه فقالوا له: إن حدث أمر فمن يكون مكـانك؟ فقـال لهتم: هـذا أبـو القـاسم الحسـين بن روح بـن أبي بـحر النوبختي، القائم مقامي والسفير بينكم وبين صاحب الأمر عليه السلام والوكيل له والثقة الأمين، فارجعوا إليه في أموركم وعولوا عليه في مهماتكم،فبذلك أمرت وقد بلغت.","27/1/43/37",""],[38,42,"وبهذا الإسناد عن هبة الله بن محمد ابن بنت أم كلثوم بنت أبي جعفر العمري قال: حدثتني أم كلثوم بنت أبي جعفر رضي الله عنه قالت: كان أبو القاسم الحسين بن روح رضي الله عنه وكيلا لأبي جعفر رضي الله عنه سنين كثيرة ينظر له في أملاكه ويلقي بأسراره الرؤساء من الشيعة وكان خصيصا به حتى أنه كان يحدثه بما يجري بينه وبين جواريه لقربه منه وأنسه. قالت: وكان يدفع إليه في كل شهر ثلاثين دينارا رزقا له غير ما يصل إليه من الوزراء والرؤساء من الشيعة مثل آل الفرات وغيرهم لجاهه ولموضعه وجلالة محله عندهم،فحصل في أنفس الشيعة محصلا جليلا لمعرفتهم باختصاص أبي إياه وتوثيقه عندهم ونشر فضله ودينه وما كان يحتمله من هذا الأمر. فمهدت له الحال في طول حياة أبي إلى أن انتهت الوصية إليه بالنص عليه فلم يختلف في أمره ولم يشك فيه أحد إلا جاهل بأمر أبي أولا مع ما لست أعلم أن أحدا من الشيعة شك فيه. وقد سمعت هذا من غير واحد من بني نوبخت رحمهم الله مثل أبي الحسن بن كبرياء وغيره.","27/1/43/38",""],[39,42,"وأخبرني جماعة عن أبي العباس بن نوح قال: وجدت بخط محمد بن نفيس فيما كتبه بالأهواز أول كتاب ورد من أبي القاسم رضي الله عنه نعرفه عرفه الله الخير كله ورضوانه وأسعده بالتوفيق وقفنا على كتابه وثقتنا بما هو عليه وأنه عندنا بالمنزلة والمحل اللذين يسرانه زاد الله في إحسانه إليه إنه ولي قدير والحمد لله لا شريك له وصلى الله على رسوله محمد وآله وسلم تسليما كثيرا. وردت هذه الرقعة يوم الأحد لست ليال خلون من شوال سنة خمس وثلاثمائة.","27/1/43/39",""],[40,42,"أخبرنا جماعة عن أبي الحسن محمد بن أحمد بن داود القمي قال: وجدت بخط أحمد بن إبراهيم النوبختي وإملاء أبي القاسم الحسين بن روح رضي الله عنه على ظهر كتاب فيه جوابـات ومسـائل أنفذت من قـم يسأل عنها هل هي جوابات الفقيه عليه السلام أو جوابات محمد بن علي الشلمغاني لأنه حكي عنه أنه قال: هذه المسائل أنا أجبت عنها. فكتب إليهم على ظهر كتابهم: بسم الله الرحمن الرحيم. قد وقفنا على هذه الرقعة وما تضمنته فجميعه جوابنا عن المسائل ولا مدخل للمخذول الضال المضل المعروف بالعزاقري لعنه الله في حرف منه، وقد كانت أشياء خرجت إليكم على يدي أحمد بن بلال وغيره من نظرائه وكان من ارتدادهم عن الإسلام مثل ما كان من هذا، عليهم لعنة الله وغضبه، فاستثبت قديما في ذلك. فخرج الجواب: ألا من استثبت فإنه لا ضرر في خروج ما خرج على أيديهم وأن ذلك صحيح وروي قديما عن بعض العلماء عليهم السلام والصلاة والرحمة أنه سئل عن مثل هذا بعينه في بعض من غضب الله عليه، وقال عليه السلام: العلم علمنا ولا شي‏ء عليكم من كفر فقد كفر فما صح لكم مما خرج على يده برواية غيره له من الثقات رحمهم الله، فاحمدوا الله واقبلوه، وما شككتم فيه أو لم يخرج إليكم في ذلك إلا على يده فردوه إلينا لنصححه أو نبطله،والله تقدست أسماؤه وجل ثناؤه ولي توفيقكم وحسبنا في أمورنا كلها ونعم الوكيل.","27/1/43/40",""],[41,42,"وقال ابن نوح: أول من حدثنا بهذا التوقيع أبو الحسين محمد بن علي بن تمام،وذكر أنه كتبه من ظهر الدرج الذي عند أبي الحسن بن داود. فلما قدم أبو الحسن بن داود وقرأته عليه ذكر أن هذا الدرج بعينه كتب به أهل قم إلى الشيخ أبي القاسم وفيه مسائل فأجابهم على ظهره بخط أحمد بن إبراهيم النوبختي وحصل الدرج عند أبي الحسن بن داود.","27/1/43/41",""],[1,43,"نسخة الدرج؛ مسائل محمد بن عبد الله بن جعفر الحميري: بسم الرحمن الرحيم. أطال الله بقاءك وأدام عزك وتأييدك وسعادتك وسلامتك، وأتم نعمته عليك وزاد في إحسانه إليك وجميل مواهبه لديك وفضله عندك، وجعلني من السوء فداك وقدمني قبلك. الناس يتنافسون في الدرجات فمن قبلتموه كان مقبولا ومن دفعتموه كان وضيعا، والخامل من وضعتموه، ونعوذ بالله من ذلك، وببلدنا أيدك الله جماعة من الوجوه يتساوون ويتنافسون في المنزلة، وورد أيدك الله كتابك إلى جماعة منهم في أمر أمرتهم به من معاونة \"ص\". وأخرج علي بن محمد بن الحسين بن مالك المعروف بأدوكة وهو ختن\"ص\" رحمهم الله من بينهم فاغتم بذلك وسألني أيدك الله أن أعلمك ما ناله من ذلك فإن كان من ذنب استغفر الله منه وإن يكن غير ذلك عرفته ما يسكن نفسه إليه إن شاء الله. التوقيع: لم نكاتب إلا من كاتبنا. وقد عودتني أدام الله عزك من تفضلك ما أنت أهل أن تجريني على العادة وقبلك أعزك الله فقهاء أنا محتاج إلى أشياء تسأل لي عنها، فروي لنا عن العالم عليه السلام أنه سئل عن إمام قوم صلى بهم بعض صلاتهم وحدثت عليه حادثة كيف يعمل من خلفه؟ فقال: يؤخر ويقدم بعضهم ويتم صلاتهم ويغتسل من مسه. التوقيع: ليس على من نحاه إلا غسل اليد وإذا لم تحدث حادثة تقطع الصلاة تمم صلاته مع القوم. وروي عن العالم عليه السلام: إن مس ميتا بحرارته غسل يديه ومن مسه وقد برد فعليه الغسل،وهذا الإمام في هذه الحالة لا يكون مسه إلا بحرارته والعمل من ذلك على ما هو ولعله ينحيه بثيابه ولا يمسه. فكيف يجب عليه الغسل؟ التوقيع: إذا مسه على هذه الحالة لم يكن عليه إلا غسل يده. وعن صلاة جعفر إذا سها في التسبيح في قيام أو قعود أو ركوع أو سجود وذكره في حالة أخرى قد صار فيها من هذه الصلاة، هل يعيد ما فاته من ذلك التسبيح في الحالة التي ذكرها أم يتجاوز في صلاته؟ التوقيع: إذا سها في حالة من ذلك ثم ذكر في حالة أخرى قضى ما فاته في الحالة التي ذكره. وعن المرأة يموت زوجها، هل يجوز أن تخرج في جنازته أم لا؟ التوقيع: تخرج في جنازته. وهل يجوز لها وهي في عدتها أن تزور قبر زوجها أم لا؟ التوقيع: تزور قبر زوجها ولا تبيت عن بيتها. وهل يجوز لها أن تخرج في قضاء حق يلزمها أم لا، تبرح من بيتها وهي في عدتها؟ التوقيع: إذا كان حق خرجت وقضته،وإذا كانت لها حاجة لم يكن لها من ينظر فيها خرجت لها حتى تقضي ولا تبيت عن منزلها. وروي في ثواب القرآن في الفرائض وغيرها أن العالم عليه السلام قال: عجبا لمن لم يقرأ في صلاته (إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ) كيف تقبل صلاته؟! وروي: ما زكت صلاة لم يقرأ فيها بـ (قُلْ هُوَ اللهُ أَحَدٌ). وروي أن من قرأ في فرائضه (الهمزة) أعطي من الدنيا. فهل يجوز أن يقرأ الهمزة ويدع هذه السور التي ذكرناها مع ما قد روي أنه لا تقبل صلاة ولا تزكو إلا بهما؟ التوقيع: الثواب في السور على ما قد روي، وإذا ترك سورة مما فيها الثواب وقرأ (قُلْ هُوَ اللهُ أَحَدٌ) و(إِنَّا أَنْزَلْنَاهُ) لفضلهما أعطي ثواب ما قرأ وثواب السورة التي ترك. ويجوز أن يقرأ غير هاتين السورتين وتكون صلاته تامة،ولكن يكون قد ترك الفضل. وعن وداع شهر رمضان، متى يكون؟ فقد اختلف فيه أصحابنا؛فبعضهم يقول يقرأ في آخر ليلة منه وبعضهم يقول هو في آخر يوم منه إذا رأى هلال شوال. التوقيع: العمل في شهر رمضان في لياليه،والوداع يقع في آخر ليلة منه. فإن خاف أن ينقص جعله في ليلتين. وعن قول الله عز وجل: (إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ) أن رسول الله صلى الله عليه وآله وسلم المعني به. (ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ) ما هذه القوة؟ (مُطاعٍ ثَمَّ أَمِينٍ) ما هذه الطاعة؟ وأين هي؟فرأيك-أدام الله عزك-بالتفضل علي بمسألة من تثق به من الفقهاء عن هذه المسائل وإجابتي عنها منعما مع ما تشرحه لي من أمر محمد بن الحسين بن مالك المقدم ذكره بما يسكن إليه ويعتد بنعمه الله عنده وتفضل علي بدعاء جامع لي ولإخواني للدنيا والآخرة فعلت مثابا إن شاء الله تعالى. التوقيع: جمـع الله لك ولإخـوانك خيـر الدنيـا والآخـرة. أطـال الله بقـاءك وأدام عزك وتأييدك وكرامتك وسعادتك وسلامتك، وأتم نعمته عليك وزاد في إحسانه إليك وجميل مواهبه لديك وفضله عندك،وجعلني من كل سوء ومكروه فداك وقدمني قبلك. الحمد لله رب العالمين وصلى على محمد وآله أجمعين.","27/1/44/1",""],[2,43,"من كتاب آخر: فرأيك أدام الله عزك في تأمل رقعتي والتفضل بما يسهل لأضيفه إلى سائر أياديك علي واحتجت أدام الله عزك أن تسأل لي بعض الفقهاء عن المصلي إذا قام من التشهد الأول للركعة الثالثة هل يجب عليه أن يكبر؟فإن بعض أصحابنا قال: لا يجب عليه التكبير ويجزيه أن يقول: بحول الله وقوته أقوم وأقعد. الجواب: قال: إن فيه حديثين، أما أحدهما فإنه إذا انتقل من حالة إلى حالة أخرى فعليه تكبير، وأما الآخر فإنه روي أنه إذا رفع رأسه من السجدة الثانية فكبر ثم جلس ثم قام فليس عليه للقيام بعد القعود تكبير، وكذلك التشهد الأول يجري هذا المجرى،وبأيهما أخذت من جهة التسليم كان صوابا. وعن الفص الخماهن هل تجوز فيه الصلاة إذا كان في إصبعه؟ الجواب: فيه كراهة أن يصلي فيه، وفيه إطلاق. والعمل على الكراهية. وعن رجل اشترى هدياً لرجل غائب عنه وسأله أن ينحر عنه هديا بمنى، فلما أراد نحر الهدي نسي اسم الرجل ونحر الهدي،ثم ذكره بعد ذلك. أيجزي عن الرجل أم لا؟ الجواب: لا بأس بذلك،وقد أجزأ عن صاحبه. وعندنا حاكة مجوس يأكلون الميتة ولا يغتسلون من الجنابة وينسجون لنا ثيابا، فهل تجوز الصلاة فيها من قبل أن تغسل؟ الجواب: لا بأس بالصلاة فيها. وعن المصلي يكون في صلاة الليل في ظلمة فإذا سجد يغلط بالسجادة ويضع جبهته على مسح أو نطع، فإذا رفع رأسه وجد السجادة، هل يعتد بهذه السجدة أم لا يعتد بها؟ الجواب: ما لم يستو جالسا فلا شي‏ء عليه في رفع رأسه لطلب الخمرة. وعن المحرم يرفع الظلال؛ هل يرفع خشب العمارية أو الكنيسة ويرفع الجناحين أم لا؟ الجواب: لا شي‏ء عليه في تركه وجميع الخشب. وعن المحرم يستظل من المطر بنطع أو غيره جذرا على ثيابه وما في محمله أن يبتل، فهل يجوز ذلك؟ الجواب: إذا فعل ذلك في المحمل في طريقه فعليه دم. والرجل يحج عن أجرة، هل يحتاج أن يذكر الذي حج عنه عند عقد إحرامه أم لا؟ وهل يجب أن يذبح عمن حج عنه وعن نفسه أم يجزيه هدي واحد؟ الجواب: يذكره،وإن لم يفعل فلا بأس. وهل يجوز للرجل أن يحرم في كساء خز أم لا؟ الجواب: لا بأس بذلك،وقد فعله قوم صالحون. وهل يجوز للرجل أن يصلي وفي رجليه بطيط لا يغطي الكعبين أم لا يجوز؟ الجواب: جائز. ويصلي الرجل ومعه في كمه أو سراويله سكين أو مفتاح حديد، هل يجوز ذلك؟ الجواب: جائز. وعن الرجل يكون مع بعض هؤلاء ومتصلا بهم يحج ويأخذ على الجادة ولا يحرمون هؤلاء من المسلخ، فهل يجوز لهذا الرجل أن يؤخر إحرامه إلى ذات عرق فيحرم معهم لما يخاف الشهرة أم لا يجوز أن يحرم إلا من المسلخ؟ الجواب: يحرم من ميقاته ثم يلبس الثياب ويلبي في نفسه،فإذا بلغ إلى ميقاتهم أظهر. وعن لبس النعل المعطون،فإن بعض أصحابنا يذكر أن لبسه كريه. الجواب: جائز ذلك ولا بأس به. وعن الرجل من وكلاء الوقف يكون مستحلا لما في يده لا يرع عن أخذ ماله،ربما نزلت في قرية وهو فيها أو أدخل منزله وقد حضر طعامه فيدعوني إليه فإن لم آكل من طعامه عاداني عليه وقال: فلان لا يستحل أن يأكل من طعامنا، فهل يجوز لي أن آكل من طعامه وأتصدق بصدقة؟ وكم مقدار الصدقة؟ وأن أهدى هذا الوكيل هدية إلى رجل آخر فأحضر فيدعوني أن أنال منها وأنا أعلم أن الوكيل لا يرع عن أخذ ما في يده،فهل علي فيه شي‏ء إن أنا نلت منها؟ الجواب: إن كان لهذا الرجل مال أو معاش غير ما في يده فكل طعامه واقبل بره،وإلا فلا. وعن الرجل ممن يقول بالحق ويرى المتعة ويقول بالرجعة إلا أن له أهلا موافقة له في جميع أمره وقد عاهدها أن لا يتزوج عليها ولا يتمتع ولا يتسرى وقد فعل هذا منذ بضع عشرة سنة ووفى بقوله، فربما غاب عن منزله الأشهر فلا يتمتع ولا تتحرك نفسه أيضا لذلك ويرى أن وقوف من معه من أخ وولد وغلام ووكيل وحاشية مما يقلله في أعينهم ويحب المقام على ما هو عليه محبة لأهله وميلا إليها وصيانة لها ولنفسه، لا يحرم المتعة بل يدين الله بها، فهل عليه في تركه ذلك مأثم أم لا؟ الجواب في ذلك: يستحب له أن يطيع الله تعالى بالمتعة ليزول عنه الحلف على المعرفة ولو مرة واحدة. فإن رأيت أدام الله عزك أن تسأل لي عن ذلك وتشرحه لي وتجيب في كل مسألة بما العمل به وتقلدني المنة في ذلك جعلك الله السبب في كل خير وأجراه على يدك فعلت مثابا إن شاء الله. أطال الله بقاءك وأدام عزك وتأييدك وسعادتك وسلامتك وكرامتك وأتم نعمته عليك وزاد في إحسانه إليك وجعلني من السوء فداك وقدمني عنك وقبلك. الحمد لله رب العالمين وصلى الله على محمد النبي وآله وسلم كثيرا.","27/1/44/2",""],[3,43,"قال ابن نوح: نسخت هذه النسخة من المدرجين القديمين الذين فيهما الخط والتوقيعات.","27/1/44/3",""],[1,44,"وكان أبو القاسم رحمه الله من أعقل الناس عند المخالف والموافق ويستعمل التقية.","27/1/45/1",""],[2,44,"فروى أبو نصر هبة الله بن محمد قال:حدثني أبو عبد الله بن غالب حمو أبي الحسن بن أبي الطيب قال: ما رأيت من هو أعقل من الشيخ أبي القاسم الحسين بن روح ولعهدي به يوما في دار ابن يسار وكان له محل عند السيد والمقتدر عظيم وكانت العامة أيضا تعظمه وكان أبو القاسم يحضر تقية وخوفا. وعهدي به وقد تناظر اثنان فزعم واحد أن أبا بكر أفضل الناس بعد رسول الله صلى الله عليه وآله وسلم ثم عمر ثم علي وقال الآخر بل علي أفضل من عمر،فزاد الكلام بينهما.فقال أبو القاسم رضي الله عنه الذي اجتمعت الصحابة عليه هو تقديم الصديق ثم بعده الفاروق ثم بعده عثمان ذو النورين ثم علي الوصي. وأصحاب الحديث على ذلك وهو الصحيح عندنـا. فبقي من حضر المجلس متعجبا من هذا القول وكان العامة الحضور يرفعونه على رءوسهم وكثر الدعاء له والطعن على من يرميه بالرفض. فوقع علي الضحك فلم أزل أتصبر وأمنع نفسي وأدس كمي في فمي فخشيت أن أفتضح، فوثبت عن المجلس ونظر إلي ففطن بي، فلما حصلت في منزلي فإذا بالباب يطرق،فخرجت مبادرا فإذا بأبي القاسم الحسين بن روح رضي الله عنه راكبا بغلته قد وافاني من المجلس قبل مضيه إلى داره. فقال لي: يا أبا عبد الله، أيدك الله، لم ضحكت فأردت أن تهتف بي كأن الذي قلته عندك ليس بحق. فقلت: كذاك هو عندي. فقال لي: اتق الله أيها الشيخ، فإني لا أجعلك في حل،تستعظم هذا القول مني.فقلت: يا سيدي، رجل يرى بأنه صاحب الإمام ووكيله يقول ذلك القول لا يتعجب منه ولا يضحك من قوله هذا؟!فقال لي: وحياتك لئن عدت لأهجرنك. وودعني وانصرف.","27/1/45/2",""],[3,44,"قال أبو نصر هبة الله بن محمد: حدثني أبو الحسن بن كبرياء النوبختي قال: بلغ الشيخ أبا القاسم رضي الله عنه أن بوابا كان له على الباب الأول قد لعن معاوية وشتمه، فأمر بطرده وصرفه عن خدمته، فبقي مدة طويله يسأل في أمره فلا والله ما رده إلى خدمته،وأخذه بعض الأهل فشغله معه كل ذلك للتقية.","27/1/45/3",""],[4,44,"قال أبو نصر هبة الله: وحدثني أبو أحمد درانويه الأبرص الذي كانت داره في درب القراطيس قال:قال لي: إني كنت أنا وإخوتي ندخل إلى أبي القاسم الحسين بن روح رضي الله عنه نعامله (قال) وكانوا باعة ونحن مثلا عشرة تسعة نلعنه وواحد يشكك، فنخرج من عنده بعد ما دخلنا إليه تسعة نتقرب إلى الله بمحبته وواحد واقف لأنه كان يجارينا من فضل الصحابة ما رويناه وما لم نروه،فنكتبه لحسنه عنه رضي الله عنه.","27/1/45/4",""],[5,44,"وأخبرني الحسين بن إبراهيم عن أبي العباس أحمد بن علي بن نوح عن أبي نصر هبة الله بن محمد الكاتب ابن بنت أم كلثوم بنت أبي جعفر العمري رضي الله عنه أن قبر أبي القاسم الحسين بن روح في النوبختية في الدرب الذي كانت فيه دار علي بن أحمد النوبختي النافذ إلى التل وإلى الدرب الآخر وإلى قنطرة الشوك رضي الله عنه.","27/1/45/5",""],[6,44,"قال: وقال لي أبو نصر: مات أبو القاسم الحسين بن روح رضي الله عنه في شعبان سنة ست وعشرين وثلاثمائة.وقد رويت عنه أخبارا كثيرة:","27/1/45/6",""],[7,44,"منها ما أخبرني به الحسين بن عبيد الله عن أبي عبد الله الحسين بن علي بن سفيان البزوفري رحمه الله قال: حدثني الشيخ أبو القاسم الحسين بن روح رضي الله عنه قال: اختلف أصحابنا في التفويض وغيره، فمضيت إلى أبي طاهر بن بلال في أيام استقامته فعرفته الخلاف، فقال: أخرني. فأخرته أياما فعدت إليه فأخرج إلي حديثا بإسناده إلى أبي عبد الله عليه السلام قال: إذا أراد الله أمراً عرضه على رسول الله صلى الله عليه وآله وسلم ثم أمير المؤمنين عليه السلام وسائر الأئمة واحدا بعد واحد إلى أن ينتهي إلى صاحب الزمان عليه السلام، ثم يخرج إلى الدنيا. وإذ أراد الملائكة أن يرفعوا إلى الله عز وجل عملا عرض على صاحب الزمان عليه السلام ثم يخرج على واحد بعد واحد إلى أن يعرض على رسول الله صلى الله عليه وآله وسلم،ثم يعرض على الله عز وجل. فما نزل من الله فعلى أيديهم وما عرج إلى الله فعلى أيديهم،وما استغنوا عن الله عز وجل طرفة عين.","27/1/45/7",""],[8,44,"وأخبرني جماعة عن أبي عبد الله محمد بن أحمد الصفواني قال: حدثني الشيخ الحسين بن روح رضي الله عنه أن يحيى بن خالد سم موسى بن جعفر عليه السلام في إحدى وعشرين رطبة وبها مات، وأن النبي والأئمة عليهم السلام ما ماتوا إلا بالسيف أو السم. وقد ذكر عن الرضا عليه السلام أنه سم، وكذلك ولده وولد ولده.","27/1/45/8",""],[9,44,"وسأله بعض المتكلمين، وهو المعروف بترك الهروي،فقال له: كم بنات رسول الله صلى الله عليه وآله وسلم؟ فقال: أربع. قال: فأيهن أفضل؟ فقال: فاطمة. فقال: ولم صارت أفضل وكانت أصغرهن سنا وأقلهن صحبة لرسول الله صلى الله عليه وآله وسلم؟ قال: لخصلتين خصها الله بهما تطولا عليها وتشريفا وإكراما لها؛ إحداهما أنها ورثت رسول الله صلى الله عليه وآله وسلم ولم يرث غيرها من ولده، والأخرى أن الله تعالى أبقى نسل رسول الله صلى الله عليه وآله وسلم منها ولم يبقه من غيرها. ولم يخصصها بذلك إلا لفضل إخلاص عرفه من نيتها. قال الهروي: فما رأيت أحدا تكلم وأجاب في هذا الباب بأحسن ولا أوجز من جوابه.","27/1/45/9",""],[10,44,"وأخبرني أبو محمد المحمدي رضي الله عنه عن أبي الحسين محمد بن الفضل بن تمام رحمه الله قال:سمعت أبا جعفر بن محمد بن أحمد بن الزكوزكي رحمه الله وقد ذكرنا كتاب التكليف وكان عندنا أنه لا يكون إلا مع غال وذلك أنه أول ما كتبنا الحديث فسمعناه يقول: وأيش كان لابن أبي العزاقر في كتاب التكليف؟! إنما كان يصلح الباب ويدخله إلى الشيخ أبي القاسم الحسين بن روح رضي الله عنه فيعرضه عليه ويحككه،فإذا صح الباب خرج فنقله وأمرنا بنسخة.يعني أن الذي أمرهم به الحسين بن روح رضي الله عنه. قال أبو جعفر: فكتبته في الإدراج بخطي ببغداد. قال ابن تمام: فقلت له: تفضل يا سيدي فادفعه إلي حتى أكتبه من خطك. فقال لي: قد خرج عن يدي.فقال ابن تمام: فخرجت وأخذت من غيره فكتبت بعد ما سمعت هذه الحكاية.","27/1/45/10",""],[11,44,"وقال أبو الحسين بن تمام: حدثني عبد الله الكوفي خادم الشيخ الحسين بن روح رضي الله عنه قال: سئل الشيخ-يعني أبا القاسم رضي الله عنه-عن كتب ابن أبي العزاقر بعد ما ذم وخرجت فيه اللعنة،فقيل له: فكيف نعمل بكتبه وبيوتنا منها ملاء؟فقال: أقول فيها ما قاله أبو محمد الحسن بن علي عليهما السلاموقد سئل عن كتب بني فضال فقالوا: كيف نعمل بكتبهم وبيوتنا منها ملاء؟ فقال عليه السلام: خذوا بما رووا وذروا ما رأوا.","27/1/45/11",""],[12,44,"وسأل أبو الحسن الأيادي رحمه الله أبا القاسم الحسين بن روح رضي الله عنه: لم كره المتعة بالبكر؟فقال:قال النبي صلى الله عليه وآله وسلم: الحياء من الإيمان.والشروط بينك وبينها فإذا حملتها على أن تنعم فقد خرجت عن الحياء وزال الإيمان. فقال له: فإن فعل فهو زان؟ قال: لا.","27/1/45/12",""],[13,44,"وأخبرني الحسين بن عبيد الله عن أبي الحسن محمد بن أحمد بن داود القمي قال:حدثني سلامة بن محمد قال: أنفذ الشيخ الحسين بن روح رضي الله عنه كتاب التأديب إلى قم وكتب إلى جماعة الفقهاء بها وقال لهم: انظروا في هذا الكتاب وانظروا فيه شي‏ء يخالفكم.فكتبوا إليه أنه كله صحيح وما فيه شي‏ء يخالف إلا قوله في الصاع في الفطرة نصف صاع من طعام والطعام عندنا مثل الشعير من كل واحد صاع.","27/1/45/13",""],[14,44,"قال ابن نوح: وسمعت جماعة من أصحابنا بمصر يذكرون أن أبا سهل النوبختي سئل فقيل له: كيف صار هذا الأمر إلى الشيخ أبي القاسم الحسين بن روح دونك؟ فقال: هم أعلم وما اختاروه، ولكن أنا رجل ألقي الخصوم وأناظرهم ولو علمت بمكانه كما علم أبو القاسم وضغطتني الحجة على مكانه لعلي كنت أدل على مكانه، وأبو القاسم فلو كانت الحجة تحت ذيله وقرض بالمقاريض ما كشف الذيل عنه أو كما قال.","27/1/45/14",""],[15,44,"وذكر محمد بن علي بن أبي العزاقر الشلمغاني في أول كتاب الغيبة الذي صنفه: وأما ما بيني وبين الرجل المذكور زاد الله في توفيقه فلا مدخل لي في ذلك إلا لمن أدخلته فيه لأن الجناية علي فإني وليها.","27/1/45/15",""],[16,44,"وقال في فصل آخر: ومن عظمت منته عليه تضاعفت الحجة عليه ولزمه الصدق فيما ساءه وسره وليس ينبغي فيما بيني وبين الله إلا الصدق عن أمره مع عظم جنايته وهذا الرجل منصوب لأمر من الأمور لا يسع العصابة العدول عنه فيه وحكم الإسلام مع ذلك جار عليه كجريه على غيره من المؤمنين وذكره.","27/1/45/16",""],[17,44,"وذكر أبو محمد هارون بن موسى قال: قال لي أبو علي بن الجنيد: قال لي أبو جعفر محمد بن علي الشلمغاني: ما دخلنا مع أبي القاسم الحسين بن روح رضي الله عنه في هذا الأمر إلا ونحن نعلم فيما دخلنا فيه. لقد كنا نتهارش على هذا الأمر كما تتهارش الكلاب على الجيف. قال أبو محمد: فلم تلتفت الشيعة إلى هذا القول وأقامت على لعنه والبراءة منه.","27/1/45/17",""],[1,45,"ذكر أمر أبي الحسن علي بن محمد السمري بعد الشيخ أبي القاسم الحسين بن روح رضي الله عنه وانقطاع الأعلام به وهم الأبواب:","27/1/46/1",""],[2,45,"أخبرني جماعة عن أبي جعفر محمد بن علي بن الحسين بن بابويه قال: حدثنا محمد بن إبراهيم بن إسحاق عن الحسن بن علي بن زكريا بمدينة السلام قال: حدثنا أبو عبد الله محمد بن خليلان قال: حدثني أبي عن جده عتاب من ولد عتاب بن أسيد قال: ولد الخلف المهدي عليه السلام يوم الجمعة، وأمه ريحانة، ويقال لها نرجس، ويقال لها صقيل، ويقال لها سوسن، إلا أنه قيل بسبب الحمل صقيل.","27/1/46/2",""],[3,45,"وكان مولده لثمان خلون من شعبان سنة ست وخمسين ومائتين ووكيله عثمان بن سعيد. فلما مات عثمـان بن سعيد أوصى إلى أبي جعفر محمد بن عثمـان رحـمه الله، وأوصى أبو جـعفر إلى أبي القاسم الحسين بن روح رضي الله عنه،وأوصى أبو القاسم إلى أبي الحسن علي بن محمد السمري رضي الله عنه.فلما حضرت السمري الوفاة سئل أن يوصي،فقال:لله أمر هو بالغه. فالغيبة التامة هي التي وقعت بعد مضي السمري رضي الله عنه.","27/1/46/3",""],[4,45,"وأخبرني محمد بن محمد بن النعمان والحسين بن عبيد الله عن أبي عبد الله محمد بن أحمد الصفواني قال: أوصى الشيخ أبو القاسم رضي الله عنه إلى أبي الحسن علي بن محمد السمري رضي الله عنه فقام بما كان إلى أبي القاسم. فلما حضرته الوفاة حضرت الشيعة عنده وسألته عن الموكل بعده ولمن يقوم مقامه،فلم يظهر شيئا من ذلك وذكر أنه لم يؤمر بأن يوصي إلى أحد بعده في هذا الشأن.","27/1/46/4",""],[5,45,"وأخبرني جماعة عن أبي جعفر محمد بن علي بن الحسين بن موسى بن بابويه قال: حدثنا أبو الحسن صالح بن شعيب الطالقاني رحمه الله في ذي القعدة سنة تسع وثلاثين وثلاثمائة قال: حدثنا أبو عبد الله أحمد بن إبراهيم بن مخلد قال: حضرت بغداد عند المشايخ رحمهم الله فقال الشيخ أبو الحسن علي بن محمد السمري قدس سره ابتداء منه: رحم الله علي بن الحسين بن بابويه القمي. قال: فكتب المشايخ تاريخ ذلك اليوم فورد الخبر أنه توفي في ذلك اليوم. ومضى أبو الحسن السمري رضي الله عنه بعد ذلك في النصف من شعبان سنة تسع وعشرين وثلاثمائة.","27/1/46/5",""],[6,45,"وأخبرنا جماعة عن أبي جعفر محمد بن علي بن الحسين بن بابويه قال: حدثني أبو محمد الحسن بن أحمد المكتب قال: كنت بمدينة السلام في السنة التي توفي فيها الشيخ أبو الحسن علي بن محمد السمري قدس سره فحضرته قبل وفاته بأيام فأخرج إلى الناس توقيعا نسخته: بسم الله الرحمن الرحيم. يا علي بن محمد السمري، أعظم الله أجر إخوانك فيك،فإنك ميت ما بينك وبين ستة أيام. فاجمع أمرك ولا توص إلى أحد فيقوم مقامك بعد وفاتك،فقد وقعت الغيبة التامة فلا ظهور إلا بعد إذن الله تعالى ذكره وذلك بعد طول الأمد وقسوة القلوب وامتلاء الأرض جورا. وسيأتي شيعتي من يدعي المشاهدة؛ألا فمن ادعى المشاهدة قبل خروج السفياني والصيحة فهو كذاب مفتر. ولا حول ولا قوة إلا بالله العلي العظيم. قال: فنسخنا هذا التوقيع وخرجنا من عنده، فلما كان اليوم السادس عدنا إليه وهو يجود بنفسه،فقيل له: من وصيك من بعدك؟ فقال: لله أمر هو بالغه، وقضى. فهذا آخر كلام سمع منه رضي الله عنه وأرضاه.","27/1/46/6",""],[7,45,"وأخبرني جماعة عن أبي عبد الله الحسين بن علي بن بابويه القمي قال:حدثني جماعة من أهل قم منهم علي بن بابويه قال:حدثني جماعة من أهل قم منهم علي بن أحمد بن عمران الصفار وقريبه علوية الصفار والحسين بن أحمد بن إدريس رحمهم الله قالوا: حضرنا بغداد في السنة التي توفي فيها أبي علي بن الحسين بن موسى بن بابويه وكان أبو الحسن علي بن محمد السمري قدس سره يسألنا كل قريب عن خبر علي بن الحسين رحمه الله،فنقول: قد ورد الكتاب باستقلاله. حتى كان اليوم الذي قبض فيه فسألنا عنه فذكرنا له مثل ذلك،فقال لنا: آجركم الله في علي بن الحسين،فقد قبض في هذه الساعة. قالوا: فأثبتنا تاريخ الساعة واليوم والشهر،فلما كان بعد سبعة عشر يوما أو ثمانية عشر يوما ورد الخبر أنه قبض في تلك الساعة التي ذكرها الشيخ أبو الحسن قدس سره.","27/1/46/7",""],[8,45,"وأخبرني الحسين بن إبراهيم عن أبي العباس بن نوح عن أبي نصر هبة الله بن محمد الكاتب أن قبر أبي الحسن السمري رضي الله عنه في الشارع المعروف بشارع الخلنجي من ربع باب المحول قريب من شاطئ نهر أبي عتاب. وذكر أنه مات رضي الله عنه في سنة تسع وعشرين وثلاثمائة.","27/1/46/8",""],[1,46,"أولهم المعروف بالشريعي:","27/1/47/1",""],[2,46,"أخبرنا جماعة عن أبي محمد التلعكبري عن أبي علي محمد بن همام قال كان الشريعي يكنى بأبي محمد قال هارون: وأظن اسمه كان الحسن، وكان من أصحاب أبي الحسن علي بن محمد ثم الحسن بن علي بعده عليهم السلام، وهو أول من ادعى مقاما لم يجعله الله فيه ولم يكن أهلا له، وكذب على الله وعلى حججه عليهمالسلام ونسب إليهم ما لا يليق بهم وما هم منه براء. فلعنته الشيعة وتبرأت منه وخرج توقيع الإمام عليه السلام بلعنه والبراءة منه. قال هارون: ثم ظهر منه القول بالكفر والإلحاد. قال: وكل هؤلاء المدعين إنما يكون كذبهم أولا على الإمام وأنهم وكلاؤه، فيدعون الضعفة بهذا القول إلى موالاتهم، ثم يترقى الأمر بهم إلى قول الحلاجية كما اشتهر من أبي جعفر الشلمغاني ونظرائه عليهم جميعا لعائن الله تترى.","27/1/47/2",""],[3,46,"ومنهم محمد بن نصير النميري:","27/1/47/3",""],[4,46,"قال ابن نوح: أخبرنا أبو نصر هبة الله بن محمد قال: كان محمد بن نصير النميري من أصحاب أبي محمد الحسن بن علي عليه السلام فلما توفي أبو محمد ادعى مقام أبي جعفر محمد بن عثمان أنه صاحب إمام الزمان وادعى له البابية،وفضحه الله تعالى بما ظهر منه من الإلحاد والجهل ولعن أبي جعفر محمد بن عثمان له وتبريه منه واحتجابه عنه وادعى ذلك الأمر بعد الشريعي.","27/1/47/4",""],[5,46,"قال أبو طالب الأنباري: لما ظهر محمد بن نصير بما ظهر لعنه أبو جعفر رضي الله عنه وتبرأ منه،فبلغه ذلك فقصد أبا جعفر رضي الله عنه ليعطف بقلبه عليه أو يعتذر إليه فلم يأذن له وحجبه ورده خائبا.","27/1/47/5",""],[6,46,"وقال سعد بن عبد الله: كان محمد بن نصير النميري يدعي أنه رسول نبي وأن علي بن محمد عليه السلام أرسله وكان يقول بالتناسخ ويغلو في أبي الحسن عليه السلام ويقول فيه بالربوبية ويقول بالإباحة للمحارم وتحليل نكاح الرجال بعضهم بعضا في أدبارهم ويزعم أن ذلك من التواضع والإخبات والتذلل في المفعول به أنه من الفاعل إحدى الشهوات والطيبات وأن الله عز وجل لا يحرم شيئا من ذلك. وكان محمد بن موسى بن الحسن بن الفرات يقوي أسبابه ويعضده.","27/1/47/6",""],[7,46,"أخبرني بذلك عن محمد بن نصير أبو زكريا يحيى بن عبد الرحمن بن خاقان أنه رآه عيانا وغلام له على ظهره قال: فلقيته فعاتبته على ذلك فقال إن هذا من اللذات وهو من التواضع لله وترك التجبر.","27/1/47/7",""],[8,46,"قـال سعد: فلمـا اعتل محمد بن نصير العلة التي توفي فيها قيل له وهو مثقل اللسان: لمن هذا الأمر من بعدك؟ فقال بلسان ضعيف ملجلج: أحمد. فلم يدروا من هو، فافترقوا بعده ثلاث فرق؛ قالت فرقة إنه أحمد ابنه، وفرقة قالت هو أحمد بن محمد بن موسى بن الفرات، وفرقة قالت إنه أحمد بن أبي الحسين بن بشر بن ��زيد، فتفرقوا فلا يرجعون إلى شي‏ء.","27/1/47/8",""],[9,46,"ومنهم أحمد بن هلال الكرخي:","27/1/47/9",""],[10,46,"قال أبو علي بن همام كان أحمد بن هلال من أصحاب أبي محمد عليه السلام فاجتمعت الشيعة على وكالة محمد بن عثمان رضي الله عنه بنص الحسن عليه السلام في حياته ولما مضى الحسن عليه السلام قالت الشيعة الجماعة له: ألا تقبل أمر أبي جعفر محمد بن عثمان وترجع إليه وقد نص عليه الإمام المفترض الطاعة؟فقال لهم: لم أسمعه ينص عليه بالوكالة،وليس أنكر أباه-يعني عثمان بن سعيد-فأما أن أقطع أن أبا جعفر وكيل صاحب الزمان فلا أجسر عليه. فقالوا: قد سمعه غيرك. فقال: أنتم وما سمعتم. ووقف على أبي جعفر فلعنوه وتبرءوا منه.ثم ظهر التوقيع على يد أبي القاسم بن روح بلعنه والبراءة منه في جملة من لعن.","27/1/47/10",""],[11,46,"ومنهم أبو طاهر محمد بن علي بن بلال: وقصته معروفة فيما جرى بينه وبين أبي جعفر محمد بن عثمان العمري نضر الله وجهه وتمسكه بالأموال التي كانت عنده للإمام وامتناعه من تسليمها وادعائه أنه الوكيل حتى تبرأت الجماعة منه ولعنوه،وخرج فيه من صاحب الزمان عليه السلام ما هو معروف.","27/1/47/11",""],[12,46,"وحكى أبو غالب الزراري قال: حدثني أبو الحسن محمد بن محمد بن يحيى المعاذي قال: كان رجل من أصحابنا قد انضوى إلى أبي طاهر بن بلال بعد ما وقعت الفرقة ثم إنه رجع عن ذلك وصار في جملتنا فسألناه عن السبب قال: كنت عند أبي طاهر بن بلال يوما وعنده أخوه أبو الطيب وابن حرز وجماعة من أصحابه إذ دخل الغلام فقال: أبو جعفر العمري على الباب. ففزعت الجماعة لذلك وأنكرته للحال التي كانت جرت وقال: يدخل. فدخل أبو جعفر رضي الله عنه فقام له أبو طاهر والجماعة وجلس في صدر المجلس وجلس أبو طاهر كالجالس بين يديه فأمهلهم إلى أن سكتوا. ثم قال: يا أبا طاهر نشدتك الله- أو نشدتك بالله-ألم يأمرك صاحب الزمان عليه السلام بحمل ما عندك من المال إلي؟ فقال: اللهم نعم. فنهض أبو جعفر رضي الله عنه منصرفا ووقعت على القوم سكتة فلما تجلت عنهم قال له أخوه أبو الطيب: من أين رأيت صاحب الزمان؟ فقال أبو طاهر: أدخلني أبو جعفر رضي الله عنه إلى بعض دوره فأشرف علي من علو داره فأمرني بحمل ما عندي من المال إليه. فقال له أبو الطيب: ومن أين علمت أنه صاحب الزمان؟ قال: قد وقع علي من الهيبة له ودخلني من الرعب منه ما علمت أنه صاحب الزمان عليه السلام، فكان هذا سبب انقطاعي عنه.","27/1/47/12",""],[13,46,"ومنهم الحسين بن منصور الحلاج:","27/1/47/13",""],[14,46,"أخبرنا الحسين بن إبراهيم عن أبي العباس أحمد بن علي بن نوح عن أبي نصر هبة الله بن محمد الكاتب ابن بنت أم كلثوم بنت أبي جعفر العمري قال: لما أراد الله تعالى أن يكشف أمر الحلاج ويظهر فضيحته ويخزيه وقع له أن أبا سهل إسماعيل بن علي النوبختي رضي الله عنه ممن تجوز عليه مخرقته وتتم عليه حيلته فوجه إليه يستدعيه وظن أن أبا سهل كغيره من الضعفاء في هذا الأمر بفرط جهله، وقدر أن يستجره إليه فيتمخرق به ويتسوف بانقياده على غيره فيستتب له ما قصد إليه من الحيلة والبهرجة على الضعفة لقدر أبي سهل في أنفس الناس ومحله من العلم والأدب أيضا عندهم ويقول له في مراسلته إياه: إني وكيل صاحب الزمان عليه السلام. وبهذا أولا كان يستجر الجهال ثم يعلو منه إلى غيره،وقد أمرت بمراسلتك وإظهار ما تريده من النصرة لك لتقوي نفسك ولا ترتاب بهذا الأمر. فأرسل إليه أبو سهل رضي الله عنه يقول له: إني أسألك أمرا يسيرا يخف مثله عليك في جنب ما ظهر على يديك من الدلائل والبراهين، وهو أني رجل أحب الجواري وأصبو إليهن ولي منهن عدة أتحظاهن والشيب يبعدني عنهن ويبغضني إليهن وأحتاج أن أخضبه في كل جمعة وأتحمل منه مشقة شديدة لأستر عنهن ذلك وإلا انكشف أمري عندهن فصار القرب بعدا والوصـال هجـرا، وأريـد أن تغنـيني عن الخضـاب وتكفيـني مؤنته وتجعل لحيتي سوداء فإني طوع يديك وصائر إليك وقائل بقولك وداع إلى مذهبك مع ما لي في ذلك من البصيرة ولك من المعونة. فلما سمع ذلك الحلاج من قوله وجوابه علم أنه قد أخطأ في مراسلته وجهل في الخروج إليه بمذهبه وأمسك عنه ولم يرد إليه جوابا ولم يرسل إليه رسولا،وصيره أبو سهل رضي الله عنه أحدوثة وضحكة ويطنز به عند كل أحد وشهر أمره عند الصغير والكبير وكان هذا الفعل سببا لكشف أمره وتنفير الجماعة عنه.","27/1/47/14",""],[15,46,"وأخبرني جماعة عن أبي عبد الله الحسين بن علي بن الحسين بن موسى بن بابويه أن ابن الحلاج صار إلى قم وكاتب قرابة أبي الحسن يستدعيه ويستدعي أبا الحسن أيضا ويقول: أنا رسول الإمام ووكيله. قال: فلما وقعت المكاتبة في يد أبي رضي الله عنه خرقها وقال لموصلها إليه: ما أفرغك للجهالات! فقال له الرجل-وأظن أنه قال إنه ابن عمته أو ابن عمه- :فإن الرجل قد استدعانا فلم خرقت مكاتبته. وضحكوا منه وهزءوا به،ثم نهض إلى دكانه ومعه جماعة من أصحابه وغلمانه. قال: فلما دخل إلى الدار التي كان فيها دكانه نهض له من كان هناك جالسا غير رجل رآه جالسا في الموضع فلم ينهض له ولم يعرفه أبي، فلما جلس وأخرج حسابه ودواته كما يكون التجار أقبل على بعض من كان حاضرا فسأله عنه، فأخبره،فسمعه الرجل يسأل عنه فأقبل عليه وقال له: تسأل عني وأنا حاضر؟فقال له أبي: أكبرتك أيها الرجل وأعظمت قدرك أن أسألك. فقال له: تخرق رقعتي وأنا أشاهدك تخرقها. فقال له أبي: فأنت الرجل إذا. ثم قال: يا غلام برجله وبقفاه. فخرج من الدار العدو لله ولرسوله. ثم قال له: أتدعي المعجزات عليك لعنة الله. أو كما قال،فأخرج بقفاه فما رأيناه بعدها بقم.","27/1/47/15",""],[16,46,"أخبرني الحسين بن إبراهيم عن أحمد بن نوح عن أبي نصر هبة الله بن محمد بن أحمد الكاتب ابن بنت أم كلثوم بنت أبي جعفر العمري رضي الله عنه قال: حدثتني الكبيرة أم كلثوم بنت أبي جعفر العمري رضي الله عنه قالت: كان أبو جعفر بن أبي العزاقر وجيها عند بني بسطام.وذاك أن الشيخ أبا القاسم رضي الله تعالى عنه وأرضاه كان قد جعل له عند الناس منزلة وجاها فكان عند ارتداده يحكي كل كذب وبلاء وكفر لبني بسطام ويسنده عن الشيخ أبي القاسم فيقبلونه منه ويأخذونه عنه حتى انكشف ذلك لأبي القاسم رضي الله عنه فأنكره وأعظمه ونهى بني بسطام عن كلامه وأمرهم بلعنه والبراءة منه، فلم ينتهوا وأقاموا على توليه. وذاك أنه كان يقول لهم: إنني أذعت السر وقد أخذ على الكتمان فعوقبت بالإبعاد بعد الاختصاص لأن الأمر عظيم لا يحتمله إلا ملك مقرب أو نبي مرسل أو مؤمن ممتحن. فيؤكد في نفوسهم عظم الأمر وجلالته.فبلغ ذلك أبا القاسم رضي الله عنه فكتب إلى بني بسطام بلعنه والبراءة منه وممن تابعه على قوله وأقام على توليه، فلما وصل إليهم أظهروه عليه فبكى بكاء عظيما ثم قال: إن لهذا القول باطنا عظيما، وهو أن اللعنة الإبعاد. فمعنى قوله: لعنه الله، أي باعده الله عن العذاب والنار. والآن قد عرفت منزلتي. ومرغ خديه على التراب وقال: عليكم بالكتمان لهذا الأمر. قالت الكبيرة رضي الله عنها: وقد كنت أخبرت الشيخ أبا القاسم أن أم أبي جعفر بن بسطام قالت لي يوما وقد دخلنا إليها فاستقبلتني وأعظمتني وزادت في إعظامي حتى انكبت على رجلي تقبلها فأنكرت ذلك وقلت لها: مهلا يا ستي،فإن هذا أمر عظيم. وانكببت على يدها فبكت ثم قالت: كيف لا أفعل بك هذا وأنت مولاتي فاطمة؟ فقلت لها: وكيف ذاك يا ستي؟ فقالت لي: إن الشيخ أبا جعفر محمد بن علي خرج إلينا بالسر. (قالت) فقلت لها: وما السر؟ قالت: قد أخذ علينا كتمانه وأفزع إن أنا أذعته عوقبت. قالت: وأعطيتها موثقا أني لا أكشفه لأحد واعتقدت في نفسي الاستثناء بالشيخ رضي الله عنه يعني أبا القاسم الحسين بن روح. قالت: إن الشيخ أبا جعفر قال لنا: إن روح رسول الله صلى الله عليه وآله وسلم انتقلت إلى أبيك- يعني أبا جعفر محمد بن عثمان رضي الله عنه- وروح أمير المؤمنين عليه السلام انتقلت إلى بدن الشيخ أبي القاسم الحسين بن روح، وروح مولاتنا فاطمة عليها السلام انتقلت إليك، فكيف لا أعظمك يا ستنا؟! فقلت لها: مهلا، لا تفعلي. فإن هذا كذب يا ستنا. فقالت لي: هو سر عظيم، وقد أخذ علينا أننا لا نكشف هذا لأحد. فالله الله في!لا يحل لي العذاب، ويا ستي فلو لا أنك حملتيني على كشفه ما كشفته لك ولا لأحد غيرك. قالت الكبيرة أم كلثوم رضي الله عنها: فلما انصرفت من عندها دخلت إلى الشيخ أبي القاسم بن روح رضي الله عنه فأخبرته بالقصة وكان يثق بي ويركن إلى قولي، فقال لي: يا بنية، إياك أن تمضي إلى هذه المرأة بعد ما جرى منها، ولا تقبلي لها رقعة إن كاتبتك ولا رسولا إن أنفذته إليك ولا تلقيها بعد قولها، فهذا كفر بالله تعالى وإلحاد قد أحكمه هذا الرجل الملعون في قلوب هؤلاء القوم ليجعله طريقا إلى أن يقول لهم بأن الله تعالى اتحد به وحل فيه كما يقول النصارى في المسيح عليه السلام،ويعدو إلى قول الحلاج لعنه الله. قالت: فهجرت بني بسطام وتركت المضي إليهم ولم أقبل لهم عذرا ولا لقيت أمهم بعدها وشاع في بني نوبخت الحديث فلم يبق أحد إلا وتقدم إليه الشيخ أبو القاسم وكاتبه بلعن أبي جعفر الشلمغاني والبراءة منه وممن يتولاه ورضي بقوله أو كلمه فضلا عن موالاته. ثم ظهر التوقيع من صاحب الزمان عليه السلام بلعن أبي جعفر محمد بن علي والبراءة منه وممن تابعه وشايعه ورضي بقوله وأقام على توليه بعد المعرفة بهذا التوقيع. وله حكايات قبيحة وأمور فظيعة ننزه كتابنا عن ذكرها،ذكرها ابن نوح وغيره.وكان سبب قتله أنه لما أظهر لعنه أبو القاسم بن روح رضي الله عنه واشتهر أمره وتبرأ منه وأمر جميع الشيعة بذلك لم يمكنه التلبيس فقال في مجلس حافل فيه رؤساء الشيعة،وكل يحكي عن الشيخ أبي القاسم لعنه والبراءة منه أجمعوا بيني وبينه حتى آخذ يده ويأخذ بيدي فإن لم تنزل عليه نار من السماء تحرقه وإلا فجميع ما قاله في حق ورقي ذلك إلى الراضي لأنه كان ذلك في دار ابن مقلة فأمر بالقبض عليه وقتله فقتل واستراحت الشيعة منه.","27/1/47/16",""],[17,46,"وقال أبو الحسن محمد بن أحمد بن داود: كان محمد بن علي الشلمغاني المعروف بابن أبي العزاقر لعنه الله يعتقد القول بحمل الضد ومعناه أنه لا يتهيأ إظهار فضيلة للولي إلا بطعن الضد فيه لأنه يحمل سامعي طعنه على طلب فضيلته فإذا هو أفضل من الولي إذ لا يتهيأ إظهار الفضل إلا به. وساقوا المذهب من وقت آدم الأول إلى آدم السابع لأنهم قالوا سبع عوالم وسبع أوادم ونزلوا إلى موسى وفرعون ومحمد وعلي مع أبي بكر ومعاوية. وأما في الضد فقال بعضهم: الولي ينصب الضد ويحمله على ذلك كما قال قوم من أصحاب الظاهر إن علي بن أبي طالب عليه السلام نصب أبا بكر في ذلك المقام. وقال بعضهم: لا ولكن هو قديم معه لم يزل.قالوا: والقائم الذي ذكروا أصحاب الظاهر أنه من ولد الحادي عشر فإنه يقوم معناه إبليس لأنه قال: ﴿فَسَجَدَ الْمَلائِكَةُ كُلُّهُمْ أَجْمَعُونَ إِلَّا إِبْلِيسَ﴾فلم يسجد ثم قال: ﴿لَأَقْعُدَنَّ لَهُمْ صِراطَكَ الْمُسْتَقِيمَ﴾فدل على أنه كان قائما في وقت ما أمر بالسجود ثم قعد بعد ذلك. وقوله يقوم القائم إنما هو ذلك القائم الذي أمر بالسجود فأبى وهو إبليس لعنه الله. وقال شاعرهم لعنهم الله: يا لاعنا للضد من عدي ما الضد إلا ظاهر الولي ولا حجامي ولا جغدي ‏قد فقت من قول على الفهدي نعم وجاوزت مدى العبدي فوق عظيم ليس بالمجوسي ‏لأنه الفرد بلا كيفي متحد بكل أوحدي مخالط النوري والظلمي يا طالبا من بيت هاشمي وجاحدا من بيت كسروي قد غاب في نسبة أعجمي ‏في الفارسي الحسب الرضي كما التوى في العرب من لوي","27/1/47/17",""],[18,46,"وقال الصفواني: سمعت أبا علي بن همام يقول:سمعت محمد بن علي العزاقري الشلمغاني يقول: الحق واحد وإنما تختلف قمصه فيوم يكون في أبيض ويوم يكون في أحمر ويوم يكون في أزرق. قال ابن همام: فهذا أول ما أنكرته من قوله لأنه قول أصحاب الحلول.","27/1/47/18",""],[19,46,"وأخبرنا جماعة عن أبي محمد هارون بن موسى عن أبي علي محمد بن همام أن محمد بن علي الشلمغاني لم يكن قط بابا إلى أبي القاسم ولا طريقا له ولا نصبه أبو القاسم لشي‏ء من ذلك على وجه ولا سبب،ومن قال بذلك فقد أبطل. وإنما كان فقيها من فقهائنا وخلط وظهر عنه ما ظهر وانتشر الكفر والإلحاد عنه.فخرج فيه التوقيع على يد أبي القاسم بلعنه والبراءة منه ممن تابعه وشايعه وقال بقوله.","27/1/47/19",""],[20,46,"وأخبرني الحسين بن إبراهيم عن أحمد بن علي بن نوح عن أبي نصر هبة الله بن محمد بن أحمد قال:حدثني أبو عبد الله الحسين بن أحمد الحامدي البزاز المعروف بغلام أبي علي بن جعفر المعروف بابن زهومة النوبختي وكان شيخا مستورا قال:سمعت روح بن أبي القاسم بن روح يقول: لما عمل محمد بن علي الشلمغاني كتاب التكليف قال الشيخ-يعني أبا القاسم رضي الله عنه-:اطلبوه إلي لأنظره. فجاءوا به فقرأه من أوله إلى آخره فقال: ما فيه شي‏ء إلا وقد روي عن الأئمة إلا موضعين أو ثلاثة فإنه كذب عليهم في روايتها لعنه الله.","27/1/47/20",""],[21,46,"وأخبرني جماعة عن أبي الحسن محمد بن أحمد بن داود وأبي عبد الله الحسين بن علي بن الحسين بن موسى بن بابويه أنهما قالا: مما أخطأ محمد بن علي في المذهب في باب الشهادة أنه روى عن العالم عليه السلام أنه قال: إذا كان لأخيك المؤمن على رجل حق فدفعه عنه ولم يكن له من البينة عليه إلا شاهد واحد وكان الشاهد ثقة رجعت إلى الشاهد فسألته عن شهادته فإذا أقامها عندك شهدت معه عند الحاكم على مثل ما يشهده عنده لئلا يتوى حق امرئ مسلم. واللفظ لابن بابويه وقال: هذا كذب منه ولسنا نعرف ذلك. وقال في موضع آخر: كذب فيه.","27/1/47/21",""],[22,46,"أخبرنا جماعة عن أبي محمد هارون بن موسى قال: حدثنا محمد بن همام قال: خرج على يد الشيخ أبي القاسم الحسين بن روح رضي الله عنه في ذي الحجة سنة اثنتي عشرة وثلاثمائة في لعن ابن أبي العزاقر والمداد رطب لم يجف. وأخبرنا جماعة عن ابن داود قال: خرج التوقيع من الحسين بن روح في الشلمغاني وأنفذ نسخته إلى أبي علي بن همام في ذي الحجة سنه اثنتي عشره وثلاثمائة. قال ابن نوح: وحدثنا أبو الفتح أحمد بن ذكا مولى علي بن محمد بن الفرات رحمه الله قال:أخبرنا أبو علي بن همام بن سهيل بتوقيع خرج في ذي الحجة سنة اثنتي عشرة وثلاثمائة. قال محمد بن الحسن بن جعفر بن إسماعيل بن صالح الصيمري أنفذ الشيخ الحسين بن روح رضي الله عنه من محبسة في دار المقتدر إلى شيخنا أبي علي بن همام في ذي الحجة سنة اثنتي عشرة وثلاثمائة وأملأه أبو علي عليّ وعرفني أن أبا القاسم رضي الله عنه راجع في ترك إظهاره فإنه في يد القوم وحبسهم فأمر بإظهاره وأن لا يخشى ويأمن فتخلص وخرج من الحبس بعد ذلك بمدة يسيرة،والحمد لله. التوقيع عرف -قال الصيمري: عرفك الله الخير وأطال الله بقاءك وعرفك الخير كله وختم به عملك-من تثق بدينه وتسكن إلى نيته من إخواننا أسعدكم الله -وقال ابن داود: أدام الله سعادتكم من تسكن إلى دينه وتثق بنيته-جميعا بأن محمد بن علي المعروف بالشلمغاني-زاد بن داود: وهو ممن عجل الله له النقمة ولا أمهله-قد ارتد عن الإسلام وفارقه-اتفقوا-وألحد في دين الله وادعى ما كفر معه بالخالق -قال هارون: فيه بالخالق-جل وتعالى وافترى كذبا وزورا وقال بهتانا وإثما عظيما -قال هارون: وأمرا عظيما - كذب العادلون بالله وضلوا ضلالا بعيدا وخسروا خسرانا مبينا وإننا قد برئنا إلى الله تعالى وإلى رسوله وآله صلوات الله وسلامه ورحمته وبركاته عليهـم بمنه ولعنّـاه عليه لعائن الله - اتفقوا،زاد بن داود تترى- في الظاهر منا والباطن في السر والجهر وفي كل وقت وعلى كل حال وعلى من شايعه وتابعه أو بلغه هذا القول منا وأقام على توليه بعده وأعلمهم- قال الصيمري: تولاكم الله. قال ابن ذكا: أعزكم الله-أنا من التوقي -وقال ابن داود: اعلم أننا من التوقي له. قال هارون: وأعلمهم أننا في التوقي- والمحاذرة منه. قال ابن داود وهارون: على مثل ما كان من تقدمنا لنظرائه. قال الصيمري: على ما كنا عليه ممن تقدمه من نظرائه. وقال ابن ذكا: على ما كان عليه من تقدمنا لنظرائه. اتفقوا- من الشريعي والنميري والهلالي والبلالي وغيرهم وعادة الله- قال ابن داود وهارون: جل ثناؤه،واتفقوا- مع ذلك قبله وبعده عندنا جميلة، وبه نثق، وإياه نستعين،وهو حسبنا في كل أمورنا ونعم الوكيل. قال هارون: وأخذ أبو علي هذا التوقيع ولم يدع أحدا من الشيوخ إلا وأقرأه إياه وكوتب من بعد منهم بنسخته في سائر الأمصار فاشتهر ذلك في الطائفة فاجتمعت على لعنه والبراءة منه. وقتل محمد بن علي الشلمغاني في سنة ثلاث وعشرين وثلاثمائة.","27/1/47/22",""],[23,46,"ذكر أمر أبي بكر البغدادي ابن أخي الشيخ أبي جعفر محمد بن عثمان العمري وأبي دلف المجنون:","27/1/47/23",""],[24,46,"أخبرني الشيخ أبو عبد الله محمد بن محمد بن النعمان عن أبي الحسن علي بن بلال المهلبي قال: سمعت أبا القاسم جعفر بن محمد بن قولويه يقول: أما أبو دلف الكاتب- لا حاطه الله- فكنا نعرفه ملحدا ثم أظهر الغلو ثم جن وسلسل ثم صار مفوصا، وما عرفناه قط إذا حضر في مشهد إلا استخف به ولا عرفته الشيعة إلا مدة يسيرة،والجماعة تتبرأ منه وممن يومئ إليه وينمس به. وقد كنا وجهنا إلى أبي بكر البغدادي لما ادعى له هذا ما ادعاه فأنكر ذلك وحلف عليه فقبلنا ذلك منه فلما دخل بغداد مال إليه وعدل عن الطائفة وأوصى إليه لم نشك أنه على مذهبه فلعناه وبرئنا منه،لأن عندنا أن كل من ادعى الأمر بعد السمري رحمه الله فهو كافر منمس ضال مضل وبالله التوفيق.","27/1/47/24",""],[25,46,"وذكر أبو عمرو محمد بن محمد بن نصر السكري قال: لما قدم ابن محمد بن الحسن بن الوليد القمي من قبل أبيه والجماعة على أبي بكر البغدادي وسألوه عن الأمر الذي حكي فيه من النيابة أنكر ذلك وقال: ليس إلى من هذا شي‏ء وعرض عليه مال فأبى وقال محرم على أخذ شي‏ء منه فإنه ليس إلى من هذا الأمر شي‏ء ولا ادعيت شيئا من هذا وكنت حاضرا لمخاطبته إياه بالبصرة.","27/1/47/25",""],[26,46,"وذكر ابن عياش قال اجتمعت يوما مع أبي دلف فأخذنا في ذكر أبي بكر البغدادي، فقال لي: تعلم من أين كان فضل سيدنا الشيخ قدس الله روحه وقدس به على أبي القاسم الحسين بن روح وعلى غيره؟ فقلت له: ما أعرف. قال: لأن أبا جعفر محمد بن عثمان قدم اسمه على اسمه في وصيته.قال: فقلت له: فالمنصور إذاً أفضل من مولانا أبي الحسن موسى عليه السلام.قال: وكيف؟ قلت: لأن الصادق عليه السلام قدم اسمه على اسمه في الوصية.فقال لي: أنت تتعصب على سيدنا وتعاديه. فقلت: والخلق كلهم تعادي أبا بكر البغدادي وتتعصب عليه غيرك وحدك. وكدنا نتقاتل ونأخذ بالأزياق. وأمر أبي بكر البغدادي في قلة العلم والمروءة أشهر،وجنون أبي دلف أكثر من أن يحصى لا نشغل كتابنا بذلك ولا نطول بذكره. وذكر ابن نوح طرفا من ذلك.","27/1/47/26",""],[27,46,"وروى أبو محمد هارون بن موسى عن أبي القاسم الحسين بن عبد الرحيم الأبراروري قال: أنفذني أبي عبد الرحيم إلى أبي جعفر محمد بن عثمان العمري رضي الله عنه في شي‏ء كان بيني وبينه فحضرت مجلسه وفيه جماعة من أصحابنا وهم يتذاكرون شيئا من الروايات وما قاله الصادقون عليه السلام حتى أقبل أبو بكر محمد بن أحمد بن عثمان المعروف بالبغدادي ابن أخي أبي جعفر العمري رضي الله عنه فلما بصر به أبو جعفر رضي الله عنه قال للجماعة: أمسكوا فإن هذا الجائي ليس من أصحابكم.","27/1/47/27",""],[28,46,"وحكي أنه توكل لليزيدي بالبصرة فبقي في خدمته مدة طويلة وجمع مالا عظيما فسعي به إلى اليزيدي فقبض عليه وصادره وضربه على أم رأسه حتى نزل الماء في عينيه فمات أبو بكر ضريرا.","27/1/47/28",""],[29,46,"وقال أبو نصر هبة الله بن محمد بن أحمد الكاتب ابن بنت أم كلثوم بنت أبي جعفر محمد بن عثمان العمري رضي الله عنه أن أبا دلف محمد بن مظفر الكاتب كان في ابتداء أمره مخمسا مشهورا بذلك لأنه كان تربية الكرخيين وتلميذهم وصنيعتهم وكان الكرخيون مخمسة لا يشك في ذلك أحد من الشيعة وقد كان أبو دلف يقول ذلك ويعترف به ويقول نقلني سيدنا الشيخ الصالح قدس الله روحه ونور ضريحه عن مذهب أبي جعفر الكرخي إلى المذهب الصحيح يعني أبا بكر البغدادي. ~","27/1/47/29",""],[1,47,"وقد كان في زمان السفراء المحمودين أقوام ثقات ترد عليهم التوقيعات من قبل المنصوبين للسفارة من الأصل.","27/1/48/1",""],[2,47,"منهم أبو الحسين محمد بن جعفر الأسدي رحمه الله:","27/1/48/2",""],[3,47,"أخبرنا أبو الحسين بن أبي جيد القمي عن محمد بن الحسن بن الوليد عن محمد بن يحيى العطار عن محمد بن أحمد بن يحيى عن صالح بن أبي صالح قال: سألني بعض الناس في سنة تسعين ومائتين قبض شي‏ء فامتنعت من ذلك وكتبت أستطلع الرأي، فأتاني الجواب: بالري محمد بن جعفر العربي فليدفع إليه فإنه من ثقاتنا.","27/1/48/3",""],[4,47,"وروى محمد بن يعقوب الكليني عن أحمد بن يوسف الشاشي قال: قال لي محمد بن الحسن الكاتب المروزي: وجهت إلى حاجز الوشاء مائتي دينار وكتبت إلى الغريم بذلك فخرج الوصول وذكر أنه كان له قبلي ألف دينار وأني وجهت إليه مائتي دينار، وقال: إن أردت أن تعامل أحدا فعليك بأبي الحسين الأسدي بالري، فورد الخبر بوفاة حاجز رضي الله عنه بعد يومين أو ثلاثة فأعلمته بموته فاغتم. فقلت له: لا تغتم فإن لك في التوقيع إليك دلالتين؛ إحداهما إعلامه إياك أن المال ألف دينار،والثانية أمره إياك بمعاملة أبي الحسين الأسدي لعلمه بموت حاجز.","27/1/48/4",""],[5,47,"وبهذا الإسناد عن أبي جعفر محمد بن علي بن نوبخت قال: عزمت على الحج وتأهبت فورد علي: نحن لذلك كارهون. فضاق صدري واغتممت وكتبت: أنا مقيم بالسمع والطاعة،غير أني مغتم بتخلفي عن الحج. فوقع: لا يضيقن صدرك فإنك تحج من قابل. فلما كان من قابل استأذنت، فورد الجواب، فكتبت إني عادلت محمد بن العباس وأنا واثق بديانته وصيانته،فورد الجواب: الأسدي نعم العديل،فإن قدم فلا تختر عليه.قال: فقدم الأسدي فعادلته.","27/1/48/5",""],[6,47,"محمد بن يعقوب عن علي بن محمد عن محمد بن شاذان النيشابوري قال: اجتمع عندي خمسمائة درهم ينقص عشرون درهما فلم أحب أن ينقص هذا المقدار، فوزنت من عندي عشرين درهما ودفعتها إلى الأسدي ولم أكتب بخبر نقصانها وأني أتممتها من مالي،فورد الجواب: قد وصلت الخمسمائة التي لك فيها عشرون. ومات الأسدي على ظاهر العدالة لم يتغير ولم يطعن عليه في شهر ربيع الآخر سنة اثنتي عشرة وثلاثمائة.","27/1/48/6",""],[7,47,"ومنهم أحمد بن إسحاق وجماعة خرج التوقيع في مدحهم:","27/1/48/7",""],[8,47,"روى أحمد بن إدريس عن أحمد بن محمد بن عيسى عن أبي محمد الرازي قال: كنت وأحمد بن أبي عبد الله بالعسكر فورد علينا رسول من قبل الرجل فقال: أحمد بن إسحاق الأشعري وإبراهيم بن محمد الهمداني وأحمد بن حمزة بن اليسع ثقات.","27/1/48/8",""],[1,48,"قد بينا بالاخبار الصحيحة بأن مولد صاحب الزمان عليه السلام كان في سنة ست وخمسين ومائتين وأن أباه عليه السلام مات في سنة ستين فكانت له حينئذ أربع سنين فيكون عمره إلى حين خروجه ما يقتضيه الحساب ولا ينافي ذلك الاخبار التي رويت في مقدار سنه مختلفة الالفاظ.","27/1/49/1",""],[2,48,"نحو ما روي عن أبي جعفر عليه السلام أنه قال: ليس صاحب هذا الامر(من جاز من أربعين)، صاحب هذا الامر القوي المشمر. وما أشبه ذلك من الاخبار التي وردت مختلفة الالفاظ متباينة المعاني.","27/1/49/2",""],[3,48,"ويقوي ذلك ما رواه أبوعلي محمد بن همام، عن جعفر بن محمد بن مالك، عن عمر بن طرخان، عن محمد بن إسماعيل، عن علي بن عمر بن علي بن الحسين، عن أبي عبد الله عليه السلام قال: إن ولي الله يعمر عمر إبراهيم الخليل عشرين ومائة سنة، ويظهر في صورة فتى موفق ابن ثلاثين سنة.","27/1/49/3",""],[4,48,"وعنه، عن الحسن بن علي العاقولي، عن الحسن بن علي بن أبي حمزة، عن أبيه، عن أبي بصير، عن أبي عبد الله عليه السلام أنه قال: لو خرج القائم لقد أنكره الناس، يرجع إليهم شابا موفقا، فلا يلبث عليه إلا كل مؤمن أخذ الله ميثاقه في الذر الاول.","27/1/49/4",""],[5,48,"وروي في خبر آخر: أن في صاحب الزمان عليه السلام شبها من يونس؛رجوعه من غيبته بشرخ الشباب.","27/1/49/5",""],[6,48,"وقد روي عن أبي عبد الله عليه السلام أنه قال: ما تنكرون أن يمد الله لصاحب هذا الامر في العمر كما مد لنوح عليه السلام في العمر؟","27/1/49/6",""],[7,48,"ويروي النصارى أن فيمن تقدم من عاش سبعمائة سنة وأكثر.","27/1/49/7",""],[8,48,"وروى أبوعبيدة معمر بن المثنى البصري التيمي قال: كانت في غطفان خلة أشهرتهم بها العرب، كان منهم نصر بن دهمان، وكان من سادة غطفان وقادتها حتى خرف وحناه الاكبر، وعاش تسعين ومائة سنة، فاعتدل بعد ذلك شابا وأسود شعره، فلا يعرب في العرب أعجوبة مثله.","27/1/49/8",""],[9,48,"وأما ما روي من الاخبار التي تتضمن أن صاحب الزمان يموت ثم يعيش أو يقتل ثم يعيش، نحو ما رواه:","27/1/49/9",""],[10,48,"الفضل بن شاذان، عن موسى بن سعدان، عن عبد الله بن قاسم الحضرمي، عن أبي سعيد الخراساني قال: قلت لابي عبد الله عليه السلام: لأي شيء سمي القائم؟ قال: لأنه يقوم بعدما يموت، إنه يقوم بأمر عظيم يقوم بأمر الله سبحانه.","27/1/49/10",""],[11,48,"وروى محمد بن عبد الله بن جعفر الحميري، عن أبيه، عن يعقوب بن يزيد، عن علي بن الحكم، عن حماد بن عثمان، عن أبي بصير قال: سمعت أبا جعفر عليه السلام يقول: مثل أمرنا في كتاب الله مثل صاحب الحمار؛ أماته الله مائة عام ثم بعثه.","27/1/49/11",""],[12,48,"وعنه، عن أبيه، عن جعفر بن محمد الكوفي، عن إسحق بن محمد، عن القاسم بن الربيع، عن علي بن خطاب، عن مؤذن مسجد الاحمر قال:سألت أبـا عبد الله عليه السلام: هل في كتاب الله مثل للقائم عليه السلام؟ فقال: نعم، آية صاحب الحمار؛ أماته الله (مائة عام) ثم بعثه.","27/1/49/12",""],[13,48,"وروى الفضل بن شاذان، عن ابن أبي نجران، عن محمد بن الفضيل، عن حماد بن عبدالكريم قال: قال أبوعبد الله عليه السلام: إن القائم عليه السلام إذا قام قال الناس:أنى يكون هذا وقد بليت عظامه منذ دهر طويل؟","27/1/49/13",""],[14,48,"روى الفضل بن شاذان، عن عبد الله بن جبلة، عن سلمة بن جناح الجعفي عن حازم بن حبيب قال: قال (لي): أبو عبد الله عليه السلام: يا حازم، إن لصاحب هذا الامر غيبتين؛ يظهر في الثانية، إن جاء‌ك من يقول: إنه نفض يده من تراب قبره، فلا تصدقه.","27/1/49/14",""],[15,48,"وروى محمد بن عبد الله الحميري، عن أبيه، عن محمد بن عيسى، عن سليمان بن داود المنقري، عن أبي بصير قال: سمعت أبا جعفر عليه السلام يقول: في صاحب هذا الامر (أربع) سنن من أربعة أنبياء:سنة من موسى ، وسنة من عيسى ، وسنة من يوسف. وسنة من محمد صلى الله عليه وآله وعليهم. فأما سنة من موسى فخائف يترقب، وأما سنة من يوسف فالغيبة، وأما سنة من عيسى فيقال: مات! ولم يمت، وأما سنة من محمد صلى الله عليه وآله وسلم فالسيف.","27/1/49/15",""],[16,48,"وروى الفضل بن شاذان، عن أحمد بن عيسى العلوي، عن أبيه، عن جده قال: قال أمير المؤمنين عليه السلام: صاحب هذا الامر من ولدي (الذي) يقال:مات! قتل! لا،بل هلك! لا،بل بأي واد سلك!","27/1/49/16",""],[1,49,"وأما وقت خروجه عليه السلام فليس بمعلوم لنا على وجه التفصيل، بل هو مغيب عنا إلى أن يأذن الله بالفرج.","27/1/50/1",""],[2,49,"كما روي عن النبي صلى الله عليه وآله (أنه قال:) لو لم يبق من الدنيا إلا يوم واحد لطول الله ذلك اليوم حتى يخرج رجل من ولدي فيملا الارض عدلاً وقسطاً كما ملئت ظلماً وجوراً.","27/1/50/2",""],[3,49,"وأخبرني الحسين بن عبد الله، عن أبي جعفر محمد بن سفيان البزوفري، عن علي بن محمد، عن الفضل بن شاذان، عن أحمد بن محمد وعبيس بن هشام، عن كرام عن الفضيل قال:سألت أبا جعفر عليه السلام: هل لهذا الامر وقت؟ فقال: كذب الوقاتون، كذب الوقاتون، كذب الوقاتون.","27/1/50/3",""],[4,49,"الفضل بن شاذان، عن الحسين بن يزيد الصحاف عن منذر الجواز عن أبي عبد الله عليه السلام قال: كذب الموقتون، ما وقتنا فيما مضى، ولا نوقت فيما يستقبل.","27/1/50/4",""],[5,49,"وبهذا الاسناد عن عبدالرحمن بن كثير قال: كنت عند أبي عبد الله عليه السلام إذ دخل عليه مهزم الاسدي فقال: أخبرني، جعلت فداك،متى هذا الامر الذي تنتظرونه؟ فقد طال. فقال: يا مهزم،كذب الوقاتون، وهلك المستعجلون، ونجا المسلمون، وإلينا يصيرون.","27/1/50/5",""],[6,49,"الفضل بن شاذان، عن ابن أبي نجران، عن صفوان بن يحيى، عن أبي أيوب الخزاز، عن محمد بن مسلم، عن أبي عبد الله عليه السلام قال: من وقت لك من الناس شيئا فلا تهابن أن تكذبه، فلسنا نوقت لأحد وقت.","27/1/50/6",""],[7,49,"الفضل بن شاذان، عن عمر بن مسلم البجلي، عن محمد بن سنان، عن أبي الجارود، عن محمد بن بشر الهمداني، عن محمد بن الحنفية- في حديث اختصرنا منه موضع الحاجة- أنه قال: إن لبني فلان ملكاً مؤجلاً، حتى إذا أمنوا واطمأنوا وظنوا أن ملكهم لا يزول صيح فيهم صيحة، فلم يبق لهم راع يجمعهم ولا واع يسمعهم، وذلك قول الله عز وجل:﴿حَتَّى إِذَا أَخَذَتِ الأَرْضُ زُخْرُفَهَا وَازَّيَّنَتْ وَظَنَّ أَهْلُهَا أَنَّهُمْ قَادِرُونَ عَلَيْهَا أَتَاهَا أَمْرُنَا لَيْلاً أَوْ نَهَاراً فَجَعَلْنَاهَا حَصِيداً كَأَنْ لَمْ تَغْنَ بِالأَمْسِ كَذَلِكَ نُفَصِّلُ الآيَاتِ لِقَوْمٍ يَتَفَكَّرُونَ﴾. قلت: جعلت فداك هل لذلك وقت؟ قال: لا،لان علم الله غلب علم الموقتين، إن الله تعالى وعد موسى ثلاثين ليلة وأتمها بعشر لم يعلمها موسى، ولم يعلمها بنو إسرائيل، فلما جاوز الوقت قالوا: غرنا موسى! فعبدوا العجل. ولكن إذا كثرت الحاجة والفاقة في الناس، وأنكر بعضهم بعضا، فعند ذلك توقعوا أمر الله صباحا ومساء.","27/1/50/7",""],[8,49,"وأما ما روي من الاخبار التي تنافي ذلك في الظاهر، مثل ما رواه:","27/1/50/8",""],[9,49,"الفضل بن شاذان، عن محمد بن علي، عن سعدان بن مسلم، عن أبي بصير قال: قلت له: ألهذا الامر أمد نريح إليه أبداننا وننتهي إليه؟ قال: بلى، ولكنكم أذعتم فزاد الله فيه.","27/1/50/9",""],[10,49,"وعنه، عن الحسن بن محبوب، عن أبي حمزة الثمالي قال: قلت لأبي جعفر عليه السلام:إن عليا عليه السلام كان يقول: إلى السبعين بلاء. وكان يقول: بعد البلاء رخاء. وقد مضت السبعون ولم نر رخاء! فقال أبوجعفر عليه السلام: يا ثابت، إن الله تعالى كان وقت هذا الأمر في السبعين، فلما قتل الحسين عليه السلام إشتد غضب الله على أهل الارض فأخره إلى أربعين ومائة سنة. فحدثناكم فأذعتم الحديث وكشفتم قناع السر، فأخره الله ولم يجعل له بعد ذلك عندنا وقتا. و﴿يَمْحُو اللهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ﴾. قال أبوحمزة: وقلت ذلك لأبي عبد الله عليه السلام فقال: قد كان ذاك.","27/1/50/10",""],[11,49,"وروى الفضل، عن محمد بن إسماعيل، عن محمد بن سنان، عن أبي يحيى التمتام السلمي، عن عثمان النو قال: سمعت أبا عبد الله عليه السلام يقول: كان هذا الامر في فأخره الله ويفعل بعد في ذريتي ما يشاء.","27/1/50/11",""],[12,49,"فالوجه في هذه الاخبار أن نقول-إن صحت-إنه لا يمتنع أن يكون الله تعالى قد وقت هذا الامر في الاوقات التى ذكرت، فلما تجدد ما تجـدد تغيـرت المصلحة واقتضت تأخيـره إلى وقت آخر، وكذلك فيما بعد، ويكون الوقت الاول، وكل وقت يجوز أن يؤخر مشروطا، بأن لا يتجدد ما يقتضي المصلحة تأخيره إلى أن يجئ الوقت الذي لا يغيره شيء فيكون محتوما. وعلى هذا يتأول ما روي في تأخير الاعمار عن أوقاتها والزيادة فيها عند الدعاء (والصدقات) وصلة الارحام، وما روي في تنقيص الاعمار عن أوقاتها إلى ما قبله عند فعل الظلم وقطع الرحم وغير ذلك، وهو تعالى وإن كان عالما بالامرين، فلا يمتنع أن يكون أحدهما معلوما بشرط والآخر بلا شرط، وهذه الجملة لا خلاف فيها بين أهل العدل. وعلى هذا يتأول أيضا ما روي من أخبارنا المتضمنة للفظ البداء ويبين أن معناها النسخ على ما يريده جميع أهل العدل فيما يجوز فيه النسخ، أو تغير شروطها إن كان طريقها الخبر عن الكائنات، لان البداء في اللغة هو الظهور، فلا يمتنع أن يظهر لنا من أفعال الله تعالى ما كنا نظن خلافه، أو نعلم ولا نعلم شرطه.","27/1/50/12",""],[13,49,"فمن ذلك ما رواه محمد بن جعفر الاسدي رحمه الله، عن علي بن إبراهيم، عن الريان بن الصلت قال: سمعت أبا الحسن الرضا عليه السلام يقول: ما بعث الله نبياً إلا بتحريم الخمر، وأن يقر لله بالبداء ﴿إِنَّ اللهَ يَفْعَلُ مَا يَشَاءُ﴾، وأن يكون في تراثه الكندر.","27/1/50/13",""],[14,49,"وروى سعد بن عبد الله، عن أحمد بن محمد بن عيسى، عن أحمد بن محمد بن أبي نصر، عن أبي الحسن الرضا عليه السلام قال: (قال) علي بن الحسين، وعلي بن أبي طالب قبله، ومحمد بن علي وجعفر بن محمد عليهم السلام: كيف لنا بالحديث مع هذه الآية: ﴿يَمْحُو اللهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ﴾؟ فأما من قال: بأن الله تعالى لا يعلم بشيء إلا بعد كونه فقد كفر وخرج عن التوحيد.","27/1/50/14",""],[15,49,"وقد روى سعد بن عبد الله عن أبي هاشم الجعفري قال: سأل محمد بن صالح الارمني أبا محمد العسكري عليه السلام عن قول الله عز وجل: ﴿يَمْحُو اللهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ﴾، فقال أبومحمد: وهل يمحو إلا ما كان ويثبت إلا ما لم يكن؟ فقلت في نفسي: هذا خـلاف مـا يقول هشـام بن الحكم:إنه لا يعلم الشيء حتى يكون. فنظر إلي أبو محمد عليه السلام فقال: تعالى الجبار العالم بالاشياء قبل كونها… والحديث مختصر.","27/1/50/15",""],[16,49,"الفضل بن شاذان، عن محمد بن علي، عن سعدان بن مسلم، عن أبي بصير قال:قلت له: ألهذا الامر أمد نريح أبداننا وننتهي إليه؟ قال: بلى ولكنكم أذعتم فزاد الله فيه.","27/1/50/16",""],[17,49,"والوجه في هذه الاخبار ما قدمنا ذكره من تغير المصلحة فيه، واقتضائها تأخير الامر إلى وقت آخر على ما بيناه، دون ظهور الامر له تعالى، فأنا لا نقول به ولا نجوزه، تعالى الله عن ذلك علوا كبيرا. فإن قيل: هذا يؤدي إلى أن لا نثق بشيء من أخبار الله تعالى. قلنا: الاخبار على ضربين ضرب لا يجوز فيه التغير في مخبراته، فإنا نقطع عليها، لعلمنا بأنه لا يجوز أن يتغير المخبر في نفسه، كالاخبار عن صفات الله تعالى وعن الكائنات فيما مضى، وكالاخبار بأنه يثيب المؤمنين. والضرب الآخر هو ما يجوز تغيره في نفسه لتغير المصلحة عند تغير شروطه، فأنا نجوز جميع ذلك، كالاخبار عن الحوادث في المستقبل إلا أن يرد الخبر على وجه يعلم أن مخبره لا يتغير، فحينئذ نقطع بكونه، ولاجل ذلك قرن الحتم بكثير من المخبرات، فأعلمنا أنه مما لا يتغير أصلا، فعند ذلك نقطع به.","27/1/50/17",""],[1,50,"أخبرني الحسين بن عبد الله، عن أبي جعفر محمد بن سفيان البزوفري، عن أحمد بن إدريس، عن علي بن محمد بن قتيبة، عن الفضل بن شاذان النيشابوري، عن إسماعيل بن الصباح قال:سمعت شيخا يذكره عن سيف بن عميرة قال:كنت عند أبي جعفر المنصور فسمعته يقول ابتداء من نفسه:يا سيف بن عميرة، لا بد من مناد ينادي باسم رجل من ولد أبي طالب من السماء. فقلت: يرويه أحد من الناس؟ قال:والذي نفسي بيده فسمع أذني منه يقول:لابد من مناد ينادي باسم رجل من السماء. قلت: يا أمير المؤمنين،إن هذا الحديث ما سمعت بمثله قط. فقال:يا سيف،إذا كان ذلك فنحن أول من نجيبه، أما إنه أحد بني عمنا. قلت: أي بني عمكم؟ قال:رجل من ولد فاطمة عليها السلام. ثم قال: يا سيف، لولا أني سمعت أبا جعفر محمد بن علي (يحدثني به) ثم حدثني به أهل الدنيا ما قبلت منهم، ولكنه محمد بن علي عليهما السلام.","27/1/51/1",""],[2,50,"وأخبرني جماعة، عن التلعكبري، عن أحمد بن علي الرازي، عن محمد بن علي، عن عثمان بن أحمد السماك، عن إبراهيم بن عبد الله الهاشمي، عن يحيى بن أبي طالب، عن علي بن عاصم، عن عطاء بن السائب، عن أبيه، عن عبد الله بن عمر قال: قال رسول الله صلى الله عليه وآله:لا تقوم الساعة حتى يخرج نحو من ستين كذابا كلهم يقول أنا نبي.","27/1/51/2",""],[3,50,"أحمد بن إدريس، عن علي بن محمد بن قتيبة، عن الفضل بن شاذان، عن الحسن بن محبوب، عن أبي حمزة الثمالي قال: قلت لابي عبد الله عليه السلام:إن أبا جعفر عليه السلام كان يقول: خروج السفياني من المحتوم، والنداء من المحتوم، وطلوع الشمس من المغرب من المحتوم، وأشياء كان يقولها من المحتوم. فقال أبوعبد الله عليه السلام: واختلاف بني فلان من المحتوم، وقتل النفس الزكية من المحتوم وخروج القائم من المحتوم. قلت: وكيف يكون النداء؟ قال: ينادي مناد من السماء أول النهار يسمعه كل قوم بألسنتهم: ألا إن الحق في علي وشيعته. ثم ينادي إبليس في آخر النهار من الارض: ألا إن الحق في عثمان وشيعته، فعند ذلك يرتاب المبطلون.","27/1/51/3",""],[4,50,"وبهذا الاسناد، عن ابن فضال، عن حماد، عن الحسين بن المختار، عن أبي نصر، عن عامر بن واثلة، عن أمير المؤمنين عليه السلام قال: قال رسول الله صلى الله عليه وآله: عشر قبل الساعة لابد منها: السفياني، والدجال، والدخان، والدابة وخروج القائم، وطلوع الشمس من مغربها، ونزول عيسى عليه السلام، وخسف بالمشرق وخسف بجزيرة العرب، ونار تخرج من قعر عدن تسوق الناس إلى المحشر.","27/1/51/4",""],[5,50,"وبهذا الاسناد، عن ابن فضال، عن حماد، عن إبراهيم بن عمر، عن عمر بن حنظلة، عن أبي عبد الله عليه السلام قال: خمس قبل قيام القائم من العلامات: الصيحة والسفياني، والخسف بالبيداء، وخروج اليماني، وقتل النفس الزكية.","27/1/51/5",""],[6,50,"الفضل بن شاذان، عن الحسن بن علي الوشاء، عن أحمد بن عائذ، عن أبي خديجة قال: قال أبوعبد الله عليه السلام: لا يخرج القائم حتى يخرج اثنا عشر من بني هاشم كلهم يدعو إلى نفسه.","27/1/51/6",""],[7,50,"وعنه، عن عبد الله بن جبلة، عن أبي عمار، عن علي بن أبي المغيرة، عن عبد الله بن شريك العامري عن عميرة بنت نفيل، قالت: سمعت الحسن بن علي عليهما السلام يقول: لا يكون هذا الامر الذي تنتظرون حتى يبرأ بعضكم من بعض، ويلعن بعضكم بعضا، ويتفل بعضكم في وجه بعض، وحتى يشهد بعضكم بالكفر على بعض. قلت: ما في ذلك خير؟. قال: الخير كله في ذلك، عند ذلك يقوم قائمنا، فيرفع ذلك كله.","27/1/51/7",""],[8,50,"وروى الفضل، عن علي بن أسباط، عن محمد بن أبي البلاد، عن علي بن محمد الاودي، عن أبيه، عن جده قال: قال أمير المؤمنين عليه السلام: بين يدي القائم موت أحمر، وموت أبيض، وجراد في حينه، وجراد في غير حينه، أحمر كألوان الدم. فأما الموت الاحمر فالسيف، وأما الموت الابيض فالطاعون.","27/1/51/8",""],[9,50,"سعد بن عبدالله، عن الحسن بن علي الزيتوني وعبدالله بن جعفر الحميري (مع) عن أحمد بن هلال العبرتائي، عن الحسن بن محبوب، عن أبي الحسن الرضا عليه السلام-في حديث له طويل اختصرنا منه موضع الحاجة-أنه قال: لابد من فتنة صماء صيلم يسقط فيها كل بطانة ووليجة، وذلك عند فقدان الشيعة الثالث من ولدي، يبكي عليه أهل السماء وأهل الارض، وكم من مؤمن متأسف حران حزين عند فقد الماء المعين. كأني بهم أسر ما يكونون، وقد نودوا نداء يسمعه من بعد كما يسمعه من قرب، يكون رحمة للمؤمنين وعذابا للكافرين. فقلت: وأي نداء هو؟ قال: ينـادون في رجب ثلاثة أصوات من السماء:صوتا منها ﴿أَلاَ لَعْنَةُ اللهِ عَلَى الظَّالِمِينَ﴾ والصوت الثاني: ﴿أَزِفَتِ الآزِفَةُ﴾ يا معشر المؤمنين. والصوت الثالث- يرون بدنا بارزا نحو عين الشمس-: هذا أمير المؤمنين قد كر في هلاك الظالمين. وفي رواية الحميري: والصوت (الثالث) بدن يرى في قرن الشمس يقول: إن الله بعث فلانا فاسمعوا له وأطيعوا. وقالا جميعا: فعند ذلك يأتي الناس الفرج، وتود الناس لو كانوا أحياء: ويشفي الله صدور قوم مؤمنين.","27/1/51/9",""],[10,50,"الفضل بن شاذان، عن نصر بن مزاحم، عن ابن لهيعة، عن أبي زرعة، عن عبد الله بن رزين، عن عمار بن ياسر رضي الله عنه، أنه قال: دعوة أهل بيت نبيكم في آخر الزمان، فالزموا الأرض وكفوا حتى تروا قادتها، فإذا خالف الترك الروم وكثرت الحروب في الأرض، ينادي مناد على سور دمشق: ويل لازم من شر قد اقترب! ويخرب حائط مسجدها.","27/1/51/10",""],[11,50,"الفضل، عن ابن أبي نجران، عن محمد بن سنان، عن أبي الجارود، عن محمد بن بشر، عن محمد بن الحنفية قال: قلت له: قد طال هذا الأمر حتى متى؟ قال: فحرك رأسه ثم قال: أنى يكون ذلك ولم يعض الزمان؟ أنى يكون ذلك ولم يجفوا الاخوان؟ أنى يكون ذلك ولم يظلم السلطان؟ أنى يكون ذلك ولم يقم الزنديق من قزوين فيهتك ستورها ويكفر صدورها ويغير سورها ويذهب بهجتها؟ من فر منه أدركه، ومن حاربه قتله، ومن اعتزله افتقر، ومن تابعه كفر حتى يقوم باكيان: باك يبكي على دينه وباك يبكي على دنياه.","27/1/51/11",""],[12,50,"الفضل، عن الحسن بن محبوب، عن عمرو بن أبي المقدام، عن جابر الجعفي، عن أبي جعفر عليه السلام قال:الزم الأرض ولا تحرك يدا ولا رجلا حتى ترى علامات أذكرها لك وما أراك تدرك:اختلاف بني فلان، ومناد ينادي من السماء، ويجيئكم الصوت من ناحية دمشق بالفتح، وخسف قرية من قرى الشام تسمى الجابية. وستقبل إخوان الترك حتى ينزلوا الجزيرة، وستقبل مارقة الروم حتى ينزلوا الرملة، فتلك السنة فيها اختلاف كثير في كل أرض من ناحية المغرب. فأول أرض تخرب الشام، يختلفون عند ذلك على ثلاث رايات:راية الأصهب، وراية الأبقع، وراية السفياني.","27/1/51/12",""],[13,50,"أحمد بن علي الرازي، عن المقانعي عن بكار بن أحمد، عن حسن بن حسين، عن عبد الله بن بكير، عن عبد الملك بن إسماعيل الأسدي، عن أبيه قال: حدثني سعيد بن جبير قال:السنة التي يقوم فيها المهدي تمطر أربعا وعشرين مطرة يرى أثرها وبركتها.","27/1/51/13",""],[14,50,"وروي عن كعب الأحبار أنه قال: إذا ملك رجل من بني العباس يقال له: عبد الله وهو ذو العين بها افتتحوا وبها يختمون، وهو مفتاح البلاء وسيف الفناء فإذا قرئ له كتاب بالشام من عبد الله عبد الله أمير المؤمنين لم تلبثوا أن يبلغكم أن كتابا قرئ على منبر مصر:من عبد الله عبد الرحمان أمير المؤمنين.وفي حديث آخر قال: الملك لبني العباس حتى يبلغكم كتاب قرئ بمصر من عبد الله عبد الرحمان أمير المؤمنين، وإذا كان ذلك فهو زوال ملكهم وانقطاع مدتهم، فإذا قرئ عليكم أول النهار لبني العباس من عبد الله (عبد الله) أمير المؤمنين فانتظروا كتابا يقرأ عليكم [من آخر النهار] من عبد الله عبد الرحمان أمير المؤمنين.وويل لعبد الله من عبد الرحمن.","27/1/51/14",""],[15,50,"وروى حذلم بن بشير قال:قلت لعلي بن الحسين عليهما السلام:صف لي خروج المهدي وعرفني دلائله وعلاماته. فقال: يكون قبل خروجه خروج رجل يقال له: عوف السلمي بأرض الجزيرة، ويكون مأواه تكريت وقتله بمسجد دمشق ثم يكون خروج شعيب بن صالح من سمرقند.ثم يخرج السفياني الملعون من الوادي اليابس وهو من ولد عتبة بن أبي سفيان، فإذا ظهر السفياني اختفى المهدي ثم يخرج بعد ذلك.","27/1/51/15",""],[16,50,"وروي عن النبي صلى الله عليه وآله [أنه] قال:يخرج بقزوين رجل اسمه اسم نبي، يسرع الناس إلى طاعته، المشرك والمؤمن، يملا الجبال خوفا.","27/1/51/16",""],[17,50,"الفضل بن شاذان، عن أحمد بن محمد بن أبي نصر، عن ثعلبة، عن بدر بن الخليل الأزدي قال: قال أبو جعفر عليه السلام: آيتان تكونان قبل القائم لم تكونا منذ هبط آدم عليه السلام إلى الأرض: تنكسف الشمس في النصف من شهر رمضان والقمر في آخره. فقال رجل: يا بن رسول الله تنكسف الشمس في آخر الشهر والقمر في النصف؟ فقال أبو جعفر عليه السلام:إني لاعلم بما تقول ولكنهما آيتان لم تكونا منذ هبط آدم عليه السلام.","27/1/51/17",""],[18,50,"الفضل، عن الحسن بن علي بن فضال، عن ثعلبة، عن شعيب الحداد، عن صالح قال: سمعت أبا عبد الله عليه السلام يقول: ليس بين قيام القائم وبين قتل النفس الزكية إلا خمس عشره ليلة.","27/1/51/18",""],[19,50,"وعنه، عن نصر بن مزاحم، عن عمرو بن شمر، عن جابر قال:قلت لأبي جعفر عليه السلام: متى يكون هذا الامر؟ فقال عليه السلام:أنى يكون ذلك يا جابر ولما تكثر القتلى بين الحيرة والكوفة؟!","27/1/51/19",""],[20,50,"عنه، عن ابن أبي نجران، عن محمد بن سنان، عن الحسين بن المختار، عن أبي عبد الله عليه السلام قال: إذا هدم حائط مسجد الكوفة مؤخره مما يلي دار عبد الله بن مسعود فعند ذلك زوال (ملك) بني فلان، أما إن هادمه لا يبنيه.","27/1/51/20",""],[21,50,"وعنه، عن سيف بن عميرة، عن بكر بن محمد الأزدي، عن أبي عبد الله عليه السلام قال: خروج الثلاثة: الخراساني والسفياني واليماني في سنة واحدة في شهر واحد في يوم واحد، وليس فيها راية بأهدى من راية اليماني يهدي إلى الحق.","27/1/51/21",""],[22,50,"عنه، عن ابن فضال، عن ابن بكير، عن محمد بن مسلم قال: يخرج قبل السفياني مصري ويماني.","27/1/51/22",""],[23,50,"عنه، عن عثمان بن عيسى، عن درست بن أبي منصور، عن عمار بن مروان، عن أبي بصير قال: سمعت أبا عبد الله عليه السلام يقول: من يضمن لي موت عبد الله أضمن له القائم. ثم قال: إذا مات عبد الله لم يجتمع الناس بعده على أحد ولم يتناه هذا الأمر دون صاحبكم إن شاء الله، ويذهب ملك السنين ويصير ملك الشهور والأيام. فقلت: يطول ذلك؟ قال: كلا.","27/1/51/23",""],[24,50,"عنه، عن محمد بن علي، عن سلام بن عبد الله، عن أبي بصير، عن بكر بن حرب، عن أبي عبد الله عليه السلام قال: لا يكون فساد ملك بني فلان حتى يختلف سيفا بني فلان، فإذا اختلفا كان عند ذلك فساد ملكهم.","27/1/51/24",""],[25,50,"الفضل، عن أحمد بن محمد بن أبي نصر، عن أبي الحسن الرضا عليه السلام قال:إن من علامات الفرج حدثا يكون بين الحرمين. قلت: وأي شئ (يكون) الحدث؟ فقال:عصبية تكون بين الحرمين، ويقتل فلان من ولد فلان خمسة عشر كبشا.","27/1/51/25",""],[26,50,"وعنه، عن ابن فضال وابن أبي نجران، عن حماد بن عيسى، عن إبراهيم بن عمر اليماني، عن أبي بصير، عن أبي عبد الله عليه السلام قال: لا يذهب ملك هؤلاء حتى يستعرضوا الناس بالكوفة يوم الجمعة، لكأني أنظر إلى رؤس تندر فيما بين المسجد وأصحاب الصابون.","27/1/51/26",""],[27,50,"وعنه، عن علي بن أسباط، عن الحسن بن الجهم قال:سأل الرجل أبا الحسن عليه السلام عن الفرج، فقال :ما تريد، الاكثار أو أجمل لك؟ فقال: أريد تجمله لي.فقال: إذا تحركت رايات قيس بمصر ورايات كندة بخراسان. أو ذكر غير كندة.","27/1/51/27",""],[28,50,"عنه، عن الحسن بن محبوب، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله عليه السلام قال: إن قدام القائم لسنة غيداقة يفسد التمر في النخل فلا تشكوا في ذلك.","27/1/51/28",""],[29,50,"وعنه، عن أحمد بن عمر بن سالم، عن يحيى بن علي، عن الربيع، عن أبي لبيد، قال: تغير الحبشة البيت فيكسرونه، ويؤخذ الحجر فينصب في مسجد الكوفة.","27/1/51/29",""],[30,50,"وعنه، عن ابن أبي عمير، عن عمر بن أذينة، عن محمد بن مسلم قال: سمعت أبا عبد الله عليه السلام يقول: إن السفياني يملك بعد ظهوره على الكور الخمس حمل امرأة. ثم قال عليه السلام:أستغفر الله حمل جمل، وهو من الامر المحتوم الذي لابد منه.","27/1/51/30",""],[31,50,"عنه، عن إسماعيل بن مهران، عن عثمان بن جبلة، عن عمر بن أبان الكلبي، عن أبي عبد الله عليه السلام قال: كأني بالسفياني أو لصاحب السفياني قد طرح رحله في رحبتكم بالكوفة، فنادى مناديه: من جاء برأس [رجل من] شيعة علي فله ألف درهم، فيثب الجار على جاره يقول: هذا منهم، فيضرب عنقه ويأخذ ألف درهم. أما إن إمارتكم يومئذ لا تكون إلا لأولاد البغايا، (و) كأني أنظر إلى صاحب البرقع. قلت: ومن صاحب البرقع؟. فقال: رجل منكم يقول بقولكم يلبس البرقع فيحوشكم فيعرفكم ولا تعرفونه، فيغمز بكم رجلا رجلا، أما [إنه] لا يكون إلا ابن بغي.","27/1/51/31",""],[32,50,"عنه، عن علي بن الحكم، عن المثنى، عن أبي بصير قال: قال أبو عبد الله عليه السلام: لينصرن الله هذا الامر بمن لا خلاق له ولو قد جاء أمرنا لقد خرج منه من هو اليوم مقيم على عبادة الأوثان.","27/1/51/32",""],[33,50,"وعنه، عن الحماني، عن محمد بن الفضيل، عن الأجلح، عن عبد الله بن [أبي] الهذيل، قال: لا تقوم الساعة حتى يجتمع كل مؤمن بالكوفة.","27/1/51/33",""],[34,50,"أحمد بن علي الرازي، عن محمد بن إسحاق المقرئ، عن المقانعي، عن بكار، عن إبراهيم بن محمد، عن جعفر بن سعيد الأسدي، عن (أبيه)، عن أبي عبد الله عليه السلام.قال: عام أو سنة الفتح ينشق الفرات حتى يدخل أزقة الكوفة.","27/1/51/34",""],[35,50,"أحمد بن علي الرازي، عن محمد بن إسحاق المقرئ، عن المقانعي، عن بكار، عن إبراهيم بن محمد، عن جعفر بن سعيد الأسدي، عن (أبيه)، عن أبي عبد الله عليه السلام.قال: عام أو سنة الفتح ينشق الفرات حتى يدخل أزقة الكوفة.","27/1/51/35",""],[36,50,"الفضل بن شاذان، عن محمد بن علي الكوفي، عن وهيب بن حفص، عن أبي بصير قال: قال أبو عبد الله عليه السلام: إن القائم صلوات الله عليه ينادي اسمه ليلة ثلاث وعشرين، ويقوم يوم عاشوراء يوم قتل فيه الحسين بن علي عليهما السلام.","27/1/51/36",""],[37,50,"الفضل، عن محمد بن علي، عن محمد بن سنان، عن حي بن مروان عن علي بن مهزيار قال: قال أبو جعفر عليه السلام: كأني بالقائم يوم عاشوراء يوم السبت قائما بين الركن والمقام، بين يديه جبرئيل عليه السلام ينادي: البيعة لله، فيملأها عدلا كما ملئت ظلما وجورا.","27/1/51/37",""],[38,50,"[الفضل، عن ابن محبوب، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله عليه السلام، قال: لا يخرج القائم إلا في وتر من السنين تسع وثلاث وخمس وإحدى].","27/1/51/38",""],[39,50,"الفضل، عن ابن محبوب، عن علي بن أبي حمزة، عن أبي عبد الله عليه السلام قال: خروج القائم من المحتوم. قلت: وكيف يكون النداء؟. قال: ينادي مناد من السماء أول النهار: ألا إن الحق في علي وشيعته. ثم ينادي إبليس لعنه الله في آخر النهار: ألا إن الحق في عثمان وشيعته، فعند ذلك يرتاب المبطلون.","27/1/51/39",""],[40,50,"وعنه، عن ابن محبوب، عن أبي أيوب، عن محمد بن مسلم قال: ينادي مناد من السماء باسم القائم عليه السلام، فيسمع ما بين المشرق إلى المغرب، فلا يبقى راقد إلا قام، ولا قائم إلا قعد، ولا قاعد إلا قام على رجليه من ذلك الصوت، وهو صوت جبرئيل الروح الأمين.","27/1/51/40",""],[41,50,"وعنه، عن إسماعيل بن عياش، عن الأعمش، عن أبي وائل، عن حذيفة قال: سمعت رسول الله صلى الله عليه وآله وسلم وذكر المهدي فقال: إنه يبايع بين الركن والمقام، اسمه أحمد و عبد الله والمهدي، فهذه أسماؤه ثلاثتها.","27/1/51/41",""],[42,50,"عنه، عن ابن أبي عمير وابن بزيع، عن منصور بن يونس، عن إسماعيل بن جابر، عن أبي خالد الكابلي، عن أبي جعفر عليه السلام قال: إذا دخل القائم الكوفة لم يبق مؤمن إلا وهو بها أو يجئ إليها -وهو قول أمير المؤمنين عليه السلام -ويقول لأصحابه: سيروا بنا إلى هذه الطاغية! فيسير إليه.","27/1/51/42",""],[43,50,"سعد بن عبد الله الأشعري، عن محمد بن عيسى بن عبيد، عن صالح بن محمد، عن هانئ التمار قال: قال لي أبو عبد الله عليه السلام: إن لصاحب هذا الامر غيبة المتمسك فيها بدينه كالخارط للقتاد بيديه. ثم قال: هكذا بيده، فأيكم يمسك شوك القتاد بيده؟ ثم قال: إن لصاحب هذا الامرغيبة فليتق الله عبد وليتمسك بدينه.","27/1/51/43",""],[44,50,"عن الفضل بن شاذان، عن إسماعيل بن مهران، عن أيمن بن محرز، عن رفاعة بن موسى ومعاوية بن وهب، عن أبي عبد الله عليه السلام قال: قال رسول الله صلى الله عليه وآله وسلم:طوبى لمن أدرك قائم أهل بيتي وهو مقتد به قبل قيامه، يتولى وليه ويتبرأ من عدوه، ويتولى الأئمة الهادية من قبله، أولئك رفقائي وذوو ودي ومودتي، وأكرم أمتي علي. قال رفاعة:…وأكرم خلق الله علي.","27/1/51/44",""],[45,50,"عنه، عن الحسن بن محبوب، عن عبد الله بن سنان، عن أبي عبد الله عليه السلام قال:قال رسول الله صلى الله عليه وآله:سيأتي قوم من بعدكم الرجل الواحد منهم له أجر خمسين منكم.قالوا:يا رسول الله نحن كنا معك ببدر وأحد وحنين ونزل فينا القرآن.فقال:إنكم لو تحملون لما حملوا لم تصبروا صبرهم.","27/1/51/45",""],[46,50,"سعد، عن أحمد بن محمد بن عيسى، عن محمد بن خالد البرقي، عمن حدثه، عن المفضل بن عمر الجعفي قال: قال أبو عبد الله عليه السلام: أقرب ما يكون العباد من الله وأرضى ما يكون عنهم إذا افتقدوا حجة الله فلم يظهر لهم ولم يعلموا بمكانه، وهم في ذلك يعلمون أنه لم تبطل حجة الله ولا ميثاقه، فعندها توقعوا الفرج صباحا ومساء، فإن أشد ما يكون غضب الله على أعدائه إذا افتقدوا حجته، فلم يظهر لهم.وقد علم أن أولياءه لا يرتابون، ولو علم أنهم يرتابون ما غيب (عنهم) حجته طرفة عين، ولا يكون ذلك إلا على رأس أشرار الناس.","27/1/51/46",""],[47,50,"الفضل، عن ابن أبي نجران، عن محمد بن سنان، عن خالد العاقولي، في حديث له عن أبي عبد الله عليه السلام أنه قال:فما تمدون أعينكم؟ فما تستعجلون؟ ألستم آمنين؟ أليس الرجل منكم يخرج من بيته فيقضي حوائجه ثم يرجع لم يختطف؟ إن كان من قبلكم [من هو] على ما أنتم عليه ليؤخذ الرجل منهم فتقطع يداه ورجلاه ويصلب على جذوع النخل وينشر بالمنشار، ثم لا يعدو ذنب نفسه. ثم تلا هذه الآية ﴿أَمْ حَسِبْتُمْ أَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا مِنْ قَبْلِكُمْ مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ وَزُلْزِلُوا حَتَّى يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَى نَصْرُ اللهِ أَلاَ إِنَّ نَصْرَ اللهِ قَرِيبٌ﴾.","27/1/51/47",""],[48,50,"الفضل، عن محمد بن علي، عن جعفر بن بشير، عن خالد بن أبي عمارة، عن المفضل بن عمر قال: ذكرنا القائم عليه السلام ومن مات من أصحابنا ينتظره، فقال لنا أبو عبد الله عليه السلام: إذا قام أتى المؤمن في قبره فيقال له: يا هذا !إنه قد ظهر صاحبك، فإن تشأ أن تلحق به فالحق، وإن تشأ أن تقيم في كرامة ربك فأقم.","27/1/51/48",""],[49,50,"عنه، عن ابن أسباط، عن الحسن بن الجهم قال: سألت أبا الحسن عليه السلام عن شئ من الفرج.فقال:أو لست تعلم أن انتظار الفرج من الفرج؟ قلت: لا أدري إلا أن تعلمني. فقال: نعم، انتظار الفرج من الفرج.","27/1/51/49",""],[50,50,"عنه، عن ابن فضال، عن ثعلبة بن ميمون قال:أعرف إمامك [فإنك] إذا عرفته لم يضرك تقدم هذا الامر أو تأخر، ومن عرف إمامه ثم مات قبل أن يرى هذا الامر ثم خرج القائم عليه السلام كان له من الاجر كمن كان مع القائم في فسطاطه.","27/1/51/50",""],[51,50,"عنه، عن عبد الرحمان بن أبي هاشم، عن علي بن أبي حمزة، عن أبي بصير قال: سمعت أبا عبد الله عليه السلام يقول: ما تستعجلون بخروج القائم؟ فوالله ما لباسه إلا الغليظ، وما طعامه إلا الشعير الجشب. وما هو إلا السيف، والموت تحت ظل السيف.","27/1/51/51",""],[52,50,"عنه، عن ابن فضال، عن المثنى الحناط، عن عبد الله بن عجلان، عن أبي عبد الله عليه السلام قال: من عرف هذا الامر ثم مات قبل أن يقوم القائم عليه السلام كان له مثل أجر من قتل معه.","27/1/51/52",""],[53,50,"ابن أبي عمير، عن جميل بن دراج، عن زرارة، عن جعفر بن محمد عليهما السلام أنه قال: حقيق على الله أن يدخل الضلال الجنة. فقال زرارة: كيف ذلك جعلت فداك؟ قال:يموت الناطق ولا ينطق الصامت، فيموت المرء بينهما فيدخله الله الجنة.","27/1/51/53",""],[54,50,"أخبرنا جماعة، عن أبي المفضل الشيباني، عن أبي نعيم نصر بن عصام بن المغيرة العمري، عن أبي يوسف يعقوب بن نعيم بن عمرو قرقارة الكاتب، عن أحمد بن محمد الأسدي، عن محمد بن أحمد، عن إسماعيل بن عياش، عن مهاجر بن حكيم، عن معاوية بن سعيد، عن أبي جعفر محمد بن علي عليهما السلام قال: قال علي بن أبي طالب عليه السلام :إذا اختلف رمحان بالشام فهو آية من آيات الله تعالى. قيل: ثم مه؟ قال: ثم رجفة تكون بالشام يهلك فيها مائة ألف يجعلها الله رحمة للمؤمنين وعذابا على الكافرين. فإذا كان ذلك فانظروا إلى أصحاب البراذين الشهب، والرايات الصفر تقبل من المغرب حتى تحل الشام. فإذا كان ذلك فانتظروا خسفا بقرية من قرى الشام يقال لها حرستا، فإذا كان ذلك فانتظروا ابن آكلة الأكباد بوادي اليابس.","27/1/51/54",""],[55,50,"قرقارة، عن محمد بن خلف، عن الحسن بن صالح بن الأسود، عن عبد الجبار بن العباس الهمداني، عن عمار الدهني قال: قال أبو جعفر عليه السلام: كم تعدون بقاء السفياني فيكم؟ قال: قلت: حمل امرأة تسعة أشهر.قال: ما أعلمكم يا أهل الكوفة.","27/1/51/55",""],[56,50,"عنه، عن أبي النصر إسماعيل بن عبد الله بن ميمون بن عبد الحميد بن أبي الرجال العجلي قال: حدثنا محمد بن عبد الرحمان بن أبي ليلى قال: حدثنا جعفر بن سعد الكاهلي، عن الأعمش، عن بشر بن غالب قال: يقبل السفياني من بلاد الروم متنصرا في عنقه صليب وهو صاحب القوم.","27/1/51/56",""],[57,50,"قرقارة، عن نصر بن الليث المروزي، عن ابن طلحة الجحدري قال: حدثنا عبد الله بن لهيعة، عن أبي زرعة، عن أبي عبد الله بن رزين، عن عمار بن ياسر أنه قال: إن دولة أهل بيت نبيكم في آخر الزمان، ولها إمارات، فإذا رأيتم فالزموا الأرض وكفوا حتى تجئ إماراتها. فإذا استثارت عليكم الروم والترك، وجهزت الجيوش، ومات خليفتكم الذي يجمع الأموال، واستخلف بعده رجل صحيح، فيخلع بعد سنين من بيعته، ويأتي هلاك ملكهم من حيث بدأ ويتخالف الترك والروم، وتكثر الحروب في الأرض، وينادي مناد من سور دمشق: ويل لأهل الأرض من شر قد اقترب، ويخسف بغربي مسجدها حتى يخر حائطها، ويظهر ثلاثة نفر بالشام كلهم يطلب الملك، رجل أبقع، ورجل أصهب، ورجل من أهل بيت أبي سفيان يخرج في كلب، ويحضر الناس بدمشق، ويخرج أهل الغرب إلى مصر.فإذا دخلوا فتلك إمارة السفياني، ويخرج قبل ذلك من يدعو لآل محمد عليهم السلام، وتنزل الترك الحيرة، وتنزل الروم فلسطين، ويسبق عبد الله (عبد الله) حتى يلتقي جنودهما بقرقيسياء على النهر، ويكون قتال عظيم، ويسير صاحب المغرب فيقتل الرجال ويسبي النساء، ثم يرجع في قيس حتى ينزل الجزيرة السفياني، فيسبق اليماني [فيقتل] ويحوز السفياني ما جمعوا.ثم يسير إلى الكوفة فيقتل أعوان آل محمد صلى الله عليه وآله وسلم ويقتل رجلا من مسميهم. ثم يخرج المهدي على لوائه شعيب بن صالح، وإذا رأى أهل الشام قد اجتمع أمرها على ابن أبي سفيان فألحقوا بمكة، فعند ذلك تقتل النفس الزكية وأخوه بمكة ضيعة، فينادي مناد من السماء:أيها الناس إن أميركم فلان، وذلك هو المهدي الذي يملأ الأرض قسطا وعدلا كما ملئت ظلما وجورا.","27/1/51/57",""],[58,50,"عنه، عن محمد بن خلف الحداد [ي]، عن إسماعيل بن أبان الأزدي، عن سفيان بن إبراهيم الجريري أنه سمع أباه يقول: النفس الزكية غلام من آل محمد اسمه: محمد بن الحسن يقتل بلا جرم ولا ذنب، فإذا قتلوه لم يبق لهم في السماء عاذر ولا في الأرض ناصر. فعند ذلك يبعث الله قائم آل محمد في عصبة لهم أدق في أعين الناس من الكحل، إذا خرجوا بكى لهم الناس، لا يرون إلا أنهم يختطفون، يفتح الله لهم مشارق الأرض ومغاربها، ألا وهم المؤمنون حقا، ألا إن خير الجهاد في آخر الزمان.","27/1/51/58",""],[59,50,"عنه، عن أبي حاتم، عن محمد بن يزيد الآدمي - بغدادي عابد- قال: حدثنا يحيى بن سليم الطائفي، عن متيل بن عباد قال: سمعت أبا الطفيل يقول: سمعت علي بن أبي طالب عليه السلام يقول: أظلتكم فتنة (مظلمة) عمياء منكشفة لا ينجو منها إلا النومة. قيل: يا أبا الحسن وما النومة؟ قال: الذي لا يعرف الناس ما في نفسه.","27/1/51/59",""],[60,50,"عنه، عن العباس بن يزيد البحراني، عن عبد الرزاق بن همام، عن معمر، عن ابن طاوس، عن علي بن عبد الله بن عباس قال: لا يخرج المهدي حتى يطلع مع الشمس آية.","27/1/51/60",""],[1,51,"محمد بن عبدالله بن جعفر الحميري، عن أبيه، عن محمد بن عيسى، عن محمد بن عطاء، عن سلام بن أبي عمرة قال: قال أبوجعفر عليه السلام: لصاحب هذا الامر بيت يقال له: بيت الحمد، فيه سراج يزهر منذ يوم ولد إلى أن يقوم بالسيف.","27/1/52/1",""],[2,51,"أخبرنا جماعة، عن التلعكبري، عن علي بن حبشي، عن جعفر بن مالك، عن أحمد بن أبي نعيم، عن إبراهيم بن صالح، عن محمد بن غزال، عن مفضل بن عمر قال:سمعت أبا عبدالله عليه السلام يقول: إن قائمنا إذا قام أشرقت الارض بنور ربها، واستغنى الناس ويعمر الرجل في ملكه حتى يولد له ألف ذكر لا يولد فيهم أنثى، ويبني في ظهر الكوفة مسجدا له ألف باب، وتتصل بيوت الكوفة بنهر كربلا وبالحيرة، حتى يخرج الرجل يوم الجمعة على بغلة سفواء يريد الجمعة فلا يدركها.","27/1/52/2",""],[3,51,"أخبرنا أبومحمد المحمدي، عن محمد بن علي بن الفضل، عن أبيه، عن محمد بن إبراهيم بن مالك، عن إبراهيم بن بنان الخثعمي، عن أحمد بن يحيى بن المعتمر، عن عمرو بن ثابت، عن أبيه، عن أبي جعفر عليه السلام- في حديث طويل- قال: يدخل المهدي الكوفة، وبها ثلاث رايات قد اضطربت بينها، فتصفو له فيدخل حتى يأتي المنبر ويخطب، ولا يدري الناس ما يقول من البكاء، وهو قول رسول الله صلى الله عليه وآله: كأني بالحسني والحسيني وقد قاداها فيسلمها إلى الحسيني فيبايعونه. فإذا كانت الجمعة الثانية قال الناس: يا بن رسول الله، الصلاة خلفك تضاهي الصلاة خلف رسول الله صلى الله عليه وآله وسلم والمسجد لا يسعنا. فيقول: أنا مرتاد لكم، فيخرج إلى الغري فيخط مسجدا له ألف باب يسع الناس، عليه أصيص ويبعث فيحفر من خلف قبر الحسين عليه السلام لهم نهرا يجري إلى الغريين حتى ينبذ في النجف ويعمل على فوهته قناطر وأرحاء في السبيل، وكأني بالعجوز وعلى رأسها مكتل فيه بر حتى تطحنه بكربلاء.","27/1/52/3",""],[4,51,"الفضل بن شاذان، عن إسماعيل بن عياش، عن الاعمش، عن أبي وائل، عن حذيفة بن اليمان، قال: سمعت رسول الله صلى الله عليه وآله وسلم يقول وذكر المهدي: إنه يبايع بين الركن والمقام إسمه أحمد وعبدالله والمهدي فهذه أسماؤه ثلاثتها.","27/1/52/4",""],[5,51,"سعد بن عبدالله، عن محمد بن عيسى بن عبيد، عن إسماعيل بن أبان، عن عمرو بن شمر، عن جابر الجعفي، قال: سمعت أبا جعفر عليه السلام يقول: سأل عمر بن الخطاب أمير المؤمنين عليه السلام فقال: أخبرني عن المهدي ما اسمه؟ فقال: أما إسمه فإن حبيبي شهد إلي أن لا أحدث باسمه حتى يبعثه الله. قال: فأخبرني عن صفته؟ قال: هو شاب مربوع، حسن الوجه، حسن الشعر، يسيل شعره على منكبيه ونور وجهه يعلو سواد لحيته ورأسه، بأبي ابن خيرة الاماء.","27/1/52/5",""],[6,51,"الفضل بن شاذان، عن عثمان بن عيسى، عن صالح بن أبي الاسود، عن أبي عبدالله عليه السلام قال ذكر مسجد السهلة فقال: أما إنه منزل صاحبنا إذا قدم بأهله.","27/1/52/6",""],[7,51,"عنه، عن موسى بن سعدان، عن عبدالله بن القاسم الحضرمي، عن أبي سعيد الخراساني قال: قلت لابي عبدالله عليه السلام: المهدي والقائم واحد؟ فقال: نعم. فقلت: لأي شيء سمي المهدي؟ قال: لأنه يهدي إلى كل أمر خفي، وسمي القائم لأنه يقوم بعدما يموت، إنه يقوم بأمر عظيم.","27/1/52/7",""],[8,51,"عنه، عن ابن محبوب، عن عمرو بن شمر، عن جابر، عن أبي جعفر عليه السلام قال: من أدرك منكم قائمنا فليقل حين يراه: السلام عليكم يا أهل بيت النبوة ومعدن العلم وموضع الرسالة.","27/1/52/8",""],[9,51,"عنه، عن عبدالرحمان بن أبي هاشم، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبدالله عليه السلام قال: إن أصحاب موسى ابتلوا بنهر، وهو قول الله عز وجل:﴿إِنَّ اللهَ مُبْتَلِيكُمْ بِنَهَرٍ﴾ وإن أصحاب القائم يبتلون بمثل ذلك.","27/1/52/9",""],[10,51,"عنه، عن عبدالرحمان، عن ابن أبي حمزة، عن أبي بصير، عن أبي عبدالله عليه السلام قال: القائم يهدم المسجد الحرام حتى يرده إلى أساسه، ومسجد الرسول صلى الله عليه وآله إلى أساسه، ويرد البيت إلى موضعه، وأقامه على أساسه، وقطع أيدي بني شيبة السراق وعلقها على الكعبة.","27/1/52/10",""],[11,51,"عنه، عن علي بن الحكم، عن سفيان الجريري، عن أبي صادق، عن أبي جعفر عليه السلام قال: دولتنا آخر الدول، ولن يبقىأهل بيت لهم دولة إلا ملكوا قبلنا لئلا يقولوا إذا رأوا سيرتنا: إذا ملكنا سرنا مثل سيرة هؤلاء. وهو قول الله عز وجل: ﴿وَالْعَاقِبَةُ لِلْمُتَّقِينَ﴾.","27/1/52/11",""],[12,51,"عنه، عن عبدالرحمان بن أبي هاشم والحسن بن علي، عن أبي خديجة عن أبي عبدالله عليه السلام قال: إذا قام القائم عليه السلام جاء بأمر غير الذي كان.","27/1/52/12",""],[13,51,"عنه، عن علي بن الحكم، عن الربيع بن محمد المسلي، عن سعد بن ظريف، عن الاصبغ بن نباتة قال: قال أمير المؤمنين عليه السلام في حديث له حتى انتهى إلى مسجد الكوفة، وكان مبنيا بخزف ودنان وطين، فقال: ويل لمن هدمك! وويل لمن سهل هدمك! وويل لبانيك بالمطبوخ المغير قبلة نوح! طوبى لمن شهد هدمك مع قائم أهل بيتي! أولئك خيار الأمة مع أبرار العترة.","27/1/52/13",""],[14,51,"وعنه، عن علي بن عبدالله، عن عبد الرحمن بن أبي عبدالله، عن أبي الجارود قال: قال أبوجعفر عليه السلام: إن القائم يملك ثلاثمائة وتسع سنين كما لبث أهل الكهف في كهفهم، يملأ الأرض عدلاً وقسطاً كما ملئت ظلماً وجوراً، ويفتح الله له شرق الارض وغربها، ويقتل الناس حتى لا يبقى إلا دين محمد صلى الله عليه وآله، يسير بسيرة سليمان بن داود…تمام الخبر.","27/1/52/14",""],[15,51,"عنه، عن عبدالله بن القاسم الحضرمي، عن عبدالكريم بن عمرو الخثعمي قال: قلت لابي عبدالله عليه السلام: كم يملك القائم؟ قال: سبع سنين يكون سبعين سنة من سنيكم هذه.","27/1/52/15",""],[16,51,"عنه، عن عبدالرحمن بن أبي هاشم، عن علي بن أبي حمزة، عن أبي بصير (عن أبي جعفر) في حديث له اختصرناه، قال: إذا قام القائم عليه السلام دخل الكوفة وأمر بهدم المساجد الأربعة حتى يبلغ أساسها ويصيرها عريشاً كعريش موسى، وتكون المساجد كلها جماء لا شرف لها كما كانت على عهد رسول الله صلى الله عليه وآله، ويوسع الطريق الأعظم فيصير ستين ذراعا، ويهدم كل مسجد على الطريق، ويسد كل كوة إلى الطريق، وكل جناح وكنيف وميزاب إلى الطريق، ويأمر الله الفلك في زمانه فيبطئ في دوره حتى يكون اليوم في أيامه كعشرة من أيامكم والشهر كعشرة أشهر والسنة كعشر سنين من سنيكم. ثم لا يلبث إلا قليلاًحتى يخرج عليه مارقة الموالي برميلة الدسكرة عشرة آلاف، شعارهم:يا عثمان يا عثمان! فيدعو رجلاً من الموالي فيقلده سيفه، فيخرج إليهم فيقتلهم حتى لا يبقى منهم أحد، ثم يتوجه إلى كابل شاه، وهي مدينة لم يفتحها أحد قط غيره فيفتحها، ثم يتوجه إلى الكوفة فينزلها وتكون داره، ويبهرج سبعين قبيلة من قبائل العرب… تمام الخبر.","27/1/52/16",""],[17,51,"وفي خبر آخر (أنه) يفتح قسطنطينة والرومية وبلاد الصين.","27/1/52/17",""],[18,51,"عنه، عن علي بن أسباط، عن أبيه أسباط بن سالم، عن موسى الابار، عن أبي عبدالله عليه السلام، أنه قال: اتق العرب فإن لهم خبر سوء. أما إنه لا يخرج مع القائم منهم واحد.","27/1/52/18",""],[19,51,"عنه، عن عبدالرحمن بن أبي هاشم، عن عمرو بن أبي المقدام، عن عمران بن ظبيان، عن حكيم بن سعد، عن أمير المؤمنين عليه السلام قال: أصحاب المهدي شباب لا كهول فيهم إلا مثل كحل العين والملح في الزاد، وأقل الزاد الملح.","27/1/52/19",""],[20,51,"عنه، عن أحمد بن عمر بن مسلم، عن الحسن بن عقبة بن النهمي، عن أبي إسحاق البناء، عن جابر الجعفي قال: قال أبوجعفر عليه السلام: يبايع القائم بين الركن والمقام ثلاثمائة ونيف عدة أهل بدر، فيهم النجباء من أهل مصر، والأبدال من أهل الشام، والأخيار من أهل العراق، فيقيم ما شاء الله أن يقيم.","27/1/52/20",""],[21,51,"عنه، عن محمد بن علي، عن وهيب بن حفص، عن أبي بصير، قال: سمعت أبا عبدالله عليه السلام يقول: كان أمير المؤمنين عليه السلام يقول: لا يزال الناس ينقصون حتى لا يقال: الله. فإذا كان ذلك ضرب يعسوب الدين بذنبه، فيبعث الله قوما من أطرافها، (و) يجيئون قزعا كقزع الخريف. والله إني لأعرفهم وأعرف أسماء‌هم وقبائلهم وإسم أميرهم (ومناخ ركابهم)، وهم قوم يحملهم الله كيف شاء، من القبيلة الرجل والرجلين… حتى بلغ تسعة، فيتوافون من الآفاق ثلاثمائة وثلاثة عشر(رجلاً) عدة أهل بدر، وهو قول الله:﴿أَيْنَمَا تَكُونُوا يَأْتِ بِكُمُ اللهُ جَمِيعاً إِنَّ اللهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾.حتى أن الرجل ليحتبى فلا يحل حبوته حتى يبلغه الله ذلك.","27/1/52/21",""],[22,51,"محمد بن عبدالله بن جعفر الحميري، عن أبيه، عن محمد بن عبدالحميد ومحمد بن عيسى، عن محمد بن الفضيل، عن أبي حمزة، عن أبي عبدالله عليه السلام في حديث طويل أنه قال: يا أبا حمزة،إن منا بعد القائم أحد عشر مهديا من ولد الحسين عليه السلام.","27/1/52/22",""],[23,51,"الفضل بن شاذان، عن الحسن بن محبوب، عن عمرو بن أبي المقدام، عن جابر الجعفي قال:سمعت أبا جعفر عليه السلام يقول: والله، ليملكن منا أهل البيت رجل بعد موته ثلاثمائة سنة يزداد تسعا. قلت:متى يكون ذلك؟ قال: بعد القائم عليه السلام. قلت: وكم يقوم القائم في عالمه؟ قال: تسع عشرة سنة،ثم يخرج المنتصر فيطلب بدم الحسين عليه السلام ودماء أصحابه، فيقتل ويسبي حتى يخرج السفاح.","27/1/52/23",""]],"name":"الغيبة للطوسي","author":"شيخ الطائفة الطوسي (ت 460 هـ)","blurb":"جمع بين الدليل العقلي والنقلي: وجوب الإمامة، حكمة الغيبة، ولادة الإمام، السفراء، التوقيعات، وطول العمر.","book":"https://thaqalayn.net/book/Kitab-al-Ghayba-Tusi"};